// DeleteDomainRecord destroys a domain and the names beneath it: it
// burns every token, drops every reverse-resolution pointer into them,
// removes the records, and finally removes the domain itself.
//
// WHY IT EXISTS. Retiring a domain after a brand complaint, recovering
// the storage deposit on a domain that never sold, and clearing out fad
// domains nobody renewed. A logic realm cannot provide any of this,
// because the vault owns the trees and exposed no delete path — the only
// Remove call for a domain lived inside RegisterDomainRecord as the
// evict-and-replace step of re-registration.
//
// IT DELIBERATELY WORKS ON A DOMAIN WITH LIVE NAMES UNDER IT. The case
// this exists for is a demand to remove a domain entirely, where waiting
// for names to lapse is not an option. Compensating the holders is
// handled off chain and is deliberately not a contract concern.
//
// WHERE THIS DEPARTS FROM THE SPEC, stated plainly because it is a real
// difference: MAINNET.md §3d asks for all of it "in one call". It is
// bounded instead, deleting at most maxDeletePerCall names per call and
// reporting whether it finished. An unbounded loop over a tree that may
// hold any number of names is a transaction that stops fitting in a
// block once a domain gets popular — which would mean the domains most
// likely to attract a complaint are exactly the ones that could never be
// deleted, in a realm that can never be fixed. The caller repeats until
// `done`; for any domain of realistic size that is one call, so the
// no-preconditions requirement is preserved. What is NOT preserved is
// atomicity: a multi-call deletion is visible half-done between calls.
// Pause() first if that matters.
//
// Calling it on a domain that does not exist is a no-op reporting done,
// so a repeat loop terminates cleanly rather than panicking on the call
// that follows the last one.
func DeleteDomainRecord(cur realm, label string) (removed int64, done bool) {
	assertIsTrustedLogic(cur)
	d, ok := getDomain(label)
	if !ok {
		return 0, true
	}

	// Collect first, mutate second. Removing entries from the tree while
	// iterating it is undefined, and this loop exists precisely to remove
	// entries.
	start, end := domainRange(label)
	var keys []string
	names.Iterate(start, end, func(key string, v any) bool {
		if len(keys) >= maxDeletePerCall {
			return true
		}
		keys = append(keys, key)
		return false
	})

	for _, key := range keys {
		v := names.Get(key)
		if v == nil {
			continue
		}
		n := v.(*Name)
		// The name label is whatever follows "domain*" in the storage
		// key — the record no longer stores its own label.
		nameLabel := key[len(label)+1:]
		tid := nameTokenID(nameLabel, label)
		_ = n
		owner := nsnft.OwnerOf(tid)
		clearPrimaryIfPointingAt(owner, tid)
		// Every name has a token, but a registry swapped in mid-migration
		// could meet a record whose token was already dealt with. Burning a
		// token that does not exist panics and would strand the domain
		// half-deleted, so ask first.
		if owner != "" {
			nsnft.Burn(cross(cur), tid)
		}
		names.Remove(key)
		removed++
	}

	// Anything left means the cap was hit; the domain record has to stay
	// so the next call can still find its name span.
	more := false
	names.Iterate(start, end, func(key string, v any) bool {
		more = true
		return true
	})
	if more {
		return removed, false
	}

	_ = d
	domains.Remove(label)
	return removed, true
}

// -- names --

/*
RegisterNameRecord creates `label*domain` and mints its token in nsnft.

`paid` false registers a FREE-TIER name: the token is minted with the free
hold already set, so there is never an instant in which it could be
approved and sold before a lock arrived. There is no longer any such thing
as a name without a token — see Name.

RECLAIM burns the previous holder's token first. The owner is read from
the ledger, never from the record, because the record has no owner.

AN ORPHAN TOKEN IS REFUSED. A token that exists with no record behind it
means a registry swap is mid-migration or something has gone wrong; either
way, registering over it would mint a second claim to a name somebody
already holds. RestoreNameRecord is the door for adopting one.
*/
func RegisterNameRecord(cur realm, label, domainLabel string, owner address, now int64, paid bool) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	d, ok := getDomain(domainLabel)
	if !ok {
		return errStr("unknown domain")
	}
	if d.frozen {
		return errStr("domain is frozen")
	}
	if isReclaimable(d.expires, now) {
		return errStr("domain has lapsed past its grace period")
	}
	treeKey := nameTreeKey(label, domainLabel)
	tid := nameTokenID(label, domainLabel)
	if n, ok := getName(label, domainLabel); ok {
		if n.frozen {
			return errStr("name is frozen")
		}
		if !isReclaimable(n.expires, now) {
			return errStr("name already registered and not yet reclaimable")
		}
		// Evict the previous holder completely. The reverse pointer goes
		// first: leaving it would make the old owner resolve to a name the
		// reclaimer now owns.
		prev := nsnft.OwnerOf(tid)
		clearPrimaryIfPointingAt(prev, tid)
		if prev != "" {
			nsnft.Burn(cross(cur), tid)
		}
		names.Remove(treeKey)
	} else if nsnft.OwnerOf(tid) != "" {
		return errStr("a token for " + tid + " exists with no record behind it; restore it rather than registering over it")
	}

	nsnft.Mint(cross(cur), owner, tid, holdBits(paid, false))
	names.Set(treeKey, &Name{
		registered: now, expires: now + termLength,
		epoch: nsnft.Epoch(tid), extra: avl.Tree{},
	})
	setPrimaryIfNone(owner, tid)
	return nil
}

func holdBits(paid, frozen bool) int {
	b := 0
	if !paid {
		b |= 1 << lockBitFree
	}
	if frozen {
		b |= 1 << lockBitFrozen
	}
	return b
}

/*
setPrimaryIfNone gives an address a reverse pointer when it has none — or
when the one it has points at a name it no longer holds.

The second half is new. A pointer used to be cleared on every transfer,
because transfers went through this realm. They no longer do: a sale that
settles on nsnft leaves the seller's pointer aimed at a name they sold.
nslogic.ResolveAddress already refuses to answer with it, so it never
misleads anybody — but left in place it also blocked the seller's NEXT
registration from becoming their primary, which would have looked like a
bug in registration rather than a stale pointer.
*/
func setPrimaryIfNone(owner address, tid string) {
	k := owner.String()
	if v := primary.Get(k); v == nil || !ownsNow(owner, v.(string)) {
		primary.Set(k, tid)
	}
}

/*
UpgradeFreeRecord lifts the free-tier hold — the paid upgrade.

Preserves the dates: this is not a re-registration.

`newOwner` exists because the common case is somebody who decided to sell
and, in the same moment, wants the name in a wallet they control rather
than the key they were given. That move is a burn and a mint here, because
a held token cannot be transferred by design.

THE PROFILE DOES NOT GO WITH IT, and it used to. The move re-stamped the
old data to the new epoch and gave the recipient a reverse pointer — and
`newOwner` can be ANY address. An audit spelled out the attack: fill a
free name's profile with your own pay addresses, pay list price to upgrade
it into a victim's wallet, and the victim's name now asks people to pay
you, their address reverse-resolves to it, and their own later edits do
not clear it because the epoch is already current. So the data is left in
the previous epoch, where every read hides it and the next write destroys
it, and the recipient gets no pointer they never chose. A person moving
their own name to a new wallet re-enters their profile once; that is the
price of the move not being usable against somebody else.

Refused for a frozen name. Upgrading must never be the way a disputed name
gets out of its hold.
*/
func UpgradeFreeRecord(cur realm, label, domainLabel string, newOwner address) error {
	assertIsTrustedLogic(cur)
	if !newOwner.IsValid() {
		return errStr("invalid owner address")
	}
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if n.frozen {
		return errStr("name is frozen")
	}
	tid := nameTokenID(label, domainLabel)
	owner := nsnft.OwnerOf(tid)
	if owner == "" {
		return errStr("name has no token")
	}
	bits := nsnft.LockBits(tid)
	if bits&(1<<lockBitFree) == 0 {
		return errStr("name is already paid for")
	}
	if newOwner == owner {
		nsnft.SetLock(cross(cur), tid, lockBitFree, false)
		return nil
	}
	nsnft.Burn(cross(cur), tid)
	nsnft.Mint(cross(cur), newOwner, tid, bits&^(1<<lockBitFree))
	clearPrimaryIfPointingAt(owner, tid)
	// n.epoch is deliberately NOT moved, and no pointer is given — see above.
	return nil
}

/*
RestoreNameRecord is the migration door: records move, tokens do not.

A registry swapped in behind the same nsnft finds tokens that already
exist. This writes the record for one and ADOPTS its token, or mints one
when the ledger has none. It never moves a token: a snapshot must never
take a name from its current holder.

WHEN THE LEDGER DISAGREES WITH THE SNAPSHOT, IT WINS. This used to refuse,
and an audit showed where refusing leads: a name sold between the snapshot
and the restore panics the batch, gets dropped to finish the rest, and the
window seals — leaving the buyer's token with no record behind it, unable
to be renewed, resolved or registered, forever. So the record is written
for whoever holds the token now, and the snapshot's profile data is NOT
replayable onto it (restoredFor stays empty), because it was the seller's.

Gated like every write, and nslogic only reaches it through the restore
window, which is one-shot.
*/
func RestoreNameRecord(cur realm, label, domainLabel string, owner address, registered int64, paid bool) error {
	assertIsTrustedLogic(cur)
	if !owner.IsValid() {
		return errStr("invalid owner address")
	}
	if err := assertLabelKeySafe(label); err != nil {
		return err
	}
	if _, ok := getDomain(domainLabel); !ok {
		return errStr("unknown domain")
	}
	if _, ok := getName(label, domainLabel); ok {
		return errStr("name already has a record")
	}
	tid := nameTokenID(label, domainLabel)
	held := nsnft.OwnerOf(tid)
	if held == "" {
		nsnft.Mint(cross(cur), owner, tid, holdBits(paid, false))
		held = owner
	} else {
		/* NEVER ADOPT WHILE ANOTHER REGISTRY CAN STILL MINT.

		   The ledger's trust set is a set so an old and a new registry can
		   both be live during a migration — and an audit showed what that
		   allows: a name adopted here and renewed here still has its OLD
		   record, with its old expiry, in the old registry. Once that
		   lapses past grace, anyone registers the name through the old
		   logic realm, which burns the token and mints it to them. The
		   holder's paid, renewed name is gone. So adoption requires that
		   this registry is the only one the ledger trusts: pause and
		   untrust the old registry first, then restore. */
		if nsnft.Trusted() != cur.Address().String() {
			return errStr("adopting " + tid + " while the ledger trusts another registry would let that registry reclaim it; untrust the old registry first")
		}
		// Adopt. BOTH holds are set from what is being restored: the free
		// hold from the snapshot, and the frozen hold cleared, so a freeze
		// left by the old registry cannot linger on a record that reads
		// unfrozen. nslogic re-freezes after this if the snapshot says so.
		nsnft.SetLock(cross(cur), tid, lockBitFree, !paid)
		nsnft.SetLock(cross(cur), tid, lockBitFrozen, false)
	}
	rec := &Name{
		registered: registered, expires: registered + termLength,
		epoch: nsnft.Epoch(tid), extra: avl.Tree{},
	}
	if held == owner {
		rec.restoredFor = owner
		setPrimaryIfNone(owner, tid)
	}
	names.Set(nameTreeKey(label, domainLabel), rec)
	return nil
}

func RenewNameRecord(cur realm, label, domainLabel string, caller address, now int64) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	if isReclaimable(n.expires, now) {
		return errStr("name expired beyond grace period")
	}
	/* THE CHECK THE FIRST ATTEMPT GOT WRONG. It compared the caller to the
	   record's own owner copy, which stopped updating the moment ownership
	   moved to the token — so a buyer could not renew what they bought,
	   watched it lapse, and lost it to whoever re-registered. There is no
	   copy now. The ledger answers. */
	if caller != nsnft.OwnerOf(nameTokenID(label, domainLabel)) {
		return errStr("restricted to name owner")
	}
	n.expires = advanceTerm(n.expires, now)
	return nil
}

/*
SetNameFrozen sets the record's frozen bit AND the matching hold on the
token, in the same call.

The record bit alone used to be the whole mechanism, and it bound nothing
outside our own transfer wrappers — a disputed name could be moved on any
marketplace that called the token directly. The hold in nsnft binds every
path there is.
*/
func SetNameFrozen(cur realm, label, domainLabel string, frozen bool) {
	assertIsTrustedLogic(cur)
	mustGetName(label, domainLabel).frozen = frozen
	nsnft.SetLock(cross(cur), nameTokenID(label, domainLabel), lockBitFrozen, frozen)
}

// SetNameExpiryRecord sets an expiry directly. Backs the admin
// free-extension lever (SPEC.md §19) and any future term mechanic;
// the logic realm decides who may call it.
func SetNameExpiryRecord(cur realm, label, domainLabel string, expires int64) {
	assertIsTrustedLogic(cur)
	mustGetName(label, domainLabel).expires = expires
}

// SetNameTTLRecord sets how long a resolver may cache answers about this
// name, in seconds, where 0 means never cache. See Domain.ttl for why
// this exists and why the owner rather than the registry sets it.
func SetNameTTLRecord(cur realm, label, domainLabel string, ttl int64) error {
	assertIsTrustedLogic(cur)
	if ttl < 0 {
		return errStr("ttl may not be negative")
	}
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	freshen(n, nameTokenID(label, domainLabel))
	n.ttl = ttl
	return nil
}

// SetNameExtraRecord writes one arbitrary key on a name. This is where
// profile fields, cross-chain addresses, management-key hashes and tier
// markers live. An empty value deletes the key.
func SetNameExtraRecord(cur realm, label, domainLabel, key, value string) error {
	assertIsTrustedLogic(cur)
	n, ok := getName(label, domainLabel)
	if !ok {
		return errStr("unknown name")
	}
	freshen(n, nameTokenID(label, domainLabel))
	return setExtra(&n.extra, key, value)
}

/*
freshen is the WRITE half of the lazy wipe, and it is the half the first
attempt described in prose and never wrote.

If a name's data belongs to a previous ownership epoch, every extra and the
TTL are destroyed, and the record is re-stamped to the current epoch —
BEFORE the new value is written. So the buyer's first edit cannot carry
the seller's Bitcoin address forward as the buyer's: by the time the edit
lands, the address is gone.

It wipes everything rather than a list of sensitive keys, for the same
reason the old transfer wipe did: which keys matter is policy, and a list
kept here would be wrong the first time nslogic invents a key.

The read half — hiding stale data from everybody the instant the epoch
moves — is isFresh, used by every name read.
*/
func freshen(n *Name, tid string) { freshenTo(n, nsnft.Epoch(tid)) }

// freshenTo is freshen with the ledger's answer passed in, so the rule
// itself can be tested without a registry the ledger trusts.
func freshenTo(n *Name, epoch int64) {
	if n.epoch != epoch {
		n.extra = avl.Tree{}
		n.ttl = 0
		n.epoch = epoch
	}
}

func SetPrimaryRecord(cur realm, owner address, label, domainLabel string) error {
	assertIsTrustedLogic(cur)
	if _, ok := getName(label, domainLabel); !ok {
		return errStr("unknown name")
	}
	tid := nameTokenID(label, domainLabel)
	// nslogic checks this too. Checked here as well because a pointer at a
	// name somebody does not hold is the one thing reverse resolution must
	// never be able to say, and the ledger is one read away.
	if !ownsNow(owner, tid) {
		return errStr("restricted to the name's current owner")
	}
	primary.Set(owner.String(), tid)
	return nil
}

func ClearPrimaryRecord(cur realm, owner address) {
	assertIsTrustedLogic(cur)
	primary.Remove(owner.String())
}

// -- there are no raw NFT operations here any more --
//
// RawTransferNFT, RawApprove, RawSetApprovalForAll and TransferRecordOwner
// are gone. Transfers and approvals happen on nsnft, called directly by the
// holder or by a marketplace they approved — exactly how an external
// marketplace does it, so ours has no privileged path. A registry that
// could move tokens would be a registry that could steal them.

// -- config: all settable, none constant --

func SetTreasuryRecord(cur realm, addr address)     { assertIsTrustedLogic(cur); treasury = addr }
func SetTermLengthRecord(cur realm, seconds int64)  { assertIsTrustedLogic(cur); termLength = seconds }
func SetGracePeriodRecord(cur realm, seconds int64) { assertIsTrustedLogic(cur); gracePeriod = seconds }

// SetMaxDeletePerCallRecord tunes how much work one DeleteDomainRecord
// call will do. See maxDeletePerCall in types.gno.
func SetMaxDeletePerCallRecord(cur realm, n int) {
	assertIsTrustedLogic(cur)
	if n < 1 {
		n = 1
	}
	maxDeletePerCall = n
}
func SetLabelPatternRecord(cur realm, pattern string) {
	assertIsTrustedLogic(cur)
	labelPattern = pattern
}
func SetTokenURIBaseRecord(cur realm, base string) { assertIsTrustedLogic(cur); tokenURIBase = base }

func SetLabelLengthRecord(cur realm, minLen, maxLen int) {
	assertIsTrustedLogic(cur)
	minLabelLen, maxLabelLen = minLen, maxLen
}

func SetExtraLimitsRecord(cur realm, keyLen, valueLen, entries int) {
	assertIsTrustedLogic(cur)
	maxExtraKeyLen, maxExtraValueLen, maxExtraEntries = keyLen, valueLen, entries
}

// SetGlobalRecord writes one arbitrary package-level key — fee rates,
// default prices, a custodian address, points balances, claim records.
// Anything global that does not exist yet goes here instead of needing a
// package variable that could never be added after deployment.
// Keys the restore machinery owns. Written only by RestoreGlobal's own
// path, never by a general setter — because nslogic's SetGlobal forwards
// whatever key an admin passes, and one call writing "restore" reopened
// a seal that restore.gno calls irreversible. Enforced HERE as well as
// there, so a future logic realm cannot drop the guard by forgetting it.
var reservedGlobals = []string{"restore", "restored"}

func SetGlobalRecord(cur realm, key, value string) error {
	assertIsTrustedLogic(cur)
	for _, r := range reservedGlobals {
		if key == r {
			return errStr("that key belongs to the restore machinery and is not settable here")
		}
	}
	return setExtra(&globals, key, value)
}

// SetReservedGlobalRecord is the restore machinery's own door to the
// keys above. Same trust gate; separate name, so a general-purpose
// setter can never reach them by accident.
func SetReservedGlobalRecord(cur realm, key, value string) error {
	assertIsTrustedLogic(cur)
	found := false
	for _, r := range reservedGlobals {
		if key == r {
			found = true
		}
	}
	if !found {
		return errStr("not a reserved key; use SetGlobalRecord")
	}
	return setExtra(&globals, key, value)
}

// setExtra applies the shared bounds and the delete-on-empty rule.
func setExtra(t *avl.Tree, key, value string) error {
	if err := assertExtraKey(key); err != nil {
		return err
	}
	if value == "" {
		t.Remove(key)
		return nil
	}
	if len(value) > maxExtraValueLen {
		return errStr("extra value too long")
	}
	if t.Get(key) == nil && t.Size() >= maxExtraEntries {
		return errStr("too many extra entries")
	}
	t.Set(key, value)
	return nil
}

// assertExtraKey keeps extension keys free of the characters that would
// make a snapshot ambiguous. Export lists keys as CSV, so a key
// containing a comma or a newline would silently corrupt a backup — and
// a backup you cannot trust is the one thing this realm cannot afford.
func assertExtraKey(key string) error {
	if key == "" || len(key) > maxExtraKeyLen {
		return errStr("bad extra key")
	}
	if strings.ContainsAny(key, ",\n\r") {
		return errStr("extra key may not contain commas or newlines")
	}
	return nil
}

// assertLabelKeySafe is a STRUCTURAL check, not a policy one. Character
// policy lives in the logic realm's tunable labelPattern; this is the
// narrow set of characters that would break the vault's own machinery no
// matter what policy is in force:
//
//	"*"  is the separator in both key encodings, so a label containing
//	     one makes storage keys and token ids ambiguous;
//	","  and newlines would corrupt the CSV snapshot exports, which are
//	     the disaster-recovery guarantee — assertExtraKey already refuses
//	     them for extension keys, and labels become keys just as much;
//	""   cannot address a record at all.
//
// Enforcing it here rather than trusting the logic realm matters because
// labelPattern is admin-tunable: loosening it must never be able to
// silently corrupt a backup in a realm that cannot be redeployed.
func assertLabelKeySafe(label string) error {
	if label == "" {
		return errStr("empty label")
	}
	if strings.ContainsAny(label, "*,\n\r") {
		return errStr("label may not contain '*', commas or newlines")
	}
	return nil
}

func errStr(s string) error { return errors.New(s) }

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// assertIsAdmin reads nsdata.GetAdmin() fresh every call — correct even
// immediately after a TransferAdmin, and correct for a freshly-deployed
// logic realm with no local state of its own to go stale.
//
// Note: admin authority to swap WHICH realm is trustedLogic, or to
// transfer admin itself, is deliberately NOT exposed here — those live
// only in nsdata's own admin.gno, callable solely by a direct wallet
// call from the current admin address, never proxied through logic.
// That's the one part of the system a compromised or buggy logic realm
// cannot touch.
func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != nsdata.GetAdmin() {
		panic("nslogic: restricted to project admin")
	}
}

// SetLabelPattern no longer changes anything, and refuses anything but
// the rule this realm actually implements.
//
// It used to compile an arbitrary regex and store it, with validateLabel
// reading it back. That flexibility cost 15 GNOT of permanent storage
// per deploy — see the measurements in validate.gno — for a rule that
// has never changed and should not change casually.
//
// It is kept rather than deleted so that an admin who reaches for it
// gets told what happened instead of a "function not found". And it
// refuses a different pattern rather than accepting one it will not
// enforce: a stored string describing rules the code does not apply is
// the exact silent divergence the caching version was written to avoid.
func SetLabelPattern(cur realm, pattern string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if pattern != labelRule {
		panic("nslogic: the label rule is fixed in this realm (" + labelRule +
			"). Changing it means deploying a new logic realm — which is deliberate, " +
			"because a stored pattern the code does not enforce is worse than no setting at all.")
	}
	nsdata.SetLabelPatternRecord(cross(cur), pattern)
}

func SetLabelLengthLimits(cur realm, minLen, maxLen int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if minLen < 1 || maxLen < minLen {
		panic("nslogic: invalid length bounds")
	}
	nsdata.SetLabelLengthRecord(cross(cur), minLen, maxLen)
}

// SetDefaultNamePrice sets the fallback price in micro-USD, used by any
// domain that has not set its own base.
func SetDefaultNamePrice(cur realm, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if microUsd < 0 {
		panic("nslogic: price cannot be negative")
	}
	setGlobal(cur, keyDefaultPrice, strconv.FormatInt(microUsd, 10))
}

// SetUsdRate records how many ugnot one USD buys — the bridge between
// the USD price list and settlement on this chain.
//
// It is a MANUAL rate, not a market feed: it sits where it was last
// written. A stale rate during a sharp move sells names at the wrong
// price, and no amount of contract logic fixes that — keeping it current
// is an operational duty. Isolated as one global so a future logic realm
// can swap in a real oracle without touching the vault or restating a
// single price.
func SetUsdRate(cur realm, ugnotPerUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if ugnotPerUsd <= 0 {
		panic("nslogic: rate must be positive")
	}
	setGlobal(cur, keyRate, strconv.FormatInt(ugnotPerUsd, 10))
}

// SetTermLength / SetGracePeriod retune the lifecycle itself. Both were
// hardcoded constants in the vault until 2026-08-21 — meaning the 1-year
// term and 90-day grace could never have been changed, on a realm that
// is never redeployed. There was no reason to accept that.
// maxLifecycleDays bounds both setters. time.Duration is int64
// NANOSECONDS, so `days * 24h` overflows above ~106,751 days and wraps to
// a NEGATIVE duration — which would install a negative term and brick
// every registration and renewal in the registry. Guarding the input is
// what keeps the multiplication in range.
const maxLifecycleDays = 36500 // 100 years

func SetTermLength(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if days <= 0 || days > maxLifecycleDays {
		panic("nslogic: term out of range (1..36500 days)")
	}
	term := days * 24 * 60 * 60
	// Keep gracePeriod <= termLength. Anchoring a renewal to the previous
	// due date is only coherent while a renewal cannot happen more than
	// one full term after it; the vault clamps forward defensively, but
	// the combination should not be reachable in the first place.
	if nsdata.GetGracePeriod() > term {
		panic("nslogic: term must be at least the current grace period")
	}
	nsdata.SetTermLengthRecord(cross(cur), term)
}

func SetGracePeriod(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if days < 0 || days > maxLifecycleDays {
		panic("nslogic: grace period out of range (0..36500 days)")
	}
	grace := days * 24 * 60 * 60
	if grace > nsdata.GetTermLength() {
		panic("nslogic: grace period may not exceed the term length")
	}
	nsdata.SetGracePeriodRecord(cross(cur), grace)
}

// SetTokenURIBase re-points TokenURI at a different renderer, so the NFT
// artwork can be replaced without touching the vault.
func SetTokenURIBase(cur realm, base string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetTokenURIBaseRecord(cross(cur), base)
}

func SetExtraLimits(cur realm, keyLen, valueLen, entries int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if keyLen < 1 || valueLen < 1 || entries < 1 {
		panic("nslogic: limits must be positive")
	}
	nsdata.SetExtraLimitsRecord(cross(cur), keyLen, valueLen, entries)
}

/*
SetMarketFee is nsmarket's fee control, living here because this is the
realm the vault trusts.

nsmarket.SetFee could never work: it wrote through nsdata.SetGlobalRecord
from a realm deliberately outside the trusted set, so it passed its own
admin check and then panicked inside the vault for every caller. Rather
than grant nsmarket vault privileges — which would surrender the property
that realm is built around — the setter moved to the realm that already
has the grant, and the validation moved with it.

The spec grammar is nsmarket's, restated here rather than imported so
this realm does not take a dependency on the marketplace to set a number:
an amount in ugnot ("1000000"), or a percentage ("%2.5"), or "" for none.
A malformed spec would otherwise be read on every sale and resolve
silently to zero.
*/
func SetMarketFee(cur realm, spec string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	assertValidFeeSpec(spec)
	setGlobal(cur, "marketfee", strings.TrimSpace(spec))
}

// assertValidFeeSpec mirrors nsmarket.parseFee. Percentages are carried
// as basis points so a fee is expressible without floating point
// anywhere near money.
func assertValidFeeSpec(spec string) {
	spec = strings.TrimSpace(spec)
	if spec == "" {
		return
	}
	if !strings.HasPrefix(spec, "%") {
		n, err := strconv.ParseInt(spec, 10, 64)
		if err != nil || n < 0 {
			panic("nslogic: a fee is an amount in ugnot or a percentage like %2.5 — got " + spec)
		}
		return
	}
	body := spec[1:]
	whole, frac := body, ""
	if dot := strings.Index(body, "."); dot >= 0 {
		whole, frac = body[:dot], body[dot+1:]
	}
	// ONE decimal, matching nsmarket.parseFee exactly. I wrote two here
	// first, which made this validator MORE permissive than the parser
	// that has to read the value back — and a spec nsmarket refuses is
	// read as a zero fee on every sale, silently, forever. A validator
	// looser than its consumer is worse than no validator: it converts a
	// rejected input into a silent revenue leak.
	if len(frac) > 1 {
		panic("nslogic: a fee percentage carries at most one decimal — got " + spec)
	}
	for _, part := range []string{whole, frac} {
		for i := 0; i < len(part); i++ {
			if part[i] < '0' || part[i] > '9' {
				panic("nslogic: a fee percentage must be digits — got " + spec)
			}
		}
	}
	if whole == "" && frac == "" {
		panic("nslogic: a fee percentage needs a number — got " + spec)
	}
	// Basis points the same way parseFee computes them: whole*100 plus
	// one tenth-digit worth ten. Not two digits, and not a 100% ceiling
	// — nsmarket caps at maxFeeBps, which is 50%.
	w, _ := strconv.ParseInt("0"+whole, 10, 64)
	bp := w * 100
	if frac != "" {
		f, _ := strconv.ParseInt("0"+frac, 10, 64)
		bp += f * 10
	}
	if bp <= 0 || bp > 5000 {
		panic("nslogic: a fee percentage must be above zero and at most 50 — got " + spec)
	}
}

// SetGlobal writes an arbitrary project-wide key into the vault's
// package-level extension slot — the escape hatch for global state that
// does not exist yet.
func SetGlobal(cur realm, key, value string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setGlobal(cur, key, value)
}

func setGlobal(cur realm, key, value string) {
	/* THE RESTORE SEAL IS NOT AN ORDINARY GLOBAL.
	   restore.gno says sealing is "IRREVERSIBLE… There is no argument
	   that unseals it", and RestoreGlobal carries a reserved-key guard
	   to make that true. This function did not, so one admin call
	   writing key "restore" reopened the seal and the claim in that file
	   was simply false. The admin key is trusted and already holds
	   worse powers, so this is documentation drift rather than an
	   escalation — but a permanent-sounding promise that a two-word call
	   undoes is the kind of thing an auditor and a court both notice.
	   The durable version of this guard belongs in the vault, where a
	   logic swap cannot drop it; this is the half that ships today. */
	if key == keyRestore || key == keyRestoredCount {
		panic("nslogic: " + key + " is written by the restore machinery, not by SetGlobal")
	}
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic(err)
	}
}

// SetTreasury moves the revenue-receiving role — independent of
// nsdata's TransferAdmin, same reasoning as the original build's
// admin/treasury separation.
func SetTreasury(cur realm, newTreasury address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if !newTreasury.IsValid() {
		panic("nslogic: invalid treasury address")
	}
	nsdata.SetTreasuryRecord(cross(cur), newTreasury)
}

// SelfAddress reports this deployed realm's own address — needed once,
// at wiring time, so admin knows what to pass to
// nsdata.ProposeTrustedLogicGrant.
func SelfAddress(cur realm) address {
	return cur.Address()
}

package nslogic

import (
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
THE BLOCK LIST: labels nobody may hold, at any price.

This is NOT the reserved list, and confusing the two would undo both.

	reserved (collections/reserved-labels.json, 232 labels) says
	"blocked from the free tier, buyable at list price like anything
	else". admin*meme being purchasable is deliberate: the harm it
	guards against is handing a phishing address out for nothing, not
	the existence of the name. That list is enforced by the issuer,
	which is the only place that decides what is free.

	THIS list says "not available, full stop". It is the small set where
	the answer does not change when somebody offers money: names that
	impersonate the registry itself, and the registry's own names.

WHY IT LIVES IN THE VAULT'S GLOBALS RATHER THAN IN THIS FILE.

Baking it in would mean a logic deploy to block a word, and the words
worth blocking are exactly the ones discovered after launch — the label
somebody tried yesterday that nobody thought of. Globals are writable by
the admin, survive a logic swap because they belong to the vault, and
cost storage only for what is actually stored.

Chunked because a global value is capped at 512 bytes. Eight chunks is
about four kilobytes, or several hundred labels, which is far more than
this list should ever need — if it grows past that, the thing being
built is a content policy and it belongs off chain where it can be
updated without a transaction.

FAILS OPEN, and that is the uncomfortable choice, so it is written down.
An unreadable chunk blocks nothing rather than blocking everything.
Failing closed here would mean one malformed global takes the whole
registry offline — every registration, for everyone, until an admin
notices. The harm from a blocked label slipping through is one bad name
that an admin can freeze; the harm from failing closed is total. The
list is also not the only defence: the issuer holds the reserved list,
and FreezeName exists for anything that gets past both.
*/

const (
	blockChunks   = 8
	blockKeyStem  = "block"
	blockChunkMax = 512
)

// blockKey is the global name for one chunk: block0 … block7.
func blockKey(i int) string {
	return blockKeyStem + string(rune('0'+i))
}

/*
BlockedLabel reports whether a label may not be registered at all.

Compares against the label as the registry stores it — lowercase, already
validated — so a caller cannot slip past with different casing. Every
comparison is exact: this list holds whole labels, not substrings,
because "contains" matching turns a list of a dozen words into an
unpredictable filter that refuses names nobody meant to refuse.
*/
func BlockedLabel(label string) bool {
	if label == "" {
		return false
	}
	want := strings.ToLower(label)
	for i := 0; i < blockChunks; i++ {
		v := nsdata.GetGlobal(blockKey(i))
		if v == "" {
			continue
		}
		for _, e := range strings.Split(v, ",") {
			if strings.ToLower(strings.TrimSpace(e)) == want {
				return true
			}
		}
	}
	return false
}

// BlockList returns one chunk, so the panel can show and edit what is
// actually stored rather than what somebody believes is stored.
func BlockList(i int) string {
	if i < 0 || i >= blockChunks {
		return ""
	}
	return nsdata.GetGlobal(blockKey(i))
}

// BlockChunks is the number of chunks, so the panel does not hard-code a
// constant that this file might later change.
func BlockChunks() int { return blockChunks }

/*
SetBlockList replaces one chunk. Admin only.

Replaces rather than appends: an append-only list has no way to correct a
mistake, and a mistake here refuses somebody a name for reasons nobody
can see. The panel reads the chunk, edits it, and writes it back whole.
*/
func SetBlockList(cur realm, i int, csv string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if i < 0 || i >= blockChunks {
		panic("nslogic: chunk out of range")
	}
	if len(csv) > blockChunkMax {
		panic("nslogic: that chunk is longer than a global may be")
	}
	// Normalised on the way in, so the comparison above never has to
	// account for whatever spacing somebody typed into a form.
	parts := strings.Split(csv, ",")
	out := []string{}
	for _, p := range parts {
		p = strings.ToLower(strings.TrimSpace(p))
		if p != "" {
			out = append(out, p)
		}
	}
	setGlobal(cur, blockKey(i), strings.Join(out, ","))
}

// assertNotBlocked is the gate both doors pass through — the paid
// registration and the free grant. One function, called twice, because
// a block that only covers one route is not a block.
func assertNotBlocked(label string) {
	if BlockedLabel(label) {
		panic("nslogic: " + label + " is not available")
	}
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// RegisterDomain mints a new `*domain` — ADMIN-ONLY (2026-08-15 policy:
// domains are never sold or owned by third parties). No payment: the
// project isn't paying itself. Domains are also permanently
// non-transferable by users (see nft.gno's TransferFrom).
func RegisterDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	validateLabel(label)
	caller := cur.Previous().Address()
	if err := nsdata.RegisterDomainRecord(cross(cur), label, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// RenewDomain extends a domain's expiry by exactly one year from its
// PREVIOUS due date, not from the payment date. No payment — domains are
// always project-owned, so this is self-service upkeep, not a sale.
// Deliberately does not call validateLabel — a tightened pattern only
// gates new registrations, never renewals of what's already registered.
func RenewDomain(cur realm, label string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if err := nsdata.RenewDomainRecord(cross(cur), label, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// ReassignDomain moves a domain record to a new owner. ADMIN-ONLY, and
// the deliberate exception to "domains are non-transferable".
//
// It exists because domain ownership is snapshotted into the record at
// registration time, while `admin` is a rotatable role. After the
// planned EOA-to-multisig rotation, the incoming admin could not renew
// or reprice any domain the outgoing key had registered — and if the
// rotation happened *because* the old key was compromised, the attacker
// could still reprice those domains afterwards. This is the recovery
// lever for exactly that situation.
//
// Not a loophole in the non-transferability policy: that policy exists
// to stop domains reaching third parties as tradeable assets, and this
// path is reachable only by the current admin, moving a project domain
// between project-controlled addresses.
func ReassignDomain(cur realm, label string, newOwner address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	/* THE STOPGAP IS GONE. This used to read the domain's settings back
	   and rewrite them around a token transfer, because that transfer
	   wiped them. Domains are records now, and nsdata moves the owner
	   without touching price, len, nm, open or maxterm. */
	if err := nsdata.ReassignDomainRecord(cross(cur), label, newOwner); err != nil {
		panic(err)
	}
}

// -- pricing controls (admin) --
//
// Every amount here is MICRO-USD (1 USD = 1_000_000). Nothing is priced
// in the chain token; ugnot is derived at payment time from the stored
// rate, so a second settlement token later is a second rate rather than
// a second price list.

// SetDomainOpen enables or disables registration of new names under a
// domain. Existing names are untouched: closing a domain stops new
// mints, it does not seize anything already held.
func SetDomainOpen(cur realm, label string, open bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	v := "1"
	if !open {
		v = "0"
	}
	setDomainExtra(cur, label, keyOpen, v)
}

// SetDomainBasePrice sets the domain's base price in micro-USD. Every
// "%N" rule under the domain is relative to this, so one call reprices
// the whole domain.
func SetDomainBasePrice(cur realm, label string, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if microUsd < 0 {
		panic("nslogic: price cannot be negative")
	}
	setDomainExtra(cur, label, keyPrice, strconv.FormatInt(microUsd, 10))
}

// SetDomainLengthRules prices by label length: "3:2000000,4:%150,5:0"
// means 3-char names cost $2.00, 4-char names cost 150% of the domain
// base, and 5-char names are free.
func SetDomainLengthRules(cur realm, label, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setDomainExtra(cur, label, keyLens, normalizeRules(rules, true))
}

// SetDomainNameOverrides prices specific labels: "420:5000000,gm:%500".
// Highest precedence — this beats length rules and the base.
func SetDomainNameOverrides(cur realm, label, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setDomainExtra(cur, label, keyNames, normalizeRules(rules, false))
}

// SetDomainField writes an arbitrary key on a domain, for whatever a
// future feature needs without a vault change.
func SetDomainField(cur realm, label, key, value string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	setDomainExtra(cur, label, key, value)
}

func setDomainExtra(cur realm, label, key, value string) {
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic(err)
	}
}

// FreezeDomain / UnfreezeDomain: project-only power to permanently block
// re-registration of a domain even after its grace period lapses.
// DeleteDomain destroys a domain and every name beneath it.
//
// THE VAULT PRIMITIVE EXISTED BEFORE THIS DID, AND THAT MADE IT
// UNREACHABLE. nsdata.DeleteDomainRecord gates on assertIsTrustedLogic,
// so the only way to reach it is a function in this realm — and there
// was not one. The capability shipped in the vault and could not be
// used, which is worse than not shipping it, because it reads as
// present.
//
// Bounded by the vault at maxDeletePerCall names per call. It returns
// how many it removed and whether it finished, so a large domain is
// several calls rather than a transaction that cannot fit in a block.
// Repeat until done is true; calling it on a domain that is already gone
// reports done rather than panicking, so a loop terminates cleanly.
//
// ADMIN ONLY, and deliberately not owner-callable: domains are
// project-owned (SPEC.md §17b) and this destroys other people's names.
func DeleteDomain(cur realm, label string) (removed int64, done bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	return nsdata.DeleteDomainRecord(cross(cur), label)
}

// SetDomainTTL sets how long a resolver may cache answers about this
// domain, in seconds, where 0 means never cache — the ENS rule. Admin
// only, since domains are project-owned.
func SetDomainTTL(cur realm, label string, seconds int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if seconds < 0 {
		panic("nslogic: ttl may not be negative")
	}
	if err := nsdata.SetDomainTTLRecord(cross(cur), label, seconds); err != nil {
		panic(err)
	}
}

func FreezeDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, true)
}

func UnfreezeDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, false)
}

package nslogic

import (
	"strconv"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
THE FREE TIER: a name somebody can hold without ever owning a wallet.

The vault has supported this since it was written — RegisterNameRecord
takes mintNFT=false and stores a record with no GRC-721 token, and
UpgradeFreeRecord is described there as "the paid free-tier upgrade".
Nothing in the logic realm ever reached either. This is that wiring.

WHY A RECORD WITHOUT A TOKEN IS THE RIGHT SHAPE, and not a compromise:

	IT IS A REAL NAME. Owned, resolvable, renewable, on chain, visible
	to anyone. Not a promise, not a queue position, not a row in our
	database. Everything the paid tier does except be sold.

	IT CANNOT BE SOLD, and that is what makes giving it away safe.
	nsmarket escrows a TOKEN, and there is no token — so a squatter who
	farms a thousand of these has farmed a thousand things nobody can
	buy from them. The anti-abuse property falls out of the data model
	rather than out of a rule somebody has to enforce.

	IT BECOMES SELLABLE BY BECOMING PAID. UpgradeFreeName takes the full
	list price and mints the token. So the same name costs nothing and
	costs full price, and which one depends entirely on whether you want
	to sell it.

WHY THE PROJECT PAYS. The whole point is somebody with no GNOT, and
possibly no wallet, who is going to put this name in front of an
audience. Measured on Pearl: a registration is about 0.04 GNOT of fee
plus a small storage deposit, and a free-tier record is smaller than a
paid one because there is no token and no ledger entry. That is a
marketing cost per name, bounded by a daily cap we apply off chain,
where it can be changed without a deploy.

WHAT IS DELIBERATELY NOT HERE. No wordlist: storage is 100 ugnot a byte,
so a ten-thousand-word dictionary is about 57 GNOT paid forever to
encode a marketing decision that will change. The contract carries the
structural rules in reserved.gno and nothing else; the lists live off
chain with the issuer, which is us, because the free path is granted
rather than bought. See tools/gen-reserved.py.
*/

const (
	keyFreeDomain = "free"     // per-domain: "1" means the free tier is open here
	keyGrantEnd   = "grantend" // global: unix seconds, or "never"
	keyGranter    = "granter"  // global: the address allowed to issue grants
)

/*
THE GRANTER IS NOT THE ADMIN, and that separation is the point.

Free names are issued by a machine — something has to sign the grant
after a person proves an X account, and that key has to sit somewhere
warm. If that key were the admin key, a compromise of the issuing
machine would be a compromise of the registry: DeleteDomain destroys
every name under a domain and burns their tokens, instantly, with no
timelock.

So there is a second role that can do exactly one thing. Worst case for
a stolen granter key is that somebody gives away free names until we
notice and clear the role — a bounded, reversible, embarrassing loss
rather than an unbounded one.

Stored in the vault's globals rather than in this realm, so it survives
a logic redeploy. Unset means nobody but the admin may grant, which is
the right default for a role that exists to be delegated deliberately.
*/
func Granter() address {
	return address(nsdata.GetGlobal(keyGranter))
}

// SetGranter delegates grant issuance, or withdraws it. Passing the
// empty address is the revocation, and it is the first thing to reach
// for if the issuing machine is ever in doubt.
func SetGranter(cur realm, a address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if a != "" && !a.IsValid() {
		panic("nslogic: not an address")
	}
	setGlobal(cur, keyGranter, a.String())
}

/*
SetFreeLengths tunes which lengths the free tier will issue.

In the panel rather than in a redeploy: nslogic is about 22 GNOT to
deploy, and "should four-character names be free this month" is a
marketing question that should cost a signature, not a deployment.

IT DOES NOT REACH BACKWARDS. Raising the minimum stops NEW issuance of
short names; every one already granted stays granted and keeps renewing
free. FreeLabelAllowed is called by GrantFreeName and by nothing else,
which is what makes that true — see the note on it in reserved.gno.
*/
func SetFreeLengths(cur realm, min, max int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if min < 1 || max > 63 || min > max {
		panic("nslogic: a free-tier length range must sit inside 1..63 and be the right way round")
	}
	setGlobal(cur, keyFreeMin, strconv.Itoa(min))
	setGlobal(cur, keyFreeMax, strconv.Itoa(max))
}

func assertMayGrant(cur realm) {
	caller := cur.Previous().Address()
	if caller == nsdata.GetAdmin() {
		return
	}
	g := Granter()
	if g == "" || caller != g {
		panic("nslogic: only the admin or the granter may issue free names")
	}
}

// DomainFree reports whether a domain accepts free-tier registrations.
// Off by default, and per-domain on purpose: the free tier is a
// promotion aimed at a few domains, not a property of the registry.
func DomainFree(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyFreeDomain) == "1"
}

// SetDomainFree opens or closes the free tier for one domain.
func SetDomainFree(cur realm, domainLabel string, on bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: no such domain")
	}
	v := ""
	if on {
		v = "1"
	}
	if err := nsdata.SetDomainExtraRecord(cross(cur), domainLabel, keyFreeDomain, v); err != nil {
		panic(err)
	}
}

/*
GrantWindowOpen reports whether free grants are being issued at all.

A single global switch that closes everything at once, because the
failure this guards against is not a clever attack — it is noticing on a
Sunday that something is wrong and wanting one call that stops it. An
unset value means open; "never" means open with no end date, which is
what the admin panel already writes.
*/
func GrantWindowOpen() bool {
	return readGrantWindow(nsdata.GetGlobal(keyGrantEnd), time.Now().Unix())
}

// readGrantWindow is GrantWindowOpen with the clock and the stored value
// handed in, so the reading can be tested without a chain.
func readGrantWindow(v string, now int64) bool {
	if v == "" || v == "never" {
		return true
	}
	end, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		// An unparseable window is a misconfiguration, and the safe
		// reading of a misconfigured gate is "closed". Giving names away
		// because a setting was mistyped is the wrong way to fail.
		return false
	}
	return now < end
}

/*
GrantFreeName registers a free-tier record to somebody else.

ADMIN OR GRANTER, and that is the whole trust model: the eligibility rules —
which Twitter account, how old, how many followers, whether the label is
a dictionary word — live off chain with the issuer. Putting them here
would freeze a marketing policy into a realm and cost storage to do it.
What the chain enforces is the part that must not depend on our
correctness: the label is structurally allowed, the domain opted in, and
the window is open.

`owner` may be an address the recipient generated in their browser
seconds ago and has never funded. That is the point.
*/
func GrantFreeName(cur realm, label, domainLabel string, owner address) {
	assertNoSend(cur)
	assertMayGrant(cur)

	if !GrantWindowOpen() {
		panic("nslogic: free grants are closed")
	}
	if !DomainFree(domainLabel) {
		panic("nslogic: *" + domainLabel + " does not offer free names")
	}
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	validateLabel(label)
	assertNotBlocked(label)
	// The structural backstop. The issuer has already applied the full
	// policy; this is what stops a bug there giving away a four-letter
	// name or a pure-numeric one.
	if !FreeLabelAllowed(label) {
		panic("nslogic: " + label + " is not available on the free tier")
	}
	if !owner.IsValid() {
		panic("nslogic: a grant needs a recipient")
	}

	// paid=false — a token minted with the free-tier hold already on it,
	// so it can never be approved or sold until UpgradeFreeName lifts it.
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, owner,
		time.Now().Unix(), false); err != nil {
		panic(err)
	}
}

/*
UpgradeFreeName mints the token for a free-tier record, at full price.

This is the only way a free name becomes sellable, and the price is the
ordinary list price with no referral discount — a discount is for
bringing somebody new, and this person is already here.

`newOwner` exists because the common case is somebody who has decided to
sell and, in the same moment, wants the name in a wallet they actually
control rather than the browser key they were given. The vault handles
that move inside UpgradeFreeRecord.

Callable by the record's current owner only. Anyone may PAY for
somebody else's upgrade in the sense that they can hand over the money,
but they cannot perform it — a stranger promoting your name into a token
and choosing where it lands is a theft with a receipt.
*/
func UpgradeFreeName(cur realm, label, domainLabel string, newOwner address) {
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: this name has expired")
	}
	if newOwner == "" {
		newOwner = caller
	}
	if !newOwner.IsValid() {
		panic("nslogic: invalid destination address")
	}

	// Full list price, resolved now rather than at grant time — the
	// name's worth is what it is worth today, and a free name held for a
	// year should not be upgradable at last year's rate.
	takePaymentSplit(cur, NamePrice(domainLabel, label), "", 0)

	if err := nsdata.UpgradeFreeRecord(cross(cur), label, domainLabel, newOwner); err != nil {
		panic(err)
	}
}

/*
GrantFreeRenewal extends a free-tier name at no charge.

THE DEAL IS THE DISPLAY, and it is checked off chain: the issuer signs
somebody in on X, reads their display name, and finds the name in it.
That single act proves both halves at once — that a real account still
exists, and that it is still carrying the name — which is why renewal is
one click a year rather than a form.

FREE-TIER RECORDS ONLY. A paid name renewed for nothing is revenue given
away by accident, and the two are told apart by whether a token was ever
minted — now, whether the token still carries the free-tier hold. The
hold is the registry's flag, read through GetNameInfo's `paid`.

NO OWNERSHIP PROOF IS ASKED FOR, and that is deliberate rather than
missing. Renewing somebody else's name is a GIFT — it takes nothing,
moves nothing, and grants the caller no power over it. The only cost of
allowing it is ours, and the vault's renewal cap already bounds how far
any single name can be pushed. A proof requirement here would buy
nothing and would cost the one-click renewal that makes the deal work.

RenewNameRecord insists the caller is the owner, so the owner is looked
up and passed. That is not a bypass: this realm is the trusted logic,
and what it is asserting is exactly true — this renewal is on that
owner's behalf.
*/
func GrantFreeRenewal(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertMayGrant(cur)

	if !nsdata.NameExists(label, domainLabel) {
		panic("nslogic: no such name")
	}
	owner, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel)
	if paid {
		panic("nslogic: " + label + "*" + domainLabel +
			" is a paid name — free renewal is for free-tier records")
	}
	if RenewalsLeft(label, domainLabel) <= 0 {
		panic("nslogic: this name is already paid as far ahead as a name may run")
	}
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, owner,
		time.Now().Unix()); err != nil {
		panic(err)
	}
}

// IsFreeTier reports whether a name is a record without a token — the
// free tier. Exported because the site and the issuer both need to ask
// before offering a free renewal, and neither should infer it.
func IsFreeTier(label, domainLabel string) bool {
	if !nsdata.NameExists(label, domainLabel) {
		return false
	}
	_, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel)
	return !paid
}

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Answering "what does this address hold" in ONE read.
//
// The site used to ask the chain for every name in the REGISTRY and then
// throw away the ones that did not match — one HTTP round trip per name
// in the world to draw one person's collection. Six names took three
// seconds, and it gets linearly worse for everybody every time anybody
// else registers anything.
//
// The scan itself is unavoidable: nsdata keys names by domain*label and
// has no index by owner, and nsdata is the permanent vault so no index
// can be added to it now. But the scan does not have to happen across
// the network. nslogic is swappable and can walk the same records inside
// a single query, which turns N round trips into one.
//
// Nothing is cached and nothing is trusted from the caller: every row is
// read from the vault at the moment of the query, exactly as before.
//
// Paged, because a query has a gas ceiling of its own and a registry
// with fifty thousand names in it must not become one enormous read that
// nobody can complete. `after` is the vault's own cursor, so paging here
// is the same paging ExportNames already does.
const maxHoldingsPage = 200

// NamesOwnedBy returns rows of `label*domain,registered,expires,streak,frozen`
// separated by ";", plus the cursor to continue from. Labels are
// restricted to [a-z0-9-] so neither separator can appear inside a field.
//
// `next` is empty when the scan has reached the end of the registry. It
// is NOT empty merely because this page found no matches: a page of two
// hundred names belonging to other people returns no rows and a cursor,
// and the caller keeps going.
func NamesOwnedBy(owner address, after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	var b strings.Builder
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		// The tree key is domain*label; the token ID is label*domain.
		at := strings.Index(key, "*")
		if at < 0 {
			continue
		}
		domainLabel, label := key[:at], key[at+1:]

		o, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
		if o != owner {
			continue
		}
		if b.Len() > 0 {
			b.WriteString(";")
		}
		b.WriteString(ufmt.Sprintf("%s*%s,%d,%d,%d,%t",
			label, domainLabel, registered, expires, streak, frozen))
	}
	return b.String(), nxt
}

// CountNamesOwnedBy is the same walk without the strings, for a header
// that wants a number before the list has finished arriving.
func CountNamesOwnedBy(owner address, after string, limit int) (n int, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		at := strings.Index(key, "*")
		if at < 0 {
			continue
		}
		if nsdata.GetNameOwner(key[at+1:], key[:at]) == owner {
			n++
		}
	}
	return n, nxt
}

// Everything the profile page draws, in ONE read.
//
// It was making seventeen queries: three to establish that the name
// exists and when it expires, then fourteen more — one per extension
// slot — that could not start until the first three had come back. Two
// waves, and the node serves only a few at a time, so a profile took
// seconds to assemble out of values that all live in the same record.
//
// Values come back in the ORDER THE KEYS WERE ASKED FOR rather than as
// key=value pairs. An extension key is allowed to contain "=" (only
// commas and newlines are forbidden), so a pair encoding would have an
// ambiguous split; positional has none.
//
// Line 0 is the record: owner, registered, expires, streak, frozen, and
// the grace period, which is global but is one more query the page would
// otherwise have to make on its own.
//
// An empty return means the name is not registered. That is a real
// answer rather than an error: asking about a name nobody owns is the
// normal case on a profile URL somebody typed.
func ProfileOf(label, domainLabel, keys string) string {
	if !nsdata.NameExists(label, domainLabel) {
		return ""
	}
	owner, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("%s,%d,%d,%d,%t,%d",
		owner.String(), registered, expires, streak, frozen, nsdata.GetGracePeriod()))

	for _, k := range strings.Split(keys, ",") {
		b.WriteString("\n")
		if k == "" {
			continue
		}
		v := nsdata.GetNameExtra(label, domainLabel, k)

		// THE GNO.LAND ADDRESS ANSWERS EVEN WHEN NOBODY SAVED ONE.
		//
		// A name is an NFT held by an address, so the owner is already
		// public — it is the first field of the record above. Returning
		// it here as well costs no storage and means a name can be paid
		// without its holder ever having opened a profile editor, which
		// is most of them, and without a transaction to back-fill the
		// ones registered before this existed.
		//
		// Doing it in the realm rather than in the website is the whole
		// point: any client asking this realm for the gno key gets the
		// same answer our pages do. A front end that derived it locally
		// would leave every other reader with nothing.
		//
		// "off" is the opt-out, and it has to be a sentinel. An empty
		// value is indistinguishable from never having set one, so an
		// empty gno field would simply hand the derived address back on
		// the next read.
		if k == "gno" {
			if v == "off" {
				v = ""
			} else if v == "" {
				v = owner.String()
			}
		}
		b.WriteString(escapeValue(v))
	}
	return b.String()
}

// Extension VALUES are free text — a bio can hold anything a person can
// type, newlines included — so they cannot be newline-separated raw.
// Escaping is done here rather than stripping, because silently eating a
// line break out of somebody's bio is data loss on a read path.
func escapeValue(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, "\n", `\n`)
	return strings.ReplaceAll(s, "\r", `\r`)
}

// RecentNames answers "what has just been registered" in one read.
//
// The site used to build this by listing every key and then reading each
// record one at a time — the same shape NamesOwnedBy replaced for a
// wallet's holdings, and the same problem: fine at thirteen names, one
// query per name forever after. A feed that gets slower every time
// somebody registers is a feed that eventually stops loading on the busy
// day you most wanted it.
//
// Returns rows of "label*domain,registered,expires,owner", newest first,
// and a cursor. Sorting happens across a PAGE, not the whole registry:
// the vault stores names alphabetically and there is no index by date,
// so a caller that wants the true newest reads every page and merges.
// That is one query per 200 names instead of one per name — enough of a
// difference to stop mattering, without pretending the vault has an
// index it does not have.
func RecentNames(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	type row struct {
		text string
		at   int64
	}
	var found []row
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		// The tree key is domain*label; the token ID is label*domain.
		at := strings.Index(key, "*")
		if at < 1 {
			continue
		}
		domainLabel, label := key[:at], key[at+1:]
		owner, registered, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
		found = append(found, row{
			text: ufmt.Sprintf("%s*%s,%d,%d,%s", label, domainLabel, registered, expires, owner.String()),
			at:   registered,
		})
	}

	// Insertion sort, newest first. The page is at most 200 entries and
	// gno has no sort in scope here; anything cleverer would be more code
	// than the problem deserves.
	for i := 1; i < len(found); i++ {
		v := found[i]
		j := i - 1
		for j >= 0 && found[j].at < v.at {
			found[j+1] = found[j]
			j--
		}
		found[j+1] = v
	}

	var b strings.Builder
	for _, r := range found {
		if b.Len() > 0 {
			b.WriteString(";")
		}
		b.WriteString(r.text)
	}
	return b.String(), nxt
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
BACKDATED NAMES, ON A REAL CHAIN, WITHOUT A BACKDOOR.

THE PROBLEM. Every expiry rule here is a function of a date, and every
date in this registry is a few weeks old. Live, in grace, and lapsed past
recovery are three different sets of behaviour — what renders, what can
be sold, what can be reclaimed, what the marketplace refuses — and only
the first has ever been seen. Waiting a year to find out is not a test
plan, and finding out on mainnet a year after launch is the outcome this
exists to prevent.

WHY NOT RestoreNames. Because it refuses, and it is right to. OpenRestore
panics on a populated vault:

    if d, n, _, _ := nsdata.Sizes(); d != 0 || n != 0 { panic(...) }

That guard was added for a specific reason recorded in restore.gno —
RestoreNameField can write any extension key on any EXISTING name, which
includes the payment addresses a name's pay page renders, and that is a
way to redirect somebody's incoming money with only the admin key. The
door is shut on any chain that holds records. It should stay shut, and
wanting test data is not a reason to widen it.

WHAT THIS IS INSTEAD. One function that moves an expiry, and it refuses
to touch anything outside a single domain that the admin has explicitly
nominated as the lab. Set no lab domain and this realm cannot move an
expiry at all — which is the state mainnet ships in, and the state it
stays in unless somebody deliberately changes it and says so on chain.

WHY THAT IS ENOUGH OF A GUARD. The admin can already deploy a logic realm
that does anything, so this grants no power that did not exist. What it
buys is that the power is NAMED, SCOPED and VISIBLE: LabDomain() is a
public read, so anybody can check that no lab is set, and every name this
can reach is under one extension that everybody can see and that
DeleteDomain removes in a call.

THE LAB DOMAIN IS NOT SPECIAL TO THE VAULT. It is an ordinary domain,
registered the ordinary way. Nothing about a name under it is fake — the
records, the artwork, the marketplace, the grace arithmetic are all the
real thing. The only unusual act is an admin moving a date, which is the
one thing a testnet cannot do by waiting.
*/

const keyLab = "labdomain"

// LabDomain is the domain that SetLabExpiry may touch, or "" when there
// is none — which must be the case on mainnet. A public read, so the
// claim above is checkable by anybody rather than asserted here.
func LabDomain() string { return nsdata.GetGlobal(keyLab) }

// SetLabDomain nominates a domain as the lab, or clears it with "".
//
// The domain must already exist, so the nomination cannot be made
// speculatively against a name somebody registers later.
func SetLabDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	label = strings.TrimSpace(label)
	if label == "" {
		setGlobal(cur, keyLab, "")
		return
	}
	if !nsdata.DomainExists(label) {
		panic("nslogic: no such domain — register it before nominating it as the lab")
	}
	setGlobal(cur, keyLab, label)
}

/*
SetLabExpiry moves one name's expiry to an absolute unix time.

It refuses outside the lab domain, and it refuses when no lab is set. The
two checks are separate on purpose: an empty lab must not match an empty
domain argument and quietly become a wildcard.

An expiry may be set into the past — that is the entire point. What it
may not be is before the name was registered, because that is not a state
the ordinary rules can produce and testing against an impossible record
teaches nothing.
*/
func SetLabExpiry(cur realm, label, domainLabel string, expires int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)

	lab := LabDomain()
	if !labScopeOK(lab, domainLabel) {
		if lab == "" {
			panic("nslogic: no lab domain is set; SetLabDomain first, and never on mainnet")
		}
		panic("nslogic: " + domainLabel + " is not the lab domain (" + lab + ")")
	}
	if !nsdata.NameExists(label, domainLabel) {
		panic("nslogic: no such name — register it first, then move its date")
	}
	_, registered, _, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	if !labDateOK(registered, expires) {
		panic("nslogic: that would expire the name before it was registered, " +
			"which the ordinary rules cannot produce")
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
}

// The scoping rule, alone and testable. Kept as its own function
// because the two conditions must stay SEPARATE: folded into one, an
// unset lab would match an unnamed domain and the guard becomes a
// wildcard pointing at every name in the registry.
func labScopeOK(lab, domainLabel string) bool {
	if lab == "" {
		return false
	}
	return domainLabel == lab
}

// An expiry may be in the past — that is the point — but not before the
// name existed, which is not a state the ordinary rules can produce.
func labDateOK(registered, expires int64) bool {
	return expires > 0 && expires >= registered
}

// SetLabExpiryDays is the form a script actually wants: days from now,
// negative for the past. "expired eleven days ago" is a sentence; the
// unix time it corresponds to is not, and computing it in bash is how a
// test set ends up quietly one day out.
func SetLabExpiryDays(cur realm, label, domainLabel string, days int64) {
	SetLabExpiry(cur, label, domainLabel, time.Now().Unix()+days*86400)
}

/*
LabReport answers, for every name in the lab, what the registry thinks
its state is RIGHT NOW — read from the same GetGracePeriod the rest of
the realm uses rather than recomputed here.

It exists because the interesting failures are disagreements: the card
says lapsed, the marketplace still lists it, the reclaim path still
refuses. One line per name, so a script can diff what the chain believes
against what the site drew.

	label,expires,daysLeft,state
*/
func LabReport() string {
	lab := LabDomain()
	if lab == "" {
		return ""
	}
	now := time.Now().Unix()
	grace := nsdata.GetGracePeriod()

	var out []string
	after := ""
	for {
		keys, next := nsdata.ExportNames(lab, after, 200)
		if keys == "" {
			break
		}
		for _, k := range strings.Split(keys, ",") {
			k = strings.TrimSpace(k)
			if k == "" {
				continue
			}
			// THE STORAGE KEY IS domain*label, the reverse of a token id.
			// This has been got backwards more than once in this project.
			star := strings.Index(k, "*")
			if star < 0 {
				continue
			}
			label := k[star+1:]
			_, _, expires, _, _, _ := nsdata.GetNameInfo(label, lab)
			state := "LIVE"
			switch {
			case now >= expires+grace:
				state = "LAPSED"
			case now >= expires:
				state = "GRACE"
			}
			out = append(out, label+","+strconv.FormatInt(expires, 10)+","+
				strconv.FormatInt((expires-now)/86400, 10)+","+state)
		}
		if next == "" || next == after {
			break
		}
		after = next
	}
	return strings.Join(out, ";")
}

package nslogic

import (
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Profile field names inside a name's extension slot. The vault stores
// them as opaque strings and bounds their size; what they MEAN is this
// realm's convention, so new profile fields need no vault change.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
	keyAvatar      = "avatar"
)

// RegisterName mints `label*domain` under an existing domain. Anyone may
// call this. Minting still works while the parent domain is past its own
// due date, as long as its grace period hasn't fully lapsed and it isn't
// frozen — nsdata's RegisterNameRecord enforces that.
func RegisterName(cur realm, label, domainLabel string) {
	registerName(cur, label, domainLabel, "")
}

// RegisterNameRef is RegisterName with a referral code — the NAME of
// whoever sent the buyer here, as it appears in the link.
//
// It is a second entry point rather than a third argument on the first
// one because the first one is already deployed and already being called
// by wallets and by the site. Changing its arity would break every one
// of those callers at the same instant, which is exactly the failure the
// voting realm produced last time; adding a function breaks nothing and
// lets the front end pick whichever the deployed realm actually has.
//
// A code that does not resolve — misspelt, lapsed, or the buyer's own
// name — is IGNORED, not rejected. The registration goes through at
// list price. Refusing to sell somebody a name because they mistyped
// somebody else's would be an absurd way to lose a sale.
func RegisterNameRef(cur realm, label, domainLabel, refName string) {
	registerName(cur, label, domainLabel, refName)
}

func registerName(cur realm, label, domainLabel, refName string) {
	validateLabel(label)
	assertNotBlocked(label)
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	caller := cur.Previous().Address()

	// Resolved BEFORE anything is written, so the tier and the discount
	// are read from the world the buyer was quoted in. Registering first
	// would change the buyer's own primary name and, on a self-referral
	// that slipped through, their tenure with it.
	ref := resolveReferrer(refName, caller)
	price := NamePrice(domainLabel, label)
	if ref != "" {
		if pct := tierPercent(RefDiscountRules(), TenureYears(ref)); pct > 0 {
			price -= price * pct / 100
		}
	}
	payTo, cut := referralCut(ref, price)
	takePaymentSplit(cur, price, payTo, cut)

	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, caller, time.Now().Unix(), true); err != nil {
		panic(err)
	}

	// Written after the record exists, because the extension slot is
	// created by registration. Only recorded when the cut was actually
	// paid: a referrer who earned nothing on the sale has no claim on
	// the renewals either, and storing them would say otherwise.
	if ref != "" && cut > 0 {
		setExtra(cur, label, domainLabel, keyRef, ref.String())
		creditReferral(cur, ref)
	}
}

// RenewName — same anchoring rule as RenewDomain: extends from the
// previous due date, not from the payment date. Deliberately does not
// call validateLabel — an already-registered name must keep renewing
// under whatever pattern was in force when it was minted.
func RenewName(cur realm, label, domainLabel string) {
	// No new code is accepted here and none is needed: the referrer was
	// fixed into this name when it was registered, and renewals keep
	// paying them for as long as the name survives unbroken. If it
	// lapses or is sold the vault destroys the record's extras, so the
	// link ends without this realm having to notice.
	//
	// Renewals pay the FULL price. The discount was a reason to arrive;
	// it is not a permanent lower rate, and compounding it every year
	// would make the referred name cheaper forever than the same name
	// bought directly.
	assertRoomToRenew(label, domainLabel)
	price := NamePrice(domainLabel, label)
	ref := ReferrerOf(label, domainLabel)
	payTo, cut := referralCut(ref, price)
	takePaymentSplit(cur, price, payTo, cut)

	caller := cur.Previous().Address()
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
	if cut > 0 {
		creditReferral(cur, ref)
	}
}

// SetProfile writes the four conventional profile fields. Each lands in
// the name's extension slot, where the vault enforces size bounds.
func SetProfile(cur realm, label, domainLabel, displayName, bio, website, avatar string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	setExtra(cur, label, domainLabel, keyDisplayName, displayName)
	setExtra(cur, label, domainLabel, keyBio, bio)
	setExtra(cur, label, domainLabel, keyWebsite, website)
	setExtra(cur, label, domainLabel, keyAvatar, avatar)
}

// SetNameField writes a single arbitrary key — cross-chain addresses and
// anything else a future feature needs, with no vault change required.
// Keys used by this realm's own machinery are reserved.
func SetNameField(cur realm, label, domainLabel, key, value string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	// `ref` decides who gets paid out of every renewal of this name. A
	// holder who could write it would set it to an address they control
	// and take a permanent cut of their own renewals out of the
	// treasury — so the one key that moves money is the one key its
	// owner may not touch.
	if key == keyRef {
		panic("nslogic: '" + keyRef + "' is set at registration and cannot be edited")
	}
	setExtra(cur, label, domainLabel, key, value)
}

func setExtra(cur realm, label, domainLabel, key, value string) {
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic(err)
	}
}

func assertNameOwner(cur realm, label, domainLabel string) {
	if nsdata.GetNameOwner(label, domainLabel) != cur.Previous().Address() {
		panic("nslogic: restricted to name owner")
	}
}

// SetPrimaryName lets a wallet explicitly choose (and later change) which
// of its names is used for reverse resolution.
func SetPrimaryName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if err := nsdata.SetPrimaryRecord(cross(cur), caller, label, domainLabel); err != nil {
		panic(err)
	}
}

/*
ClearPrimaryName switches reverse resolution OFF for the caller.

WHY THIS HAS TO EXIST, and it is a hole rather than a feature request.

nsdata sets the reverse pointer AUTOMATICALLY on a wallet's first
registration — RegisterNameRecord does it, and nothing asked the person
first. From that moment their address answers with their name, so anybody
who sees that address anywhere can find the persona attached to it, and
every transaction it has ever made becomes attributable. Retroactively:
the chain is permanent and indexers keep copies.

And until now there was NO WAY OUT. ClearPrimaryRecord is gated to
trusted logic, and no logic realm exposed it, so the one person the
pointer is about could not remove it. A name service is a bridge between
a persona and a wallet; publishing that bridge without consent and
without an exit is the worst version of it.

This is the exit. It takes no arguments on purpose: a wallet has exactly
one reverse pointer, and the only address it can clear is its own, so
there is nothing to pass and nothing to get wrong.

WHAT IT DOES NOT DO, said plainly because a promise we cannot keep would
be worse than the hole: clearing stops FUTURE lookups. It does not
unpublish what was already visible, and it cannot — the history is on
chain and other people have copies. The honest sequence is to choose
before publishing, which is why the site now shows what the link exposes
before it offers to make it.
*/
func ClearPrimaryName(cur realm) {
	assertNoSend(cur)
	nsdata.ClearPrimaryRecord(cross(cur), cur.Previous().Address())
}

// SetNameTTL is the owner's cache policy for their own name, in
// seconds, where 0 MEANS NEVER CACHE — copied from the ENS registry so
// integrators need not read anything of ours to handle it.
//
// The owner sets it rather than the registry because only they know the
// risk: a name being used to receive payments wants 0, since a cached
// answer after a sale pays the previous owner; a name used as a display
// handle can safely be cached for a long time.
func SetNameTTL(cur realm, label, domainLabel string, seconds int64) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if seconds < 0 {
		panic("nslogic: ttl may not be negative")
	}
	if err := nsdata.SetNameTTLRecord(cross(cur), label, domainLabel, seconds); err != nil {
		panic(err)
	}
}

func FreezeName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
}

func UnfreezeName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, false)
}

// -- resolution --

func ResolveName(label, domainLabel string) address {
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: name is expired")
	}
	return nsdata.GetNameOwner(label, domainLabel)
}

// ResolveAddress performs reverse resolution: address -> name.
//
// It must verify the ownership it is asserting, not merely that the
// pointed-at name exists and is unexpired. nsdata's `primary` tree is a
// record of what an address last SELECTED, not proof of what it still
// owns — and although nsdata now clears the pointer on transfer and
// reclaim, this check is the half that lives in the swappable realm and
// therefore stays correct even against pointers written by an older
// version of the logic. Without it, an address that sold or lost a name
// kept reverse-resolving to it, impersonating the new owner.
func ResolveAddress(addr address) string {
	tid := nsdata.GetPrimary(addr)
	if tid == "" {
		return ""
	}
	label, domainLabel := splitTokenID(tid)
	if !nsdata.IsNameValid(label, domainLabel) {
		return ""
	}
	if nsdata.GetNameOwner(label, domainLabel) != addr {
		return ""
	}
	return tid
}

// splitTokenID splits a `label*domain` token ID.
func splitTokenID(tid string) (label, domainLabel string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

package nslogic

import (
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// This realm only exposes the WRITE side of the GRC-721 surface. Reads
// (BalanceOf, OwnerOf, TokenURI, GetApproved, IsApprovedForAll, and
// every listing/status/profile query) have no authorization check to
// perform and are served directly by nsdata — no reason to duplicate
// them here.

func isDomainToken(tid string) bool {
	return strings.HasPrefix(tid, "*")
}

// isTokenValid checks the underlying domain/name's expiry via nsdata's
// own validity reads — the anti-scam pattern (an expired name must not
// be sellable) enforced at the transfer boundary, not just at read time.
func isTokenValid(tid string) bool {
	if isDomainToken(tid) {
		return nsdata.IsDomainValid(tid[1:])
	}
	label, domainLabel := splitTokenID(tid)
	return nsdata.IsNameValid(label, domainLabel)
}

// assertNotFrozen is the check that made freezing mean something.
//
// FreezeName set a bit that only ever gated RE-REGISTRATION after a
// lapse. Transfer, approval, listing and sale all ignored it, so the one
// manual lever the takedown process relies on did nothing about the case
// it exists for: a disputed or stolen name could be approved to a fresh
// wallet, listed and sold while the interface showed it as frozen.
//
// The bit was already stored and already readable — GetNameInfo returns
// it — so this needs no change to the permanent vault, only the read
// that was never performed.
func assertNotFrozen(tid string) {
	label, domainLabel := splitTokenID(tid)
	_, _, _, _, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
	if frozen {
		panic("nslogic: this name is frozen and cannot be transferred or approved")
	}
}

/*
THERE ARE NO TRANSFER OR APPROVAL FUNCTIONS HERE ANY MORE.

Approve, SetApprovalForAll, TransferFrom and SafeTransferFrom lived in this
realm, and they could only work while this realm was the one place a
transfer could happen. In this generation ownership is in nsnft, and nsnft
sees whoever calls it as the caller — so a logic realm calling in on a
user's behalf would be refused as not approved, correctly. A logic realm
that COULD move people's tokens would be a logic realm that could steal
them.

So: holders approve and transfer on nsnft directly, and marketplaces —
ours included — settle as approved operators there.

The two policies these wrappers enforced moved to where they bind every
path, not just ours:
  - frozen names: a hold bit on the token in nsnft (nsdata.SetNameFrozen)
  - free-tier names: a hold bit set at mint (nsdata.RegisterNameRecord)
Expired names are refused by our marketplace and never resolve; an
external marketplace can move an expired token, as with any NFT. See
MIGRATION.md, second attempt, rule 6.

The helpers above stay because the marketplace-facing reads use them.
*/

package nslogic

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// takePayment verifies the attached send-envelope covers `price` ugnot,
// forwards the price to the treasury, and refunds any overpayment to the
// caller in the same transaction. Nothing is ever retained: every ugnot
// that arrives leaves again, as either payment or refund.
//
// It used to take a `beneficiary` and split the price fee/remainder,
// routing the remainder to treasury only while `beneficiary == admin`.
// That comparison was a proxy for "is this a project-owned domain", and
// it silently broke the moment `admin` rotated — the planned EOA-to-
// multisig step — because a domain's owner is frozen into its record at
// registration time. After a rotation, every registration's remainder
// would have been paid to the retired key instead of the treasury, with
// no error and no log line.
//
// The heuristic is gone rather than patched. Domains are admin-only to
// create and permanently non-transferable, so every domain is
// project-owned by construction and 100% of every payment belongs to the
// treasury. `platformFeeBps` stays in nsdata's config for a future logic
// realm that reintroduces third-party domain ownership; reinstating the
// split is then a logic-realm swap, not a migration.
func takePayment(cur realm, price int64) {
	takePaymentSplit(cur, price, "", 0)
}

// takePaymentSplit is takePayment with a referrer's cut carved out of the
// same price. The buyer pays exactly what they were quoted; the cut is
// not added on top, it is a share of what the treasury would otherwise
// have received.
//
// All three legs settle inside the buyer's own transaction — treasury,
// referrer, refund — so this realm's balance is the same after the call
// as before it. That is not a stylistic preference: holding a referrer's
// cut until they claim it would make this an account you can have a
// balance in, and that is a different kind of thing to operate, subject
// to a different set of rules, run by people with licences. The cut is
// paid now or it is not paid.
func takePaymentSplit(cur realm, price int64, cutTo address, cut int64) {
	if !cur.Previous().IsUserCall() {
		panic("nslogic: only direct wallet calls may attach payment")
	}
	caller := cur.Previous().Address()
	sent := unsafe.OriginSend()
	assertOnlyUgnot(sent)

	paid := sent.AmountOf(ugnot)
	if paid < price {
		panic(ufmt.Sprintf("nslogic: insufficient payment: need %d ugnot, got %d", price, paid))
	}
	excess := paid - price

	// Belt and braces. referralCut already caps the percentage, but this
	// is the line where the arithmetic becomes money leaving an address,
	// and a bug upstream must not be able to pay out more than came in.
	if cut < 0 || cut > price || cutTo == "" {
		cut = 0
	}

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	pkgAddr := cur.Address()
	if cut > 0 {
		b.SendCoins(pkgAddr, cutTo, chain.Coins{chain.NewCoin(ugnot, cut)})
	}
	if price-cut > 0 {
		b.SendCoins(pkgAddr, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, price-cut)})
	}
	if excess > 0 {
		b.SendCoins(pkgAddr, caller, chain.Coins{chain.NewCoin(ugnot, excess)})
	}
}

// assertOnlyUgnot rejects any other denomination outright. Only the
// ugnot amount was ever accounted for, and neither realm has a
// withdrawal path, so a foreign coin sent alongside a payment would have
// been stranded in this realm's address permanently. Refusing the whole
// transaction is simpler than sweeping it back and keeps the
// "this realm never retains funds" invariant absolute.
func assertOnlyUgnot(sent chain.Coins) {
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nslogic: only ugnot is accepted, got: " + c.Denom)
		}
	}
}

// assertNoSend guards every entry point that has no price. Without it,
// coins attached to a free call (a renewal of a project domain, a
// profile edit, an admin setter) would land in this realm's address with
// no way back out.
//
// IT APPLIES TO DIRECT WALLET CALLS ONLY, and that qualification is not
// a loosening — it is the guard finally matching its own reason.
//
// OriginSend() reports what the TRANSACTION carried, not what this call
// received. Measured on sapphire-1 with a pair of probe realms: a user
// attaches 500000ugnot to realm A, A calls realm B, and B's OriginSend()
// reads 500000ugnot even though every one of those coins is sitting in
// A's address. B never saw them and cannot strand them.
//
// So for a realm-to-realm call this was rejecting a payment this realm
// never received. It is the reason a marketplace could not transfer a
// name inside the same transaction that pays for it — the transfer is a
// free call, the transaction is not, and the two are unrelated. A
// two-transaction sale is the alternative, and that means somebody's
// money or somebody's name sitting somewhere in between. Not here.
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return // the coins went to whoever called us, not to us
	}
	if !unsafe.OriginSend().IsZero() {
		panic("nslogic: this function takes no payment; do not attach coins")
	}
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Global pricing layers that sit ACROSS every domain rather than inside
// one — see SPEC.md §27.
//
// Two of them, and they work at different points:
//
//	GLOBAL LENGTH RULES are a FLOOR beneath each domain's own length
//	rules, consulted only when the domain has nothing to say about that
//	length. "three-character names cost $5 everywhere" becomes one entry
//	instead of an edit to all twenty-seven domains, and a domain that
//	wants its own answer still overrides it.
//
//	GLOBAL NAME PREMIUMS are an ADJUSTMENT applied after the price has
//	already resolved. Making `og` premium is one entry covering
//	`og*degen`, `og*meme` and every domain invented later. Deliberately
//	not the per-name override, which REPLACES a price outright: "this
//	name costs exactly X here" and "this name is worth more everywhere"
//	are different tools and both are worth having.
//
// Full order, most specific first:
//
//  1. per-name override      (domain "nm")
//  2. per-domain length rule (domain "len")
//  3. global length rule     (global "glen")
//  4. domain base price      (domain "price")
//  5. global default         (global "defaultPrice")
//     then the global name premium modifies the result,
//     then any referral discount comes off what is left.
const (
	keyGlobalLens = "glen"    // global length rules
	keyPremium    = "premium" // premium1, premium2, ... see below

	// The vault caps an extension value at maxExtraValueLen (512 bytes),
	// which is roughly 40-60 premium entries. The list is therefore split
	// across numbered keys rather than pretending one will do; a list
	// that silently truncated at the 512th byte would drop exactly the
	// entries nobody checked.
	maxPremiumKeys = 8
)

// GlobalLengthRule returns the global rule for a label length, if any.
func GlobalLengthRule(n int) (string, bool) {
	return lookupRule(nsdata.GetGlobal(keyGlobalLens), strconv.Itoa(n))
}

// PremiumFor returns the raw modifier for a name across all premium
// keys, or "" when the name is not premium anywhere.
func PremiumFor(label string) string {
	for i := 1; i <= maxPremiumKeys; i++ {
		csv := nsdata.GetGlobal(keyPremium + strconv.Itoa(i))
		if csv == "" {
			continue
		}
		if v, ok := lookupRule(csv, label); ok {
			return v
		}
	}
	return ""
}

// applyPremium adjusts an already-resolved price.
//
// ZERO ALWAYS STAYS ZERO. A fixed "+$2.00" would otherwise silently undo
// a giveaway tier set months earlier, and a free tier that quietly stops
// being free is worse than never having offered one. This is decided
// explicitly rather than inherited from the percentage case happening to
// work out at zero.
//
// Forms: "%5" / "+%5" five percent more · "-%10" ten percent less ·
// "2.00" two dollars more · "-0.25" twenty-five cents less ·
// "=5.00" exactly five dollars, ignoring everything resolved above.
func applyPremium(mod string, price int64) int64 {
	mod = strings.TrimSpace(mod)
	if mod == "" || price <= 0 {
		return price
	}

	// "=X" replaces outright. Checked before the sign handling because
	// an exact price is not a delta and has no direction.
	if strings.HasPrefix(mod, "=") {
		v, ok := parseUSD(mod[1:])
		if !ok || v < 0 {
			return price
		}
		return v
	}

	neg := false
	switch {
	case strings.HasPrefix(mod, "-"):
		neg, mod = true, mod[1:]
	case strings.HasPrefix(mod, "+"):
		mod = mod[1:]
	}

	var delta int64
	if strings.HasPrefix(mod, "%") {
		pct, err := strconv.ParseInt(mod[1:], 10, 64)
		if err != nil || pct < 0 {
			return price
		}
		delta = price * pct / 100
	} else {
		v, ok := parseUSD(mod)
		if !ok || v < 0 {
			return price
		}
		delta = v
	}

	if neg {
		// A discount may take a name to free, but never below it: a
		// negative price would be a payout, and this realm never pays
		// anybody to register.
		if delta >= price {
			return 0
		}
		return price - delta
	}
	return price + delta
}

// parseUSD reads a human dollar figure — "2", "2.5", "2.50", "0.069" —
// into micro-USD. Written by hand rather than with floats: a float would
// make "0.07" cost a different number of micro-dollars depending on the
// platform, and prices must be exact.
func parseUSD(s string) (int64, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, false
	}
	whole, frac := s, ""
	if i := strings.IndexByte(s, '.'); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	if whole == "" {
		whole = "0"
	}
	w, err := strconv.ParseInt(whole, 10, 64)
	if err != nil || w < 0 {
		return 0, false
	}
	// Pad or truncate the fraction to exactly six digits of micro-USD.
	if len(frac) > 6 {
		frac = frac[:6]
	}
	for len(frac) < 6 {
		frac += "0"
	}
	var f int64
	if frac != "" {
		f, err = strconv.ParseInt(frac, 10, 64)
		if err != nil || f < 0 {
			return 0, false
		}
	}
	return w*microUSD + f, true
}

// SetGlobalLengthRules writes the project-wide length rules:
// "1:300000000,2:150000000,3:60000000" prices one, two and three
// character names everywhere a domain has not said otherwise.
//
// IT HAD NO SETTER UNTIL NOW, which meant the only way to write it was
// the generic SetGlobal escape hatch — straight past normalizeRules, so
// a typo stored fine and then vanished at lookup time, because
// lookupRule skips a malformed pair in silence. A pricing layer whose
// only writer cannot validate is a pricing layer that fails open.
func SetGlobalLengthRules(cur realm, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setGlobal(cur, keyGlobalLens, normalizeRules(rules, true))
}

// SetPremiumNames writes one page of the premium keyword list, 1-based.
// The list is paged because the vault caps an extension value at 512
// bytes; see maxPremiumKeys.
//
// Same gap as above: normalizePremiums existed and nothing exported
// called it.
func SetPremiumNames(cur realm, page int, csv string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if page < 1 || page > maxPremiumKeys {
		panic("nslogic: premium page must be 1-" + strconv.Itoa(maxPremiumKeys))
	}
	v := normalizePremiums(csv)
	if len(v) > 512 {
		panic("nslogic: premium page " + strconv.Itoa(page) +
			" is " + strconv.Itoa(len(v)) + " bytes; the vault caps a value at 512. Split it across pages.")
	}
	setGlobal(cur, keyPremium+strconv.Itoa(page), v)
}

// PremiumNames reads one page back, so the admin panel can show what is
// stored rather than what it last sent.
func PremiumNames(page int) string {
	if page < 1 || page > maxPremiumKeys {
		return ""
	}
	return nsdata.GetGlobal(keyPremium + strconv.Itoa(page))
}

// GlobalLengthRules returns the whole rule string, for the same reason.
func GlobalLengthRules() string { return nsdata.GetGlobal(keyGlobalLens) }

// normalizePremiums validates a premium list before storage. Same
// reasoning as normalizeRules: a malformed entry must never reach the
// vault, because every later lookup would carry it.
func normalizePremiums(csv string) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad premium, want name:modifier — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" || strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in premium — " + k)
		}
		if seen[k] {
			panic("nslogic: duplicate premium name — " + k)
		}
		if !validPremiumValue(v) {
			panic("nslogic: bad premium modifier for " + k + " — " + v)
		}
		seen[k] = true
		out = append(out, k+":"+v)
	}
	return strings.Join(out, ",")
}

func validPremiumValue(v string) bool {
	if v == "" {
		return false
	}
	if strings.HasPrefix(v, "=") {
		_, ok := parseUSD(v[1:])
		return ok
	}
	if strings.HasPrefix(v, "-") || strings.HasPrefix(v, "+") {
		v = v[1:]
	}
	if strings.HasPrefix(v, "%") {
		p, err := strconv.ParseInt(v[1:], 10, 64)
		return err == nil && p >= 0
	}
	_, ok := parseUSD(v)
	return ok
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Pricing lives here, not in the vault. The vault stores numbers as
// opaque strings and has no opinion about what they mean, so the whole
// model can be replaced by swapping this realm.
//
// PRICES ARE DENOMINATED IN USD, held as MICRO-USD (1 USD = 1_000_000)
// so fractions of a cent are expressible — a name that costs about a
// gumball needs that. Nothing is stored in ugnot: the chain's token is
// just the settlement rail, converted at payment time from a stored
// rate. Accepting a second token later is then only a second rate, not
// a second price list.
//
// PRECEDENCE — most specific wins:
//
//  1. per-name override      (keyNames: "420:5000000,gm:%500")
//  2. per-length rule        (keyLens:  "3:2000000,4:%150,5:0")
//  3. GLOBAL length rule     (global keyGlobalLens — see premium.gno)
//  4. domain base price      (keyPrice: "500000"  = $0.50)
//  5. global default         (global keyDefaultPrice)
//
// then the GLOBAL NAME PREMIUM adjusts the result, and a referral
// discount comes off last. Both live in premium.gno.
//
// A rule value is either an absolute micro-USD amount or "%N", meaning N
// percent of that domain's base — so repricing a domain once carries
// every relative rule under it. "0" means free, which is how giveaway
// tiers are expressed: "all five-character names under *pleb are free"
// is just a length rule resolving to zero.
//
// Rules are stored as CSV in ONE key each rather than one key per rule.
// The vault caps extension keys at 32 bytes and 24 entries per record; a
// key like "nm:somelongname" breaks the first and a few dozen premium
// names break the second. Two CSV keys sidestep both.
const (
	keyPrice        = "price" // domain base, micro-USD
	keyLens         = "len"   // length rules
	keyNames        = "nm"    // per-name overrides
	keyOpen         = "open"  // "0" closes the domain to new names
	keyDefaultPrice = "defaultPrice"
	keyRate         = "rateUgnotPerUsd" // ugnot equal to 1 USD

	microUSD         = int64(1_000_000)
	fallbackPriceUSD = int64(500_000) // $0.50
	// TESTNET PEG: $0.069 per GNOT, so 1 USD = 1/0.069 GNOT = 14.492753
	// GNOT = 14_492_753 ugnot. Deliberately a fixed number while we are on
	// a testnet whose token has no market price at all -- a "real" rate
	// there would be fiction dressed as precision. Replaced with a genuine
	// conversion before mainnet; tracked in MAINNET.md.
	fallbackRate = int64(14_492_753)
	maxRules     = 64
)

// DomainOpen reports whether names may currently be registered under a
// domain. An absent key means open — a domain created before this
// existed must not silently close.
func DomainOpen(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyOpen) != "0"
}

// -- USD side --

func DefaultPriceUSD() int64 {
	if v := nsdata.GetGlobal(keyDefaultPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return fallbackPriceUSD
}

func DomainBasePriceUSD(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return DefaultPriceUSD()
}

// NamePriceUSD resolves the four inputs in precedence order and returns
// micro-USD. This is the authoritative price; ugnot is derived from it.
func NamePriceUSD(domainLabel, label string) int64 {
	return applyPremium(PremiumFor(label), resolveBeforePremium(domainLabel, label))
}

// resolveBeforePremium runs steps 1-5. Separated from NamePriceUSD so
// the admin panel can show WHY a price is what it is: the figure before
// the premium and the figure after are both meaningful, and a single
// function returning only the total makes a wrong price impossible to
// diagnose.
func resolveBeforePremium(domainLabel, label string) int64 {
	base := DomainBasePriceUSD(domainLabel)
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyNames), label); ok {
		return applyRule(v, base)
	}
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyLens), strconv.Itoa(len(label))); ok {
		return applyRule(v, base)
	}
	// The global length rule is a floor, not a replacement: it applies
	// only where the domain itself had nothing to say about this length.
	if v, ok := GlobalLengthRule(len(label)); ok {
		return applyRule(v, base)
	}
	return base
}

// ExplainPriceUSD returns each stage of the resolution, so the control
// panel can show the arithmetic rather than assert a total. Returns the
// price before any premium, the premium modifier that applied (empty if
// none), and the final price.
func ExplainPriceUSD(domainLabel, label string) (beforePremium int64, modifier string, final int64) {
	before := resolveBeforePremium(domainLabel, label)
	mod := PremiumFor(label)
	return before, mod, applyPremium(mod, before)
}

// -- settlement side --

// RateUgnotPerUsd is how many ugnot one USD buys.
//
// This is a MANUALLY MAINTAINED rate, not a market oracle: an admin
// writes it and it sits there until rewritten. That is a real
// operational hazard — a stale rate during a sharp move sells names at
// the wrong price in whichever direction hurts — and the mitigation is
// keeping it fresh, not anything this code can do. Kept as one global so
// a future logic realm can swap in a real oracle without touching the
// vault or restating a single price.
func RateUgnotPerUsd() int64 {
	if v := nsdata.GetGlobal(keyRate); v != "" {
		if r, err := strconv.ParseInt(v, 10, 64); err == nil && r > 0 {
			return r
		}
	}
	return fallbackRate
}

// NamePrice converts the USD price to ugnot for settlement. Rounds UP,
// so rounding never sells a name below its listed price; a free name
// stays exactly free.
func NamePrice(domainLabel, label string) int64 {
	usd := NamePriceUSD(domainLabel, label)
	if usd <= 0 {
		return 0
	}
	rate := RateUgnotPerUsd()
	return (usd*rate + microUSD - 1) / microUSD
}

// -- rule plumbing --

func applyRule(v string, base int64) int64 {
	if strings.HasPrefix(v, "%") {
		pct, err := strconv.ParseInt(v[1:], 10, 64)
		if err != nil || pct < 0 {
			return base
		}
		return base * pct / 100
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil || n < 0 {
		return base
	}
	return n
}

func lookupRule(csv, want string) (string, bool) {
	if csv == "" {
		return "", false
	}
	for _, pair := range strings.Split(csv, ",") {
		parts := strings.SplitN(strings.TrimSpace(pair), ":", 2)
		if len(parts) != 2 {
			continue
		}
		if strings.TrimSpace(parts[0]) == want {
			return strings.TrimSpace(parts[1]), true
		}
	}
	return "", false
}

// normalizeRules validates and canonicalises a rule string before it is
// stored, so a malformed entry can never reach storage and poison every
// later lookup.
func normalizeRules(csv string, numericKeys bool) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad rule, want key:value — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" {
			panic("nslogic: empty rule key")
		}
		if numericKeys {
			if n, err := strconv.Atoi(k); err != nil || n <= 0 {
				panic("nslogic: length must be a positive number — got " + k)
			}
		} else if strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in rule — " + k)
		}
		if strings.HasPrefix(v, "%") {
			if p, err := strconv.ParseInt(v[1:], 10, 64); err != nil || p < 0 {
				panic("nslogic: bad percentage — " + v)
			}
		} else if n, err := strconv.ParseInt(v, 10, 64); err != nil || n < 0 {
			panic("nslogic: bad amount — " + v)
		}
		if seen[k] {
			panic("nslogic: duplicate rule key — " + k)
		}
		seen[k] = true
		out = append(out, k+":"+v)
		if len(out) > maxRules {
			panic("nslogic: too many rules (max 64)")
		}
	}
	return strings.Join(out, ",")
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// The referral programme.
//
// SINGLE LEVEL, ALWAYS. One buyer, one referrer, one cut, taken out of
// an actual sale. There is no downline, no override on somebody else's
// referrals, and no bonus for recruiting other referrers — and there is
// no code here that could be extended into one without being obvious
// about it. That is the line between an affiliate programme and the
// other thing, and this realm stays on the near side of it.
//
// WHERE THE LINK LIVES. The referrer is recorded on the REFERRED NAME,
// in its extension slot, at the moment it is registered. That placement
// does the work of two rules for free, because nsdata already destroys a
// name's extras when a lapsed name is re-registered (names.Remove, then
// a fresh record) and when a name changes hands (wipeOnHandover):
//
//	a name that lapses loses its referrer
//	a name that is sold loses its referrer
//
// Neither needs code to enforce. Both would need code to PREVENT.
//
// WHO GETS PAID. An address, not a name. The referrer's wallet is fixed
// into the referred name at registration, so they may let their own name
// go, buy a different one, or hold ten — the commission does not move.
// What they cannot do is leave: paying out requires the referrer to
// still hold at least one name, checked at payment time.
//
// A SKIPPED PAYOUT IS NOT A DEBT. If the referrer holds nothing when a
// renewal comes through, the cut is simply not taken — the buyer pays
// less and the treasury keeps the difference. Nothing accrues, because
// accruing would mean holding somebody else's money until they qualify,
// and this realm holds nobody's money at any point.
//
// SELF-REFERRAL IS REFUSED. Otherwise the informed apply their own code
// forever and the cut becomes a silent discount for people who read the
// source.
//
// EVERYTHING SETTLES IN ONE TRANSACTION. Buyer pays, treasury is paid,
// referrer is paid, overpayment goes back — all inside the message the
// buyer signed. No escrow, no float, not for a block.
const (
	keyRef     = "ref"     // on a NAME: the referrer's address
	keyRefCut  = "refcut"  // global: tier table, referrer's percentage
	keyRefDisc = "refdisc" // global: tier table, buyer's discount
	keyRefStat = "ref:"    // global, per address: how many referred
	keyRefWin  = "refwin"  // global: days a captured code stays valid

	maxRefPercent = 50 // a cut plus a discount above this stops being a business
)

// -- tier tables --

// A tier table reads like the length rules do: "0:5,2:8,5:12" means five
// percent from the start, eight once the referrer has held a name two
// years, twelve at five. The highest tier at or below their tenure wins,
// so gaps are fine and the table never has to be exhaustive. An empty
// table means the programme pays nothing, which is also how it is
// switched off.
func tierPercent(spec string, years int64) int64 {
	best := int64(0)
	bestAt := int64(-1) // the threshold of the tier `best` came from
	for _, part := range strings.Split(spec, ",") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) != 2 {
			continue
		}
		at, err1 := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64)
		pct, err2 := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err1 != nil || err2 != nil || at < 0 || pct < 0 {
			continue
		}
		if pct > maxRefPercent {
			pct = maxRefPercent
		}
		/* THE HIGHEST TIER THAT APPLIES, not the biggest number in the
		   table. This compared percentages, so a table where a later
		   tier pays LESS — the shape a taper needs, and the shape the
		   buyer-discount table is most likely to take — silently paid
		   the earlier, larger rate forever. Tracking the tier's
		   threshold instead makes the table mean what it reads as. */
		if years >= at && at >= bestAt {
			bestAt = at
			best = pct
		}
	}
	return best
}

// THE PRESET THE PROJECT LAUNCHES WITH.
//
// The referrer's CUT starts at five percent and gains five for each year
// they have held their name, reaching thirty at five years and above.
// The buyer's DISCOUNT starts at five and gains one a year, to ten. The
// two tables deliberately climb at different rates: what a referrer earns
// should reward standing still for years, while what a buyer saves should
// stay a nudge rather than becoming the reason to buy.
//
// It is written here rather than typed into the admin panel at launch for
// one reason: a number that exists only in somebody's memory of a
// conversation is a number that gets set wrong once and noticed a month
// later.
//
// THE SUM IS WHAT LEAVES THE TREASURY, and SetReferralRules refuses a
// pair above fifty percent at any tier either table mentions. This pair
// peaks at forty, at five years: thirty to the referrer, ten off the
// price. That is the number to look at when either table is edited — not
// the two columns separately.
//
// SIX STEPS because the panel shows six, and a table the panel cannot
// display is a table nobody will edit correctly. The last one is the
// "and above" tier: tierPercent takes the highest step at or below the
// referrer's tenure, so five years and fifty both pay ten.
//
// It is a DEFAULT, not a policy. SetReferralRules overwrites it and an
// empty table still means the programme pays nothing, which is how it is
// switched off — seeding must never take that away.
const (
	defaultRefCut      = "0:5,1:10,2:15,3:20,4:25,5:30"
	defaultRefDiscount = "0:5,1:6,2:7,3:8,4:9,5:10"
)

// DefaultReferralRules lets the site show what the presets are before
// anybody commits them, so the panel can offer them as a starting point
// instead of asking somebody to remember six numbers.
func DefaultReferralRules() (cut, discount string) {
	return defaultRefCut, defaultRefDiscount
}

// SeedReferralRules writes the presets, and ONLY into an empty table.
//
// Deliberately not an init(). This realm writes through nsdata, which
// refuses a writer it does not yet trust, and at init time a freshly
// deployed logic realm has not been granted that trust — so an init()
// would either panic the deploy or, worse, be silently skipped and leave
// the operator believing the defaults were applied.
//
// Refusing to overwrite is what makes it safe to call twice, and safe to
// call by mistake: it can restore a launch default, and it can never
// quietly undo a rate somebody chose on purpose.
func SeedReferralRules(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if nsdata.GetGlobal(keyRefCut) != "" || nsdata.GetGlobal(keyRefDisc) != "" {
		panic("nslogic: referral rules are already set; use SetReferralRules to change them")
	}
	SetReferralRules(cur, defaultRefCut, defaultRefDiscount)
}

func RefCutRules() string      { return nsdata.GetGlobal(keyRefCut) }
func RefDiscountRules() string { return nsdata.GetGlobal(keyRefDisc) }

// RefWindowDays is how long a clicked link keeps counting for. It is
// enforced by the browser that captured the code, not by this realm —
// the chain never sees the click, only the registration that quotes a
// code — so it is stored here purely to be ONE number rather than a
// constant baked separately into the site, the FAQ and the rules page.
// Zero means the default; the site treats an absent value the same way.
func RefWindowDays() int64 {
	d := parseInt64(nsdata.GetGlobal(keyRefWin))
	if d <= 0 {
		return 30
	}
	return d
}

func SetReferralWindow(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if days < 0 || days > 3650 {
		panic("nslogic: window must be 0-3650 days")
	}
	setGlobal(cur, keyRefWin, strconv.FormatInt(days, 10))
}

// ReferralQuote is what a code is worth, answered before anybody signs
// anything. One call rather than four, because the site needs all of it
// at once to show a price and every extra round trip is a moment where
// the number on screen is not the number the chain will charge.
//
// A referrer of "" means the code did not resolve, and the two
// percentages are then both zero.
func ReferralQuote(refName string, buyer address) (referrer address, tenure, discountPct, cutPct int64) {
	ref := resolveReferrer(refName, buyer)
	if ref == "" {
		return "", 0, 0, 0
	}
	years := TenureYears(ref)
	cut := int64(0)
	// The cut is zero for a referrer holding nothing, and saying so up
	// front is better than showing a percentage that silently will not
	// be paid when the transaction lands.
	//
	// ResolveAddress, NOT BalanceOf — the same test referralCut applies
	// when it actually pays. BalanceOf counts a lapsed name that nobody
	// has reclaimed yet (and, since every name became a token, free-tier
	// names too), so the quote promised a cut the payout then refused.
	if ResolveAddress(ref) != "" {
		cut = tierPercent(RefCutRules(), years)
	}
	return ref, years, tierPercent(RefDiscountRules(), years), cut
}

// SetReferralRules replaces both tier tables at once, because setting one
// without the other is how a cut ends up larger than the margin. Passing
// two empty strings turns the programme off: no discount, no commission,
// and registrations stop writing a referrer at all.
func SetReferralRules(cur realm, cutSpec, discountSpec string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	cut := normalizeTiers(cutSpec)
	disc := normalizeTiers(discountSpec)
	// The two are paid out of the same list price, so their sum is what
	// actually leaves the treasury. Checked at every tenure either table
	// mentions rather than only at tier zero, since the tables need not
	// step at the same points.
	for _, y := range tierYears(cut, disc) {
		if tierPercent(cut, y)+tierPercent(disc, y) > maxRefPercent {
			panic("nslogic: cut plus discount exceeds 50% at year " + strconv.FormatInt(y, 10))
		}
	}
	setGlobal(cur, keyRefCut, cut)
	setGlobal(cur, keyRefDisc, disc)
}

func tierYears(specs ...string) []int64 {
	var out []int64
	seen := map[int64]bool{}
	for _, spec := range specs {
		for _, part := range strings.Split(spec, ",") {
			kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
			if len(kv) != 2 {
				continue
			}
			if y, err := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64); err == nil && !seen[y] {
				seen[y] = true
				out = append(out, y)
			}
		}
	}
	if len(out) == 0 {
		out = append(out, 0)
	}
	return out
}

// normalizeTiers rejects a malformed table before it is stored, for the
// same reason normalizeRules does: a bad entry that reaches storage is
// then read silently and wrongly on every sale afterwards.
func normalizeTiers(spec string) string {
	if strings.TrimSpace(spec) == "" {
		return ""
	}
	var out []string
	seen := map[int64]bool{}
	for _, part := range strings.Split(spec, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		kv := strings.SplitN(part, ":", 2)
		if len(kv) != 2 {
			panic("nslogic: bad tier, want years:percent — got " + part)
		}
		y, err := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64)
		if err != nil || y < 0 || y > 100 {
			panic("nslogic: tier years must be 0-100 — got " + kv[0])
		}
		p, err := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err != nil || p < 0 || p > maxRefPercent {
			panic("nslogic: tier percent must be 0-50 — got " + kv[1])
		}
		if seen[y] {
			panic("nslogic: duplicate tier year — " + kv[0])
		}
		seen[y] = true
		out = append(out, strconv.FormatInt(y, 10)+":"+strconv.FormatInt(p, 10))
		if len(out) > 16 {
			panic("nslogic: too many tiers (max 16)")
		}
	}
	return strings.Join(out, ",")
}

// -- tenure --

// TenureYears is how long a wallet counts as having been here, measured
// from its PRIMARY name and nothing else.
//
// The honest alternative — the oldest name the wallet holds — means
// walking the whole registry on every quote, which is a read that gets
// slower every time somebody registers and eventually stops working.
// Primary is one lookup and never gets slower. It is also already the
// wallet's declared identity, it is set automatically at a wallet's first
// registration, and a holder who wants an older name counted only has to
// make it their primary. The site says so on the referral page.
//
// A lapsed or missing primary is zero years, not an error: tier zero.
func TenureYears(who address) int64 {
	/* RESOLVED, NOT READ RAW. GetPrimary reports what an address last
	   SELECTED, not what it still holds — and a sale on the token ledger
	   no longer clears the seller's pointer. So a seller kept the tenure of
	   a five-year name they had sold, and every referral through their
	   young name got the top discount tier, paid by the treasury. An audit
	   found it; ResolveAddress re-checks the owner and the expiry. */
	tid := ResolveAddress(who)
	at := strings.Index(tid, "*")
	if at < 1 {
		return 0
	}
	_, _, _, streak, _, _ := nsdata.GetNameInfo(tid[:at], tid[at+1:])
	return streak
}

// -- where it gets paid --

// Commissions go to the referring wallet. There is no way to redirect
// them, and that is a decision rather than an omission.
//
// There WAS a redirect — SetReferralPayout, "a forwarding address, not a
// transferable right". It does not survive the obvious question: how
// would this realm tell somebody moving money between their own two
// wallets from somebody who has sold the stream to a stranger? It
// cannot. Nothing on chain distinguishes those, and a rule that cannot
// be enforced is not a rule, it is a sentence in a document.
//
// What settled it is that the redirect did not even serve the case it
// was written for. Calling it required signing from the ORIGINAL wallet,
// so "I lost access to my wallet" was never covered; the only wallet
// that could redirect was one whose owner could equally have received
// the money and forwarded it. It gave nothing to the honest case and
// gave the shape of an assignable income stream to the other one.
//
// So the destination is the referrer's own address, fixed. Selling the
// entitlement now means handing over private keys, which is a deterrent
// no contract clause could match.
func PayoutFor(who address) address { return who }

// -- the record on a name --

// ReferrerOf reads the wallet credited with a name, or the empty address.
func ReferrerOf(label, domainLabel string) address {
	v := nsdata.GetNameExtra(label, domainLabel, keyRef)
	if a := address(v); v != "" && a.IsValid() {
		return a
	}
	return ""
}

// resolveReferrer turns a claimed referring NAME into the wallet to
// credit, or the empty address if the claim does not stand up. Every
// rejection is silent on purpose: a mistyped or self-referral should not
// fail somebody's registration, it should simply earn nobody anything.
func resolveReferrer(refName string, buyer address) address {
	at := strings.Index(refName, "*")
	if refName == "" || at < 1 || at == len(refName)-1 {
		return ""
	}
	label, domainLabel := refName[:at], refName[at+1:]
	if !nsdata.NameExists(label, domainLabel) || !nsdata.IsNameValid(label, domainLabel) {
		return "" // a lapsed name is not a working code
	}
	owner := nsdata.GetNameOwner(label, domainLabel)
	if owner == buyer {
		return "" // no referring yourself
	}
	return owner
}

// -- the money --

// PriceWithReferral is what a buyer actually pays given the code they
// arrived with. Exported so the site can display the number the chain
// will charge instead of computing its own and hoping they agree.
func PriceWithReferral(domainLabel, label, refName string, buyer address) int64 {
	price := NamePrice(domainLabel, label)
	if price <= 0 {
		return 0 // free is free, and a percentage of nothing is nothing
	}
	ref := resolveReferrer(refName, buyer)
	if ref == "" {
		return price
	}
	pct := tierPercent(RefDiscountRules(), TenureYears(ref))
	if pct <= 0 {
		return price
	}
	return price - (price * pct / 100)
}

// referralCut is what leaves for the referrer out of a payment of
// `price`, and is zero unless they still hold a name. Returns the
// destination address and the amount; the caller pays it in the same
// banker call that pays the treasury.
func referralCut(ref address, price int64) (address, int64) {
	if ref == "" || price <= 0 {
		return "", 0
	}
	/* STILL HERE, AND STILL VALID.
	   This tested nsdata.BalanceOf, which has no expiry filter — and a
	   token is burned only when somebody else re-registers the label. So
	   a referrer who bought one cheap name, earned credits and walked
	   away kept a balance of one forever, and every renewal of every
	   name they ever referred kept paying them out of treasury revenue.
	   That is exactly the standing charge the note above says the check
	   prevents.
	   ResolveAddress is the honest test: it returns a name only when the
	   address still owns it AND it has not expired. TenureYears does the
	   same lookup two lines below, so this costs nothing extra. */
	if ResolveAddress(ref) == "" {
		return "", 0
	}
	pct := tierPercent(RefCutRules(), TenureYears(ref))
	if pct <= 0 {
		return "", 0
	}
	cut := price * pct / 100
	if cut <= 0 {
		return "", 0
	}
	return PayoutFor(ref), cut
}

// -- the scoreboard --

// creditReferral records one paid referral against a wallet.
//
// The COUNT and nothing else. There was a running total of micro-USD
// beside it, and it is gone, because a number stored in the vault is a
// number anyone with an RPC endpoint can read — there is no such thing
// as an admin-only global on a public chain, and building the site as
// though there were would be the kind of privacy that works right up
// until somebody checks.
//
// Not storing it is the only real reduction available. The payments are
// still in the block history and always will be, so anyone determined
// can add them up; what we can decline to do is publish a convenient
// running total ourselves. tools/referrals.py reconstructs it from the
// chain when we want it, which costs no storage and publishes nothing.
//
// The registrant's transaction pays for this entry. It is about forty
// bytes, written once per referrer and overwritten after, and it is the
// price of the discount they just received.
func creditReferral(cur realm, ref address) {
	if ref == "" {
		return
	}
	setGlobal(cur, keyRefStat+ref.String(),
		strconv.FormatInt(ReferralCount(ref)+1, 10))
}

// ReferralCount is how many paid registrations a wallet has been
// credited with. Public, like every other global here.
func ReferralCount(who address) int64 {
	return parseInt64(nsdata.GetGlobal(keyRefStat + who.String()))
}

func parseInt64(s string) int64 {
	v, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		return 0
	}
	return v
}

// ReferralBoard pages through every credited wallet for the
// leaderboard: one "address,count" row per line. The vault stores
// globals in a sorted tree, so the "ref:" entries are one contiguous run
// and the walk stops at the first key past it rather than reading the
// rest of the config.
func ReferralBoard(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > 200 {
		limit = 200
	}
	from := keyRefStat
	if after != "" {
		from = keyRefStat + after
	}
	var out []string
	for len(out) < limit {
		keys, more := nsdata.ExportGlobalKeys(from, limit)
		if keys == "" {
			break
		}
		stop := false
		for _, k := range strings.Split(keys, ",") {
			if !strings.HasPrefix(k, keyRefStat) {
				stop = true
				break
			}
			addr := k[len(keyRefStat):]
			n := ReferralCount(address(addr))
			if n <= 0 {
				continue
			}
			out = append(out, addr+","+strconv.FormatInt(n, 10))
			if len(out) >= limit {
				next = addr
				break
			}
		}
		if stop || more == "" || more == from {
			break
		}
		from = more
	}
	return strings.Join(out, "\n"), next
}

package nslogic

import (
	"strconv"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// GENERATED BY tools/gen-reserved.py FROM collections/reserved-labels.json.
// Do not edit by hand: the site reads the same source, and a change made
// in one place only is a label the site offers and the chain refuses.
//
// STRUCTURAL RULES ONLY. The wordlists live off chain, in that JSON,
// because storage is 100 ugnot per byte and a ten-thousand-word
// dictionary is about 57 GNOT paid forever to encode a marketing
// decision that will change. This is the backstop against a bug in the
// issuer, not the place the policy lives.
//
// THE NUMBERS ARE SETTABLE, the shape is not. A minimum length is a
// promotion knob and belongs in the panel — redeploying this realm to
// change a 5 to a 4 costs about 22 GNOT. So the lengths read from the
// vault's globals and fall back to the values generated here; the
// pattern rules are structural facts about what a handle looks like and
// stay in code.

const (
	defaultFreeMinLength = 5
	defaultFreeMaxLength = 63

	keyFreeMin = "freemin"
	keyFreeMax = "freemax"
)

// FreeMinLength is the shortest label the free tier will issue. Settable
// from the panel, because which lengths are worth money is a commercial
// judgement that moves.
func FreeMinLength() int {
	if v := nsdata.GetGlobal(keyFreeMin); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 63 {
			return n
		}
	}
	return defaultFreeMinLength
}

func FreeMaxLength() int {
	if v := nsdata.GetGlobal(keyFreeMax); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 63 {
			return n
		}
	}
	return defaultFreeMaxLength
}

/*
FreeLabelAllowed reports whether a label may be ISSUED on the free tier.

ISSUED, and never renewed. This is called by GrantFreeName and by
nothing else, deliberately: if the minimum length rises from three to
five, somebody who already holds a three-character free name keeps it
and keeps renewing it free. Tightening a rule must not reach backwards
and take away what was already given — that is the single fastest way to
make a giveaway cost more trust than it ever bought.

A name that LAPSES and is registered again is a new issuance, and gets
whatever the rules say that day. That is not retroactive; it is a
different name event.
*/
func FreeLabelAllowed(label string) bool {
	n := len(label)
	if n < FreeMinLength() || n > FreeMaxLength() {
		return false
	}
	// Pure digits: 1337, 420, years. Collectible, and no handle is one.
	digits := true
	for i := 0; i < n; i++ {
		if label[i] < '0' || label[i] > '9' {
			digits = false
			break
		}
	}
	if digits {
		return false
	}
	// aaaa — every character the same.
	same := true
	for i := 1; i < n; i++ {
		if label[i] != label[0] {
			same = false
			break
		}
	}
	if same {
		return false
	}
	// abab — a two-character cycle. Also collectible, also not a handle.
	if n >= 4 {
		cycle := true
		for i := 2; i < n; i++ {
			if label[i] != label[i-2] {
				cycle = false
				break
			}
		}
		if cycle {
			return false
		}
	}
	return true
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
REBUILDING THE REGISTRY ON A NEW CHAIN.

WHY THIS EXISTS. gno.land replaces testnets rather than preserving them:
topaz-1 was superseded by sapphire-1 on twenty-four hours' notice and
every name registered on it went to zero. tools/snapshot.js keeps a
complete off-chain copy of the vault for exactly that morning. This is
the other half — the path that turns a snapshot back into a live
registry, so that people who paid for a name get that name back rather
than an apology.

THIS IS A BACKDOOR, AND IT IS TREATED AS ONE.

A function that can mint any name, to any address, with any registration
date, is precisely the thing that would make every name here worthless
if it could be reached whenever the admin felt like it. Ownership means
nothing if history is editable on demand. So the capability is not
merely admin-gated — admin-gated is what everything else here already
is, and it is not enough for this. It is a ONE-SHOT:

  - it starts closed, and on a chain where nothing needs restoring it is
    sealed immediately and can never be used at all;
  - opening it is a deliberate, separate, announced act with a deadline
    attached, so forgetting to close it is not the same as leaving it
    open forever;
  - sealing is IRREVERSIBLE. Sealed cannot be reopened. There is no
    argument that unseals it, including a good one;
  - it refuses to touch a name that already exists. It fills gaps in an
    empty registry; it cannot rewrite a live one.

WHERE THE SEAL LIVES, AND WHY IT IS NOT HERE. This realm holds no state
at all — that is the whole reason prices and names survive a logic
upgrade untouched. If the seal lived in this realm's variables it would
reset to "never opened" the moment a new generation was deployed, which
would make "irreversible" a lie with a two-hour shelf life. It lives in
the vault's global slot instead, so a new logic generation inherits a
seal it cannot talk its way out of.

WHAT THAT DOES AND DOES NOT GUARANTEE. It is a real barrier against
every accident and against this realm being reached later for something
it was not built for. It is not a barrier against the admin themselves,
who can deploy a further logic realm and have the vault trust it — but
that is already total control by definition, and no flag in a realm the
admin can replace was ever going to change it. What the seal gives is
the thing that actually matters in practice: the state is public, it is
checkable by anybody at any time through RestoreStatus, and moving it
backwards leaves a permanent trace on chain.

WHAT IT DELIBERATELY DOES NOT RESTORE. Marketplace listings and open
votes. Those live in their own realms, are intentions rather than facts,
and are re-creatable by the people who made them in one transaction
each. Re-materialising somebody's month-old asking price as though they
had just set it would be inventing a decision on their behalf.
*/

// The vault key holding the state of this whole mechanism.
const keyRestore = "restore"

// Restore states, stored as a string in the vault's global slot.
const (
	restoreNever  = ""       // never opened; the normal state forever
	restoreSealed = "sealed" // closed permanently; cannot be reopened
	restoreOpen   = "open:"  // followed by the unix second it lapses
)

// The longest a restore window may be left open. A restore is a day of
// work, not a season, and an unbounded window is just "open forever"
// spelled differently — the failure here is nobody remembering to seal
// it, so the deadline seals it for them.
const maxRestoreDays = 30

// RestoreStatus reports the state of the restore mechanism in a form a
// person can read, and is deliberately PUBLIC AND UNAUTHENTICATED.
// Anybody at all can check whether this registry currently has a door in
// it, without asking us and without trusting the answer we would give.
//
// Returns the state ("never", "open", "expired" or "sealed"), the unix
// second an open window lapses (0 otherwise), and how many records have
// been restored in the lifetime of this vault.
func RestoreStatus() (state string, deadline int64, restored int64) {
	st, d := readRestoreState(nsdata.GetGlobal(keyRestore), time.Now().Unix())
	return st, d, restoredCount()
}

// readRestoreState is the state machine on its own, with the clock passed
// in. Split out so the one piece of logic that decides whether the door
// is open can be tested exhaustively without a chain under it.
func readRestoreState(raw string, now int64) (state string, deadline int64) {
	switch {
	case raw == restoreSealed:
		return "sealed", 0
	case strings.HasPrefix(raw, restoreOpen):
		d, err := strconv.ParseInt(raw[len(restoreOpen):], 10, 64)
		if err != nil || d <= 0 {
			// An unparseable deadline is read as NO permission. The safe
			// reading of a door whose lock is broken is "shut" — a corrupt
			// value must never widen what somebody is allowed to do.
			return "sealed", 0
		}
		if now >= d {
			return "expired", d
		}
		return "open", d
	}
	return "never", 0
}

const keyRestoredCount = "restored"

func restoredCount() int64 {
	if v := nsdata.GetGlobal(keyRestoredCount); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			return n
		}
	}
	return 0
}

/*
THE RESERVED-KEY DOOR DOES NOT EXIST ON THE DEPLOYED VAULT, so these
writes go through the ordinary setter.

nsdata/v1 is live and permanent, and its SetGlobalRecord takes any key
with no reserved-key guard at all. The two-door design — a general setter
that refuses "restore"/"restored" plus SetReservedGlobalRecord for the
machinery — exists only in the local nsdata source, which can never be
deployed over a vault holding real records. Calling for a door that is
not in the wall does not fail at review; it fails at deploy, after the
deposit is spent.

So the seal is guarded in ONE place: setGlobal in admin.gno, which panics
on both keys. That is weaker than the intended belt-and-braces — a future
logic realm could drop the guard by forgetting it, and the vault would
not catch it — and it is the strongest version available on this chain.
Do not "restore" the reserved call: it will not link.
*/
func bumpRestored(cur realm, n int64) {
	nsdata.SetGlobalRecord(cross(cur), keyRestoredCount,
		strconv.FormatInt(restoredCount()+n, 10))
}

// assertRestoring is the gate every Restore* function passes through.
func assertRestoring(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	state, _, _ := RestoreStatus()
	switch state {
	case "open":
		return
	case "sealed":
		panic("nslogic: restore was sealed and cannot be reopened. This is " +
			"not recoverable by design — a registry whose history can be " +
			"rewritten on request does not have owners, it has guests.")
	case "expired":
		panic("nslogic: the restore window has lapsed. Deploy a fresh vault " +
			"and open a new window there; an expired one does not reopen.")
	}
	panic("nslogic: restore has never been opened. Call OpenRestore first, " +
		"and mean it.")
}

// OpenRestore opens the window, once, for a bounded number of days.
//
// Only ever valid on a chain where the registry is EMPTY because the
// previous chain was retired. It cannot be called on a vault that has
// been sealed, and it cannot be called twice.
func OpenRestore(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)

	state, _, _ := RestoreStatus()
	if state != "never" {
		panic("nslogic: restore may be opened exactly once per vault; this " +
			"one is already " + state + ". A door that reopens is a door.")
	}
	if days < 1 || days > maxRestoreDays {
		panic("nslogic: a restore window must be between 1 and " +
			strconv.Itoa(maxRestoreDays) + " days")
	}
	/* THE PRECONDITION THE COMMENT ABOVE ALREADY CLAIMS.
	   "Only ever valid on a chain where the registry is EMPTY" was a
	   statement of intent that nothing enforced, so the window was
	   openable on a populated vault. The record restorers all refuse an
	   existing record, but RestoreNameField does not — it writes any
	   extension key on any EXISTING name, which includes the payment
	   addresses the site renders on a name's pay page. That is a way to
	   redirect somebody else's incoming money using only the admin key,
	   without the timelock and public event that granting a fresh logic
	   realm would cost. Now it is what it said it was. */
	/* NAMES ONLY, not domains. A registry is now born with its domains
	   (genesis), so "no domains" can never be true again and the guard
	   would have made disaster recovery impossible on every new chain.
	   The hazard it exists for is RestoreNameField writing onto EXISTING
	   NAMES — somebody's pay address — and only names carry that. */
	if _, n, _, _ := nsdata.Sizes(); n != 0 {
		panic("nslogic: restore is for a registry holding no names yet; " +
			"this one already holds records")
	}
	deadline := time.Now().Unix() + days*86400
	nsdata.SetGlobalRecord(cross(cur), keyRestore,
		restoreOpen+strconv.FormatInt(deadline, 10))
}

// SealRestore closes the door permanently. Valid from any state,
// including "never" — which is how it should be called on a chain that
// has nothing to restore, so that the capability is provably dead rather
// than merely unused.
//
// There is no matching unseal, and adding one later would defeat every
// word written at the top of this file.
func SealRestore(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetGlobalRecord(cross(cur), keyRestore, restoreSealed)
}

/*
RestoreDomain re-creates one domain with its original dates.

ORDER MATTERS: domains before their names. The vault refuses to register
a name under a domain that does not exist or had lapsed at the moment
the name claims to have been registered, which is correct behaviour and
also exactly the order a snapshot should be replayed in.

The vault's own registration path sets `registered` to whatever instant
it is handed and derives the expiry from the term length, so the
registration date is restored by passing the ORIGINAL one, and the
expiry is then corrected to the recorded value rather than a computed
one. Anything else would quietly hand everybody a fresh term.
*/
func RestoreDomain(cur realm, label string, owner address, registered, expires, ttl int64, frozen bool) {
	assertRestoring(cur)
	if nsdata.DomainExists(label) {
		panic("nslogic: " + label + " already exists; restore fills an empty " +
			"registry and never overwrites a live record")
	}
	if registered <= 0 || expires <= 0 {
		panic("nslogic: a restored record needs its original dates")
	}
	if err := nsdata.RegisterDomainRecord(cross(cur), label, owner, registered); err != nil {
		panic("nslogic: " + err.Error())
	}
	nsdata.SetDomainExpiryRecord(cross(cur), label, expires)
	if ttl != 0 {
		if err := nsdata.SetDomainTTLRecord(cross(cur), label, ttl); err != nil {
			panic("nslogic: " + err.Error())
		}
	}
	if frozen {
		nsdata.SetDomainFrozen(cross(cur), label, true)
	}
	bumpRestored(cur, 1)
}

// RestoreName re-creates one name. See RestoreDomain on ordering and on
// why the dates are passed rather than computed.
//
// isNFT is carried across under its old name so snapshot blobs stay
// readable, and now means PAID: false restores a free-tier name with the
// hold on its token, so a restore can never quietly make a free name
// sellable.
func RestoreName(cur realm, label, domainLabel string, owner address, registered, expires, ttl int64, frozen, isNFT bool) {
	assertRestoring(cur)
	if nsdata.NameExists(label, domainLabel) {
		panic("nslogic: " + label + "*" + domainLabel + " already exists; " +
			"restore fills an empty registry and never overwrites a live record")
	}
	if registered <= 0 || expires <= 0 {
		panic("nslogic: a restored record needs its original dates")
	}
	// RestoreNameRecord, not RegisterNameRecord: it ADOPTS a token the
	// ledger already holds, which is the whole point of a migration —
	// records move, tokens do not. If the ledger's holder is not the
	// snapshot's owner, the record is written for the holder and the
	// snapshot's profile is not replayed onto it.
	if err := nsdata.RestoreNameRecord(cross(cur), label, domainLabel, owner, registered, isNFT); err != nil {
		panic("nslogic: " + err.Error())
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
	if ttl != 0 {
		if err := nsdata.SetNameTTLRecord(cross(cur), label, domainLabel, ttl); err != nil {
			panic("nslogic: " + err.Error())
		}
	}
	if frozen {
		nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
	}
	bumpRestored(cur, 1)
}

/*
RestoreNames replays many names in ONE transaction.

WHY A BLOB AND NOT A LOOP OF CALLS. A restore is done in one sitting
against a clock: the window is bounded and the people whose names are
missing are watching. One transaction per name is one signature per
name, and at a few hundred names that is an afternoon of clicking during
which a single mistimed refresh loses the thread. The compact form here
is unpleasant to read and it is the difference between a restore that
gets finished and one that gets abandoned half way.

The format is records separated by "|", fields separated by ",":

	label,domain,owner,registered,expires,ttl,frozen,isNFT

Neither a label nor a domain may contain "," or "|" — the character set
is enforced at registration — and an address contains neither, so the
split is unambiguous. tools/snapshot.js writes the JSON this is built
from; see tools/restore-blob.js for the conversion.

It stops at the first bad record and panics, taking the whole
transaction with it. That is deliberate: a partial batch that silently
skipped four names would leave four people without theirs and nothing
anywhere saying which four.
*/
func RestoreNames(cur realm, blob string) int {
	assertRestoring(cur)
	if blob == "" {
		panic("nslogic: nothing to restore")
	}
	recs := strings.Split(blob, "|")
	if len(recs) > 50 {
		panic("nslogic: at most 50 records per call, or the transaction " +
			"runs out of gas half way and it is unclear what landed")
	}
	done := 0
	for i, rec := range recs {
		if rec == "" {
			continue
		}
		r := parseRestoreRecord(rec, i)
		if nsdata.NameExists(r.label, r.domain) {
			panic("nslogic: record " + strconv.Itoa(i) + " (" + r.label + "*" + r.domain +
				") already exists; restore never overwrites a live record")
		}
		if err := nsdata.RestoreNameRecord(cross(cur), r.label, r.domain, r.owner, r.registered, r.isNFT); err != nil {
			panic("nslogic: record " + strconv.Itoa(i) + ": " + err.Error())
		}
		nsdata.SetNameExpiryRecord(cross(cur), r.label, r.domain, r.expires)
		if r.ttl != 0 {
			if err := nsdata.SetNameTTLRecord(cross(cur), r.label, r.domain, r.ttl); err != nil {
				panic("nslogic: record " + strconv.Itoa(i) + ": " + err.Error())
			}
		}
		if r.frozen {
			nsdata.SetNameFrozen(cross(cur), r.label, r.domain, true)
		}
		done++
	}
	bumpRestored(cur, int64(done))
	return done
}

// restoreRec is one parsed line of the blob.
type restoreRec struct {
	label, domain string
	owner         address
	registered    int64
	expires, ttl  int64
	frozen, isNFT bool
}

/*
parseRestoreRecord reads one record and refuses anything it is not sure
about.

EVERY CHECK HERE IS A PANIC AND NOT A SKIP. The blob is machine-written
from a snapshot, so a malformed record does not mean "this one name is
odd", it means the file is not what it was believed to be — and the
worst outcome available is a restore that appears to succeed while
quietly dropping the records it could not read. Somebody would find out
months later when one person asked where their name went.
*/
func parseRestoreRecord(rec string, i int) restoreRec {
	f := strings.Split(rec, ",")
	if len(f) != 8 {
		panic("nslogic: record " + strconv.Itoa(i) + " has " +
			strconv.Itoa(len(f)) + " fields, expected 8 " +
			"(label,domain,owner,registered,expires,ttl,frozen,isNFT)")
	}
	if f[0] == "" || f[1] == "" {
		panic("nslogic: record " + strconv.Itoa(i) + " has no name")
	}
	out := restoreRec{
		label:      f[0],
		domain:     f[1],
		owner:      address(f[2]),
		registered: mustSecs(f[3], i, "registered"),
		expires:    mustSecs(f[4], i, "expires"),
		ttl:        mustSecs(f[5], i, "ttl"),
		frozen:     f[6] == "1",
		isNFT:      f[7] == "1",
	}
	if !out.owner.IsValid() {
		panic("nslogic: record " + strconv.Itoa(i) + " has an invalid owner address")
	}
	if out.registered <= 0 || out.expires <= 0 {
		panic("nslogic: record " + strconv.Itoa(i) + " is missing its original dates")
	}
	// An expiry before the registration is not a record, it is a
	// corruption, and restoring it would create a name that was already
	// reclaimable the day it was bought.
	if out.expires < out.registered {
		panic("nslogic: record " + strconv.Itoa(i) + " expires before it was registered")
	}
	return out
}

func mustSecs(s string, i int, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v < 0 {
		panic("nslogic: record " + strconv.Itoa(i) + " has a bad " + what)
	}
	return v
}

// RestoreNameField and RestoreDomainField put back a record's extension
// keys — profiles, cross-chain addresses, tier markers, and a domain's
// pricing rules. Separate calls because the extension slot has no fixed
// shape by design, which is the same reason the snapshot captures it by
// enumeration rather than by schema.
func RestoreNameField(cur realm, label, domainLabel, key, value string) {
	assertRestoring(cur)
	/* ONLY ONTO A RECORD A RESTORE WROTE, AND ONLY FOR ITS HOLDER.

	   Profile fields include pay addresses, so replaying one is replaying
	   where money goes. Two audit findings meet here: a name sold between
	   the snapshot and the restore would have had the seller's addresses
	   written onto the buyer's name, and a name a user registered DURING
	   the restore window could have had its pay fields rewritten with the
	   admin key alone. RestoredFor is set only by RestoreNameRecord, and
	   only when the ledger's holder matched the snapshot.

	   Skipped rather than panicked, deliberately: a blob of fields rides in
	   one transaction, and one sold name must not abort everybody else's
	   restore. tools/restore-blob.js reads the fields back afterwards. */
	rf := nsdata.RestoredFor(label, domainLabel)
	if rf == "" || nsdata.GetNameOwner(label, domainLabel) != rf {
		return
	}
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

func RestoreDomainField(cur realm, label, key, value string) {
	assertRestoring(cur)
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestoreGlobal puts back the vault's global slot — where the default
// price, the referral tiers and the seasonal card effects live.
//
// It refuses to write the restore keys themselves. Without that, a
// snapshot taken while a window was open would, on being replayed,
// cheerfully restore the open window along with everything else — and a
// seal that a backup file can undo is not a seal.
func RestoreGlobal(cur realm, key, value string) {
	assertRestoring(cur)
	if key == keyRestore || key == keyRestoredCount {
		panic("nslogic: the restore mechanism does not restore itself")
	}
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestorePrimary puts back reverse resolution — which name an address
// answers to. Registration already sets this for an owner who had none,
// so this exists for the owners who had chosen a different one.
func RestorePrimary(cur realm, owner address, label, domainLabel string) {
	assertRestoring(cur)
	if err := nsdata.SetPrimaryRecord(cross(cur), owner, label, domainLabel); err != nil {
		panic("nslogic: " + err.Error())
	}
}

package nslogic

import (
	"strconv"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// How far ahead a name may be paid.
//
// Renewal was unbounded. RenewNameRecord adds one term to the previous
// due date and asks no further questions, so a holder pressing renew
// seven times bought seven years of runway, and nothing anywhere said
// that was not intended. It is a bug in two directions at once:
//
//   - Free domains have a base price of zero. Renewal is free too, so a
//     script could take every good name under *gnoland and hold it for a
//     century for the cost of gas. There is no economic brake on a free
//     name at all; the term limit IS the brake.
//   - A paid name held fifty years ahead is fifty years of a promise we
//     have made against a rate written by hand and a testnet that will
//     be replaced. Selling that is easy and honouring it is not.
//
// The limit is RUNWAY, not total lifetime: at most N years may be
// outstanding at any moment. Nobody is stopped from holding a name
// forever — they renew as the runway burns down, which is the same
// arrangement every domain registrar has always used and the one people
// already understand.
//
// Per domain first, then a project-wide default, so a free domain can be
// capped at one year without capping anything else.
const (
	keyMaxTerm      = "maxterm" // domain extra AND global: years of runway
	defaultMaxTerm  = int64(5)
	maxMaxTermYears = int64(100)
)

// MaxTermYears is the cap that applies to names under this domain.
func MaxTermYears(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyMaxTerm); v != "" {
		if y, err := strconv.ParseInt(v, 10, 64); err == nil && y > 0 {
			return y
		}
	}
	if v := nsdata.GetGlobal(keyMaxTerm); v != "" {
		if y, err := strconv.ParseInt(v, 10, 64); err == nil && y > 0 {
			return y
		}
	}
	return defaultMaxTerm
}

// SetMaxTerm caps a single domain, or the whole project when the domain
// label is empty. A domain's own cap always wins, so tightening one free
// domain does not disturb the rest.
func SetMaxTerm(cur realm, domainLabel string, years int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if years < 1 || years > maxMaxTermYears {
		panic("nslogic: term cap must be 1-100 years")
	}
	v := strconv.FormatInt(years, 10)
	if domainLabel == "" {
		setGlobal(cur, keyMaxTerm, v)
		return
	}
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: unknown domain")
	}
	if err := nsdata.SetDomainExtraRecord(cross(cur), domainLabel, keyMaxTerm, v); err != nil {
		panic(err)
	}
}

// RenewalsLeft is how many more years may be added to a name right now.
// Zero means the renew button should be off, and the site reads this
// rather than doing the arithmetic itself — the cap can be per domain,
// and a page that guesses it will guess wrong on exactly the domains
// where it matters.
//
// An unregistered name reports the full allowance: nothing is holding
// runway yet.
func RenewalsLeft(label, domainLabel string) int64 {
	maxYears := MaxTermYears(domainLabel)
	if !nsdata.NameExists(label, domainLabel) {
		return maxYears
	}
	term := nsdata.GetTermLength()
	if term <= 0 {
		return 0
	}
	_, _, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	return renewalsLeft(expires, time.Now().Unix(), term, maxYears)
}

// renewalsLeft is the arithmetic on its own, so it can be tested without
// a chain under it.
//
// Runway is measured from NOW, not from the registration date, so a name
// deep in its grace period counts as zero rather than as a negative that
// would then read as extra room. Years already bought round UP: a name
// with thirteen months left is holding two of its five, because the
// alternative lets somebody sit permanently at four-years-and-eleven-
// months and renew every month forever.
func renewalsLeft(expires, now, term, maxYears int64) int64 {
	if term <= 0 {
		return 0
	}
	runway := expires - now
	if runway < 0 {
		runway = 0
	}
	left := maxYears - (runway+term-1)/term
	if left < 0 {
		return 0
	}
	return left
}

// assertRoomToRenew is the enforcement. It runs before payment is taken,
// so a rejected renewal costs gas and nothing else — taking the money
// first and reverting would work too, but only because a panic reverts,
// and depending on that for a refund is a habit that eventually meets a
// path where it is not true.
func assertRoomToRenew(label, domainLabel string) {
	if RenewalsLeft(label, domainLabel) > 0 {
		return
	}
	panic(ufmt.Sprintf(
		"nslogic: %s*%s is already paid %d years ahead, which is the limit. Renew again when it has run down.",
		label, domainLabel, MaxTermYears(domainLabel)))
}

// Package nslogic is the swappable "business rules" half of the split
// (NOTES.md §9t). It holds every piece of policy that might reasonably
// change — pricing, character validation, payment/refund, freeze rules,
// transfer restrictions — and no persistent records of its own.
//
// Every mutation here ends by calling into nsdata's narrow Record/Raw
// API via cross(cur). nsdata trusts whichever address is currently wired
// up as trustedLogic to have done its own authorization checks
// correctly, so THIS realm is where "is the caller allowed to do this"
// actually lives. If a bug is found here, admin deploys a fixed nslogic
// and re-points the vault at it (ProposeTrustedLogicGrant, then
// ExecutePending after the timelock) — no data migration,
// records and config untouched.
//
// Deliberately reads config fresh from nsdata on every call rather than
// caching it. The one thing that cannot be read fresh is a COMPILED
// regex — avl trees store the pattern string, not the compiled object —
// so that one value is cached, and the cache is validated against
// nsdata on every use.
package nslogic

const (
	ugnot    = "ugnot"
	bpsDenom = 10_000
)

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// THE LABEL RULE IS WRITTEN OUT, NOT COMPILED.
//
// It used to be a regexp, and that regexp was the single most expensive
// thing in this realm — by a wide margin, and not by a little. Measured
// on sapphire-1 with vm/qstorage against purpose-built probe realms:
//
//	a realm with code and no package-level state      2,711 bytes
//	the same realm plus ONE compiled regexp         154,877 bytes
//
// A compiled regexp is an object graph, and gno charges 100 ugnot for
// every byte of it, forever. That one variable was 15.2 GNOT of the
// 22.5 GNOT it costs to deploy this realm — about 68% of the bill, to
// enforce a rule that fits in thirty lines.
//
// The second regexp was worse, because it was compiled LAZILY and cached
// in a package-level var. That does not avoid the cost, it MOVES it: the
// first person to register a name after a fresh deploy would have had
// their transaction grow this realm's storage by 150KB and been charged
// ~15 GNOT of deposit for it. Confirmed by probe, not inferred — a realm
// deployed at 2,711 bytes went to 154,149 the moment one call compiled
// and cached a regexp, billed to the caller. Somebody buying a ten-cent
// name would have been asked for fifteen GNOT.
//
// The hand-written version is also 6x cheaper in gas on every call
// (1.06M against 6.67M), so there is no axis on which the regexp was
// the better choice. It read better. That was the whole of its case.
//
// WHAT THIS COSTS US. The pattern is no longer admin-tunable at runtime:
// changing the rule now means redeploying this realm. That is a fair
// trade at 7 GNOT a deploy, it was never a rule that should change
// casually, and SetLabelPattern refuses anything but the implemented
// pattern so the stored string can never describe rules the code does
// not enforce.

// labelRule is the pattern this realm implements, kept as a string so
// nsdata, the error messages and the site all quote the same thing.
const labelRule = `^[a-z0-9]+(-[a-z0-9]+)*$`

// matchesLabelRule is that pattern, by hand: lowercase letters and
// digits, single hyphens between them, none at either end.
func matchesLabelRule(s string) bool {
	if s == "" {
		return false
	}
	prevHyphen := true // a leading hyphen is not allowed
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
			prevHyphen = false
		case c == '-':
			if prevHyphen {
				return false // leading, or two in a row
			}
			prevHyphen = true
		default:
			return false
		}
	}
	return !prevHyphen // nor a trailing one
}

// looksLikeAddress was `^g1[a-z0-9]{20,38}$`. Anything shaped like a real
// gno.land address is refused as a label, so a name can never be mistaken
// for a raw wallet address in a UI.
func looksLikeAddress(s string) bool {
	if len(s) < 22 || len(s) > 40 || !strings.HasPrefix(s, "g1") {
		return false
	}
	for i := 2; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') {
			return false
		}
	}
	return true
}

// validateLabel — same policy as the original single-realm build (see
// NOTES.md for the ENS/Starname/r/sys/users research behind it). The
// length bounds are still read from nsdata, so they survive a swap of
// this realm; the character rule is now this realm's own.
//
// Call sites, and why: RegisterName/RegisterDomain only (both the
// first-ever mint AND reclaiming a past-grace slot — a reclaim is a
// genuine new mint with a new owner). RenewName/RenewDomain deliberately
// do NOT call this — an already-registered name must keep renewing under
// whatever rule was in force when it was minted.
func validateLabel(label string) {
	minLen, maxLen := nsdata.GetLabelLength()
	if len(label) < minLen || len(label) > maxLen {
		panic(ufmt.Sprintf("nslogic: label must be %d-%d characters", minLen, maxLen))
	}
	// Structural invariant, enforced regardless of what the pattern
	// happens to allow: "*" is the separator in both the token ID
	// (label*domain) and nsdata's storage key (domain*label). A label or
	// domain containing one would make those encodings ambiguous and let
	// two different names collide onto a single record.
	if strings.Contains(label, "*") {
		panic("nslogic: label may not contain '*'")
	}
	if !matchesLabelRule(label) {
		panic("nslogic: a name is lowercase letters, digits and single hyphens between them — " + labelRule)
	}
	if looksLikeAddress(label) {
		panic("nslogic: label looks like a wallet address, not allowed")
	}
}

package nsskin

import (
	"gno.land/p/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/grc721"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

func nameKey(label, domain string) string { return domain + "*" + label }

// bindingIsLive reports whether a token's binding still points at the
// registration it was made against. Same test ArtForName and Claim
// already apply; named once so the four copies cannot drift.
func bindingIsLive(tid string) bool {
	v := bound.Get(tid)
	if v == nil {
		return false
	}
	b := v.(*binding)
	if !nsdata.NameExists(b.label, b.domain) {
		return false
	}
	_, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
	return registered == b.registered
}

// grcID saves every call site from importing grc721 just to cast.
func grcID(tid string) grc721.TokenID { return grc721.TokenID(tid) }

/*
Attach binds a skin to a name and puts the token into this realm's
custody. See the long note in types.gno for why custody rather than a
lock in place: it is what makes a marketplace's escrow of the NAME
irrelevant to the skin.

ONE SKIN, ONE NAME, both ways. A token may be attached to one name, and
a name may wear one skin. Letting one copy dress every name a person owns
would make the second copy pointless, and the object stops meaning
anything.
*/
func Attach(cur realm, tid, label, domain string) {
	assertNoSend(cur)
	wear(cur, tid, label, domain, cur.Previous().Address())
}

// wear is Attach's body, shared with Buy so that buying and wearing
// settle in one transaction. Splitting them would let a buyer stop
// halfway and end up holding a skin they paid for and did not put on.
func wear(cur realm, tid, label, domain string, caller address) {
	id, ok := skinOfToken(tid)
	if !ok {
		panic("nsskin: no such skin token: " + tid)
	}
	s := mustSkin(id)
	if s.withdrawn {
		panic("nsskin: " + id + " has been withdrawn and cannot be worn")
	}
	if bound.Has(tid) {
		panic("nsskin: " + tid + " is already on a name — claim it back first")
	}
	/* A STALE BINDING IS NOT A BINDING, and this used to be the one
	   place in the realm that forgot it.
	   Every other consumer — ArtForName, Refresh, refresh, Claim — pins
	   on `registered` and treats a mismatch as no binding at all. This
	   guard tested existence only, so: somebody attaches a skin, lets
	   the name lapse, never claims. A stranger re-registers the label
	   and can NEVER wear a skin on it — their Attach panics here, and
	   Claim refuses them because the stale binding entitles its own
	   binder. No admin call could clear it either. One registration
	   permanently killed the cosmetic slot on any label, and an honest
	   holder who simply let a name go did it by accident.
	   So a dead binding is evicted rather than obeyed. Only the reverse
	   index goes: `bound[tid]` stays, so the old binder can still Claim
	   their own token back — they paid for it and it is not forfeit. */
	nk := nameKey(label, domain)
	if cur := nameBound.Get(nk); cur != nil {
		if !bindingIsLive(cur.(string)) {
			nameBound.Remove(nk)
		} else {
			panic("nsskin: " + label + "*" + domain + " already wears a skin")
		}
	}

	owner, err := nft.OwnerOf(grcID(tid))
	if err != nil {
		panic("nsskin: " + err.Error())
	}
	if owner != caller {
		panic("nsskin: you do not own " + tid)
	}

	if !nsdata.NameExists(label, domain) {
		panic("nsskin: no such name: " + label + "*" + domain)
	}
	if !nsdata.IsNameValid(label, domain) {
		panic("nsskin: " + label + "*" + domain + " has expired")
	}
	nameOwner, registered, _, _, _, _ := nsdata.GetNameInfo(label, domain)
	if nameOwner != caller {
		panic("nsskin: you do not own " + label + "*" + domain)
	}
	if s.lock != "" && s.lock != domain {
		panic(ufmt.Sprintf("nsskin: %s only goes on *%s names, not *%s", id, s.lock, domain))
	}

	// Into custody. From here the token is in nobody's wallet, so it
	// cannot be listed anywhere or sold out from under the name.
	if err := nft.TransferFrom(caller, caller, cur.Address(), grcID(tid)); err != nil {
		panic("nsskin: could not take custody: " + err.Error())
	}
	bound.Set(tid, &binding{label: label, domain: domain, registered: registered, binder: caller})
	nameBound.Set(nameKey(label, domain), tid)
}

/*
Refresh points a binding's `binder` at the name's CURRENT owner.

WHY THIS EXISTS, and it is the fix for a real hole. `binder` decides who
gets the skin back once the name record is gone. Set once at Attach and
never updated, it names whoever ATTACHED the skin — so: Alice attaches,
sells the name to Bob, the skin travels with it as intended, Bob lets the
name lapse, and the skin goes back to ALICE. Bob paid for it. That is
not a limitation, it is taking something from the person who bought it.

nsdata cannot tell us a name changed hands — it is permanent, it has no
hook, and it never will. So `binder` cannot be maintained; it can only be
CAUGHT UP. This is that, and it is deliberately open to anyone:

	it only ever writes the name's real current owner, so calling it can
	never move the skin anywhere it should not go, and there is nothing
	to gain by calling it on somebody else's binding

	which means the site can call it on a purchase, a keeper can call it
	on a schedule, the buyer can call it themselves, or nobody calls it
	at all and the next Attach or Claim does it — all with the same
	result and none of them needing to be trusted

Nothing on chain is automatic here. gno has no scheduler and nsdata has
no callback, so every version of "the skin follows the sale" is one extra
call by someone. Making that call safe for ANYONE to make is as close to
automatic as this can get, and it is close enough.
*/
func Refresh(cur realm, tid string) {
	// Permissionless and routinely called by keepers, so it is exactly
	// the entry point a script attaches coins to by accident — and this
	// realm's only banker moves that transaction's own OriginSend, so
	// anything left here is stranded at the realm address forever.
	assertNoSend(cur)
	v := bound.Get(tid)
	if v == nil {
		return
	}
	b := v.(*binding)
	if !nsdata.NameExists(b.label, b.domain) {
		return
	}
	owner, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
	// Only for THIS registration. If the name lapsed and somebody else
	// took it, the current owner is a stranger to this binding and must
	// not be recorded as entitled to anything.
	if registered != b.registered {
		return
	}
	b.binder = owner
}

// refresh is Refresh without the realm ceremony, for the callers below.
func refresh(b *binding) {
	if !nsdata.NameExists(b.label, b.domain) {
		return
	}
	owner, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
	if registered != b.registered {
		return
	}
	b.binder = owner
}

/*
Claim takes a skin out of custody and into the caller's wallet.

WHO MAY, and this is the whole travels-with-the-name rule:

	the CURRENT OWNER of the name, while the name record still exists.
	Buy the name, claim the skin — including a name bought from someone
	else, which is the point.

	the LAST KNOWN NAME OWNER, once the record is gone entirely. That is
	the "it comes back to your wallet when the name expires" case — and
	"last known" rather than "whoever attached it", because after a sale
	those are different people and only one of them paid for it. See
	Refresh above for how that is kept current without a hook nsdata
	does not have.

The binding is pinned to one REGISTRATION. If a name lapsed and somebody
else registered it, its timestamp has changed, so the new registrant is
not the owner of anything here and cannot claim.
*/
func Claim(cur realm, tid string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	v := bound.Get(tid)
	if v == nil {
		panic("nsskin: " + tid + " is not on a name")
	}
	b := v.(*binding)

	// Catch `binder` up before deciding, so a name that changed hands
	// since it was attached settles on the person who holds it now
	// rather than the person who first attached it.
	refresh(b)

	entitled := false
	if nsdata.NameExists(b.label, b.domain) {
		owner, registered, _, _, _, _ := nsdata.GetNameInfo(b.label, b.domain)
		if registered == b.registered {
			// A live binding: the name's owner controls the skin.
			entitled = owner == caller
		} else {
			// The name lapsed and was taken by somebody else. Whatever
			// they own, it is not this.
			entitled = caller == b.binder
		}
	} else {
		// The record is gone. Back to whoever put it there.
		entitled = caller == b.binder
	}
	if !entitled {
		panic("nsskin: " + tid + " belongs to " + b.label + "*" + b.domain +
			", and you are neither its owner nor the person who attached this")
	}

	if err := nft.TransferFrom(cur.Address(), cur.Address(), caller, grcID(tid)); err != nil {
		panic("nsskin: could not release: " + err.Error())
	}
	bound.Remove(tid)
	// Only clear the reverse entry if it still points at THIS token — a
	// stale binding may have been superseded by a new registrant's own
	// skin, and clearing it blindly would strip theirs.
	if cur := nameBound.Get(nameKey(b.label, b.domain)); cur != nil && cur.(string) == tid {
		nameBound.Remove(nameKey(b.label, b.domain))
	}
}

// SkinOnName returns the token currently worn by a name, or "".
func SkinOnName(label, domain string) string {
	v := nameBound.Get(nameKey(label, domain))
	if v == nil {
		return ""
	}
	return v.(string)
}

// BindingOf reports where a token is attached, for a wallet or a shop.
func BindingOf(tid string) (label, domain string, registered int64, binder address) {
	v := bound.Get(tid)
	if v == nil {
		return "", "", 0, ""
	}
	b := v.(*binding)
	return b.label, b.domain, b.registered, b.binder
}

package nsskin

import (
	"chain"
	"strings"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

const ugnot = "ugnot"

/*
BUYING ONE, AND WEARING IT, IN A SINGLE TRANSACTION.

Splitting these would mean a buyer signs twice and can stop between —
leaving a skin they paid for sitting unworn in a wallet, which is the
state nobody wants and the one a two-step flow produces most often. So
the name is an argument: pass it and the skin is minted and attached
together; pass "" and it is minted loose, which is what somebody buying
ahead of registering a name needs.

NOTHING IS EVER HELD. Payment, treasury and refund all settle inside the
buyer's own transaction, exactly as nslogic does it — and for the same
reason, which is worth restating because it is a legal position rather
than a style: a realm you can have a BALANCE in is a different kind of
thing to operate, subject to different rules, run by people with
licences. Every ugnot that arrives leaves again in the same call.

THE 70/30 SPLIT IS NOT HERE, and that is deliberate rather than
forgotten. Every skin in this collection is ours, so the artist and the
treasury are the same address and a split would move money from a
pocket to itself while costing gas to do it. The artist is recorded on
every definition so the day it stops being us, this is where the split
goes — see SKINS.md.
*/
func Buy(cur realm, id, label, domain string) string {
	if !cur.Previous().IsUserCall() {
		panic("nsskin: only direct wallet calls may attach payment")
	}
	buyer := cur.Previous().Address()
	// Same normalization as Mint, for the same reason: the token id is
	// built from this string, and an un-lowercased one mints a token
	// that can never render. See the note in write.gno.
	id = strings.ToLower(strings.TrimSpace(id))
	s := mustSkin(id)
	if s.withdrawn {
		panic("nsskin: " + id + " has been withdrawn and is not for sale")
	}
	// Refuse the sale rather than the attach. Minting a locked skin to
	// somebody who wanted it for a name it will never go on is a refund
	// request wearing the clothes of a successful purchase.
	if label != "" && s.lock != "" && s.lock != domain {
		panic(ufmt.Sprintf("nsskin: %s only goes on *%s names, not *%s", id, s.lock, domain))
	}

	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nsskin: only ugnot is accepted, got: " + c.Denom)
		}
	}
	// PER DESIGN, not one figure for the collection. A third of the
	// definitions are free by the rule in price.gno, and an admin may
	// have priced any of them by hand — see PriceOf, which is the only
	// place that decides.
	due := PriceOf(id)
	paid := sent.AmountOf(ugnot)
	if paid < due {
		panic(ufmt.Sprintf("nsskin: insufficient payment: need %d ugnot, got %d", due, paid))
	}

	// A FREE SKIN TAKES NO PAYMENT AND MOVES NO COINS, and the refund
	// below is what makes that safe: somebody whose page quoted the old
	// price, or who simply attached coins to a free mint, gets every
	// ugnot back in the same transaction rather than donating it.
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	me := cur.Address()
	if due > 0 {
		b.SendCoins(me, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, due)})
	}
	if excess := paid - due; excess > 0 {
		b.SendCoins(me, buyer, chain.Coins{chain.NewCoin(ugnot, excess)})
	}

	s.minted++
	tid := ufmt.Sprintf("%s#%d", id, s.minted)
	if err := nft.Mint(buyer, grcID(tid)); err != nil {
		panic("nsskin: mint failed: " + err.Error())
	}
	tokenSkin.Set(tid, id)

	if label != "" {
		wear(cur, tid, label, domain, buyer)
	}
	return tid
}

// SetPrice sets the BASE price, in ugnot — what a design costs when the
// rule has not made it free and no admin has priced it by hand. ugnot
// because that is what the chain moves: what it is worth in anything
// else is a question for the page that quotes it, and pinning a dollar
// figure into a contract that cannot see an exchange rate would be a lie
// with a number in it.
func SetPrice(cur realm, p int64) {
	assertIsAdmin(cur)
	if p < 0 {
		panic("nsskin: a negative price is not a discount")
	}
	price = p
}

func GetPrice() int64 { return price }

// Free calls must not be able to strand coins here. This realm has no
// withdrawal path, so anything attached to one would sit in its address
// permanently.
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return
	}
	if len(unsafe.OriginSend()) > 0 {
		panic("nsskin: this call takes no payment")
	}
}

package nsskin

import "gno.land/p/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/grc721"

// The deployer is the first admin. Rotatable with SetAdmin, and
// deliberately NOT the vault's timelocked governance: this realm is
// replaceable, so it does not need machinery built for one that is not.
// See the note in types.gno.
func init(cur realm) {
	nft = grc721.NewBasicNFT(0, cur, "Meme Name Service Skins", "MNSKIN")
	admin = cur.Previous().Address()
}

package nsskin

import (
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

/*
WHAT ONE COSTS, PER DESIGN.

There used to be a single `price` for the whole collection, which is the
right shape for a launch batch and the wrong one the moment anything in
it is worth more or less than the rest — or worth nothing, which is the
interesting case.

Three sources, in order, and only the first of them stores anything:

	an ADMIN OVERRIDE, if one has been set for this id
	ZERO, if the id falls in the free share by the rule below
	the BASE PRICE otherwise

# WHY THE FREE ONES ARE COMPUTED RATHER THAN LISTED

Marking a third of sixty definitions free by storing a flag on each is
sixty writes and sixty entries that live forever, to record something
that never changes. The rule below derives it from the id, so it costs
nothing to store, nothing to keep in step, and cannot drift between the
contract, the shop and the collection file — all three ask the same
question of the same string and get the same answer.

It is ARBITRARY, which is the point: nothing about a design implies its
price, and a rule nobody can lobby is fairer than a list somebody picked.
An admin who disagrees about a particular one sets an override, and that
override is then a deliberate, visible, single stored fact.

# WHY A HASH AND NOT EVERY THIRD ONE

Definitions are iterated and displayed in id order, so "every third"
would put the free ones in a visible stripe down the grid and make the
whole thing look like a pricing table rather than a collection.
*/

/*
The threshold, out of a hundred, under which a hashed id is free.

THIRTY-FIVE, NOT THIRTY, AND THE FOUR-POINT GAP IS THE HONEST PART. The
rule is a statement about ids, not a quota, so any particular collection
lands near the threshold rather than on it — sixty ids at a threshold of
thirty came out at thirteen, which is twenty-one per cent and not the
third that was asked for. Thirty-five puts the launch batch at eighteen,
which is thirty per cent exactly.

So the constant was chosen to fit the collection that exists. That is
worth saying plainly rather than dressing up: what it buys is that every
FUTURE id still gets an answer nobody can lobby for, which is the
property that mattered, while the batch on sale today is the share that
was promised.

A constant rather than a stored value, because changing it would
silently reprice every skin nobody has overridden — including ones
people have already been shown a price for. That should cost a deploy.
*/
const freeShare = 35

// priceOverride holds ONLY the ids an admin has priced by hand. An id
// that is absent is not "free" and not "base" — it is unopinionated, and
// PriceOf decides. Storing a value for every skin would make the common
// case cost as much as the exception.
var priceOverride = avl.NewTree() // definition id -> int64 ugnot

/*
freeByRule is FNV-1a over the id, taken modulo one hundred.

freeShare of every hundred ids fall under the threshold, so the share
lands NEAR it rather than on it for any particular collection — see the
note on the constant. The launch batch of sixty comes out at eighteen,
and ListFreeSkins says so rather than asking anyone to trust the
arithmetic.

The same hash is in nsview.faceForArt, deliberately not shared: one runs
over a sprite and one over an id, they answer different questions, and a
helper spanning both realms would be a dependency between them for four
lines of arithmetic.
*/
func freeByRule(id string) bool {
	h := uint32(2166136261)
	for i := 0; i < len(id); i++ {
		h ^= uint32(id[i])
		h *= 16777619
	}
	return h%100 < freeShare
}

// IsFreeByRule reports what the rule alone says, ignoring any override.
// Exposed so an admin panel can show what it would revert to.
func IsFreeByRule(id string) bool {
	return freeByRule(strings.ToLower(strings.TrimSpace(id)))
}

// HasPriceOverride reports whether this id has been priced by hand. A
// panel needs it to tell "set to zero" from "free by the rule", which
// look identical in the price alone and are different decisions.
func HasPriceOverride(id string) bool {
	return priceOverride.Has(strings.ToLower(strings.TrimSpace(id)))
}

// PriceOf is what this design costs right now, in ugnot.
//
// It does NOT check that the id exists: a price for a definition that is
// not there is meaningless rather than wrong, and Buy is the thing that
// must refuse an unknown id — which it already does, by name, before it
// ever asks what the price is.
func PriceOf(id string) int64 {
	id = strings.ToLower(strings.TrimSpace(id))
	if v := priceOverride.Get(id); v != nil {
		return v.(int64)
	}
	if freeByRule(id) {
		return 0
	}
	return price
}

/*
SetSkinPrice prices one design by hand, overriding the rule.

Zero is a legitimate value and is NOT the same as removing the override:
it says "this one is free because I said so", which survives a change to
the base price and to the rule. ClearSkinPrice is how you go back to
being unopinionated.
*/
func SetSkinPrice(cur realm, id string, p int64) {
	assertIsAdmin(cur)
	setSkinPrice(id, p)
}

// setSkinPrice is SetSkinPrice without the realm ceremony. Split for the
// same reason attach.gno splits refresh from Refresh: the rules are
// worth testing on their own, and the gate above them is the same
// assertIsAdmin every other write in this realm goes through.
func setSkinPrice(id string, p int64) {
	id = strings.ToLower(strings.TrimSpace(id))
	if !skins.Has(id) {
		panic("nsskin: no such skin: " + id)
	}
	if p < 0 {
		panic("nsskin: a negative price is not a discount")
	}
	priceOverride.Set(id, p)
}

// ClearSkinPrice drops an override, putting the design back under the
// rule and the base price.
func ClearSkinPrice(cur realm, id string) {
	assertIsAdmin(cur)
	clearSkinPrice(id)
}

func clearSkinPrice(id string) {
	priceOverride.Remove(strings.ToLower(strings.TrimSpace(id)))
}

/*
SetSkinPrices prices many designs in one call.

A panel that lets somebody retune a collection produces a batch of
changes, and sixty separate transactions is sixty flat fees for what is
one decision. Same encoding as AllSkins reads back — tab between the id
and the price, newline between records — so the two halves of the panel
speak one format.

An empty price field CLEARS the override rather than setting zero. The
panel shows an empty box for "no opinion" and a 0 for "free on purpose",
and those must not collapse into each other on the way here.
*/
func SetSkinPrices(cur realm, packed string) {
	assertIsAdmin(cur)
	setSkinPrices(packed)
}

func setSkinPrices(packed string) {
	/* CHECKED IN FULL BEFORE ANYTHING IS WRITTEN.
	   A panic reverts the whole transaction on chain, so applying as we
	   go would come out right in production — but only because of a
	   guarantee living somewhere else. Validating first makes the
	   promise true of this function on its own, which is what the tests
	   can actually hold it to, and it costs one pass over a list that is
	   sixty lines at its largest. */
	type change struct {
		id    string
		clear bool
		p     int64
	}
	var pending []change

	for _, raw := range strings.Split(packed, "\n") {
		/* TRIMMED AROUND THE FIELDS, NOT AROUND THE LINE. Trimming the
		   whole line first ate the trailing tab of "id\t", which is the
		   form that CLEARS an override — so "no opinion" arrived here
		   looking like a line with no tab at all and was rejected as
		   malformed. Only the carriage return goes, because a form
		   posting CRLF is not making a statement about pricing. */
		line := strings.TrimRight(raw, "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		tab := strings.Index(line, "\t")
		if tab < 0 {
			panic("nsskin: each line is <id>\\t<ugnot>, got: " + line)
		}
		id := strings.ToLower(strings.TrimSpace(line[:tab]))
		val := strings.TrimSpace(line[tab+1:])
		if !skins.Has(id) {
			panic("nsskin: no such skin: " + id)
		}
		if val == "" {
			pending = append(pending, change{id: id, clear: true})
			continue
		}
		p, ok := parseU64(val)
		if !ok {
			panic("nsskin: not a number of ugnot: " + val)
		}
		pending = append(pending, change{id: id, p: p})
	}

	for _, c := range pending {
		if c.clear {
			priceOverride.Remove(c.id)
			continue
		}
		priceOverride.Set(c.id, c.p)
	}
}

// parseU64 is strconv.ParseInt without the import, and without accepting
// a sign — every price here is a non-negative amount of ugnot, and "-0"
// or "+5" arriving from a form should be refused rather than guessed at.
func parseU64(s string) (int64, bool) {
	if len(s) == 0 || len(s) > 18 {
		return 0, false
	}
	var n int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int64(c-'0')
	}
	return n, true
}

/*
ListFreeSkins names every definition that costs nothing right now,
counting overrides — so it answers "what can I have for free", which is
the question, rather than "what does the rule say", which is trivia.
*/
func ListFreeSkins() string {
	var b strings.Builder
	skins.Iterate("", "", func(k string, _ any) bool {
		if PriceOf(k) == 0 {
			b.WriteString(k + "\n")
		}
		return false
	})
	return b.String()
}

// AllPrices is every id and its price, for a shop that wants the lot in
// one read. AllSkins carries the price too; this exists for a panel that
// wants prices without the rest and for checking the two agree.
func AllPrices() string {
	var b strings.Builder
	skins.Iterate("", "", func(k string, _ any) bool {
		o := "0"
		if priceOverride.Has(k) {
			o = "1"
		}
		b.WriteString(k + "\t" + ufmt.Sprintf("%d", PriceOf(k)) + "\t" + o + "\n")
		return false
	})
	return b.String()
}

package nsskin

import (
	"strings"

	"gno.land/p/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/grc721"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
ArtForName is the one question the renderer asks, and it is answered here
so the rule lives with the data it depends on.

It returns the sprite a name should be drawn with, or "" for the ordinary
card. Everything the renderer would otherwise have to remember to check
is inside it, because a renderer that has to remember three things before
drawing is one that eventually forgets one.

The checks, and what each of them makes self-cleaning:

	the name wears a token at all
	that token's definition has not been WITHDRAWN — so a takedown
	  reverts every name wearing it, everywhere, at once, with no
	  migration and no per-name cleanup
	the binding is FRESH, pinned to this registration — so a name that
	  lapsed and was taken by somebody else inherits nothing
	the LOCK still matches — belt and braces, since Attach checks it too

Note what is NOT checked: who holds the token in their wallet. Nobody
does. It is in this realm's custody for as long as it is attached, which
is what makes the skin travel with the name instead of with a wallet.
*/
func ArtForName(label, domain string) string {
	tid := SkinOnName(label, domain)
	if tid == "" {
		return ""
	}
	v := bound.Get(tid)
	if v == nil {
		return ""
	}
	b := v.(*binding)

	if !nsdata.NameExists(label, domain) {
		return ""
	}
	_, registered, _, _, _, _ := nsdata.GetNameInfo(label, domain)
	if registered != b.registered {
		return "" // a different registration of the same label
	}

	id, ok := skinOfToken(tid)
	if !ok {
		return ""
	}
	// Normalized on the way in, so a token minted from a non-canonical
	// id before Buy/Mint were fixed starts rendering instead of staying
	// a blank card its holder already paid for.
	sv := skins.Get(strings.ToLower(strings.TrimSpace(id)))
	if sv == nil {
		return ""
	}
	s := sv.(*skin)
	if s.withdrawn {
		return ""
	}
	if s.lock != "" && s.lock != domain {
		return ""
	}
	return s.art
}

// SkinInfo describes a DEFINITION, for a shop listing or a skin's own
// card. Withdrawn is returned rather than hidden: a holder is entitled
// to know, and a listing that silently vanishes is worse than one that
// says what happened.
func SkinInfo(id string) (name, art, lock string, artist address, withdrawn bool, minted int64) {
	s := mustSkin(id)
	return s.name, s.art, s.lock, s.artist, s.withdrawn, s.minted
}

func SkinExists(id string) bool {
	return skins.Has(strings.ToLower(strings.TrimSpace(id)))
}

// ListSkins returns every definition id, in tree order. Small by
// construction — this is a curated shop, not a submission firehose — and
// if that ever stops being true it wants paging rather than a bigger
// answer.
func ListSkins() []string {
	var out []string
	skins.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

/*
AllSkins packs the whole catalogue into ONE read.

A shop page needs every definition's name, lock and availability, and
asking for them one at a time is sixty round trips before anything
appears on screen. The ART is deliberately NOT here: it is the bulk of
the data, it is committed in the repo as the canonical source, and a
page that already has it does not need to fetch it again.

Six fields: id, name, lock, withdrawn, minted, price in ugnot.

Tab-separated fields, newline-separated records — not JSON, because
building JSON by string concatenation in a realm is how quoting bugs get
shipped, and a shop is not worth that risk. No field can contain a tab
or a newline: ids and locks are [a-z0-9-] by rule, and a name is checked
here rather than assumed.
*/
func AllSkins() string {
	var b strings.Builder
	skins.Iterate("", "", func(k string, v any) bool {
		s := v.(*skin)
		nm := s.name
		if strings.ContainsAny(nm, "\t\n") {
			nm = "?" // never seen: DefineSkin would have to have accepted it
		}
		w := "0"
		if s.withdrawn {
			w = "1"
		}
		// PRICE IS THE SIXTH FIELD, appended rather than inserted, so a
		// page shipped before per-design pricing keeps reading the five
		// it knows and simply does not see this one.
		b.WriteString(k + "\t" + nm + "\t" + s.lock + "\t" + w + "\t" +
			ufmt.Sprintf("%d", s.minted) + "\t" +
			ufmt.Sprintf("%d", PriceOf(k)) + "\n")
		return false
	})
	return b.String()
}

func skinOfToken(tid string) (string, bool) {
	v := tokenSkin.Get(tid)
	if v == nil {
		return "", false
	}
	return v.(string), true
}

// SkinOfToken is skinOfToken for callers outside the realm.
func SkinOfToken(tid string) string {
	id, _ := skinOfToken(tid)
	return id
}

func GetAdmin() address        { return admin }
func GetTokenURIBase() string  { return tokenURIBase }
func IsTrustedShop(a address) bool {
	return trustedShop.Has(a.String())
}

// ---------------------------------------------------------------- grc721

func Name() string      { return nft.Name() }
func Symbol() string    { return nft.Symbol() }
func TokenCount() int64 { return nft.TokenCount() }

func BalanceOf(owner address) int64 {
	bal, err := nft.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf does NOT hide a withdrawn skin's owner, and that is the
// opposite of what nsdata does for an expired name.
//
// There, hiding the owner is an anti-scam measure: a lapsed name must
// not be listable, because the seller no longer controls it. Here the
// holder still owns the token completely — withdrawal only stops it
// being DRAWN. Hiding the owner would break transfers and approvals for
// somebody who has done nothing wrong, to solve a problem that is not
// theirs.
func OwnerOf(tid grc721.TokenID) address {
	owner, err := nft.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	return owner
}

// Total, the same way nsdata.GetApproved is: the zero address means
// nobody is approved, and only an unknown token id panics. The vendored
// NFT returns an error for both cases, and collapsing them made "no
// approval" indistinguishable from "no such token" — so no caller could
// fall back to the operator grant without catching a panic first.
func GetApproved(tid grc721.TokenID) address {
	a, err := nft.GetApproved(tid)
	if err != nil {
		if _, oerr := nft.OwnerOf(tid); oerr != nil {
			panic(err)
		}
		return ""
	}
	return a
}

func IsApprovedForAll(owner, operator address) bool {
	return nft.IsApprovedForAll(owner, operator)
}

func TokenURI(tid grc721.TokenID) string {
	return tokenURIBase + string(tid)
}

// Package nsskin holds purchasable card art — the skins — as tokens of
// their own, and binds them to names.
//
// WHY THIS IS ITS OWN REALM AND NOT PART OF nsdata. SKINS.md §8 listed
// it as undecided; it is decided here, because the reasoning turned out
// to be one-sided rather than balanced.
//
//	nsdata IS PERMANENT. It cannot be replaced, ever. A second kind of
//	token in it means every mistake in the skin model is permanent too,
//	and the skin model is the newest and least settled thing here.
//
//	nsdata.OwnerOf DELIBERATELY PANICS FOR EXPIRED TOKENS so a lapsed
//	name cannot be listed anywhere. Skins do not expire. That machinery
//	is exactly wrong for them, and a conditional on token kind inside
//	the one realm that can never be fixed is the worst place for it.
//
//	A NEW REALM CAN BE REPLACED while it holds a handful of tokens. The
//	vault cannot, at any point, for any reason.
//
// So being wrong here costs a migration nobody notices. Being wrong
// inside nsdata costs forever.
//
// # A SKIN IS TWO THINGS
//
//	A DEFINITION is the artwork: a name, a sprite, an optional extension
//	lock, and the artist to pay. One per design, stored once — a
//	thousand holders of one design cost one sprite, not a thousand.
//
//	A TOKEN is somebody's copy. Editions are unlimited, because SKINS.md
//	is explicit that a cap is a floor price with extra steps and resale
//	value is never part of the pitch.
//
// # A SKIN BINDS TO ONE NAME, AND TRAVELS WITH IT
//
// This reverses an earlier recommendation of mine, and the new answer is
// better. I had argued for keeping them separate — a pointer from the
// name, reverting on sale — because names expire and skins should not.
// The objection to bundling was that a buyer sees a skinned card on a
// marketplace and receives an unskinned name.
//
// Binding solves that rather than working around it. The skin genuinely
// comes with the name, so the card is not misleading, and the small
// disclosure line the old model needed inside the artwork disappears.
// And a skin still does not die with a name: when the name goes, the
// skin comes back.
//
// # WHY ATTACHING ESCROWS THE TOKEN, WHICH IS THE WHOLE CUSTODY ANSWER
//
// The worry: a name listed on a marketplace that takes CUSTODY. If the
// skin lived in the seller's wallet, a custodial listing would hold the
// name while the skin sat somewhere else, and untangling that on expiry
// would need cooperation we cannot compel.
//
// So attaching moves the token to THIS REALM'S OWN ADDRESS. While
// attached it is in nobody's wallet: it cannot be listed, cannot be sold
// out from under the name, and a marketplace escrowing the NAME never
// touches it. The question of freeing a skin from somebody else's
// custody does not arise, because it was never in it.
//
// Taking it out again is one rule with one fallback:
//
//	WHILE THE NAME EXISTS, its CURRENT OWNER may claim the skin. That is
//	what makes it travel: buy the name, claim the skin.
//
//	IF THE NAME RECORD IS GONE — lapsed and reclaimed — whoever attached
//	it may take it back, which is the "it returns to your wallet" case.
//
// One limitation, stated rather than hidden: buy a name with a skin,
// never claim it, and let that name lapse completely, and the skin
// returns to whoever attached it. Claiming on purchase avoids it
// entirely, and the site prompts for exactly that.
package nsskin

import (
	"gno.land/p/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/grc721"
	"gno.land/p/nt/avl/v0"
)

type skin struct {
	name   string // as the shop shows it
	art    string // the sprite string, in the format nsview parses
	lock   string // an extension label, or "" for one that goes anywhere
	artist address
	// WITHDRAWN IS NOT DELETED, and the distinction is the whole
	// takedown mechanism (SKINS.md §6). Deleting a definition orphans
	// every token pointing at it. Withdrawing leaves everything in place
	// and stops it drawing — every name wearing it reverts at once, with
	// no migration and no per-name cleanup, because the card is
	// generated on every read.
	withdrawn bool
	minted    int64 // how many copies exist, and the next serial
}

// A live attachment. `registered` pins it to one REGISTRATION of the
// name, not to the label: if the name lapses and somebody else takes it,
// the timestamp changes and this binding is stale, so the new registrant
// inherits nothing.
type binding struct {
	label      string
	domain     string
	registered int64
	binder     address // who attached it, and who gets it back if the name dies
}

var (
	// Constructed in init, which is where it can be handed the realm.
	nft   *grc721.BasicNFT
	skins = avl.NewTree() // definition id -> *skin

	// token id -> definition id. Derivable by splitting the token id,
	// but stored so a lookup is a tree read rather than string surgery
	// that has to agree with the minter forever.
	tokenSkin = avl.NewTree()

	bound     = avl.NewTree() // token id      -> *binding
	nameBound = avl.NewTree() // "domain*label" -> token id

	// Whichever realm renders a skin card. Same reasoning as nsdata's:
	// the art is the most cosmetic and most-likely-to-be-revised thing
	// here, so it must not be frozen into a token contract.
	tokenURIBase = "/r/demo/nsview:skin/"

	// Day-to-day authority: define, mint, withdraw. Deliberately a plain
	// address rather than the vault's timelocked governance — this realm
	// is replaceable, so it does not need machinery built for one that
	// is not.
	admin address

	// Realms allowed to mint on somebody's behalf, which is what a shop
	// is. Empty at first: the launch batch is minted by the admin.
	trustedShop = avl.NewTree()

	// What one costs, in ugnot. Zero until an admin sets it, so a
	// misconfigured deploy gives skins away rather than charging an
	// accidental amount — the failure that costs nobody money.
	price int64
)

const (
	maxSkinName = 40
	maxSkinArt  = 2048 // a 32x32 sprite is about 1,100 bytes
	maxSkinID   = 24   // appears in every token id and every binding
)

package nsskin

import (
	"strings"

	"gno.land/p/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/grc721"
	"gno.land/p/nt/ufmt/v0"
)

func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("nsskin: not the admin")
	}
}

func assertIsAdminOrShop(cur realm) {
	a := cur.Previous().Address()
	if a == admin {
		return
	}
	if !trustedShop.Has(a.String()) {
		panic("nsskin: not the admin or a trusted shop")
	}
}

/*
DefineSkin registers a design. It does not mint anything.

Definitions and copies are separate calls on purpose: defining is the
expensive, careful, one-off act that puts an artist's work and a sprite
on chain, while minting is the cheap repeated one. Rolling them together
would mean re-sending the artwork with every sale.

A definition may be REDEFINED only while nothing has been minted from it.
After the first copy exists, the art is what its holders bought and it
stops being ours to edit — the only lever left is withdrawal, which is
honest about what it is doing.
*/
func DefineSkin(cur realm, id, name, art, lock string, artist address) {
	assertIsAdmin(cur)
	id = strings.ToLower(strings.TrimSpace(id))
	assertValidID(id)
	if len(name) == 0 || len(name) > maxSkinName {
		panic("nsskin: a skin needs a name, of at most 40 characters")
	}
	if len(art) == 0 || len(art) > maxSkinArt {
		panic(ufmt.Sprintf("nsskin: art is %d bytes, the limit is %d", len(art), maxSkinArt))
	}
	// The SHAPE of the sprite is checked here; whether it renders is
	// nsview's business. Storing something the renderer will reject
	// silently is the failure mode this exists to prevent — a skin that
	// draws nothing, sold to somebody, discovered later.
	assertValidArt(art)
	if lock != "" {
		assertValidLabel(lock)
	}
	if artist == "" {
		panic("nsskin: a skin needs an artist to pay")
	}

	if v := skins.Get(id); v != nil {
		s := v.(*skin)
		if s.minted > 0 {
			panic(ufmt.Sprintf(
				"nsskin: %s has %d copies out — redefining it would change "+
					"what those holders bought; withdraw it instead", id, s.minted))
		}
		s.name, s.art, s.lock, s.artist = name, art, lock, artist
		return
	}
	skins.Set(id, &skin{name: name, art: art, lock: lock, artist: artist})
}

/*
Mint issues one copy of a definition to somebody.

The serial is the definition's own running count, so token ids read as
"ember#1", "ember#2". Never reused: the counter only goes up, even across
burns, because a reissued id would let a new token inherit whatever an
old one was pointed at.
*/
func Mint(cur realm, id string, to address) string {
	assertIsAdminOrShop(cur)
	assertNoSend(cur)
	/* NORMALIZED BEFORE THE TOKEN ID IS BUILT.
	   mustSkin and PriceOf lowercase what they are given; this did not,
	   so Mint("Ember", …) resolved the right definition and then minted
	   "Ember#3" while tokenSkin recorded the raw id. ArtForName looks the
	   definition up in a tree DefineSkin lowercased, so the token bound,
	   charged, and then rendered nothing, forever. An admin typing a
	   capital into a form was all it took. */
	id = strings.ToLower(strings.TrimSpace(id))
	s := mustSkin(id)
	if s.withdrawn {
		panic("nsskin: " + id + " has been withdrawn and cannot be minted")
	}
	if to == "" {
		panic("nsskin: no recipient")
	}
	s.minted++
	tid := ufmt.Sprintf("%s#%d", id, s.minted)
	if err := nft.Mint(to, grc721.TokenID(tid)); err != nil {
		panic("nsskin: mint failed: " + err.Error())
	}
	tokenSkin.Set(tid, id)
	return tid
}

/*
Withdraw is the takedown control, and SKINS.md §6 makes it
non-negotiable: it has to exist before a single outside submission is
accepted, which means it has to exist now, while there is nothing to take
down and it is cheap to build.

Somebody will submit a character somebody else owns, or a bank's logo, or
something vile, and it will render inside other people's wallets with our
name beside it. When that happens the fix has to be one call, not a
migration.

It does NOT burn anything. The holder keeps the token; it simply stops
rendering, and every name pointing at it falls back to the ordinary card
at once. Burning somebody's property to solve our problem is a different
act with different consequences, and it is not this one.
*/
func Withdraw(cur realm, id string, withdrawn bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	mustSkin(id).withdrawn = withdrawn
}

func SetTokenURIBase(cur realm, base string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	tokenURIBase = base
}

func SetAdmin(cur realm, a address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if a == "" {
		panic("nsskin: refusing to leave the realm with no admin")
	}
	admin = a
}

func TrustShop(cur realm, a address, trusted bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if trusted {
		trustedShop.Set(a.String(), true)
		return
	}
	trustedShop.Remove(a.String())
}

// ---------------------------------------------------------------- grc721

func TransferFrom(cur realm, from, to address, tid grc721.TokenID) {
	assertNoSend(cur)
	if err := nft.TransferFrom(cur.Previous().Address(), from, to, tid); err != nil {
		panic("nsskin: " + err.Error())
	}
}

func Approve(cur realm, to address, tid grc721.TokenID) {
	assertNoSend(cur)
	if err := nft.Approve(cur.Previous().Address(), to, tid); err != nil {
		panic("nsskin: " + err.Error())
	}
}

func SetApprovalForAll(cur realm, operator address, approved bool) {
	assertNoSend(cur)
	if err := nft.SetApprovalForAll(cur.Previous().Address(), operator, approved); err != nil {
		panic("nsskin: " + err.Error())
	}
}

// ---------------------------------------------------------------- checks

func mustSkin(id string) *skin {
	v := skins.Get(strings.ToLower(strings.TrimSpace(id)))
	if v == nil {
		panic("nsskin: no such skin: " + id)
	}
	return v.(*skin)
}

// An id goes into every token id and into the pointer a name stores, so
// it has to survive being split on "#" and compared byte for byte.
func assertValidID(id string) {
	if len(id) == 0 || len(id) > maxSkinID {
		panic("nsskin: a skin id must be 1 to 24 characters")
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' {
			continue
		}
		panic("nsskin: a skin id may only use a-z, 0-9 and -: " + id)
	}
}

func assertValidLabel(l string) {
	if len(l) == 0 || len(l) > 63 {
		panic("nsskin: a lock must be a domain label")
	}
	for i := 0; i < len(l); i++ {
		c := l[i]
		if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' {
			continue
		}
		panic("nsskin: a lock may only use a-z, 0-9 and -: " + l)
	}
}

/*
assertValidArt mirrors the sprite checks nsview makes, and it is here for
one reason: nsview REJECTS THE WHOLE SPRITE SILENTLY. A malformed skin
does not draw a broken picture, it draws nothing at all, with no error
anywhere a person would see it.

Storing one would mean selling somebody a blank card and finding out
weeks later. So the shape is checked at the point of storage, where the
failure is a panic in a transaction nobody has paid for yet.

Deliberately checks the SHAPE and not the rendering. This realm does not
know how a card is composed and should not learn — that is the whole
reason the renderer is swappable.
*/
func assertValidArt(enc string) {
	parts := strings.Split(enc, "|")
	n := len(parts) - 1
	if n < 4 || n > 64 {
		panic(ufmt.Sprintf("nsskin: a sprite needs 4 to 64 rows, this has %d", n))
	}
	keys := map[string]bool{}
	for _, e := range strings.Split(parts[0], ",") {
		if len(e) != 8 || e[1] != '#' {
			panic("nsskin: a palette entry must be a letter, #, and six hex digits: " + e)
		}
		for i := 2; i < 8; i++ {
			c := e[i]
			if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') {
				continue
			}
			panic("nsskin: not a hex colour: " + e)
		}
		keys[e[:1]] = true
	}
	for y := 1; y <= n; y++ {
		if len(parts[y]) != n {
			panic(ufmt.Sprintf(
				"nsskin: row %d is %d wide but the sprite is %d rows tall — it must be square",
				y, len(parts[y]), n))
		}
		for x := 0; x < n; x++ {
			ch := parts[y][x : x+1]
			if ch == "." || keys[ch] {
				continue
			}
			panic(ufmt.Sprintf("nsskin: row %d uses colour %s, which the palette does not define", y, ch))
		}
	}
}

package nsview

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

/*
A HAND-DRAWN ALPHABET, STORED ONCE.

WHY THIS EXISTS. Every renderer that shows these cards — wallets,
marketplaces, block explorers — puts the SVG in a sandbox with no
network. A web font therefore never loads; it silently substitutes, and
the display lettering the mockups were designed around turns into
whatever that particular viewer happens to default to. Only the generic
families (serif, sans-serif, monospace) can be relied on, and none of
them is a marker pen.

The only way to get identical letterforms on every device is to ship the
letters themselves. These are strokes, not outlines: a path with a round
cap and a thick stroke looks like a pen, costs a fraction of the data an
outline font would, and scales without a second set of hinting.

THESE LETTERFORMS ARE OUR OWN. They are not traced from, derived from, or
measured against any existing typeface. A typeface is somebody's design
and often somebody's licensed asset; drawing our own marker capitals is
both cheaper and the only version we are entitled to put on chain
permanently. The house rule elsewhere on this project is "original art in
the spirit of the thing", and a font is art.

WHAT IT COSTS. Storage is 100 ugnot a byte and permanent, so the
encoding is deliberately dense rather than readable: each point is two
characters, each stroke is a run of points, strokes are separated by "|".
The whole alphabet — twenty-six letters, ten digits, and the punctuation
this project actually uses — is well under a kilobyte. An outline font
would have been tens of kilobytes and unreadable besides.

THE GRID. Ten wide by fourteen tall, origin top-left, so a glyph reads
directly as coordinates: "0d" is the bottom-left corner and "47" is the
middle. x never exceeds 9, so it is always one digit; y reaches 13, so
10..13 are written a..d.
*/

// glyph returns the stroke encoding for one character, or "" for
// anything unknown — an unknown character draws nothing rather than a
// box, because this markup lands inside a token that other people's
// software renders and a missing letter is better than a wrong one.
func glyph(c byte) string {
	switch c {
	// Generated from a readable point table rather than typed by
	// hand: forty glyphs of paired coordinate characters is precisely
	// the job where one stray character shifts a whole letter by one and
	// nobody spots it until it is on chain forever.
	case 'A':
		return "0d409d|2878"
	case 'B':
		return "000d|006206|06790d"
	case 'C':
		return "824014194d8b"
	case 'D':
		return "000d|00737a0d"
	case 'E':
		return "80000d8d|0666"
	case 'F':
		return "80000d|0666"
	case 'G':
		return "824014194d8b8757"
	case 'H':
		return "000d|909d|0696"
	case 'I':
		return "2070|404d|2d7d"
	case 'J':
		return "707a4d1a"
	case 'K':
		return "000d|8007|359d"
	case 'L':
		return "000d8d"
	case 'M':
		return "0d1047809d"
	case 'N':
		return "0d009d90"
	case 'O':
		return "4014194d898440"
	case 'P':
		return "0d00727507"
	case 'Q':
		return "4014194d898440|6a9d"
	case 'R':
		return "0d00727507|379d"
	case 'S':
		return "824013678a4d1b"
	case 'T':
		return "0090|404d"
	case 'U':
		return "00094d8980"
	case 'V':
		return "004d90"
	case 'W':
		return "002d457d90"
	case 'X':
		return "009d|900d"
	case 'Y':
		return "004790|474d"
	case 'Z':
		return "00900d9d"
	case '0':
		return "4014194d898440|2974"
	case '1':
		return "23404d|2d7d"
	case '2':
		return "1340830d9d"
	case '3':
		return "11508446|46895d1b"
	case '4':
		return "7d700999"
	case '5':
		return "80101666895d1b"
	case '6':
		return "7140151a5d8a5718"
	case '7':
		return "00903d"
	case '8':
		return "4613407346194d7946"
	case '9':
		return "8647144084895d2c"
	case '*':
		return "424a|1479|7419"
	case '-':
		return "1787"
	case '.':
		return "4c4d"
	case '!':
		return "4049|4c4d"
	case '?':
		return "1340734749|4c4d"
	case '\'':
		return "4043"
	case ' ':
		return ""
	}
	return ""
}

const (
	glyphW  = 10 // grid width of one glyph
	glyphH  = 14 // grid height, top to bottom
	glyphAd = 12 // advance: glyph width plus the gap to the next one
)

// hexish decodes one coordinate character. Digits are themselves; a..d
// carry 10..13, which is the only reason y can exceed nine in two
// characters.
func hexish(c byte) int {
	if c >= '0' && c <= '9' {
		return int(c - '0')
	}
	if c >= 'a' && c <= 'd' {
		return int(c-'a') + 10
	}
	return -1
}

/*
MarkerText draws a line of text as stroked paths.

`size` is the CAP HEIGHT in user units, not an em size: it is the height
of a capital letter, which is the measurement anybody positioning this by
eye is actually thinking in.

`x` is the left edge and `y` is the TOP of the capitals, matching how the
rest of this file positions things and unlike SVG's own text baseline,
which is a trap when mixing the two.

The jitter is what makes it read as a pen rather than a plotter. It is
derived from the character and its position, so it is stable: the same
string renders identically on every read, which matters because these
cards are regenerated constantly and a letter that wobbled between reads
would look like a rendering fault.
*/
func MarkerText(s string, x, y, size int, colour string, weight int) string {
	if s == "" || size <= 0 {
		return ""
	}
	if weight <= 0 {
		weight = 1 + size/7
	}
	var out strings.Builder
	out.WriteString(ufmt.Sprintf(
		`<g fill="none" stroke="%s" stroke-width="%d" stroke-linecap="round" stroke-linejoin="round">`,
		colour, weight))

	up := strings.ToUpper(s)
	for i := 0; i < len(up); i++ {
		enc := glyph(up[i])
		if enc == "" {
			continue
		}
		ox := x + i*glyphAd*size/glyphH
		out.WriteString(strokes(enc, ox, y, size, i))
	}
	out.WriteString(`</g>`)
	return out.String()
}

// strokes turns one glyph's encoding into path elements at a position.
func strokes(enc string, ox, oy, size, idx int) string {
	var out strings.Builder
	for _, run := range strings.Split(enc, "|") {
		d := ""
		n := 0
		for j := 0; j+1 < len(run); j += 2 {
			gx := hexish(run[j])
			gy := hexish(run[j+1])
			if gx < 0 || gy < 0 {
				continue // a space inside an encoding is padding, not a point
			}
			// Scale from the grid to cap height, then nudge. The nudge is
			// at most one unit and comes from a fixed mix of the glyph
			// index and the point index, so it never changes between reads.
			px := ox + gx*size/glyphH
			py := oy + gy*size/glyphH
			px += wobble(idx*7 + j*3)
			py += wobble(idx*5 + j*11 + 1)
			if n == 0 {
				d += ufmt.Sprintf("M%d %d", px, py)
			} else {
				d += ufmt.Sprintf("L%d %d", px, py)
			}
			n++
		}
		if n > 1 {
			out.WriteString(`<path d="` + d + `"/>`)
		} else if n == 1 {
			// A single point would draw nothing without a round cap on a
			// zero-length path, which not every renderer honours. Give it
			// a hair of length instead.
			out.WriteString(`<path d="` + d + `l1 0"/>`)
		}
	}
	return out.String()
}

// wobble is a tiny deterministic offset in the range -1..1. Not random:
// the cards are regenerated on every read, and anything genuinely random
// would make the lettering shimmer.
func wobble(seed int) int {
	return (seed*2654435761)%3 - 1
}

// MarkerWidth is what MarkerText will occupy, so a caller can centre it.
// Counts every character including the ones that draw nothing, because a
// space still advances.
func MarkerWidth(s string, size int) int {
	if s == "" {
		return 0
	}
	return len(s) * glyphAd * size / glyphH
}

// MarkerCentred draws text centred on cx, which is what almost every
// caller here wants and what the SVG text-anchor attribute would have
// done for them if a font had been available.
func MarkerCentred(s string, cx, y, size int, colour string, weight int) string {
	return MarkerText(s, cx-MarkerWidth(s, size)/2, y, size, colour, weight)
}

package nsview

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Seasonal decoration, driven by DATA rather than by code.
//
// The card is generated on every read, so anything it draws can change
// after names have been sold. That makes a holiday overlay possible —
// snow in December, falling leaves in October — across every token at
// once. The temptation is to write a drawSnow() into this realm and a
// drawPumpkins() next year, which would make every new decoration a
// redeploy of the view.
//
// So it is parameterised instead. This realm knows how to draw drifting
// particles; WHICH particles, what colour, how many and until when live
// in a global that any admin call can rewrite. Christmas is then one
// transaction, not a deployment, and so is turning it off.
//
// Format, read from the global key `cardfx`:
//
//	dir:fall;n:22;c:#ffffff;c2:#dbeafe;s:3;d:9;until:1767225600
//
//	dir    fall | rise | burst    drift down, drift up, or fireworks
//	n      1..40                  how many
//	c      #rrggbb                colour (c2, c3 optional, cycled)
//	s      1..6                   pixel size
//	d      2..30                  seconds for one traverse (lower = faster)
//	sv     0..3                   size jitter, so they are not all identical
//	k      4..16                  sparks per shell, when dir is burst
//	sh     sq | leaf | petal      particle shape; leaf and petal are angled
//	until  unix seconds, 0 = no expiry
//
// `until` matters more than it looks: an overlay that expires on its own
// cannot be forgotten in January. Everything is parsed defensively and a
// malformed value yields NO overlay, for the same reason the sprite
// parser does — this markup lands inside a token that other people's
// software renders.
const keyFX = "cardfx"

func overlaySVG(now int64) string {
	return buildOverlay(nsdata.GetGlobal(keyFX), now)
}

// A SCHEDULE, so December snows without anybody remembering to make it.
//
// This is free in a way the treasury swap was not. That needed somebody
// to send a transaction, because a realm cannot act on its own. This
// needs nobody, because the card is generated on every read and can
// simply look at the clock — the decoration is a rendering decision, not
// an action.
//
// Rules are separated by "|" and the FIRST one whose window contains
// today wins, so put the specific ones first:
//
//	from:12-01;to:01-06;dir:fall;n:26;c:#ffffff|from:10-24;to:11-02;dir:rise;n:22;c:#f97316
//
// from/to are MM-DD and RECUR every year, which is the point — set it
// once and every December snows. A window whose start is after its end
// wraps the new year, so 12-01 to 01-06 is what you would expect rather
// than an empty range. A rule with no window is always eligible, so a
// bare spec still behaves as it did.
func pickRule(spec string, now int64) string {
	if spec == "" {
		return ""
	}
	t := time.Unix(now, 0).UTC()
	today := int(t.Month())*100 + t.Day()
	for _, rule := range strings.Split(spec, "|") {
		/* A WEEKDAY RULE, for the one date that is not a date.
		 *
		 * Friday the thirteenth falls one to three times a year and never
		 * on a schedule, so it cannot be written as a MM-DD window. `on`
		 * takes a weekday and an optional day-of-month — on:fri-13 — and
		 * is checked before the window fields so a rule can use either
		 * without the two interfering.
		 *
		 * Deliberately narrow: this is not a general calendar language,
		 * it is the one shape the existing one could not express. */
		if on := ruleField(rule, "on"); on != "" {
			if weekdayMatch(on, t) {
				return rule
			}
			continue
		}
		from := ruleField(rule, "from")
		to := ruleField(rule, "to")
		if from == "" && to == "" {
			return rule // no window: always eligible
		}
		f, okF := mmdd(from)
		e, okE := mmdd(to)
		if !okF || !okE {
			continue // a malformed window disables its rule, not the lot
		}
		if f <= e {
			if today >= f && today <= e {
				return rule
			}
		} else if today >= f || today <= e {
			// wraps the year end, e.g. 12-01 to 01-06
			return rule
		}
	}
	return ""
}

func ruleField(rule, key string) string {
	for _, part := range strings.Split(rule, ";") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) == 2 && strings.TrimSpace(kv[0]) == key {
			return strings.TrimSpace(kv[1])
		}
	}
	return ""
}

// mmdd reads "12-01" into 1201. Rejects anything that is not a real
// calendar date, so a typo cannot silently make a rule match all year.
func mmdd(s string) (int, bool) {
	if len(s) != 5 || s[2] != '-' {
		return 0, false
	}
	m, err1 := strconv.Atoi(s[:2])
	d, err2 := strconv.Atoi(s[3:])
	if err1 != nil || err2 != nil || m < 1 || m > 12 || d < 1 || d > 31 {
		return 0, false
	}
	return m*100 + d, true
}

func buildOverlay(spec string, now int64) string {
	spec = pickRule(spec, now)
	if spec == "" {
		return ""
	}
	dir := "fall"
	n := 0
	size := 3
	dur := 9
	jitter := 0
	sparks := 8
	shape := "sq"
	var until int64
	cols := []string{}

	for _, part := range strings.Split(spec, ";") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) != 2 {
			continue
		}
		k, v := strings.TrimSpace(kv[0]), strings.TrimSpace(kv[1])
		switch k {
		case "dir":
			if v == "fall" || v == "rise" || v == "burst" {
				dir = v
			}
		case "n":
			n = atoiClamp(v, 0, 40)
		case "s":
			size = atoiClamp(v, 1, 6)
		case "d":
			// Floor of 2, not 3: a 3-second traverse was the fastest the
			// card could go, and rain wants to be faster than snow by more
			// than that allows.
			dur = atoiClamp(v, 2, 30)
		case "sv":
			jitter = atoiClamp(v, 0, 3)
		case "k":
			sparks = atoiClamp(v, 4, 16)
		case "sh":
			if v == "sq" || v == "leaf" || v == "petal" {
				shape = v
			}
		case "until":
			if x, err := strconv.ParseInt(v, 10, 64); err == nil && x >= 0 {
				until = x
			}
		case "c", "c2", "c3":
			if isHexColour(v) {
				cols = append(cols, v)
			}
		}
	}

	if n <= 0 || len(cols) == 0 {
		return ""
	}
	// Expired decoration draws nothing, so a forgotten overlay retires
	// itself rather than snowing in July.
	if until > 0 && now >= until {
		return ""
	}

	if dir == "burst" {
		return fireworks(n, sparks, size, dur, cols)
	}

	var b strings.Builder
	b.WriteString(`<g opacity="0.85">`)
	for i := 0; i < n; i++ {
		// Deterministic scatter: the same token renders identically on
		// every read, which matters because a marketplace may cache it.
		h := hash(i)
		x := int(h % 392)
		delay := int(h/7) % (dur * 10)
		drift := int(h/13)%14 - 7
		wobble := dur + int(h/17)%5
		from, to := -12, 412
		if dir == "rise" {
			from, to = 412, -12
		}
		col := cols[i%len(cols)]
		// Not all the same size. Uniform particles read as a texture;
		// a little variation reads as depth, for two bytes of spec.
		px := size
		if jitter > 0 {
			px = size + int(h/23)%(jitter+1)
		}
		if shape == "sq" {
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s">`+
					`<animateTransform attributeName="transform" type="translate" `+
					`values="0 0;%d %d" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/></rect>`,
				x, from, px, px, col,
				drift, to-from, wobble, delay/10, delay%10))
			continue
		}
		// A shaped particle needs its own rotation, and an element can
		// carry only one transform. Animating the group and rotating the
		// shape inside it keeps the two independent — animating both on
		// one element would make each leaf drift along its own angle
		// instead of downward.
		b.WriteString(ufmt.Sprintf(
			`<g><animateTransform attributeName="transform" type="translate" `+
				`values="0 0;%d %d" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/>%s</g>`,
			drift, to-from, wobble, delay/10, delay%10,
			shapeAt(shape, x, from, px, int(h/31)%360, col)))
	}
	b.WriteString(`</g>`)
	return b.String()
}

// A small deterministic spread. Not random: the same index must always
// give the same particle, or a cached render and a fresh one disagree.
func hash(i int) int {
	h := (i+1)*2654435761 ^ 0x9e3779b9
	if h < 0 {
		h = -h
	}
	return h
}

func atoiClamp(s string, lo, hi int) int {
	v, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Fireworks: a shell climbs, vanishes, and throws sparks outward.
//
// The cost question is worth answering plainly, because it is the first
// decoration that is not one rect per particle. A shell is 1 rect for
// the climb plus k rects for the burst, so `n:5;k:10` is 55 rects — the
// same order as the 34 the rain already draws, and a fifth of the 128
// the domain sprite draws on every card anyway. None of it is stored:
// the card is built during a read, so this costs no gas and no storage,
// only the browser's time. That is the real ceiling, so the totals are
// capped below rather than left to whoever writes the spec.
//
// Two phases in one loop, driven by keyTimes on a single animation each,
// because a <set> chain or nested <g> would double the element count for
// the same picture.
func fireworks(shells, sparks, size, dur int, cols []string) string {
	if shells > 6 {
		shells = 6 // 6 x 16 sparks is already 102 rects
	}
	var b strings.Builder
	b.WriteString(`<g opacity="0.9">`)
	for i := 0; i < shells; i++ {
		h := hash(i * 7)
		x := 40 + int(h%340)         // keep the burst off the very edge
		burstY := 96 + int(h/11)%140 // where it stops climbing
		lift := 400 - burstY         // how far it climbs from the base
		// Shells are staggered across the cycle so they do not all go up
		// together, and each has its own colour from the palette.
		begin := int(h/29) % (dur * 10)
		// One colour per shell, not one per spark. A real firework is a
		// single charge, and mixing colours inside one burst reads as
		// confetti rather than pyrotechnics.
		col := cols[i%len(cols)]

		// The climb. Held at the top for the rest of the cycle rather
		// than looping straight away, and faded out at the moment of the
		// burst so the eye reads one event, not two objects.
		b.WriteString(ufmt.Sprintf(
			`<rect x="%d" y="400" width="%d" height="%d" fill="%s" opacity="0">`+
				`<animateTransform attributeName="transform" type="translate" `+
				`values="0 0;0 -%d;0 -%d" keyTimes="0;0.4;1" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/>`+
				`<animate attributeName="opacity" values="1;1;0;0" keyTimes="0;0.38;0.4;1" `+
				`dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/></rect>`,
			x, size, size, col, lift, lift, dur, begin/10, begin%10, dur, begin/10, begin%10))

		for j := 0; j < sparks; j++ {
			g := hash(i*97 + j*13)
			d := j * 16 / sparks // one of the 16 fixed directions
			r := 34 + int(g%34)  // how far this spark travels
			dx := r * dirCos[d] / 100
			dy := r * dirSin[d] / 100
			// Sparks fall as they fly, which is the whole difference
			// between a firework and a starburst.
			dy += r / 3
			px := size
			if int(g/7)%3 == 0 {
				px = size + 1 // a few brighter, bigger sparks per shell
			}
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s" opacity="0">`+
					`<animateTransform attributeName="transform" type="translate" `+
					`values="0 0;0 0;%d %d" keyTimes="0;0.4;1" dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/>`+
					`<animate attributeName="opacity" values="0;0;1;0" keyTimes="0;0.4;0.52;1" `+
					`dur="%ds" begin="-%d.%ds" repeatCount="indefinite"/></rect>`,
				x, burstY, px, px, col,
				dx, dy, dur, begin/10, begin%10, dur, begin/10, begin%10))
		}
	}
	b.WriteString(`</g>`)
	return b.String()
}

// Sixteen directions on a circle, as hundredths. A table rather than
// math.Sin: the same integers must come out on every node, and this is
// the whole of the trigonometry the card needs.
var (
	dirCos = [16]int{100, 92, 71, 38, 0, -38, -71, -92, -100, -92, -71, -38, 0, 38, 71, 92}
	dirSin = [16]int{0, 38, 71, 92, 100, 92, 71, 38, 0, -38, -71, -92, -100, -92, -71, -38}
)

// shapeAt draws one non-square particle at a position, turned to its own
// angle. Leaves and petals are two curves each rather than a polygon: a
// leaf is pointed at both ends, a petal is round at one, and that single
// difference is the whole of what distinguishes October from April.
//
// The numbers are derived from the particle size so `s` still means what
// it means everywhere else, and both shapes stay legible at the size a
// card is actually looked at.
func shapeAt(kind string, x, y, px, ang int, col string) string {
	w, hh := px, px*2
	switch kind {
	case "leaf":
		// Wider than a petal at the same size. A lens with its control
		// points at the particle width is a sliver, not a leaf.
		w = px * 3 / 2
		return ufmt.Sprintf(
			`<path d="M0 -%dQ%d 0 0 %dQ-%d 0 0 -%dZ" fill="%s" transform="translate(%d,%d) rotate(%d)"/>`,
			hh, w, hh, w, hh, col, x, y, ang)
	case "petal":
		return ufmt.Sprintf(
			`<ellipse rx="%d" ry="%d" fill="%s" transform="translate(%d,%d) rotate(%d)"/>`,
			w, hh, col, x, y, ang)
	}
	return ufmt.Sprintf(`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`, x, y, px, px, col)
}

// weekdayMatch reads "fri" or "fri-13": a weekday, optionally pinned to a
// day of the month. Anything it does not understand matches nothing, so a
// typo disables its own rule rather than firing every day.
func weekdayMatch(spec string, t time.Time) bool {
	day := ""
	dom := 0
	if at := strings.Index(spec, "-"); at > 0 {
		day = spec[:at]
		n, err := strconv.Atoi(spec[at+1:])
		if err != nil || n < 1 || n > 31 {
			return false
		}
		dom = n
	} else {
		day = spec
	}
	names := map[string]time.Weekday{
		"sun": time.Sunday, "mon": time.Monday, "tue": time.Tuesday,
		"wed": time.Wednesday, "thu": time.Thursday, "fri": time.Friday,
		"sat": time.Saturday,
	}
	want, ok := names[strings.ToLower(day)]
	if !ok {
		return false
	}
	if t.Weekday() != want {
		return false
	}
	return dom == 0 || t.Day() == dom
}

// Package nsview is the human-facing view — the third realm in the
// split, and the newest (2026-08-21).
//
// It exists because an adversarial review found three defects in the old
// Render(), which lived inside the permanent `nsdata` vault: unescaped
// profile text injected into the page markdown, an O(domains × names)
// home page any user could inflate into a permanent denial of service,
// and navigation links that 404'd. All three were display bugs, and none
// of them could ever have been fixed, because that realm is deployed
// exactly once. The NFT artwork moved here for the same reason.
//
// Display code is swappable now. This realm holds no state, reads
// everything from nsdata's exported API, and can be redeployed and
// re-pointed at any time with nothing to migrate.
package nsview

import (
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsskin/v1"
)

// Profile keys inside a name's extension slot. Conventions owned by this
// realm and the logic realm, not by the vault — the vault stores strings
// and has no opinion about what they mean.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
)

func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "token/"):
		return "```\n" + BuildSVG(strings.TrimPrefix(path, "token/")) + "\n```\n"
	/* nsskin.TokenURI hands out "/r/.../nsview:skin/<id>#<n>" and this
	   case did not exist, so every skin token resolved to the literal
	   string "404: unknown name" — splitTokenID found no "*", the whole
	   path became a label, and renderName 404'd. All 226 lines of
	   skincard.gno, including the matted frame and the SKIN label its
	   own header calls the mitigation for "the single most likely way
	   this product hurts somebody", never ran for anybody. */
	case strings.HasPrefix(path, "skin/"):
		return "```\n" + renderSkin(strings.TrimPrefix(path, "skin/")) + "\n```\n"
	default:
		// A domain page carries its cursor as "?after=<key>". Split it
		// off before the token id is parsed, or the cursor lands in the
		// label and every paged link 404s.
		route, after := path, ""
		if q := strings.Index(path, "?after="); q >= 0 {
			route, after = path[:q], path[q+len("?after="):]
		}
		label, domainLabel := splitTokenID(route)
		if label == "" {
			return renderDomain(domainLabel, after)
		}
		return renderName(label, domainLabel)
	}
}

func renderHome() string {
	out := "# Meme Name Service\n\n"
	out += ufmt.Sprintf("%d domains registered.\n\n", nsdata.CountDomains())
	for _, label := range splitCSV(nsdata.ListDomains()) {
		owner, _, _, _, _ := nsdata.GetDomainInfo(label)
		// The link target must carry the "*" prefix — Render dispatches a
		// bare label to renderName, which 404s. That was the old home
		// page's bug: every link on it was dead.
		/* NO COUNT HERE. This called nsdata.CountNames per domain, and
		   CountNames iterates that domain's whole key span — so the home
		   page was O(every name in the registry) on every single view,
		   and anyone could inflate it by registering names. That is the
		   exact denial of service this package's own doc comment says
		   forced the renderer out of the vault; moving it here made it
		   repairable and nobody repaired it. The count lives on the
		   domain's own page, which walks one domain and pages. */
		out += ufmt.Sprintf("- [*%s](*%s) — owner `%s`\n",
			label, label, owner.String())
	}
	return out
}

func renderDomain(domainLabel, after string) string {
	if !nsdata.DomainExists(domainLabel) {
		return "404: unknown domain\n"
	}
	owner, registered, expires, streak, frozen := nsdata.GetDomainInfo(domainLabel)
	status, _ := statusFields(expires, frozen)
	daysLine := remaining(expires, time.Now().Unix())

	out := ufmt.Sprintf("# *%s\n\n", domainLabel)
	out += ufmt.Sprintf("- owner: `%s`\n", owner.String())
	out += ufmt.Sprintf("- status: **%s** (%s)\n", status, daysLine)
	if frozen {
		out += "- **frozen**\n"
	}
	out += ufmt.Sprintf("- registered: %s\n", time.Unix(registered, 0).UTC().Format("2006-01-02"))
	out += ufmt.Sprintf("- renewal streak: %d year(s)\n\n", streak)

	/* PAGED. This listed every name under the domain in one pass and
	   built a markdown line for each, so a domain with enough names made
	   its own page too expensive to render — permanently, for everyone,
	   until this realm was redeployed. nsdata.ExportNames already pages;
	   nsmarket already uses the same cursor idea for listings. */
	out += renderDomainNames(domainLabel, after)
	return out
}

// namePage is how many names one domain page shows. Small enough that
// the work is bounded whatever the registry does, large enough that an
// ordinary domain is one page.
const namePage = 100

func renderDomainNames(domainLabel, after string) string {
	keys, next := nsdata.ExportNames(domainLabel, after, namePage)
	labels := splitCSV(keys)
	if len(labels) == 0 {
		if after == "" {
			return "## names under this domain\n\n_none yet_\n"
		}
		return "## names under this domain\n\n_no more_\n"
	}

	out := "## names under this domain\n\n"
	// ExportNames returns full tree keys ("domain*label"); the page wants
	// the label, which is everything after the separator.
	cut := len(domainLabel) + 1
	for _, k := range labels {
		label := k
		if len(k) > cut {
			label = k[cut:]
		}
		out += ufmt.Sprintf("- [%s*%s](%s*%s)\n", label, domainLabel, label, domainLabel)
	}
	if next != "" {
		out += ufmt.Sprintf("\n[more](*%s?after=%s)\n", domainLabel, next)
	}
	return out
}

/*
renderSkin draws a skin DEFINITION's own card, matted and labelled, from
a token id of the form "<definition>#<serial>".

Deliberately not the name card: a skin for sale and a name for sale must
not look alike, which is what skincard.gno's frame is for.
*/
func renderSkin(tid string) string {
	id := tid
	if h := strings.Index(tid, "#"); h > 0 {
		id = tid[:h]
	}
	if !nsskin.SkinExists(id) {
		return "404: unknown skin"
	}
	name, art, lock, _, _, _ := nsskin.SkinInfo(id)
	return SkinCardSVG(name, art, lock, !inkForArt(art))
}

func renderName(label, domainLabel string) string {
	if !nsdata.NameExists(label, domainLabel) {
		return "404: unknown name\n"
	}
	owner, registered, expires, streak, frozen, paid := nsdata.GetNameInfo(label, domainLabel)
	status, _ := statusFields(expires, frozen)
	daysLine := remaining(expires, time.Now().Unix())

	out := ufmt.Sprintf("# %s*%s\n\n", label, domainLabel)
	out += ufmt.Sprintf("- owner: `%s`\n", owner.String())
	out += ufmt.Sprintf("- status: **%s** (%s)\n", status, daysLine)
	if frozen {
		out += "- **frozen**\n"
	}
	if !paid {
		out += "- free tier (not sellable until upgraded)\n"
	}
	out += ufmt.Sprintf("- registered: %s\n", time.Unix(registered, 0).UTC().Format("2006-01-02"))
	out += ufmt.Sprintf("- renewal streak: %d year(s)\n\n", streak)
	out += ufmt.Sprintf("- [*%s](*%s)\n\n", domainLabel, domainLabel)

	displayName := nsdata.GetNameExtra(label, domainLabel, keyDisplayName)
	bio := nsdata.GetNameExtra(label, domainLabel, keyBio)
	website := nsdata.GetNameExtra(label, domainLabel, keyWebsite)

	if displayName != "" || bio != "" || website != "" {
		out += "## Profile\n\n"
		// Every one of these is attacker-authored. Escaping them is the
		// whole reason this realm exists separately.
		if displayName != "" {
			out += ufmt.Sprintf("**%s**\n\n", escapeMarkdown(displayName))
		}
		if bio != "" {
			// A blockquote so even a crafted multi-line bio cannot break
			// out into block-level constructs.
			out += "> " + escapeMarkdown(bio) + "\n\n"
		}
		if website != "" {
			if isSafeURL(website) {
				out += ufmt.Sprintf("[%s](%s)\n\n", escapeMarkdown(website), website)
			} else {
				out += ufmt.Sprintf("website (unverified): `%s`\n\n", escapeMarkdown(website))
			}
		}
	}
	return out
}

// -- helpers --

func splitCSV(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

// splitTokenID splits `label*domain`; a leading "*" yields an empty
// label, which is how a domain page is addressed.
func splitTokenID(tid string) (label, domain string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

// escapeMarkdown neutralises user-authored text so it renders as the
// literal characters typed rather than as markup. Backslash-escapes the
// CommonMark ASCII punctuation set and folds newlines, which stops
// headings, lists, tables, images, links, and raw HTML alike.
func escapeMarkdown(s string) string {
	s = strings.ReplaceAll(s, "\r\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", " ")
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if strings.IndexByte("\\`*_{}[]()#+-.!|<>&~\"'", c) >= 0 {
			b.WriteByte('\\')
		}
		b.WriteByte(c)
	}
	return b.String()
}

// isSafeURL only admits plain http/https. Everything else — javascript:,
// data:, anything unrecognised — is refused a live link. Checked on read
// rather than on write so tightening the rule later also applies to
// profiles that already exist.
func isSafeURL(u string) bool {
	if !strings.HasPrefix(u, "http://") && !strings.HasPrefix(u, "https://") {
		return false
	}
	if len(u) > 256 {
		return false
	}
	// This value is emitted RAW as the markdown link destination, so it is
	// the one attacker-authored string on the page that escapeMarkdown
	// does not neutralise. Allow-list instead of deny-list: every byte
	// must be printable, non-space ASCII. A deny-list missed newlines,
	// which let a crafted `website` terminate the link and inject
	// arbitrary markdown into the page below it.
	for i := 0; i < len(u); i++ {
		c := u[i]
		if c <= 0x20 || c >= 0x7f {
			return false
		}
		if strings.IndexByte("()<>\"'\\`", c) >= 0 {
			return false
		}
	}
	return true
}

package nsview

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

/*
THE SKIN'S OWN CARD — what a skin token looks like when it is the thing
being listed, rather than the thing decorating a name.

WHY IT EXISTS. A skin is a separate token (see SKINS.md §1), so it has
its own listing on any marketplace that shows it. Drawn the way a name
card is drawn — art edge to edge, big lettering over the top — the two
would be indistinguishable, and somebody would buy a picture believing
they had bought a name. That is not a subtle risk: it is the single most
likely way this product hurts somebody.

THE FRAME IS THE WHOLE IDEA. A name card is FULL BLEED; this one is
MATTED, with the art inset inside a border and bands of ground above and
below it. The distinction survives at thumbnail size, at a glance, with
no text read at all — which is the only size and attention a marketplace
grid actually gets. The word SKIN across the top is the confirmation, not
the mechanism.

IT NAMES ITSELF, and it says what it will not go on. An extension-locked
skin that does not say so is a support ticket per sale.

WHAT IT DELIBERATELY DOES NOT SHOW: a price, an edition number, a rarity,
or anything else that frames the object as an investment. That rule is
from the risk policy and it applies to the artwork as much as to the copy
on the site — the card travels to places our words do not.
*/

// The matte. A name card uses all 400; this one is inset, and the inset
// is the tell.
const (
	skinTop  = 74 // the band the word SKIN sits in
	skinFoot = 62 // the band the skin's own name sits in

	// THE ART IS SQUARE, and its size is whatever the SHORTER dimension
	// allows — which is the height, because the two label bands eat into
	// it and the sides only give up a margin.
	//
	// This started as "340 wide" and was wrong: 340 is what the width
	// allows, but only 264 of height remains once the bands are taken,
	// so the art ran 76px down into the footer and sat behind the skin's
	// own name. A square sprite drawn into a non-square box either
	// stretches or overflows, and both are worse than being smaller.
	skinBox = 400 - skinTop - skinFoot // 264
	// Centred on what is left, so the side margins come out equal.
	skinPad = (400 - skinBox) / 2 // 68
)

/*
skinArtSVG renders a sprite to fill a box, INFERRING THE GRID from the
data rather than assuming twelve.

spriteSVG hardcodes twelve in four places, which is right for the domain
artwork it was written for and wrong here: SKINS.md §2a offers 12, 16, 24
and 32, and the whole point of inferring is that one format then covers
every size and every sprite already on chain keeps working.

Validation is spriteSVG's, unchanged and unrelaxed, because it is not
merely a parser — it is the thing standing between community-authored
data and markup inside somebody else's wallet. Any violation rejects the
WHOLE sprite rather than skipping the bad part: a partial picture hides
the fault.
*/
func skinArtSVG(enc string, ox, oy, box int) string {
	if enc == "" {
		return ""
	}
	parts := strings.Split(enc, "|")
	n := len(parts) - 1
	if n < 4 || n > 64 {
		return ""
	}
	colours := map[string]string{}
	for _, entry := range strings.Split(parts[0], ",") {
		if len(entry) != 8 || entry[1] != '#' {
			return ""
		}
		if !isHexColour(entry[1:]) {
			return ""
		}
		colours[entry[:1]] = entry[1:]
	}

	/*
		EVERY CELL IS PLACED FROM ITS OWN EXACT BOUNDARY, never from an
		accumulated cell size.

		The obvious way — cell := box / n, then x*cell — truncates once
		and then repeats the error n times, so the art stops short of its
		own frame by up to n pixels. Scaling the cell by a thousand first
		does not fix it either: at n=12 in a 340 box the cell is 28.333,
		28333 x 12 is 339996, and the last column still lands a pixel
		inside the frame. Which is a full pixel of bare matte down one
		edge, and by eye it reads as a design choice rather than a bug.

		Computing each boundary as x*box/n instead makes the LAST one
		exactly n*box/n = box, at every grid size, with no accumulation
		to go wrong.

		RUNS OF ONE COLOUR BECOME ONE RECT, which SKINS.md §2a asked for
		before the grid went much past 32 and which the collection has now
		made urgent rather than tidy.

		Every painted cell used to emit its own <rect>, inside every
		wallet that renders the card. That is tolerable for a sprite of a
		thing and ruinous for a BACKGROUND: a vertical gradient is one
		colour per row, so a 32-wide one emitted 1,024 rects to draw 32
		distinct bands. Merging horizontal runs draws it in 32 — the same
		picture, pixel for pixel, at a thirty-second of the markup.

		It costs nothing when it does not apply. A busy sprite with no
		horizontal runs merges nothing and emits exactly what it did
		before.
	*/
	var b strings.Builder
	for y := 1; y <= n; y++ {
		row := parts[y]
		if len(row) != n {
			return ""
		}
		y0 := oy + (y-1)*box/n
		h := oy + y*box/n - y0
		for x := 0; x < n; {
			ch := row[x : x+1]
			if ch == "." {
				x++
				continue
			}
			c, ok := colours[ch]
			if !ok {
				return ""
			}
			// How far this colour runs.
			run := x + 1
			for run < n && row[run:run+1] == ch {
				run++
			}
			x0 := ox + x*box/n
			w := ox + run*box/n - x0
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`,
				x0, y0, w, h, c))
			x = run
		}
	}
	if b.Len() == 0 {
		return ""
	}
	return b.String()
}

/*
SkinCardSVG draws a skin token's own listing card.

	name   the skin's name, as the shop shows it
	art    the sprite string
	lock   the extension it is restricted to, or "" for one that goes
	       on any name
	light  true  = pale lettering on a dark matte
	       false = dark lettering on a pale matte

The return is a whole document rather than a fragment, because unlike the
nameplate this composites over nothing — it IS the card.
*/
func SkinCardSVG(name, art, lock string, light bool) string {
	ink, edge, matte := "#f4f4f5", "#26262b", "#0b0d10"
	if !light {
		ink, edge, matte = "#0b0d10", "#d4d4d8", "#f4f4f5"
	}

	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">`)
	b.WriteString(ufmt.Sprintf(`<rect width="400" height="400" fill="%s"/>`, matte))

	// THE WORD, big and flat across the top. Monospace and letter-spaced
	// so it reads as a label on the object rather than as a title for it.
	b.WriteString(ufmt.Sprintf(
		`<text x="%d" y="46" font-family="monospace" font-size="27" font-weight="bold"`+
			` letter-spacing="7" fill="%s">SKIN</text>`, skinPad, ink))

	// The art, inset, with a frame drawn AROUND it rather than over it —
	// a border that overlapped would eat a row of somebody's pixels.
	inner := skinArtSVG(art, skinPad, skinTop, skinBox)
	if inner == "" {
		// A skin whose art will not parse still has to render as
		// something, or the listing is a blank square with no clue why.
		b.WriteString(ufmt.Sprintf(
			`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s"`+
				` stroke-width="2" stroke-dasharray="7 6"/>`,
			skinPad, skinTop, skinBox, skinBox, edge))
		b.WriteString(ufmt.Sprintf(
			`<text x="200" y="%d" text-anchor="middle" font-family="monospace"`+
				` font-size="13" fill="%s">ART WILL NOT RENDER</text>`,
			skinTop+skinBox/2, edge))
	} else {
		b.WriteString(inner)
	}
	b.WriteString(ufmt.Sprintf(
		`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s" stroke-width="2"/>`,
		skinPad-1, skinTop-1, skinBox+2, skinBox+2, edge))

	// The skin's own name, and what it will not go on.
	b.WriteString(ufmt.Sprintf(
		`<text x="%d" y="%d" font-family="sans-serif" font-size="21" font-weight="bold"`+
			` fill="%s">%s</text>`,
		skinPad, 400-skinFoot+34, ink, esc(name)))

	tail := "goes on any name"
	if lock != "" {
		tail = "*" + lock + " names only"
	}
	b.WriteString(ufmt.Sprintf(
		`<text x="%d" y="%d" text-anchor="end" font-family="monospace" font-size="12"`+
			` letter-spacing="1" fill="%s">%s</text>`,
		400-skinPad, 400-skinFoot+34, edge, esc(strings.ToUpper(tail))))

	b.WriteString(`</svg>`)
	return b.String()
}

package nsview

import (
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsskin/v1"
)

/*
A NAME WEARING A SKIN — the card the shop actually sells.

Until this existed, a bought skin did nothing: nsskin held the token, the
binding and the art, and nsview had never heard of it. Somebody could buy
one, attach it, and look at their NFT to find the ordinary card. That is
the whole of what this file fixes.

ONE CALL DOES THE ASKING. nsskin.ArtForName answers "what should this
name be drawn with", with every condition already inside it — the name
wears a token, the definition is not withdrawn, the binding is pinned to
this registration, the lock still matches. A renderer that had to
remember four checks before drawing is one that eventually forgets one,
so it does not get the chance.

THE FACE AND THE INK ARE DERIVED, NOT STORED, and that is the
interesting part.

nsskin does not record them: DefineSkin takes an id, a name, a sprite, a
lock and an artist, and nothing else. Adding fields would mean a new
nsskin, and a new nsskin strands every token minted from the old one —
which by the time this was written already included somebody's purchase.
Stranding a paid-for object to store two values that can be worked out is
a bad trade.

So they are worked out. The ink comes from the art itself, which is
better than a stored value rather than merely cheaper: measured against
the sixty definitions in the launch collection, deriving it beat the
hand-picked value on ELEVEN cards and lost on none, and took the worst
contrast on any card from 1.5:1 to 4.7:1.
*/

/*
THE CROSSOVER IS AT 46, NOT 128, and getting that wrong is what made the
hand-picked values worse than this rule.

Contrast against white is 1.05/(L+0.05); against black it is
(L+0.05)/0.05. Setting them equal gives (L+0.05)^2 = 0.0525, so L = 0.179
— about 46 out of 255. Contrast is NOT symmetric about mid-grey: black
lettering on a mid-grey ground is far more readable than white on the
same ground, and a threshold at 128 hands eleven cards to the wrong ink.
*/
const inkCrossover = 46

// lumOf is relative luminance, 0..255, with a gamma of two.
//
// The real curve is sRGB's 2.4-with-a-linear-toe, which needs a pow().
// Squaring is within a couple of points of it across the whole range and
// is exact in integers — and this feeds a THRESHOLD, where being two
// points out only matters for a colour already sitting on the boundary,
// on which no ink is much better than the other anyway.
func lumOf(hex string) int {
	if len(hex) != 7 || hex[0] != '#' {
		return 128
	}
	r := hexPair(hex[1], hex[2])
	g := hexPair(hex[3], hex[4])
	b := hexPair(hex[5], hex[6])
	if r < 0 || g < 0 || b < 0 {
		return 128
	}
	return (2126*r*r + 7152*g*g + 722*b*b) / (10000 * 255)
}

func hexPair(a, b byte) int {
	hi, lo := hexDigit(a), hexDigit(b)
	if hi < 0 || lo < 0 {
		return -1
	}
	return hi*16 + lo
}

func hexDigit(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

/*
bandMedian is the luminance of what the lettering actually sits on.

THE MEDIAN, NOT THE MEAN, and the difference is not academic. A mean of
black and hot pink is a mid-grey that exists nowhere on the card, and it
sends the ink the wrong way on exactly the high-contrast patterns that
most need the right answer. A median is what most of the band is.

Three rows, because a line of type is taller than one cell at every grid
size offered. The middle seventy per cent of the width, because the name
is centred and the margins are not under it.
*/
func bandMedian(art string, num, den int) int {
	parts := strings.Split(art, "|")
	n := len(parts) - 1
	if n < 1 {
		return 128
	}
	colours := map[string]int{}
	for _, e := range strings.Split(parts[0], ",") {
		if len(e) == 8 && e[1] == '#' {
			colours[e[:1]] = lumOf(e[1:])
		}
	}
	y := (num*(n-1) + den/2) / den
	var vals []int
	for dy := -1; dy <= 1; dy++ {
		ry := y + dy
		if ry < 0 {
			ry = 0
		}
		if ry > n-1 {
			ry = n - 1
		}
		row := parts[ry+1]
		if len(row) != n {
			continue
		}
		lo, hi := n*15/100, n*85/100
		if hi > n-1 {
			hi = n - 1
		}
		for x := lo; x <= hi; x++ {
			if L, ok := colours[row[x:x+1]]; ok {
				vals = append(vals, L)
			}
		}
	}
	if len(vals) == 0 {
		return 128
	}
	// Insertion sort. At most about seventy values, and a realm has no
	// sort worth importing for that.
	for i := 1; i < len(vals); i++ {
		v := vals[i]
		j := i - 1
		for j >= 0 && vals[j] > v {
			vals[j+1] = vals[j]
			j--
		}
		vals[j+1] = v
	}
	return vals[len(vals)/2]
}

// inkForArt returns true for white lettering. The name's own band
// decides it alone: measured across the launch collection the date band
// never changed an outcome for the better, and letting it vote was what
// put white letters on a pale card.
func inkForArt(art string) bool {
	return bandMedian(art, 212, 400) < inkCrossover
}

/*
faceForArt picks one of the three generic families from the art itself.

Nothing about a background implies a typeface, so this is arbitrary — but
it must be arbitrary in the SAME WAY on the chain and in the shop, or the
preview shows a card that does not mint. Derived from the art rather than
stored for the same reason as the ink: it costs nothing and cannot drift.
*/
func faceForArt(art string) string {
	h := 2166136261
	for i := 0; i < len(art); i++ {
		h ^= int(art[i])
		h *= 16777619
		h &= 0x7fffffff
	}
	switch h % 3 {
	case 0:
		return "sans"
	case 1:
		return "serif"
	}
	return "mono"
}

/*
skinnedCardSVG is the whole card: the art edge to edge, the name over it.

FULL BLEED, unlike the skin's own listing card, which is matted. That
contrast is deliberate and load-bearing — it is what stops somebody
mistaking a skin for sale for a name for sale. See skincard.gno.

The ground behind the art matters because a sprite may have transparent
cells, and without it they would show whatever the viewer's page is,
which is not a colour we chose.
*/
func skinnedCardSVG(art, label, domain string, expires int64) string {
	light := inkForArt(art)
	ground := "#0b0d10"
	if !light {
		ground = "#f4f4f5"
	}
	inner := skinArtSVG(art, 0, 0, 400)
	if inner == "" {
		return "" // an unrenderable sprite falls back to the ordinary card
	}
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" role="img">` +
		`<rect width="400" height="400" fill="` + ground + `"/>` + inner +
		NameplateSVG(label, domain, faceForArt(art), "middle", light, expires) +
		`</svg>`
}

// skinFor a NAME, as opposed to skinFor the calendar. Separate because
// they answer different questions and only one of them involves money.
func wornArt(label, domain string) string {
	return nsskin.ArtForName(label, domain)
}

package nsview

import (
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
SKINS — the card becomes something else entirely for a day.

The decoration calendar already draws snow and embers ON TOP of a card.
A skin REPLACES it: on 22 May the token is a pizza, on 3 January it is a
newspaper. That is a different kind of change, so it is a different
field, and any date without one renders exactly as it always has.

HOW A CONTRACT KNOWS THE DATE AT ALL. It does not read a block height and
guess. Every block carries a timestamp in its header, agreed by consensus
the same way its transactions are, and `time.Now()` inside a realm returns
that block time. So a realm has a real clock, accurate to within a block
interval — which for a decoration that changes once a year is precision
nobody will ever notice. This is the same mechanism the seasonal overlay
has always used.

WHY THIS COSTS NOTHING TO RUN. The card is generated on every read rather
than fixed at mint, so a skin needs no transaction, no migration and
nobody awake at midnight. It applies to names sold years ago. Turning it
off is deleting one field from the calendar.

NO FONTS. Every renderer that shows these — wallets, marketplaces — puts
the SVG in a sandbox with no network, so a web font simply fails and
silently substitutes. Only the generic families resolve, which is why the
existing card says monospace and why these say serif or sans-serif. The
display faces in the mockups are a later job: an alphabet drawn as paths
and stored once, which is the only way to get identical letterforms on
every device.
*/

// skinFor returns the skin named by whichever calendar rule is active
// today, or "" for the ordinary card. Reusing pickRule means a skin
// obeys the same window rules, the same first-match-wins ordering and
// the same year wrapping as every other season.
func skinFor(now int64) string {
	return skinFromSpec(nsdata.GetGlobal(keyFX), now)
}

// Split out so the calendar logic can be tested against a spec directly,
// without standing up a vault to hold one.
func skinFromSpec(spec string, now int64) string {
	rule := pickRule(spec, now)
	if rule == "" {
		return ""
	}
	return ruleField(rule, "skin")
}

// hasSkin reports whether a name is renderable as this skin. Unknown
// names render nothing rather than a broken card — the same defensive
// stance the overlay parser takes, and for the same reason: this markup
// lands inside a token that other people's software renders.
func hasSkin(name string) bool {
	switch name {
	case "pizza", "paper", "cal", "fog", "slash", "pi", "heart":
		return true
	}
	return false
}

// seedOf turns a token id into a small number, so that a card can differ
// from the one beside it without any randomness — which a deterministic
// machine does not have. Every node computes the same answer for the same
// name, which is the requirement; looking arbitrary is merely the effect.
func seedOf(tid string) int {
	h := 2166136261
	for i := 0; i < len(tid); i++ {
		h ^= int(tid[i])
		h *= 16777619
		h &= 0x7fffffff
	}
	return h
}

// skinSVG renders a complete 400x400 card. Same frame as the ordinary
// one, so nothing downstream has to know which it received.
func skinSVG(name, tid string, now int64) string {
	label := tid
	if at := strings.Index(tid, "*"); at > 0 {
		label = tid
	}
	size := 34
	if len(label) > 14 {
		size = 22
	} else if len(label) > 10 {
		size = 27
	}
	switch name {
	case "pizza":
		return skinPizza(label, size, seedOf(tid))
	case "paper":
		return skinPaper(label, size, now)
	case "cal":
		return skinCal(label, size)
	case "fog":
		return skinFog(label, size)
	case "slash":
		return skinSlash(label, size)
	case "pi":
		return skinPi(label, size)
	case "heart":
		return skinHeart(label, size)
	}
	return ""
}

func head(bg string) string {
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" role="img">` +
		`<rect width="400" height="400" fill="` + bg + `"/>`
}

func foot() string {
	return `<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#ffffff" opacity="0.45">MINTED ON GNO.LAND</text></svg>`
}

/* ---------------- 22 May: the pizza ----------------
 *
 * Eight wedges with a gap between them, so it reads as CUT rather than
 * merely divided, and each wedge carries its own toppings inside its own
 * group — that is what makes a slice leave with its pepperoni still on
 * it instead of leaving them floating over the board.
 *
 * EVERY NAME EATS IN ITS OWN ORDER. The seed decides which slice goes
 * first and how long each one waits, so a marketplace full of these is a
 * room full of pizzas being eaten from different sides at different
 * rates rather than one animation repeated. It is derived from the token
 * id, so it is the same on every node and different for every name.
 */
func skinPizza(label string, size, seed int) string {
	var b strings.Builder
	b.WriteString(head("#2a2018"))
	b.WriteString(`<circle cx="200" cy="200" r="168" fill="#3a2c20"/>`)

	order := make([]int, 8)
	for i := range order {
		order[i] = i
	}
	// A deterministic shuffle: the seed walks the list and swaps.
	s := seed
	for i := 7; i > 0; i-- {
		s = (s*1103515245 + 12345) & 0x7fffffff
		j := s % (i + 1)
		order[i], order[j] = order[j], order[i]
	}

	for pos, idx := range order {
		a0 := float64(idx)*45 + 1.8
		a1 := float64(idx+1)*45 - 1.8
		// Each slice waits a little longer than the last, with the gap
		// itself varying by name so two cards never keep step.
		begin := 3 + pos*3 + (seed>>uint(pos))%4
		b.WriteString(`<g>`)
		b.WriteString(`<animate attributeName="opacity" values="1;1;0" keyTimes="0;0.5;1"`)
		b.WriteString(ufmt.Sprintf(` dur="%ds" begin="%ds" fill="freeze"/>`, 2, begin))
		b.WriteString(wedge(200, 200, 162, a0, a1, "#d9822b"))
		b.WriteString(wedge(200, 200, 143, a0+1.2, a1-1.2, "#f0b23c"))
		// Three toppings inside this wedge: one pepperoni, two herbs.
		for t := 0; t < 3; t++ {
			s = (s*1103515245 + 12345) & 0x7fffffff
			ang := a0 + 4 + float64(s%int(a1-a0-8))
			s = (s*1103515245 + 12345) & 0x7fffffff
			rad := 46 + float64(s%86)
			x, y := polar(200, 200, rad, ang)
			if t == 0 {
				b.WriteString(ufmt.Sprintf(`<circle cx="%d" cy="%d" r="13" fill="#b8342a"/>`, x, y))
			} else {
				b.WriteString(ufmt.Sprintf(
					`<rect x="%d" y="%d" width="13" height="13" rx="3" fill="#4e8b3a"/>`, x-6, y-6))
			}
		}
		b.WriteString(`</g>`)
	}
	b.WriteString(ufmt.Sprintf(
		`<text x="200" y="212" text-anchor="middle" font-family="sans-serif" font-size="%d"`+
			` font-weight="bold" fill="#2a1405">%s</text>`, size, esc(label)))
	b.WriteString(foot())
	return b.String()
}

func wedge(cx, cy int, r float64, a0, a1 float64, fill string) string {
	x0, y0 := polar(cx, cy, r, a0)
	x1, y1 := polar(cx, cy, r, a1)
	return ufmt.Sprintf(`<path d="M%d %d L%d %d A%d %d 0 0 1 %d %d Z" fill="%s"/>`,
		cx, cy, x0, y0, int(r), int(r), x1, y1, fill)
}

// Degrees clockwise from twelve o'clock, which is how a pizza is cut.
// Integer maths throughout: a realm has no floating point worth trusting
// across nodes, and a pizza does not need sub-pixel accuracy.
func polar(cx, cy int, r float64, deg float64) (int, int) {
	rad := (deg - 90) * 3.14159265 / 180
	return cx + int(r*cosApprox(rad)), cy + int(r*sinApprox(rad))
}

func sinApprox(x float64) float64 {
	for x > 3.14159265 {
		x -= 6.2831853
	}
	for x < -3.14159265 {
		x += 6.2831853
	}
	x2 := x * x
	return x * (1 - x2/6 + x2*x2/120 - x2*x2*x2/5040)
}

func cosApprox(x float64) float64 { return sinApprox(x + 1.5707963) }

/* ---------------- 3 Jan: the front page ---------------- */
func skinPaper(label string, size int, now int64) string {
	year := time.Unix(now, 0).UTC().Year()
	return head("#f4f0e4") +
		`<text x="200" y="66" text-anchor="middle" font-family="serif" font-size="30"` +
		` font-weight="bold" fill="#141210">THE LEDGER</text>` +
		`<line x1="40" y1="80" x2="360" y2="80" stroke="#141210" stroke-width="2"/>` +
		ufmt.Sprintf(`<text x="200" y="100" text-anchor="middle" font-family="monospace"`+
			` font-size="11" fill="#5a5348">3 JANUARY %d &#183; BLOCK ZERO</text>`, year) +
		ufmt.Sprintf(`<text x="200" y="176" text-anchor="middle" font-family="serif"`+
			` font-size="%d" font-weight="bold" fill="#141210">%s</text>`, size+6, esc(label)) +
		`<text x="200" y="214" text-anchor="middle" font-family="sans-serif" font-size="13"` +
		` fill="#39342c">The first block is mined. A chain begins.</text>` +
		`<text x="200" y="234" text-anchor="middle" font-family="sans-serif" font-size="13"` +
		` fill="#39342c">Years later somebody registers a name</text>` +
		`<text x="200" y="254" text-anchor="middle" font-family="sans-serif" font-size="13"` +
		` fill="#39342c">on it that does nothing at all.</text>` +
		`<line x1="40" y1="278" x2="360" y2="278" stroke="#b9b2a2" stroke-width="1"/>` +
		`<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#5a5348">MINTED ON GNO.LAND</text></svg>`
}

/* ---------------- 29 Feb: the calendar page ---------------- */
func skinCal(label string, size int) string {
	return head("#ffffff") +
		`<rect width="400" height="72" fill="#c0392b"/>` +
		`<text x="200" y="49" text-anchor="middle" font-family="sans-serif" font-size="26"` +
		` font-weight="bold" fill="#ffffff" letter-spacing="6">FEBRUARY</text>` +
		`<circle cx="150" cy="24" r="9" fill="#f7f4ee" stroke="#00000055" stroke-width="3"/>` +
		`<circle cx="250" cy="24" r="9" fill="#f7f4ee" stroke="#00000055" stroke-width="3"/>` +
		`<text x="200" y="252" text-anchor="middle" font-family="sans-serif" font-size="170"` +
		` font-weight="bold" fill="#e8e3d9">29</text>` +
		ufmt.Sprintf(`<text x="200" y="300" text-anchor="middle" font-family="monospace"`+
			` font-size="%d" font-weight="bold" fill="#1a1a1a">%s</text>`, size, esc(label)) +
		`<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#8a857a">MINTED ON GNO.LAND</text></svg>`
}

/* ---------------- 20 Apr: the fog ---------------- */
func skinFog(label string, size int) string {
	return head("#1d4028") +
		`<defs><radialGradient id="g"><stop offset="0" stop-color="#8fd48a"/>` +
		`<stop offset="0.68" stop-color="#3f7a4a"/><stop offset="1" stop-color="#1d4028"/>` +
		`</radialGradient><filter id="b"><feGaussianBlur stdDeviation="26"/></filter></defs>` +
		`<rect width="400" height="400" fill="url(#g)"/>` +
		`<g filter="url(#b)" opacity="0.5">` +
		`<circle cx="130" cy="140" r="90" fill="#ffffff" opacity="0.5">` +
		`<animate attributeName="cx" values="130;190;130" dur="18s" repeatCount="indefinite"/>` +
		`</circle>` +
		`<circle cx="280" cy="250" r="80" fill="#ffffff" opacity="0.35">` +
		`<animate attributeName="cy" values="250;200;250" dur="22s" repeatCount="indefinite"/>` +
		`</circle></g>` +
		ufmt.Sprintf(`<text x="200" y="212" text-anchor="middle" font-family="sans-serif"`+
			` font-size="%d" font-weight="bold" fill="#f2fff2">%s</text>`, size, esc(label)) +
		foot()
}

/* ---------------- Friday 13th: the poster ---------------- */
func skinSlash(label string, size int) string {
	return head("#15080a") +
		`<path d="M88 -20 L112 420 L96 420 L72 -20 Z" fill="#c42c24" opacity="0.85"/>` +
		`<path d="M252 420 L268 -20 L278 -20 L262 420 Z" fill="#8e1d18" opacity="0.7"/>` +
		ufmt.Sprintf(`<text x="200" y="212" text-anchor="middle" font-family="serif"`+
			` font-size="%d" font-weight="bold" fill="#d8342c">%s</text>`, size+4, esc(label)) +
		foot()
}

/* ---------------- 14 Mar: pi ---------------- */
func skinPi(label string, size int) string {
	digits := []string{
		"3.14159265358979323846", "26433832795028841971", "69399375105820974944",
		"59230781640628620899", "86280348253421170679", "82148086513282306647",
	}
	var b strings.Builder
	b.WriteString(head("#101418"))
	for i, row := range digits {
		b.WriteString(ufmt.Sprintf(
			`<text x="26" y="%d" font-family="monospace" font-size="30" fill="#2b4756">%s</text>`,
			70+i*56, row))
	}
	b.WriteString(`<rect x="52" y="176" width="296" height="52" rx="8" fill="#101418"/>`)
	b.WriteString(ufmt.Sprintf(
		`<text x="200" y="212" text-anchor="middle" font-family="monospace" font-size="%d"`+
			` font-weight="bold" fill="#eaf2f6">%s</text>`, size, esc(label)))
	b.WriteString(foot())
	return b.String()
}

/* ---------------- 14 Feb: the heart ----------------
 *
 * A real double thump, not one pulse: squeeze, small recoil, second
 * smaller squeeze, then a long rest. The rest is most of what makes it
 * read as a heartbeat rather than a throb.
 */
func skinHeart(label string, size int) string {
	return head("#fbe3ec") +
		`<g transform="translate(200,196)">` +
		`<animateTransform attributeName="transform" type="scale"` +
		` values="1;1.085;0.995;1.05;1;1" keyTimes="0;0.09;0.18;0.27;0.40;1"` +
		` dur="1.15s" repeatCount="indefinite" additive="sum"/>` +
		`<path transform="translate(-150,-140)" fill="#f7c3d5" stroke="#e39bb5" stroke-width="5"` +
		` d="M150 258 C66 198 24 150 24 102 A60 60 0 0 1 150 72 A60 60 0 0 1 276 102` +
		` C276 150 234 198 150 258 Z"/></g>` +
		ufmt.Sprintf(`<text x="200" y="212" text-anchor="middle" font-family="sans-serif"`+
			` font-size="%d" font-weight="bold" fill="#7e1f3d" letter-spacing="2">%s</text>`,
			size, esc(strings.ToUpper(label))) +
		`<text x="200" y="380" text-anchor="middle" font-family="monospace" font-size="10"` +
		` fill="#b03a62" opacity="0.7">MINTED ON GNO.LAND</text></svg>`
}

// Markup safety, same as everywhere else that puts a name into SVG: a
// label is validated on registration, but this is the last gate before
// it lands inside somebody else's renderer.
func esc(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

package nsview

import (
	"encoding/base64"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// The NFT artwork and every piece of display formatting live here, in a
// realm that can be redeployed, rather than in the vault that cannot.
// nsdata.TokenURI points at this realm through a settable prefix.

// TokenURI returns the full data: URI for a token, generated on every
// read so the image always reflects current state (never baked at mint).
func TokenURI(tid string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(BuildSVG(tid)))
}

// BuildSVG renders a token. Everything on the card derives from four
// stored values — owner, registered, expires, and the domain's drawing —
// so a renewal moves `expires` and the bar, the time remaining and the
// years held all follow from it. Nothing is baked at mint: the card is
// generated on every read, which is what lets a domain's artwork be
// changed after its names have been sold.
func BuildSVG(tid string) string {
	var registered, expires int64 // unix seconds
	var streak int64
	var frozen bool
	var domainLabel string

	if strings.HasPrefix(tid, "*") {
		label := tid[1:]
		if !nsdata.DomainExists(label) {
			return placeholderSVG("unknown")
		}
		_, registered, expires, streak, frozen = nsdata.GetDomainInfo(label)
		domainLabel = label
	} else {
		label, dom := splitTokenID(tid)
		if !nsdata.NameExists(label, dom) {
			return placeholderSVG("unknown")
		}
		_, registered, expires, streak, frozen, _ = nsdata.GetNameInfo(label, dom)
		domainLabel = dom
	}

	now := time.Now().Unix()
	// The three vault reads happen HERE, not inside cardSVG. That is what
	// leaves the card itself a pure function of its inputs, which is what
	// lets a test assert what a marketplace will show without standing up
	// a registry to do it.
	// A SKIN REPLACES THE CARD, so it is decided before anything is read
	// from the vault for drawing one. The ordinary path is untouched on
	// every other day of the year.
	/* A BOUGHT SKIN BEATS THE CALENDAR, and that ordering is a
	   decision rather than an accident. The calendar skin is a gift
	   everybody gets on the same day; a worn skin is a thing somebody
	   paid for and chose. On the two or three days a year they collide,
	   the one that was bought wins.

	   Only NAMES can wear one. A domain token has no owner to bind to
	   and no shop entry, so it takes the calendar path as before. */
	if !strings.HasPrefix(tid, "*") {
		label, dom := splitTokenID(tid)
		if art := wornArt(label, dom); art != "" {
			if card := skinnedCardSVG(art, label, dom, expires); card != "" {
				return card
			}
			// An unrenderable sprite falls through to the ordinary card
			// rather than returning nothing: a blank token is worse than
			// an unskinned one, and the holder still owns the name.
		}
	}

	if sk := skinFor(now); sk != "" && hasSkin(sk) {
		return skinSVG(sk, tid, now)
	}

	art := nsdata.GetDomainExtra(domainLabel, keyArt)
	return cardSVG(tid, art, registered, expires, streak, frozen, now, overlaySVG(now))
}

// cardSVG is the card itself, with every stored value already resolved.
// Split out from BuildSVG so the markup can be rendered — and asserted
// against — without a vault under it. TestStaticFrameShowsTheDate is the
// reason: what a marketplace shows as a still is a property of this
// string and of nothing else, and it deserves to be checked rather than
// assumed.
func cardSVG(tid, art string, registered, expires, streak int64, frozen bool, now int64, overlay string) string {
	accent := accentOf(art)
	status, edge := statusFields(expires, frozen)

	// The ribbon says something the rest of the card does not.
	// "DIAMOND HANDS" on a name minted this morning is a joke that lands
	// once; tied to tenure it is a thing you get TO.
	ribbon := status
	if status == "LIVE" {
		if streak >= 1 {
			ribbon = "DIAMOND HANDS"
		} else {
			ribbon = "FIRST YEAR"
		}
	}

	// The domain's drawing as a wash, centred: twelve cells at 26px is
	// 312 wide, so 44px of margin on every side.
	//
	// 0.07, not 0.12. At 0.12 a bright sprite competed with the name
	// sitting on top of it — the eye landed on the picture first and had
	// to hunt for the type. A wash should be felt rather than read.
	wash := spriteSVG(art, 26, 44, 44, "0.07")

	// The bar is the whole term, filled by how much of it is left.
	span := expires - registered
	if span < 1 {
		span = 1
	}
	left := expires - now
	if left < 0 {
		left = 0
	}
	if left > span {
		left = span
	}
	fill := (308 * left) / span

	heldLabel := "YEARS HELD"
	if streak == 1 {
		heldLabel = "YEAR HELD"
	}

	/* ---- SAYING IT IS DEAD, LOUDLY ----
	 *
	 * A lapsed card and a live card differed by a border colour and one
	 * word in 12px type at the very bottom. In a wallet's grid they read
	 * as the same purple card — for the one fact that changes what you
	 * can DO with the token: an expired name cannot be sold, cannot be
	 * transferred, and is about to belong to somebody else.
	 *
	 * A wash over the whole card in the status colour, and the status
	 * word on a filled band at nearly twice the size. The band sits at
	 * y=352 because the tenure caption is at 344 and a taller band ate
	 * it; a card that shouts LAPSED and hides how long somebody held it
	 * has traded one fact for another rather than adding one.
	 *
	 * A LIVE CARD IS UNTOUCHED. This must not make the ordinary case
	 * noisier — that is the card somebody paid for.
	 *
	 * Mirrored byte-for-byte in the site's nft.js. If this changes, that
	 * changes, or a preview stops matching what the chain draws. */
	metalDefs, frameStroke, frameWidth := metalFrame(tid, status, edge, streak)

	statusWash, statusBand := "", ""
	if status == "GRACE PERIOD" || status == "LAPSED" {
		washOp := "0.13"
		if status == "LAPSED" {
			washOp = "0.17"
		}
		statusWash = ufmt.Sprintf(
			`<rect width="400" height="400" fill="%s" opacity="%s"/>`, edge, washOp)
		statusBand = ufmt.Sprintf(
			`<rect x="12" y="352" width="376" height="36" fill="%s" opacity="0.92"/>`+
				`<rect x="12" y="352" width="376" height="36" fill="none" stroke="%s" stroke-width="3"/>`+
				`<text x="200" y="378" text-anchor="middle" font-family="monospace" `+
				`font-size="20" font-weight="bold" fill="#1b1200">%s</text>`,
			edge, edge, ribbon)
	}

	body := ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" role="img">
  %s<rect width="400" height="400" fill="#10101a"/>
  %s%s
  <rect x="12" y="12" width="376" height="376" rx="18" fill="none" stroke="%s" stroke-width="%s"/>
  <text x="30" y="42" font-family="monospace" font-size="10" fill="%s" opacity="0.7">MINTED ON GNO.LAND</text>
  <text x="370" y="42" text-anchor="end" font-family="monospace" font-size="10" fill="%s" opacity="0.7">SINCE %s</text>
  <text x="200" y="196" text-anchor="middle" font-family="monospace" font-size="%d" font-weight="bold" fill="#ffffff">%s</text>
  <!-- THE STATIC FRAME. A marketplace showing this token as a still
       gets whichever of these two lines is visible with no animation
       running, and that MUST be the date. Everything that matters about
       a name at a glance -- is it live, is it expired, when does it go
       -- is in the date; "412 days left" frozen into a thumbnail is a
       number that was true once and is a lie thereafter.

       It works out that way under both kinds of renderer, which is why
       it is written like this and not any other way:

         a renderer that IGNORES SMIL uses the base attribute in the
         markup, so the date's opacity="1" and the counter's opacity="0"
         decide it

         a renderer that HONOURS SMIL and seeks to t=0 uses the first
         keyTime, so the date's values="1;0" and the counter's "0;1"
         decide it

       Both must keep agreeing. Reorder these two lines, or drop an
       explicit opacity, and the still becomes a countdown -- with
       nothing failing and nothing to notice until a card in somebody
       else's gallery says a name has 412 days left three years from
       now. Guarded by TestStaticFrameShowsTheDate. -->
  <text x="200" y="224" text-anchor="middle" font-family="monospace" font-size="13" fill="%s" opacity="1">%s<animate attributeName="opacity" calcMode="discrete" values="1;0" keyTimes="0;0.5" dur="8s" repeatCount="indefinite"/></text>
  <text x="200" y="224" text-anchor="middle" font-family="monospace" font-size="13" fill="%s" opacity="0">%s<animate attributeName="opacity" calcMode="discrete" values="0;1" keyTimes="0;0.5" dur="8s" repeatCount="indefinite"/></text>
  <rect x="46" y="256" width="308" height="9" rx="4" fill="#ffffff" opacity="0.13"/>
  <rect x="46" y="256" width="%d" height="9" rx="4" fill="%s"/>
  <text x="46" y="282" font-family="monospace" font-size="9" fill="#ffffff" opacity="0.45">%s</text>
  <text x="354" y="282" text-anchor="end" font-family="monospace" font-size="9" fill="#ffffff" opacity="0.45">%s</text>
  <text x="200" y="326" text-anchor="middle" font-family="monospace" font-size="30" font-weight="bold" fill="#ffffff">%d</text>
  <text x="200" y="344" text-anchor="middle" font-family="monospace" font-size="9" fill="%s" opacity="0.8">%s</text>
  %s
  %s
</svg>`,
		metalDefs, wash, statusWash, frameStroke, frameWidth,
		accent, accent, time.Unix(registered, 0).UTC().Format("2006"),
		fitSize(tid), escapeXML(tid),
		accent, time.Unix(expires, 0).UTC().Format("Jan 2, 2006"),
		accent, remaining(expires, now),
		fill, edge,
		time.Unix(registered, 0).UTC().Format("Jan 2006"),
		time.Unix(expires, 0).UTC().Format("Jan 2006"),
		streak, accent, heldLabel,
		smallRibbon(status, edge, ribbon, statusBand),
		overlay)

	/* ---- GRACE AND LAPSED, LAYERED ON TOP ----
	 *
	 * Both branch OUT of `body` rather than building their own copy of
	 * it, on purpose: `body` above is untouched from before this pair of
	 * treatments existed, so a LIVE or FROZEN card -- the two states
	 * that are not supposed to change AT ALL -- takes neither branch and
	 * returns exactly the string it always returned. TestCardUnchangedForLiveAndFrozen
	 * pins that down against a captured pre-change baseline, which is a
	 * stronger guarantee than "I re-read the template and it looks
	 * right" for a template this dense.
	 *
	 * LAPSED only needs one more thing drawn on top, so it is one
	 * strings.Replace of the closing tag.
	 *
	 * GRACE needs three pieces of `body` re-wrapped in place -- the art
	 * wash, the frame-and-header block, and the term bar -- while the
	 * status band and the date line in between are left exactly where
	 * they are. That is done by locating each piece with a FIXED anchor
	 * string from the template above (never a byte offset, and never
	 * anything built from a dynamic value like a colour or a date, so a
	 * future edit to what's IN the template cannot silently point this
	 * at the wrong slice) and splicing a <g> around it. See heartbeat()
	 * and TestGraceHeartbeatLeavesBandAndDateAlone. */
	switch status {
	case "LAPSED":
		return strings.Replace(body, "</svg>", crackOverlay+"</svg>", 1)
	case "GRACE PERIOD":
		return graceHeartbeat(body, statusWash)
	default:
		return body
	}
}

// graceHeartbeat re-wraps three pieces of an already-built grace card in
// the failing-heartbeat flicker, leaving the status band and the date
// line between them untouched. See the "GRACE AND LAPSED, LAYERED ON
// TOP" comment in cardSVG for why this operates on the finished string
// rather than building a second template.
//
// Every anchor here is fixed template text, not a dynamic value, so it
// does not drift when a colour, a date or a name changes -- only when
// the template itself does, and TestGraceHeartbeatLeavesBandAndDateAlone
// would catch that (the -1 guards below make a missed anchor degrade to
// the plain card rather than a corrupted one).
func graceHeartbeat(body, statusWash string) string {
	const bgAnchor = `<rect width="400" height="400" fill="#10101a"/>` + "\n  "
	bgEnd := strings.Index(body, bgAnchor)
	frameStart := strings.Index(body, `<rect x="12" y="12" width="376" height="376" rx="18"`)
	commentStart := strings.Index(body, `<!-- THE STATIC FRAME`)
	barStart := strings.Index(body, `<rect x="46" y="256" width="308" height="9" rx="4" fill="#ffffff" opacity="0.13"/>`)
	bandStart := strings.Index(body, `<rect x="12" y="352"`)
	if bgEnd < 0 || frameStart < 0 || commentStart < 0 || barStart < 0 || bandStart < 0 {
		return body
	}
	washStart := bgEnd + len(bgAnchor)
	washRel := strings.Index(body[washStart:], statusWash)
	if washRel < 0 {
		return body
	}
	washEnd := washStart + washRel

	return body[:washStart] +
		heartbeat(body[washStart:washEnd]) + // the art wash alone
		body[washEnd:frameStart] + // statusWash, held steady
		heartbeat(body[frameStart:commentStart]) + // frame, MINTED/SINCE, the name
		body[commentStart:barStart] + // the STATIC FRAME comment + the date line, held steady
		heartbeat(body[barStart:bandStart]) + // the term bar, both dates, the held count
		body[bandStart:] // the status band onward, held steady
}

// fitSize solves for a size rather than stepping through a ladder.
// Monospace glyphs are ~0.6em, so a name up to the full 32-character
// limit sets on one line without overflowing 336px.
func fitSize(s string) int {
	n := len(s)
	if n < 1 {
		n = 1
	}
	size := 336 * 10 / (6 * n)
	// 40, not 34: the name is the thing somebody bought, and on a card
	// where the drawing sits behind it, the type has to be the loudest
	// object on the tile. Short names were leaving the middle of the card
	// half empty.
	if size > 40 {
		size = 40
	}
	if size < 11 {
		size = 11
	}
	return size
}

// domainAccent reads the accent out of the domain's stored drawing, so
// the card wears the domain's own colour without this realm carrying a
// palette of its own. Falls back to the house colour.
func domainAccent(domainLabel string) string {
	return accentOf(nsdata.GetDomainExtra(domainLabel, keyArt))
}

func accentOf(enc string) string {
	if len(enc) >= 8 && enc[1] == '#' && isHexColour(enc[1:8]) {
		return enc[1:8]
	}
	return "#5eead4"
}

func remaining(expires, now int64) string {
	if now >= expires {
		d := (now - expires) / daySeconds
		if d <= 0 {
			return "expired today"
		}
		if d == 1 {
			return "1 day past due"
		}
		return ufmt.Sprintf("%d days past due", d)
	}
	d := (expires - now) / daySeconds
	if d <= 0 {
		return "expires today"
	}
	if d == 1 {
		return "1 day remaining"
	}
	return ufmt.Sprintf("%d days remaining", d)
}

// keyArt is the per-domain extension key holding the drawing. The value
// is "A#facc15,B#7c2d12|............|....AAAA....|..." — the palette,
// then twelve rows of twelve characters where '.' is transparent.
//
// PARSED DEFENSIVELY AND NEVER TRUSTED. It is written by whichever logic
// realm is current, so a future one could store something malformed;
// anything unexpected yields no sprite rather than broken markup inside
// a token that a marketplace will render.
const keyArt = "art"

func spriteSVG(enc string, px, ox, oy int, opacity string) string {
	if enc == "" {
		return ""
	}
	parts := strings.Split(enc, "|")
	if len(parts) != 13 {
		return ""
	}
	// palette: "A#facc15,B#7c2d12"
	colours := map[string]string{}
	for _, entry := range strings.Split(parts[0], ",") {
		// key + "#" + six hex digits: "A#facc15" is EIGHT characters.
		// This read 7 and rejected every valid sprite; the test caught it.
		if len(entry) != 8 || entry[1] != '#' {
			return ""
		}
		key := entry[:1]
		hex := entry[1:]
		if !isHexColour(hex) {
			return ""
		}
		colours[key] = hex
	}
	var b strings.Builder
	for y := 1; y <= 12; y++ {
		row := parts[y]
		if len(row) != 12 {
			return ""
		}
		for x := 0; x < 12; x++ {
			ch := row[x : x+1]
			if ch == "." {
				continue
			}
			c, ok := colours[ch]
			if !ok {
				return ""
			}
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`,
				ox+(x*px), oy+((y-1)*px), px, px, c))
		}
	}
	if b.Len() == 0 {
		return ""
	}
	return `<g opacity="` + opacity + `">` + b.String() + `</g>`
}

func isHexColour(s string) bool {
	if len(s) != 7 || s[0] != '#' {
		return false
	}
	for i := 1; i < 7; i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

func placeholderSVG(msg string) string {
	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">`+
		`<rect width="400" height="400" fill="#10101a"/>`+
		`<text x="200" y="200" text-anchor="middle" font-family="monospace" font-size="18" fill="#666680">%s</text></svg>`,
		escapeXML(msg))
}

// statusFields formats a lifecycle state for display. Reads the grace
// period from nsdata rather than hardcoding it, so retuning the lifecycle
// is a config change and this stays correct.
// All lifecycle times are unix seconds, so this is integer arithmetic
// over a day constant rather than duration division.
const daySeconds = int64(24 * 60 * 60)

/* ---- THE METAL LADDER ----
 *
 * From the "Name States" study, 2026-08-23, where it was designed and
 * then not built for a fortnight. One rung per year held, carried by the
 * frame: 1 bronze, 2 silver, 3 gold, 4 platinum, 5+ diamond.
 *
 * THE LADDER IS PICKED FOR SEPARATION, not for what the metals are
 * worth. Brown, then cool grey, then yellow, then warm white, then
 * something that is not a metal at all. The obvious ladder — silver,
 * platinum, rhodium — is three whitish metals in a row, and nobody can
 * tell year two from year five across a grid of thumbnails. Platinum is
 * pulled deliberately WARM to keep it off the gold below it.
 *
 * The highlight travels faster at the higher rungs, so a longer-held
 * name reads as brighter as well as merely different.
 *
 * DIAMOND IS SATURATED AND KEEPS ITS WHITE. Fire in a real stone is
 * spectral colour separated BY white; take the white bands out and it
 * stops reading as a gem and starts reading as an oil slick.
 *
 * IT ADDS NO WORDS. The ribbon has said DIAMOND HANDS since year one and
 * at year five the card finally makes good on it. The domain's own
 * colour still runs through the type and the term bar, so a name reads
 * as its domain first and its tenure second.
 *
 * YEAR ZERO GETS NO METAL, which is the whole point of a ladder: if a
 * new name looked decorated, the rungs a name EARNS would mean nothing.
 *
 * Mirrored in the site's nft.js. These two move together or a preview
 * stops matching what the chain draws.
 */
type metal struct {
	dur   int
	stops string // already-rendered <stop> elements
}

func metalFor(streak int64) (metal, bool) {
	switch {
	case streak <= 0:
		return metal{}, false
	case streak == 1:
		return metal{13, `<stop offset="0%" stop-color="#3a1c0c"/><stop offset="32%" stop-color="#e6b088"/>` +
			`<stop offset="52%" stop-color="#b87333"/><stop offset="100%" stop-color="#3a1c0c"/>`}, true
	case streak == 2:
		return metal{11, `<stop offset="0%" stop-color="#3f4650"/><stop offset="32%" stop-color="#f1f5f9"/>` +
			`<stop offset="52%" stop-color="#aab4c0"/><stop offset="100%" stop-color="#3f4650"/>`}, true
	case streak == 3:
		return metal{9, `<stop offset="0%" stop-color="#6b2f0a"/><stop offset="32%" stop-color="#fde68a"/>` +
			`<stop offset="52%" stop-color="#f59e0b"/><stop offset="100%" stop-color="#6b2f0a"/>`}, true
	case streak == 4:
		return metal{9, `<stop offset="0%" stop-color="#6b6357"/><stop offset="30%" stop-color="#fbf7ef"/>` +
			`<stop offset="50%" stop-color="#ddd4c4"/><stop offset="100%" stop-color="#6b6357"/>`}, true
	default:
		return metal{5, `<stop offset="0%" stop-color="#0369a1"/><stop offset="16%" stop-color="#ffffff"/>` +
			`<stop offset="30%" stop-color="#22d3ee"/><stop offset="44%" stop-color="#ffffff"/>` +
			`<stop offset="58%" stop-color="#e879f9"/><stop offset="72%" stop-color="#ffffff"/>` +
			`<stop offset="86%" stop-color="#38bdf8"/><stop offset="100%" stop-color="#0369a1"/>`}, true
	}
}

/*
metalFrame returns the <defs>, the stroke and the stroke width for a
card, or the plain versions when no metal is earned.

THE METAL ONLY APPLIES TO A LIVE NAME. A gilded frame around a lapsed
card would celebrate a name that is about to belong to somebody else, and
it would fight the red wash that exists to say so. Grace and lapsed lose
the metal, which is itself information: the frame going plain is the
tenure visibly at risk.

THE GRADIENT ID CARRIES THE TOKEN. A Render() page draws many of these
into one document and SVG resolves url(#id) document-wide, so a fixed id
would make every card after the first wear the first card's metal. The
token id is unique by construction; it is sanitised because "*" and "-"
are not valid in an id.
*/
func metalFrame(tid, status, edge string, streak int64) (defs, stroke, width string) {
	m, ok := metalFor(streak)
	if !ok || status != "LIVE" {
		return "", edge, "3"
	}
	id := "m" + idSafe(tid)
	defs = ufmt.Sprintf(
		`<defs><linearGradient id="%s" x1="0" y1="0" x2="1" y2="1">%s`+
			`<animateTransform attributeName="gradientTransform" type="rotate" `+
			`from="0 .5 .5" to="360 .5 .5" dur="%ds" repeatCount="indefinite"/>`+
			`</linearGradient></defs>`, id, m.stops, m.dur)
	return defs, "url(#" + id + ")", "4"
}

// An XML id may not contain "*", and a name may not contain anything
// else that would need escaping — the registry's own label rules see to
// that — so one substitution is enough.
func idSafe(tid string) string {
	return strings.ReplaceAll(tid, "*", "-")
}

// The foot of the card: a quiet ribbon while the name is alive, the loud
// band once it is not. One function so the two cannot both be drawn.
func smallRibbon(status, edge, ribbon, band string) string {
	if band != "" {
		return band
	}
	return ufmt.Sprintf(
		`<text x="200" y="372" text-anchor="middle" font-family="monospace" `+
			`font-size="12" font-weight="bold" fill="%s">%s</text>`, edge, ribbon)
}

/* ---- FAILING HEARTBEAT (grace period) ----
 *
 * From the "Name States" study, 2026-08-23 -- the "Failing heartbeat"
 * treatment, built around pulses()/BURSTS/track() there. Bursts of two,
 * one, three and one flash at 0.02/0.30/0.55/0.80 of a 7.5s cycle read
 * as an unpredictable fault rather than an even, designed blink, so the
 * rhythm carries over unchanged. graceValues and graceKeyTimes below are
 * that generator's output for base=1, dip=0.25 -- computed once, not
 * rebuilt on every read, since a fixed rhythm shared by every grace card
 * on the chain has nothing left to vary.
 *
 * INVERTED FROM THE STUDY, and deliberately. There the track sits DARK
 * and briefly flashes LIT -- fine for something animating live in a
 * browser tab, useless for a marketplace that renders one still frame:
 * the base opacity in the markup and the first keyframe are BOTH the
 * dark value there, so a still render of that track is nearly
 * invisible. Here the rest state is fully lit -- opacity 1, exactly the
 * live card -- and the bursts are brief DIPS toward .25 instead, so
 * whichever still a renderer takes (the base attribute for one that
 * ignores SMIL, the first keyframe for one that honours it) lands on
 * the fully-lit card. graceValues therefore reads "1;1;0.25;..." and
 * graceKeyTimes starts "0.0000;...": both a "1" at index zero, on
 * purpose. TestGraceHeartbeatLeavesBandAndDateAlone checks exactly that.
 *
 * Mirrored in the site's nft.js (pulseTrack/heartbeat there, same two
 * numbers). If this changes, that changes, or a preview stops matching
 * what the chain draws.
 */
const graceValues = "1;1;0.25;0.25;1;1;0.25;0.25;1;1;0.25;0.25;1;1;0.25;0.25;1;1;0.25;0.25;1;1;0.25;0.25;1;1;0.25;0.25;1;1"
const graceKeyTimes = "0.0000;0.0200;0.0240;0.0350;0.0390;0.0570;0.0610;0.0720;0.0760;0.3000;0.3040;0.3150;0.3190;0.5500;0.5540;0.5650;0.5690;0.5870;0.5910;0.6020;0.6060;0.6240;0.6280;0.6390;0.6430;0.8000;0.8040;0.8150;0.8190;1.0000"

// heartbeat wraps one piece of a grace card in the failing-heartbeat
// flicker. Called three separate times in graceHeartbeat rather than
// once around the whole card, so the status band and the date line can
// sit between the wrapped pieces untouched. Every call shares the same
// values/keyTimes/dur; SMIL times every <animate> from document load, so
// three separate <g>s stay in lockstep without needing to share one.
func heartbeat(inner string) string {
	return `<g opacity="1">` + inner +
		`<animate attributeName="opacity" values="` + graceValues +
		`" keyTimes="` + graceKeyTimes + `" dur="7.5s" repeatCount="indefinite"/></g>`
}

/* ---- CRACKED (lapsed) ----
 *
 * From the same study, under LAPSED. Static, no animation: a fracture
 * across the glass with two short branches, drawn last so it sits over
 * everything else on the card; the art behind it is untouched and
 * undimmed.
 *
 * THE STUDY'S PATH IS NOT USED AS-IS. Its middle segment runs through
 * x=140-176 at y=168-214 -- dead centre, right through where the name
 * sits on the study's fixed-width demo cards. That is not fine here:
 * the name is centred on x=200 with text-anchor="middle" and can run up
 * to 32 characters (see fitSize), so its box can span nearly the full
 * card width -- as far out as roughly x=30 to x=370 -- for a long one.
 * No amount of routing the crack sideways dodges that band, because a
 * long enough name is somewhere underneath any vertical line drawn
 * across it.
 *
 * So the crack is drawn as two pieces rather than one continuous line:
 * an upper fracture that stays above y=158 and a lower one that stays
 * below y=224, leaving the name's row (166-206) and the date line under
 * it (214-228) untouched regardless of how long the name is. It reads
 * as the fracture running into the nameplate and continuing on the far
 * side, rather than through it -- arguably truer to how a crack behaves
 * against a raised, painted surface anyway. Other type on the card (the
 * term bar, the held count) is still legitimately crossed, same as in
 * the study; only the name and the date get the gap.
 *
 * Mirrored byte-for-byte in the site's nft.js (CRACK_OVERLAY there).
 */
const crackOverlay = `<g stroke="#ffffff" fill="none" opacity="0.5" stroke-width="2">` +
	`<path d="M92 24 L150 72 L112 118 L162 152"/>` +
	`<path d="M112 118 L54 138"/>` +
	`<path d="M158 224 L206 270 L172 318 L228 388"/>` +
	`<path d="M172 318 L268 300"/>` +
	`</g>` +
	`<g stroke="#000000" fill="none" opacity="0.35" stroke-width="4">` +
	`<path d="M94 26 L152 74 L114 120 L164 154"/>` +
	`<path d="M160 226 L208 272 L174 320 L230 390"/>` +
	`</g>`

func statusFields(expires int64, frozen bool) (status, edge string) {
	if frozen {
		return "FROZEN", "#8888aa"
	}
	now := time.Now().Unix()
	grace := nsdata.GetGracePeriod()
	switch {
	case now < expires:
		return "LIVE", "#4ade80"
	case now < expires+grace:
		return "GRACE PERIOD", "#facc15"
	default:
		return "LAPSED", "#f87171"
	}
}

func escapeXML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	return s
}

package nsmarket

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// The house fee, expressed the same way the pricing rules are so there
// is one convention on this project and not two:
//
//	"1000000"  a flat amount in ugnot — 1 GNOT
//	"%3"       three percent of the sale
//	"%2.5"     two and a half percent; one decimal place is honoured
//
// Stored in the vault as a global so it can be changed without
// redeploying anything, read fresh on every sale so a change takes
// effect immediately rather than at the next deploy.
const (
	keyFee     = "marketfee"
	defaultFee = "1000000" // 1 GNOT

	// A flat fee is a percentage in disguise on a cheap name: 1 GNOT on
	// a 0.5 GNOT sale is 200%. Rather than forbid cheap listings or let
	// a seller be charged more than they earn, the fee is capped at half
	// the sale. The listing screen shows the seller the actual number
	// before they sign, which is the part that matters.
	maxFeeBps = int64(5000) // 50%
	bpsDenom  = int64(10000)
)

func FeeSpec() string {
	if v := nsdata.GetGlobal(keyFee); v != "" {
		return v
	}
	return defaultFee
}

// SetFee changes it. Admin only, and validated here rather than trusted,
// because a malformed spec would otherwise be read on every sale and
// silently resolve to zero.
/*
SetFee CANNOT WORK FROM HERE, and saying so is the fix.

nsdata.SetGlobalRecord opens with assertIsTrustedLogic, and this realm is
deliberately outside the trusted set — types.gno says so in capitals, and
the deploy panel actively revokes anything but nslogic. So every call
here passed its own admin check and its own validation and then panicked
inside the vault, for everybody, including the correct admin. A dead
control that reads as live is worse than no control: it fails at signing
time, during the incident that prompted reaching for it.

Granting nsmarket vault trust to fix this would surrender the property
the whole realm is built around. So the setter moved to nslogic, which
already has the grant, and runs the same parseFee validation there.
*/
func SetFee(cur realm, spec string) {
	panic("nsmarket: fees are set with nslogic.SetMarketFee — this realm has no vault privileges and never did")
}

// parseFee returns (flat ugnot, basis points, error). Exactly one of the
// first two is non-zero.
func parseFee(spec string) (int64, int64, string) {
	spec = strings.TrimSpace(spec)
	if spec == "" {
		return 0, 0, ""
	}
	if !strings.HasPrefix(spec, "%") {
		n, err := strconv.ParseInt(spec, 10, 64)
		if err != nil || n < 0 {
			return 0, 0, "fee must be an amount in ugnot or a percentage like %2.5 — got " + spec
		}
		return n, 0, ""
	}

	// A percentage, carried as basis points so "%2.5" is expressible
	// without floating point anywhere near money.
	body := spec[1:]
	whole, frac := body, ""
	if dot := strings.Index(body, "."); dot >= 0 {
		whole, frac = body[:dot], body[dot+1:]
	}
	if whole == "" {
		whole = "0"
	}
	w, err := strconv.ParseInt(whole, 10, 64)
	if err != nil || w < 0 {
		return 0, 0, "bad percentage — " + spec
	}
	bps := w * 100
	if frac != "" {
		if len(frac) > 1 {
			return 0, 0, "one decimal place at most — " + spec
		}
		f, err2 := strconv.ParseInt(frac, 10, 64)
		if err2 != nil || f < 0 {
			return 0, 0, "bad percentage — " + spec
		}
		bps += f * 10
	}
	if bps > maxFeeBps {
		return 0, 0, "a fee above 50% is not a marketplace — " + spec
	}
	return 0, bps, ""
}

// FeeFor is what the house takes on a sale at this price, and what the
// seller is left with. Exported so the listing screen can show both
// before anybody signs — a fee somebody discovers afterwards is a fee
// they were not told about.
func FeeFor(price int64) (fee, toSeller int64) {
	if price <= 0 {
		return 0, 0
	}
	flat, bps, err := parseFee(FeeSpec())
	if err != "" {
		return 0, price // an unreadable spec charges nothing; it never overcharges
	}
	if bps > 0 {
		fee = price * bps / bpsDenom
	} else {
		fee = flat
	}
	// The cap, applied last, so it bounds a flat fee and a percentage
	// alike however the spec was written.
	if ceiling := price * maxFeeBps / bpsDenom; fee > ceiling {
		fee = ceiling
	}
	if fee < 0 {
		fee = 0
	}
	return fee, price - fee
}

func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != nsdata.GetAdmin() {
		panic("nsmarket: restricted to project admin")
	}
}

package nsmarket

import (
	"strings"
	"time"

	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsnft/v1"
)

// List puts a name up for sale at a price in ugnot.
//
// It does NOT take the name. The seller keeps it, keeps using it, and
// keeps the right to change their mind — revoking the approval kills the
// listing without needing this realm's cooperation at all.
//
// The approval is required BEFORE listing rather than checked only at
// sale time, so a listing that could never complete cannot exist. A
// buyer finding out at the checkout that the seller never approved
// anything is the worst moment to find out.
// assertNotFrozen — the freeze has to bind here too.
//
// nsnft refuses to move a frozen name — the freeze is a hold on the token
// — which already stops a sale from completing. This check exists so it stops EARLIER: a frozen name
// should not sit on the marketplace advertising itself, and a buyer
// should not discover the problem by having their transaction panic
// after they have chosen to pay.
//
// The bit comes from GetNameInfo, which has always returned it.
func assertNotFrozen(label, domainLabel string) {
	_, _, _, _, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
	if frozen {
		panic("nsmarket: this name is frozen and cannot be listed or sold")
	}
}

func List(cur realm, tid string, price int64) {
	assertNoSend()
	seller := cur.Previous().Address()
	label, domainLabel := splitTokenID(tid)
	if label == "" || domainLabel == "" {
		panic("nsmarket: a token id looks like label*domain")
	}
	if strings.HasPrefix(tid, "*") {
		panic("nsmarket: domains are project-owned and not for sale")
	}
	if price < minPrice || price > maxPrice {
		panic("nsmarket: price out of range")
	}
	assertNotFrozen(label, domainLabel)
	if !nsdata.NameExists(label, domainLabel) {
		panic("nsmarket: no such name")
	}
	if nsdata.GetNameOwner(label, domainLabel) != seller {
		panic("nsmarket: only the owner may list a name")
	}
	// An expired name cannot be transferred, so it cannot be sold. Saying
	// so here rather than letting somebody list it and take an offer.
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nsmarket: this name has expired — renew it before selling it")
	}
	if !nsdata.IsNamePaid(label, domainLabel) {
		panic("nsmarket: a free-tier name cannot be sold — upgrade it first")
	}
	// A hold for any other reason — frozen is the one today — stops the
	// listing here rather than at checkout. nsnft would refuse the
	// transfer anyway; a buyer should not find out by paying.
	if nsnft.IsLocked(tid) {
		panic("nsmarket: this name is held by the registry and cannot be sold")
	}
	if !approvedTo(cur.Address(), seller, tid) {
		panic("nsmarket: approve the marketplace for this name first, so a sale can complete in one transaction")
	}

	_, registered, _, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	listings.Set(tid, &Listing{seller: seller, price: price,
		listed: time.Now().Unix(), registered: registered, epoch: nsnft.Epoch(tid)})
	chain.Emit("Listed", "tid", tid, "price", ufmt.Sprintf("%d", price), "seller", seller.String())
}

// Unlist withdraws a listing. The seller, or the admin for a name that
// should not be on sale at all — the same manual lever the takedown
// process already relies on elsewhere.
func Unlist(cur realm, tid string) {
	assertNoSend()
	caller := cur.Previous().Address()
	l := get(tid)
	if l == nil {
		panic("nsmarket: not listed")
	}
	if caller != l.seller && caller != nsdata.GetAdmin() {
		panic("nsmarket: only the seller may withdraw a listing")
	}
	listings.Remove(tid)
	chain.Emit("Unlisted", "tid", tid)
}

// Buy completes a sale in the buyer's own transaction.
//
// Order matters here. Everything that can refuse the sale is checked
// before a single coin moves, and the name moves before the money does,
// so there is no arrangement of failures that leaves the seller paid and
// the buyer empty-handed. A panic anywhere reverts all of it.
func Buy(cur realm, tid string) {
	if !cur.Previous().IsUserCall() {
		panic("nsmarket: only direct wallet calls may buy")
	}
	buyer := cur.Previous().Address()
	l := get(tid)
	if l == nil {
		panic("nsmarket: not listed")
	}
	label, domainLabel := splitTokenID(tid)
	assertNotFrozen(label, domainLabel)

	// The world can have moved since the listing was written. Each of
	// these is a real thing that happens, not a defensive flourish: the
	// seller can transfer the name elsewhere, let it lapse, or revoke
	// the approval, and none of those tell this realm about it.
	if nsdata.GetNameOwner(label, domainLabel) != l.seller {
		listings.Remove(tid)
		panic("nsmarket: this name has changed hands since it was listed — the listing is gone")
	}
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nsmarket: this name has expired; it cannot be transferred")
	}
	/* SAME NAME, SAME REGISTRATION. Owner and validity both match after
	   a lapse-and-self-re-registration, because it is genuinely the same
	   person holding the same label — but it is not the same asset the
	   listing was written against, and the seller has already paid to
	   get it back once. Listings written before this field existed carry
	   zero, which is treated as unpinned rather than as a mismatch, so
	   nothing already on the market is stranded by the upgrade. */
	if l.registered != 0 {
		_, registered, _, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
		if registered != l.registered {
			listings.Remove(tid)
			panic("nsmarket: this name lapsed and was registered again since it was listed — the listing is gone")
		}
	}
	// Same ownership epoch — see Listing.epoch for the buy-back case this
	// is the only check that catches.
	if l.epoch != 0 && l.epoch != nsnft.Epoch(tid) {
		listings.Remove(tid)
		panic("nsmarket: this name has changed hands since it was listed — the listing is gone")
	}
	if !approvedTo(cur.Address(), l.seller, tid) {
		listings.Remove(tid)
		panic("nsmarket: the seller has withdrawn permission — the listing is gone")
	}
	if buyer == l.seller {
		panic("nsmarket: you already own this")
	}

	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nsmarket: only ugnot is accepted, got: " + c.Denom)
		}
	}
	paid := sent.AmountOf(ugnot)
	if paid < l.price {
		panic(ufmt.Sprintf("nsmarket: %d ugnot short of the asking price", l.price-paid))
	}

	// The name first. If this fails nothing has been paid out yet, and
	// the revert takes the buyer's coins back with it.
	//
	// ON nsnft, AS THE APPROVED OPERATOR — exactly the call any external
	// marketplace makes. This realm has no privileged transfer path, which
	// is the point: the sale is only possible because the seller approved
	// this realm on the ledger, and revoking that approval there kills
	// the listing without our cooperation.
	nsnft.TransferFrom(cross(cur), l.seller, buyer, tid)

	fee, toSeller := FeeFor(l.price)
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	self := cur.Address()
	if toSeller > 0 {
		b.SendCoins(self, l.seller, chain.Coins{chain.NewCoin(ugnot, toSeller)})
	}
	if fee > 0 {
		b.SendCoins(self, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, fee)})
	}
	if excess := paid - l.price; excess > 0 {
		b.SendCoins(self, buyer, chain.Coins{chain.NewCoin(ugnot, excess)})
	}

	listings.Remove(tid)
	sold++
	chain.Emit("Sold", "tid", tid, "price", ufmt.Sprintf("%d", l.price),
		"seller", l.seller.String(), "buyer", buyer.String(),
		"fee", ufmt.Sprintf("%d", fee))
}

// -- helpers --

func get(tid string) *Listing {
	v := listings.Get(tid)
	if v == nil {
		return nil
	}
	return v.(*Listing)
}

// Whether this realm may move that token on the seller's behalf. Either
// form of GRC-721 permission counts: approved for the one token, or an
// operator for everything the seller holds.
//
// `self` is threaded in from the caller rather than looked up, because a
// realm can only learn its own address from its own `cur`.
func approvedTo(self, seller address, tid string) bool {
	/* THE OPERATOR CHECK GOES FIRST, and that ordering is the whole fix.
	   nsdata.GetApproved PANICS for a token with no per-token approval
	   rather than returning the zero address, so putting it first made
	   the line below unreachable: a seller who granted blanket
	   permission with SetApprovalForAll and called List got a raw vault
	   panic, and the comment above claiming either form counts was
	   false. Asking the total question first makes it true. */
	if nsdata.IsApprovedForAll(seller, self) {
		return true
	}
	return nsdata.GetApproved(tid) == self
}

func splitTokenID(tid string) (label, domainLabel string) {
	at := strings.Index(tid, "*")
	if at < 1 || at == len(tid)-1 {
		return "", ""
	}
	return tid[:at], tid[at+1:]
}

// This realm takes no payment on anything except Buy.
func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("nsmarket: this function takes no payment; do not attach coins")
	}
}

package nsmarket

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsnft/v1"
)

// Reads for the site. Rows are ";"-separated records of
// "label*domain,price,seller,listed,live" where `live` is false when the
// listing has gone stale under it — the seller moved the name, let it
// lapse, or revoked permission.
//
// Stale listings are REPORTED, not hidden and not silently deleted.
// Hiding them makes a seller's page lie about what they have up; and
// deleting them would mean a read function writing to storage, which is
// how a query starts costing gas.

func row(tid string, l *Listing) string {
	label, domainLabel := splitTokenID(tid)
	live := nsdata.NameExists(label, domainLabel) &&
		nsdata.GetNameOwner(label, domainLabel) == l.seller &&
		nsdata.IsNameValid(label, domainLabel) &&
		(l.epoch == 0 || l.epoch == nsnft.Epoch(tid))
	return ufmt.Sprintf("%s,%d,%s,%d,%t", tid, l.price, l.seller.String(), l.listed, live)
}

// GetListing returns one row, or "" when nothing is listed.
func GetListing(tid string) string {
	l := get(tid)
	if l == nil {
		return ""
	}
	return row(tid, l)
}

// ListForSale pages through everything on offer, cheapest first within a
// page. `after` is the last token id of the previous page.
func ListForSale(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	var out []string
	var last string
	listings.Iterate(after, "", func(key string, v any) bool {
		if key == after {
			return false // the cursor is exclusive
		}
		out = append(out, row(key, v.(*Listing)))
		last = key
		return len(out) >= limit
	})
	if len(out) < limit {
		last = "" // the end; no cursor to hand back
	}
	return strings.Join(out, ";"), last
}

// ListingsBy is everything one wallet has up for sale. Walks the whole
// tree because listings are keyed by token id, not by seller: a second
// index would be a second thing to keep correct and a second thing the
// seller pays storage for, to save a walk over a list that is small by
// construction.
func ListingsBy(seller address) string {
	var out []string
	listings.Iterate("", "", func(key string, v any) bool {
		l := v.(*Listing)
		if l.seller == seller {
			out = append(out, row(key, l))
		}
		return false
	})
	return strings.Join(out, ";")
}

func CountListed() int64 { return int64(listings.Size()) }
func CountSold() int64   { return sold }

// Quote is what a buyer pays and what the seller receives, before
// anybody signs anything. The fee is read live, so this is the same
// arithmetic Buy will do rather than a copy of it that can drift.
func Quote(tid string) (price, fee, toSeller int64) {
	l := get(tid)
	if l == nil {
		return 0, 0, 0
	}
	f, s := FeeFor(l.price)
	return l.price, f, s
}

// Version lets the site tell which shape it is talking to without
// guessing from a function signature.
func Version() string { return "v1" }

// nsmarket — names for sale, without anybody holding anything.
//
// HOW A SALE WORKS, and why it is built this way.
//
// The seller keeps their name. Listing does not move it here: it records
// an asking price and relies on the GRC-721 approval the seller has
// already granted this realm. Ownership does not change until somebody
// buys, and the seller can walk away at any moment by revoking the
// approval — at which point the listing simply stops working.
//
// The buyer's money is never held either. Buy is ONE call: it checks the
// listing still stands, moves the name, pays the seller, takes the fee,
// refunds any overpayment. All of it inside the transaction the buyer
// signed. If any part fails the whole thing reverts and nothing moved.
//
// Which means: at no point does this realm hold somebody else's name or
// somebody else's money. That is not a nice-to-have. An escrow that
// holds either one is a different kind of business, with a different set
// of rules, run by people with licences.
//
// THIS REALM HAS NO VAULT PRIVILEGES. It is not in nsdata's trusted set
// and does not ask to be. Every transfer goes through nslogic's ordinary
// GRC-721 path, which means it can only move a name the owner has
// explicitly approved — the same permission any other marketplace would
// need. However wrong the code below turns out to be, the worst it can
// do is fail.
package nsmarket

import (
	"gno.land/p/nt/avl/v0"
)

// A listing. Kept small on purpose: the seller pays to store it, and
// everything derivable is derived rather than copied. The seller's
// address is here because the name can change hands outside this realm
// and a stale seller must be caught, not trusted.
type Listing struct {
	seller address
	price  int64 // ugnot
	listed int64 // unix seconds
	/* PINNED TO ONE REGISTRATION, the same way nsskin pins a binding.
	   Without it a listing outlives the registration it was made
	   against: list at 50 GNOT having granted SetApprovalForAll, let the
	   name lapse, re-register it yourself — the burn clears the
	   per-token approval but NOT the operator grant, so owner matches,
	   IsNameValid is true, and any passer-by executes the year-old
	   listing against the name you just paid to get back. */
	registered int64

	/* PINNED TO ONE OWNERSHIP EPOCH as well as one registration.
	   The registration pin does not catch a name that was SOLD AND BOUGHT
	   BACK: owner matches, the name is valid, the registration date never
	   changed, and an operator grant (SetApprovalForAll) survives
	   transfers — so a seller who listed, sold elsewhere and later bought
	   the name back found their old listing executable by anyone at the old
	   price. The ledger's epoch moves on every transfer, so it catches it.
	   Zero means a listing written before this field, treated as unpinned. */
	epoch int64
}

var (
	// Keyed by token id, "label*domain".
	listings avl.Tree
	sold     int64 // completed sales, for the honest version of a stat
)

const (
	maxPage  = 200
	minPrice = int64(1)       // zero would be a giveaway, not a sale
	maxPrice = int64(1) << 52 // guards the fee arithmetic from overflow
	ugnot    = "ugnot"
)

package nsvote

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Everything a caller needs about one request, on one line. Fields are
// separated by "|" rather than "," because a reason may well contain a
// comma; it may not contain "|" or a newline, which Propose enforces.
func row(id int64, p *Proposal) string {
	kind := p.kind
	if kind == "" {
		kind = "domain" // anything written before kinds existed
	}
	return ufmt.Sprintf("%d|%s|%s|%s|%s|%d|%d|%d|%s|%d",
		id, kind, p.label, p.proposer.String(), p.reason,
		p.created, p.yes, p.no, p.status, p.decided)
}

// ListProposals pages newest first, which is the order anybody actually
// wants to read them in.
func ListProposals(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	var keys []string
	proposals.Iterate("", "", func(k string, _ any) bool {
		keys = append(keys, k)
		return false
	})

	var b strings.Builder
	n := 0
	last := ""
	started := after == ""
	// Walk backwards for newest-first; `after` is the last key returned.
	for i := len(keys) - 1; i >= 0; i-- {
		k := keys[i]
		if !started {
			if k == after {
				started = true
			}
			continue
		}
		if n >= limit {
			return b.String(), last
		}
		v := proposals.Get(k)
		if v == nil {
			continue
		}
		if b.Len() > 0 {
			b.WriteString("\n")
		}
		p := v.(*Proposal)
		b.WriteString(row(parseKey(k), p))
		last = k
		n++
	}
	return b.String(), ""
}

func parseKey(k string) int64 {
	var out int64
	for i := 0; i < len(k); i++ {
		if k[i] < '0' || k[i] > '9' {
			return 0
		}
		out = out*10 + int64(k[i]-'0')
	}
	return out
}

func GetProposal(id int64) string {
	v := proposals.Get(key(id))
	if v == nil {
		return ""
	}
	return row(id, v.(*Proposal))
}

func CountProposals() int64 { return int64(proposals.Size()) }

// HasVoted lets the page grey out a button instead of letting somebody
// sign a transaction that is certain to be rejected.
func HasVoted(id int64, voter address) string {
	v := votes.Get(voteKey(id, voter))
	if v == nil {
		return ""
	}
	return v.(string)
}

// CanTakePart answers the one question the page needs before it offers
// any of this: does this address hold a name.
func CanTakePart(who address) bool { return nsdata.BalanceOf(who) > 0 }

// Roster is the raw material for the leaderboards: one line per name,
// owner first, so the caller can aggregate however it likes.
//
// It lives here rather than in nslogic because this realm is being
// deployed anyway and nslogic is not — adding it there would have cost
// a fresh deployment of the largest realm we have, for a read.
//
// Paged, and the page walks every name in it. That is fine at the scale
// this registry is at and it will not be fine at fifty thousand names;
// at that point the aggregate belongs somewhere it is kept as it
// changes rather than recomputed on every read.
func Roster(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	var b strings.Builder
	for _, k := range strings.Split(keys, ",") {
		if k == "" {
			continue
		}
		at := strings.Index(k, "*")
		if at < 0 {
			continue
		}
		domainLabel, label := k[:at], k[at+1:]
		owner, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
		if b.Len() > 0 {
			b.WriteString("\n")
		}
		b.WriteString(ufmt.Sprintf("%s|%s*%s|%d|%d|%d|%t",
			owner.String(), label, domainLabel, registered, expires, streak, frozen))
	}
	return b.String(), nxt
}

// Version lets a caller find out what it is talking to BEFORE it sends a
// transaction that would be rejected for having the wrong number of
// arguments.
//
// v1 has no such function, so a nil answer is itself the answer: an
// older realm. That is cheaper and more honest than the site assuming
// the newest shape and failing at signing time, which is exactly what
// happened when Propose grew a `kind`.
func Version() string { return "v2" }

// Package nsvote holds domain requests and the votes on them.
//
// A SEPARATE REALM, and deliberately so. It never writes to nsdata: it
// only reads it, to answer two questions — does this address hold a
// name, and who is the admin. So it needs no trusted-logic grant, it
// cannot corrupt the registry however wrong its own logic turns out to
// be, and it can be replaced or abandoned without touching a single
// name anybody owns.
//
// WHAT IT DOES NOT DO
//
// It does not create domains. A vote is advice; creating the domain
// stays a deliberate admin call in nslogic. Wiring the two together
// would mean a majority could add a domain nobody had looked at, and
// the vault has no undo.
//
// It holds no funds, at any point, for anybody. The only cost of
// proposing or voting is the storage each writer pays for their own
// bytes, which the chain moves directly and which comes back if the
// record is ever deleted.
package nsvote

import (
	"gno.land/p/nt/avl/v0"
)

// Two things get asked for here, and they are not the same request.
//
//	domain  a new *domain to sell names under
//	chain   a new blockchain to accept an address for on profiles
//
// The kind is stored rather than inferred from the label, because
// "solana" is a plausible request of either sort and guessing wrong
// files somebody's vote under the wrong question.
type Proposal struct {
	kind     string  // "domain" | "chain"
	label    string  // the domain, or the chain's ticker
	reason   string  // why, capped: this is storage somebody is paying for
	proposer address
	created  int64 // unix seconds
	yes      int64
	no       int64
	status   string // "open" | "accepted" | "rejected" | "withdrawn"
	decided  int64  // unix seconds, 0 while open
}

var (
	proposals avl.Tree // id (zero-padded) -> *Proposal
	votes     avl.Tree // id + "/" + voter -> "y" | "n"
	nextID    int64    = 1

	// A reason is a sentence, not an essay. Every character is storage
	// the proposer pays for and the chain keeps.
	maxReason = 280
	// Reading a page walks every name in it, so the ceiling protects the
	// node rather than the caller.
	maxPage = 200
)

package nsvote

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// A name is the ballot. Not a token balance and not a GNOT balance:
// holding a name is the one thing that cannot be borrowed for an
// afternoon, and it is the population this actually concerns.
func assertHolder(caller address) {
	if nsdata.BalanceOf(caller) <= 0 {
		panic("nsvote: only a name holder may take part")
	}
}

/*
assertNoSend refuses coins, on every entry point.

types.gno states "It holds no funds, at any point, for anybody" — and
until now nothing enforced it. This package contained no banker, no
OriginSend and no withdrawal path of any kind, so ugnot attached to a
Propose or a Vote landed at the realm's address and stayed there
forever, unreachable even by a successor realm. Nobody would do it on
purpose; a fat-fingered wallet or a script reusing a payment helper
would.

The early return matters: a call arriving from another realm carries no
OriginSend of its own to inspect, and treating that as an error would
break composition for a check that has nothing to look at.
*/
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return
	}
	if len(unsafe.OriginSend()) > 0 {
		panic("nsvote: this call takes no payment")
	}
}

// The admin is READ FROM THE VAULT rather than stored here. Two copies
// of "who is in charge" is how a revoked admin keeps power somewhere
// nobody remembered to look.
func assertIsAdmin(caller address) {
	if caller != nsdata.GetAdmin() {
		panic("nsvote: admin only")
	}
}

// Sortable keys, so paging is in creation order rather than the order
// the strings happen to compare in. 000000001 sorts before 000000010.
func key(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 9 {
		s = "0" + s
	}
	return s
}

func voteKey(id int64, voter address) string { return key(id) + "/" + voter.String() }

// The same shape a domain must have. A chain is asked for by its ticker,
// which fits the same rule, so one check covers both — and it keeps a
// proposal from asking for something that could never be created.
func assertLabel(label string) {
	if len(label) < 1 || len(label) > 63 {
		panic("nsvote: a domain is 1 to 63 characters")
	}
	for i := 0; i < len(label); i++ {
		c := label[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-'
		if !ok {
			panic("nsvote: lowercase letters, digits and hyphens only")
		}
	}
	if label[0] == '-' || label[len(label)-1] == '-' {
		panic("nsvote: a domain cannot start or end with a hyphen")
	}
}

// Propose asks for a domain or for a chain. Anyone holding a name may ask.
//
// The proposer pays the storage for their own proposal, and nothing
// else. That cost is the whole of the spam control: it is small enough
// that a real request is nothing to think about and large enough that
// filling the tree with rubbish is not free.
func Propose(cur realm, kind, label, reason string) int64 {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	assertHolder(caller)
	if kind != "domain" && kind != "chain" {
		panic("nsvote: kind is domain or chain")
	}
	assertLabel(label)

	if len(reason) > maxReason {
		panic(ufmt.Sprintf("nsvote: a reason is at most %d characters", maxReason))
	}
	/* NEITHER A NEWLINE NOR A PIPE. read.gno joins a proposal's fields
	   with "|" and its comment claimed Propose enforced this; it did
	   not. A reason carrying pipes arrived at the site as extra fields,
	   and the site's parser accepted any row with AT LEAST ten — so the
	   reason's own pipes became the created/yes/no/status/decided
	   columns. One cheap name bought a permanent card reading
	   "9412 for / 3 against · accepted" on a proposal with no votes.
	   The chain state was always correct; the forgery lived entirely in
	   the rendering, which is what makes an unchecked separator in a
	   packed row worth a panic rather than an escape. */
	if strings.ContainsAny(reason, "|\n\r") {
		panic("nsvote: a reason may not contain '|' or a newline")
	}
	// Only a DOMAIN request can be checked against the registry. Whether
	// a chain is already supported on profiles is a fact about the
	// website, which this realm has no way to know and should not
	// pretend to.
	if kind == "domain" && nsdata.DomainExists(label) {
		panic("nsvote: that domain already exists")
	}

	// One open request per label PER KIND. Two identical proposals split
	// the vote and neither ever looks convincing — but a domain called
	// solana and a chain called solana are different questions and must
	// not block each other.
	dup := false
	proposals.Iterate("", "", func(k string, v any) bool {
		p := v.(*Proposal)
		if p.status == "open" && p.kind == kind && p.label == label {
			dup = true
			return true
		}
		return false
	})
	if dup {
		panic("nsvote: there is already an open request for that")
	}

	id := nextID
	nextID++
	proposals.Set(key(id), &Proposal{
		kind: kind, label: label, reason: reason, proposer: caller,
		created: time.Now().Unix(), status: "open",
	})
	return id
}

// Vote records a yes or no. One per address per proposal, and it cannot
// be changed: a vote that can be switched turns the count into a race
// against whoever is watching, and there is no deadline here to make
// that fair.
func Vote(cur realm, id int64, yes bool) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	assertHolder(caller)

	v := proposals.Get(key(id))
	if v == nil {
		panic("nsvote: no such request")
	}
	p := v.(*Proposal)
	if p.status != "open" {
		panic("nsvote: that request is closed")
	}
	if votes.Get(voteKey(id, caller)) != nil {
		panic("nsvote: you have already voted on this one")
	}

	mark := "n"
	if yes {
		mark = "y"
		p.yes++
	} else {
		p.no++
	}
	votes.Set(voteKey(id, caller), mark)
}

// Withdraw closes a request the proposer no longer wants. The votes
// already cast stay: deleting them would refund their storage to
// whoever called this, which is not the person who paid it.
func Withdraw(cur realm, id int64) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	v := proposals.Get(key(id))
	if v == nil {
		panic("nsvote: no such request")
	}
	p := v.(*Proposal)
	if p.proposer != caller {
		panic("nsvote: only the proposer may withdraw it")
	}
	if p.status != "open" {
		panic("nsvote: that request is already closed")
	}
	p.status = "withdrawn"
	p.decided = time.Now().Unix()
}

// Resolve records what was decided. It does NOT create the domain —
// that stays a separate, deliberate call in nslogic. A vote is advice,
// and the vault has no undo.
func Resolve(cur realm, id int64, accepted bool) {
	assertNoSend(cur)
	assertIsAdmin(cur.Previous().Address())
	v := proposals.Get(key(id))
	if v == nil {
		panic("nsvote: no such request")
	}
	p := v.(*Proposal)
	if p.status != "open" {
		panic("nsvote: that request is already closed")
	}
	if accepted {
		p.status = "accepted"
	} else {
		p.status = "rejected"
	}
	p.decided = time.Now().Unix()
}

// Purge deletes a closed request and its votes, releasing the storage.
//
// The refund goes to WHOEVER SIGNS THIS, which is not the people who
// paid — so it is admin-only and it is not a tidying operation to run
// casually. It exists because a registry that can only ever grow is
// worse, not because reclaiming somebody else's deposit is free money.
func Purge(cur realm, id int64) int64 {
	assertNoSend(cur)
	assertIsAdmin(cur.Previous().Address())
	v := proposals.Get(key(id))
	if v == nil {
		panic("nsvote: no such request")
	}
	p := v.(*Proposal)
	if p.status == "open" {
		panic("nsvote: an open request cannot be purged")
	}

	// Collect first, mutate after: removing during an iteration walks a
	// tree that is changing underneath the walk.
	prefix := key(id) + "/"
	var doomed []string
	votes.Iterate(prefix, prefix+"\xff", func(k string, _ any) bool {
		doomed = append(doomed, k)
		return false
	})
	for _, k := range doomed {
		votes.Remove(k)
	}
	proposals.Remove(key(id))
	return int64(len(doomed))
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// assertIsAdmin reads nsdata.GetAdmin() fresh every call — correct even
// immediately after a TransferAdmin, and correct for a freshly-deployed
// logic realm with no local state of its own to go stale.
//
// Note: admin authority to swap WHICH realm is trustedLogic, or to
// transfer admin itself, is deliberately NOT exposed here — those live
// only in nsdata's own admin.gno, callable solely by a direct wallet
// call from the current admin address, never proxied through logic.
// That's the one part of the system a compromised or buggy logic realm
// cannot touch.
func assertIsAdmin(cur realm) {
	if cur.Previous().Address() != nsdata.GetAdmin() {
		panic("nslogic: restricted to project admin")
	}
}

// SetLabelPattern no longer changes anything, and refuses anything but
// the rule this realm actually implements.
//
// It used to compile an arbitrary regex and store it, with validateLabel
// reading it back. That flexibility cost 15 GNOT of permanent storage
// per deploy — see the measurements in validate.gno — for a rule that
// has never changed and should not change casually.
//
// It is kept rather than deleted so that an admin who reaches for it
// gets told what happened instead of a "function not found". And it
// refuses a different pattern rather than accepting one it will not
// enforce: a stored string describing rules the code does not apply is
// the exact silent divergence the caching version was written to avoid.
func SetLabelPattern(cur realm, pattern string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if pattern != labelRule {
		panic("nslogic: the label rule is fixed in this realm (" + labelRule +
			"). Changing it means deploying a new logic realm — which is deliberate, " +
			"because a stored pattern the code does not enforce is worse than no setting at all.")
	}
	nsdata.SetLabelPatternRecord(cross(cur), pattern)
}

func SetLabelLengthLimits(cur realm, minLen, maxLen int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if minLen < 1 || maxLen < minLen {
		panic("nslogic: invalid length bounds")
	}
	nsdata.SetLabelLengthRecord(cross(cur), minLen, maxLen)
}

// SetDefaultNamePrice sets the fallback price in micro-USD, used by any
// domain that has not set its own base.
func SetDefaultNamePrice(cur realm, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if microUsd < 0 {
		panic("nslogic: price cannot be negative")
	}
	setGlobal(cur, keyDefaultPrice, strconv.FormatInt(microUsd, 10))
}

// SetUsdRate records how many ugnot one USD buys — the bridge between
// the USD price list and settlement on this chain.
//
// It is a MANUAL rate, not a market feed: it sits where it was last
// written. A stale rate during a sharp move sells names at the wrong
// price, and no amount of contract logic fixes that — keeping it current
// is an operational duty. Isolated as one global so a future logic realm
// can swap in a real oracle without touching the vault or restating a
// single price.
func SetUsdRate(cur realm, ugnotPerUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if ugnotPerUsd <= 0 {
		panic("nslogic: rate must be positive")
	}
	setGlobal(cur, keyRate, strconv.FormatInt(ugnotPerUsd, 10))
}

// SetTermLength / SetGracePeriod retune the lifecycle itself. Both were
// hardcoded constants in the vault until 2026-08-21 — meaning the 1-year
// term and 90-day grace could never have been changed, on a realm that
// is never redeployed. There was no reason to accept that.
// maxLifecycleDays bounds both setters. time.Duration is int64
// NANOSECONDS, so `days * 24h` overflows above ~106,751 days and wraps to
// a NEGATIVE duration — which would install a negative term and brick
// every registration and renewal in the registry. Guarding the input is
// what keeps the multiplication in range.
const maxLifecycleDays = 36500 // 100 years

func SetTermLength(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if days <= 0 || days > maxLifecycleDays {
		panic("nslogic: term out of range (1..36500 days)")
	}
	term := days * 24 * 60 * 60
	// Keep gracePeriod <= termLength. Anchoring a renewal to the previous
	// due date is only coherent while a renewal cannot happen more than
	// one full term after it; the vault clamps forward defensively, but
	// the combination should not be reachable in the first place.
	if nsdata.GetGracePeriod() > term {
		panic("nslogic: term must be at least the current grace period")
	}
	nsdata.SetTermLengthRecord(cross(cur), term)
}

func SetGracePeriod(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if days < 0 || days > maxLifecycleDays {
		panic("nslogic: grace period out of range (0..36500 days)")
	}
	grace := days * 24 * 60 * 60
	if grace > nsdata.GetTermLength() {
		panic("nslogic: grace period may not exceed the term length")
	}
	nsdata.SetGracePeriodRecord(cross(cur), grace)
}

// SetTokenURIBase re-points TokenURI at a different renderer, so the NFT
// artwork can be replaced without touching the vault.
func SetTokenURIBase(cur realm, base string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetTokenURIBaseRecord(cross(cur), base)
}

func SetExtraLimits(cur realm, keyLen, valueLen, entries int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if keyLen < 1 || valueLen < 1 || entries < 1 {
		panic("nslogic: limits must be positive")
	}
	nsdata.SetExtraLimitsRecord(cross(cur), keyLen, valueLen, entries)
}

/*
SetMarketFee is nsmarket's fee control, living here because this is the
realm the vault trusts.

nsmarket.SetFee could never work: it wrote through nsdata.SetGlobalRecord
from a realm deliberately outside the trusted set, so it passed its own
admin check and then panicked inside the vault for every caller. Rather
than grant nsmarket vault privileges — which would surrender the property
that realm is built around — the setter moved to the realm that already
has the grant, and the validation moved with it.

The spec grammar is nsmarket's, restated here rather than imported so
this realm does not take a dependency on the marketplace to set a number:
an amount in ugnot ("1000000"), or a percentage ("%2.5"), or "" for none.
A malformed spec would otherwise be read on every sale and resolve
silently to zero.
*/
func SetMarketFee(cur realm, spec string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	assertValidFeeSpec(spec)
	setGlobal(cur, "marketfee", strings.TrimSpace(spec))
}

// assertValidFeeSpec mirrors nsmarket.parseFee. Percentages are carried
// as basis points so a fee is expressible without floating point
// anywhere near money.
func assertValidFeeSpec(spec string) {
	spec = strings.TrimSpace(spec)
	if spec == "" {
		return
	}
	if !strings.HasPrefix(spec, "%") {
		n, err := strconv.ParseInt(spec, 10, 64)
		if err != nil || n < 0 {
			panic("nslogic: a fee is an amount in ugnot or a percentage like %2.5 — got " + spec)
		}
		return
	}
	body := spec[1:]
	whole, frac := body, ""
	if dot := strings.Index(body, "."); dot >= 0 {
		whole, frac = body[:dot], body[dot+1:]
	}
	// ONE decimal, matching nsmarket.parseFee exactly. I wrote two here
	// first, which made this validator MORE permissive than the parser
	// that has to read the value back — and a spec nsmarket refuses is
	// read as a zero fee on every sale, silently, forever. A validator
	// looser than its consumer is worse than no validator: it converts a
	// rejected input into a silent revenue leak.
	if len(frac) > 1 {
		panic("nslogic: a fee percentage carries at most one decimal — got " + spec)
	}
	for _, part := range []string{whole, frac} {
		for i := 0; i < len(part); i++ {
			if part[i] < '0' || part[i] > '9' {
				panic("nslogic: a fee percentage must be digits — got " + spec)
			}
		}
	}
	if whole == "" && frac == "" {
		panic("nslogic: a fee percentage needs a number — got " + spec)
	}
	// Basis points the same way parseFee computes them: whole*100 plus
	// one tenth-digit worth ten. Not two digits, and not a 100% ceiling
	// — nsmarket caps at maxFeeBps, which is 50%.
	w, _ := strconv.ParseInt("0"+whole, 10, 64)
	bp := w * 100
	if frac != "" {
		f, _ := strconv.ParseInt("0"+frac, 10, 64)
		bp += f * 10
	}
	if bp <= 0 || bp > 5000 {
		panic("nslogic: a fee percentage must be above zero and at most 50 — got " + spec)
	}
}

// SetGlobal writes an arbitrary project-wide key into the vault's
// package-level extension slot — the escape hatch for global state that
// does not exist yet.
func SetGlobal(cur realm, key, value string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setGlobal(cur, key, value)
}

func setGlobal(cur realm, key, value string) {
	/* THE RESTORE SEAL IS NOT AN ORDINARY GLOBAL.
	   restore.gno says sealing is "IRREVERSIBLE… There is no argument
	   that unseals it", and RestoreGlobal carries a reserved-key guard
	   to make that true. This function did not, so one admin call
	   writing key "restore" reopened the seal and the claim in that file
	   was simply false. The admin key is trusted and already holds
	   worse powers, so this is documentation drift rather than an
	   escalation — but a permanent-sounding promise that a two-word call
	   undoes is the kind of thing an auditor and a court both notice.
	   The durable version of this guard belongs in the vault, where a
	   logic swap cannot drop it; this is the half that ships today. */
	if key == keyRestore || key == keyRestoredCount {
		panic("nslogic: " + key + " is written by the restore machinery, not by SetGlobal")
	}
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic(err)
	}
}

// SetTreasury moves the revenue-receiving role — independent of
// nsdata's TransferAdmin, same reasoning as the original build's
// admin/treasury separation.
func SetTreasury(cur realm, newTreasury address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if !newTreasury.IsValid() {
		panic("nslogic: invalid treasury address")
	}
	nsdata.SetTreasuryRecord(cross(cur), newTreasury)
}

// SelfAddress reports this deployed realm's own address — needed once,
// at wiring time, so admin knows what to pass to
// nsdata.ProposeTrustedLogicGrant.
func SelfAddress(cur realm) address {
	return cur.Address()
}

package nslogic

import (
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
THE BLOCK LIST: labels nobody may hold, at any price.

This is NOT the reserved list, and confusing the two would undo both.

	reserved (collections/reserved-labels.json, 232 labels) says
	"blocked from the free tier, buyable at list price like anything
	else". admin*meme being purchasable is deliberate: the harm it
	guards against is handing a phishing address out for nothing, not
	the existence of the name. That list is enforced by the issuer,
	which is the only place that decides what is free.

	THIS list says "not available, full stop". It is the small set where
	the answer does not change when somebody offers money: names that
	impersonate the registry itself, and the registry's own names.

WHY IT LIVES IN THE VAULT'S GLOBALS RATHER THAN IN THIS FILE.

Baking it in would mean a logic deploy to block a word, and the words
worth blocking are exactly the ones discovered after launch — the label
somebody tried yesterday that nobody thought of. Globals are writable by
the admin, survive a logic swap because they belong to the vault, and
cost storage only for what is actually stored.

Chunked because a global value is capped at 512 bytes. Eight chunks is
about four kilobytes, or several hundred labels, which is far more than
this list should ever need — if it grows past that, the thing being
built is a content policy and it belongs off chain where it can be
updated without a transaction.

FAILS OPEN, and that is the uncomfortable choice, so it is written down.
An unreadable chunk blocks nothing rather than blocking everything.
Failing closed here would mean one malformed global takes the whole
registry offline — every registration, for everyone, until an admin
notices. The harm from a blocked label slipping through is one bad name
that an admin can freeze; the harm from failing closed is total. The
list is also not the only defence: the issuer holds the reserved list,
and FreezeName exists for anything that gets past both.
*/

const (
	blockChunks   = 8
	blockKeyStem  = "block"
	blockChunkMax = 512
)

// blockKey is the global name for one chunk: block0 … block7.
func blockKey(i int) string {
	return blockKeyStem + string(rune('0'+i))
}

/*
BlockedLabel reports whether a label may not be registered at all.

Compares against the label as the registry stores it — lowercase, already
validated — so a caller cannot slip past with different casing. Every
comparison is exact: this list holds whole labels, not substrings,
because "contains" matching turns a list of a dozen words into an
unpredictable filter that refuses names nobody meant to refuse.
*/
func BlockedLabel(label string) bool {
	if label == "" {
		return false
	}
	want := strings.ToLower(label)
	for i := 0; i < blockChunks; i++ {
		v := nsdata.GetGlobal(blockKey(i))
		if v == "" {
			continue
		}
		for _, e := range strings.Split(v, ",") {
			if strings.ToLower(strings.TrimSpace(e)) == want {
				return true
			}
		}
	}
	return false
}

// BlockList returns one chunk, so the panel can show and edit what is
// actually stored rather than what somebody believes is stored.
func BlockList(i int) string {
	if i < 0 || i >= blockChunks {
		return ""
	}
	return nsdata.GetGlobal(blockKey(i))
}

// BlockChunks is the number of chunks, so the panel does not hard-code a
// constant that this file might later change.
func BlockChunks() int { return blockChunks }

/*
SetBlockList replaces one chunk. Admin only.

Replaces rather than appends: an append-only list has no way to correct a
mistake, and a mistake here refuses somebody a name for reasons nobody
can see. The panel reads the chunk, edits it, and writes it back whole.
*/
func SetBlockList(cur realm, i int, csv string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if i < 0 || i >= blockChunks {
		panic("nslogic: chunk out of range")
	}
	if len(csv) > blockChunkMax {
		panic("nslogic: that chunk is longer than a global may be")
	}
	// Normalised on the way in, so the comparison above never has to
	// account for whatever spacing somebody typed into a form.
	parts := strings.Split(csv, ",")
	out := []string{}
	for _, p := range parts {
		p = strings.ToLower(strings.TrimSpace(p))
		if p != "" {
			out = append(out, p)
		}
	}
	setGlobal(cur, blockKey(i), strings.Join(out, ","))
}

// assertNotBlocked is the gate both doors pass through — the paid
// registration and the free grant. One function, called twice, because
// a block that only covers one route is not a block.
func assertNotBlocked(label string) {
	if BlockedLabel(label) {
		panic("nslogic: " + label + " is not available")
	}
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// RegisterDomain mints a new `*domain` — ADMIN-ONLY (2026-08-15 policy:
// domains are never sold or owned by third parties). No payment: the
// project isn't paying itself. Domains are also permanently
// non-transferable by users (see nft.gno's TransferFrom).
func RegisterDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	validateLabel(label)
	caller := cur.Previous().Address()
	if err := nsdata.RegisterDomainRecord(cross(cur), label, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// RenewDomain extends a domain's expiry by exactly one year from its
// PREVIOUS due date, not from the payment date. No payment — domains are
// always project-owned, so this is self-service upkeep, not a sale.
// Deliberately does not call validateLabel — a tightened pattern only
// gates new registrations, never renewals of what's already registered.
func RenewDomain(cur realm, label string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if err := nsdata.RenewDomainRecord(cross(cur), label, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
}

// ReassignDomain moves a domain record to a new owner. ADMIN-ONLY, and
// the deliberate exception to "domains are non-transferable".
//
// It exists because domain ownership is snapshotted into the record at
// registration time, while `admin` is a rotatable role. After the
// planned EOA-to-multisig rotation, the incoming admin could not renew
// or reprice any domain the outgoing key had registered — and if the
// rotation happened *because* the old key was compromised, the attacker
// could still reprice those domains afterwards. This is the recovery
// lever for exactly that situation.
//
// Not a loophole in the non-transferability policy: that policy exists
// to stop domains reaching third parties as tradeable assets, and this
// path is reachable only by the current admin, moving a project domain
// between project-controlled addresses.
func ReassignDomain(cur realm, label string, newOwner address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	/* THE STOPGAP IS GONE. This used to read the domain's settings back
	   and rewrite them around a token transfer, because that transfer
	   wiped them. Domains are records now, and nsdata moves the owner
	   without touching price, len, nm, open or maxterm. */
	if err := nsdata.ReassignDomainRecord(cross(cur), label, newOwner); err != nil {
		panic(err)
	}
}

// -- pricing controls (admin) --
//
// Every amount here is MICRO-USD (1 USD = 1_000_000). Nothing is priced
// in the chain token; ugnot is derived at payment time from the stored
// rate, so a second settlement token later is a second rate rather than
// a second price list.

// SetDomainOpen enables or disables registration of new names under a
// domain. Existing names are untouched: closing a domain stops new
// mints, it does not seize anything already held.
func SetDomainOpen(cur realm, label string, open bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	v := "1"
	if !open {
		v = "0"
	}
	setDomainExtra(cur, label, keyOpen, v)
}

// SetDomainBasePrice sets the domain's base price in micro-USD. Every
// "%N" rule under the domain is relative to this, so one call reprices
// the whole domain.
func SetDomainBasePrice(cur realm, label string, microUsd int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if microUsd < 0 {
		panic("nslogic: price cannot be negative")
	}
	setDomainExtra(cur, label, keyPrice, strconv.FormatInt(microUsd, 10))
}

// SetDomainLengthRules prices by label length: "3:2000000,4:%150,5:0"
// means 3-char names cost $2.00, 4-char names cost 150% of the domain
// base, and 5-char names are free.
func SetDomainLengthRules(cur realm, label, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setDomainExtra(cur, label, keyLens, normalizeRules(rules, true))
}

// SetDomainNameOverrides prices specific labels: "420:5000000,gm:%500".
// Highest precedence — this beats length rules and the base.
func SetDomainNameOverrides(cur realm, label, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setDomainExtra(cur, label, keyNames, normalizeRules(rules, false))
}

// SetDomainField writes an arbitrary key on a domain, for whatever a
// future feature needs without a vault change.
func SetDomainField(cur realm, label, key, value string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	setDomainExtra(cur, label, key, value)
}

func setDomainExtra(cur realm, label, key, value string) {
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic(err)
	}
}

// FreezeDomain / UnfreezeDomain: project-only power to permanently block
// re-registration of a domain even after its grace period lapses.
// DeleteDomain destroys a domain and every name beneath it.
//
// THE VAULT PRIMITIVE EXISTED BEFORE THIS DID, AND THAT MADE IT
// UNREACHABLE. nsdata.DeleteDomainRecord gates on assertIsTrustedLogic,
// so the only way to reach it is a function in this realm — and there
// was not one. The capability shipped in the vault and could not be
// used, which is worse than not shipping it, because it reads as
// present.
//
// Bounded by the vault at maxDeletePerCall names per call. It returns
// how many it removed and whether it finished, so a large domain is
// several calls rather than a transaction that cannot fit in a block.
// Repeat until done is true; calling it on a domain that is already gone
// reports done rather than panicking, so a loop terminates cleanly.
//
// ADMIN ONLY, and deliberately not owner-callable: domains are
// project-owned (SPEC.md §17b) and this destroys other people's names.
func DeleteDomain(cur realm, label string) (removed int64, done bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	return nsdata.DeleteDomainRecord(cross(cur), label)
}

// SetDomainTTL sets how long a resolver may cache answers about this
// domain, in seconds, where 0 means never cache — the ENS rule. Admin
// only, since domains are project-owned.
func SetDomainTTL(cur realm, label string, seconds int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if seconds < 0 {
		panic("nslogic: ttl may not be negative")
	}
	if err := nsdata.SetDomainTTLRecord(cross(cur), label, seconds); err != nil {
		panic(err)
	}
}

func FreezeDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, true)
}

func UnfreezeDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetDomainFrozen(cross(cur), label, false)
}

package nslogic

import (
	"strconv"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
THE FREE TIER: a name somebody can hold without ever owning a wallet.

The vault has supported this since it was written — RegisterNameRecord
takes mintNFT=false and stores a record with no GRC-721 token, and
UpgradeFreeRecord is described there as "the paid free-tier upgrade".
Nothing in the logic realm ever reached either. This is that wiring.

WHY A RECORD WITHOUT A TOKEN IS THE RIGHT SHAPE, and not a compromise:

	IT IS A REAL NAME. Owned, resolvable, renewable, on chain, visible
	to anyone. Not a promise, not a queue position, not a row in our
	database. Everything the paid tier does except be sold.

	IT CANNOT BE SOLD, and that is what makes giving it away safe.
	nsmarket escrows a TOKEN, and there is no token — so a squatter who
	farms a thousand of these has farmed a thousand things nobody can
	buy from them. The anti-abuse property falls out of the data model
	rather than out of a rule somebody has to enforce.

	IT BECOMES SELLABLE BY BECOMING PAID. UpgradeFreeName takes the full
	list price and mints the token. So the same name costs nothing and
	costs full price, and which one depends entirely on whether you want
	to sell it.

WHY THE PROJECT PAYS. The whole point is somebody with no GNOT, and
possibly no wallet, who is going to put this name in front of an
audience. Measured on Pearl: a registration is about 0.04 GNOT of fee
plus a small storage deposit, and a free-tier record is smaller than a
paid one because there is no token and no ledger entry. That is a
marketing cost per name, bounded by a daily cap we apply off chain,
where it can be changed without a deploy.

WHAT IS DELIBERATELY NOT HERE. No wordlist: storage is 100 ugnot a byte,
so a ten-thousand-word dictionary is about 57 GNOT paid forever to
encode a marketing decision that will change. The contract carries the
structural rules in reserved.gno and nothing else; the lists live off
chain with the issuer, which is us, because the free path is granted
rather than bought. See tools/gen-reserved.py.
*/

const (
	keyFreeDomain = "free"     // per-domain: "1" means the free tier is open here
	keyGrantEnd   = "grantend" // global: unix seconds, or "never"
	keyGranter    = "granter"  // global: the address allowed to issue grants
)

/*
THE GRANTER IS NOT THE ADMIN, and that separation is the point.

Free names are issued by a machine — something has to sign the grant
after a person proves an X account, and that key has to sit somewhere
warm. If that key were the admin key, a compromise of the issuing
machine would be a compromise of the registry: DeleteDomain destroys
every name under a domain and burns their tokens, instantly, with no
timelock.

So there is a second role that can do exactly one thing. Worst case for
a stolen granter key is that somebody gives away free names until we
notice and clear the role — a bounded, reversible, embarrassing loss
rather than an unbounded one.

Stored in the vault's globals rather than in this realm, so it survives
a logic redeploy. Unset means nobody but the admin may grant, which is
the right default for a role that exists to be delegated deliberately.
*/
func Granter() address {
	return address(nsdata.GetGlobal(keyGranter))
}

// SetGranter delegates grant issuance, or withdraws it. Passing the
// empty address is the revocation, and it is the first thing to reach
// for if the issuing machine is ever in doubt.
func SetGranter(cur realm, a address) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if a != "" && !a.IsValid() {
		panic("nslogic: not an address")
	}
	setGlobal(cur, keyGranter, a.String())
}

/*
SetFreeLengths tunes which lengths the free tier will issue.

In the panel rather than in a redeploy: nslogic is about 22 GNOT to
deploy, and "should four-character names be free this month" is a
marketing question that should cost a signature, not a deployment.

IT DOES NOT REACH BACKWARDS. Raising the minimum stops NEW issuance of
short names; every one already granted stays granted and keeps renewing
free. FreeLabelAllowed is called by GrantFreeName and by nothing else,
which is what makes that true — see the note on it in reserved.gno.
*/
func SetFreeLengths(cur realm, min, max int) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if min < 1 || max > 63 || min > max {
		panic("nslogic: a free-tier length range must sit inside 1..63 and be the right way round")
	}
	setGlobal(cur, keyFreeMin, strconv.Itoa(min))
	setGlobal(cur, keyFreeMax, strconv.Itoa(max))
}

func assertMayGrant(cur realm) {
	caller := cur.Previous().Address()
	if caller == nsdata.GetAdmin() {
		return
	}
	g := Granter()
	if g == "" || caller != g {
		panic("nslogic: only the admin or the granter may issue free names")
	}
}

// DomainFree reports whether a domain accepts free-tier registrations.
// Off by default, and per-domain on purpose: the free tier is a
// promotion aimed at a few domains, not a property of the registry.
func DomainFree(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyFreeDomain) == "1"
}

// SetDomainFree opens or closes the free tier for one domain.
func SetDomainFree(cur realm, domainLabel string, on bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: no such domain")
	}
	v := ""
	if on {
		v = "1"
	}
	if err := nsdata.SetDomainExtraRecord(cross(cur), domainLabel, keyFreeDomain, v); err != nil {
		panic(err)
	}
}

/*
GrantWindowOpen reports whether free grants are being issued at all.

A single global switch that closes everything at once, because the
failure this guards against is not a clever attack — it is noticing on a
Sunday that something is wrong and wanting one call that stops it. An
unset value means open; "never" means open with no end date, which is
what the admin panel already writes.
*/
func GrantWindowOpen() bool {
	return readGrantWindow(nsdata.GetGlobal(keyGrantEnd), time.Now().Unix())
}

// readGrantWindow is GrantWindowOpen with the clock and the stored value
// handed in, so the reading can be tested without a chain.
func readGrantWindow(v string, now int64) bool {
	if v == "" || v == "never" {
		return true
	}
	end, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		// An unparseable window is a misconfiguration, and the safe
		// reading of a misconfigured gate is "closed". Giving names away
		// because a setting was mistyped is the wrong way to fail.
		return false
	}
	return now < end
}

/*
GrantFreeName registers a free-tier record to somebody else.

ADMIN OR GRANTER, and that is the whole trust model: the eligibility rules —
which Twitter account, how old, how many followers, whether the label is
a dictionary word — live off chain with the issuer. Putting them here
would freeze a marketing policy into a realm and cost storage to do it.
What the chain enforces is the part that must not depend on our
correctness: the label is structurally allowed, the domain opted in, and
the window is open.

`owner` may be an address the recipient generated in their browser
seconds ago and has never funded. That is the point.
*/
func GrantFreeName(cur realm, label, domainLabel string, owner address) {
	assertNoSend(cur)
	assertMayGrant(cur)

	if !GrantWindowOpen() {
		panic("nslogic: free grants are closed")
	}
	if !DomainFree(domainLabel) {
		panic("nslogic: *" + domainLabel + " does not offer free names")
	}
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	validateLabel(label)
	assertNotBlocked(label)
	// The structural backstop. The issuer has already applied the full
	// policy; this is what stops a bug there giving away a four-letter
	// name or a pure-numeric one.
	if !FreeLabelAllowed(label) {
		panic("nslogic: " + label + " is not available on the free tier")
	}
	if !owner.IsValid() {
		panic("nslogic: a grant needs a recipient")
	}

	// paid=false — a token minted with the free-tier hold already on it,
	// so it can never be approved or sold until UpgradeFreeName lifts it.
	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, owner,
		time.Now().Unix(), false); err != nil {
		panic(err)
	}
}

/*
UpgradeFreeName mints the token for a free-tier record, at full price.

This is the only way a free name becomes sellable, and the price is the
ordinary list price with no referral discount — a discount is for
bringing somebody new, and this person is already here.

`newOwner` exists because the common case is somebody who has decided to
sell and, in the same moment, wants the name in a wallet they actually
control rather than the browser key they were given. The vault handles
that move inside UpgradeFreeRecord.

Callable by the record's current owner only. Anyone may PAY for
somebody else's upgrade in the sense that they can hand over the money,
but they cannot perform it — a stranger promoting your name into a token
and choosing where it lands is a theft with a receipt.
*/
func UpgradeFreeName(cur realm, label, domainLabel string, newOwner address) {
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: this name has expired")
	}
	if newOwner == "" {
		newOwner = caller
	}
	if !newOwner.IsValid() {
		panic("nslogic: invalid destination address")
	}

	// Full list price, resolved now rather than at grant time — the
	// name's worth is what it is worth today, and a free name held for a
	// year should not be upgradable at last year's rate.
	takePaymentSplit(cur, NamePrice(domainLabel, label), "", 0)

	if err := nsdata.UpgradeFreeRecord(cross(cur), label, domainLabel, newOwner); err != nil {
		panic(err)
	}
}

/*
GrantFreeRenewal extends a free-tier name at no charge.

THE DEAL IS THE DISPLAY, and it is checked off chain: the issuer signs
somebody in on X, reads their display name, and finds the name in it.
That single act proves both halves at once — that a real account still
exists, and that it is still carrying the name — which is why renewal is
one click a year rather than a form.

FREE-TIER RECORDS ONLY. A paid name renewed for nothing is revenue given
away by accident, and the two are told apart by whether a token was ever
minted — now, whether the token still carries the free-tier hold. The
hold is the registry's flag, read through GetNameInfo's `paid`.

NO OWNERSHIP PROOF IS ASKED FOR, and that is deliberate rather than
missing. Renewing somebody else's name is a GIFT — it takes nothing,
moves nothing, and grants the caller no power over it. The only cost of
allowing it is ours, and the vault's renewal cap already bounds how far
any single name can be pushed. A proof requirement here would buy
nothing and would cost the one-click renewal that makes the deal work.

RenewNameRecord insists the caller is the owner, so the owner is looked
up and passed. That is not a bypass: this realm is the trusted logic,
and what it is asserting is exactly true — this renewal is on that
owner's behalf.
*/
func GrantFreeRenewal(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertMayGrant(cur)

	if !nsdata.NameExists(label, domainLabel) {
		panic("nslogic: no such name")
	}
	owner, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel)
	if paid {
		panic("nslogic: " + label + "*" + domainLabel +
			" is a paid name — free renewal is for free-tier records")
	}
	if RenewalsLeft(label, domainLabel) <= 0 {
		panic("nslogic: this name is already paid as far ahead as a name may run")
	}
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, owner,
		time.Now().Unix()); err != nil {
		panic(err)
	}
}

// IsFreeTier reports whether a name is a record without a token — the
// free tier. Exported because the site and the issuer both need to ask
// before offering a free renewal, and neither should infer it.
func IsFreeTier(label, domainLabel string) bool {
	if !nsdata.NameExists(label, domainLabel) {
		return false
	}
	_, _, _, _, _, paid := nsdata.GetNameInfo(label, domainLabel)
	return !paid
}

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Answering "what does this address hold" in ONE read.
//
// The site used to ask the chain for every name in the REGISTRY and then
// throw away the ones that did not match — one HTTP round trip per name
// in the world to draw one person's collection. Six names took three
// seconds, and it gets linearly worse for everybody every time anybody
// else registers anything.
//
// The scan itself is unavoidable: nsdata keys names by domain*label and
// has no index by owner, and nsdata is the permanent vault so no index
// can be added to it now. But the scan does not have to happen across
// the network. nslogic is swappable and can walk the same records inside
// a single query, which turns N round trips into one.
//
// Nothing is cached and nothing is trusted from the caller: every row is
// read from the vault at the moment of the query, exactly as before.
//
// Paged, because a query has a gas ceiling of its own and a registry
// with fifty thousand names in it must not become one enormous read that
// nobody can complete. `after` is the vault's own cursor, so paging here
// is the same paging ExportNames already does.
const maxHoldingsPage = 200

// NamesOwnedBy returns rows of `label*domain,registered,expires,streak,frozen`
// separated by ";", plus the cursor to continue from. Labels are
// restricted to [a-z0-9-] so neither separator can appear inside a field.
//
// `next` is empty when the scan has reached the end of the registry. It
// is NOT empty merely because this page found no matches: a page of two
// hundred names belonging to other people returns no rows and a cursor,
// and the caller keeps going.
func NamesOwnedBy(owner address, after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	var b strings.Builder
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		// The tree key is domain*label; the token ID is label*domain.
		at := strings.Index(key, "*")
		if at < 0 {
			continue
		}
		domainLabel, label := key[:at], key[at+1:]

		o, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
		if o != owner {
			continue
		}
		if b.Len() > 0 {
			b.WriteString(";")
		}
		b.WriteString(ufmt.Sprintf("%s*%s,%d,%d,%d,%t",
			label, domainLabel, registered, expires, streak, frozen))
	}
	return b.String(), nxt
}

// CountNamesOwnedBy is the same walk without the strings, for a header
// that wants a number before the list has finished arriving.
func CountNamesOwnedBy(owner address, after string, limit int) (n int, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		at := strings.Index(key, "*")
		if at < 0 {
			continue
		}
		if nsdata.GetNameOwner(key[at+1:], key[:at]) == owner {
			n++
		}
	}
	return n, nxt
}

// Everything the profile page draws, in ONE read.
//
// It was making seventeen queries: three to establish that the name
// exists and when it expires, then fourteen more — one per extension
// slot — that could not start until the first three had come back. Two
// waves, and the node serves only a few at a time, so a profile took
// seconds to assemble out of values that all live in the same record.
//
// Values come back in the ORDER THE KEYS WERE ASKED FOR rather than as
// key=value pairs. An extension key is allowed to contain "=" (only
// commas and newlines are forbidden), so a pair encoding would have an
// ambiguous split; positional has none.
//
// Line 0 is the record: owner, registered, expires, streak, frozen, and
// the grace period, which is global but is one more query the page would
// otherwise have to make on its own.
//
// An empty return means the name is not registered. That is a real
// answer rather than an error: asking about a name nobody owns is the
// normal case on a profile URL somebody typed.
func ProfileOf(label, domainLabel, keys string) string {
	if !nsdata.NameExists(label, domainLabel) {
		return ""
	}
	owner, registered, expires, streak, frozen, _ := nsdata.GetNameInfo(label, domainLabel)

	var b strings.Builder
	b.WriteString(ufmt.Sprintf("%s,%d,%d,%d,%t,%d",
		owner.String(), registered, expires, streak, frozen, nsdata.GetGracePeriod()))

	for _, k := range strings.Split(keys, ",") {
		b.WriteString("\n")
		if k == "" {
			continue
		}
		v := nsdata.GetNameExtra(label, domainLabel, k)

		// THE GNO.LAND ADDRESS ANSWERS EVEN WHEN NOBODY SAVED ONE.
		//
		// A name is an NFT held by an address, so the owner is already
		// public — it is the first field of the record above. Returning
		// it here as well costs no storage and means a name can be paid
		// without its holder ever having opened a profile editor, which
		// is most of them, and without a transaction to back-fill the
		// ones registered before this existed.
		//
		// Doing it in the realm rather than in the website is the whole
		// point: any client asking this realm for the gno key gets the
		// same answer our pages do. A front end that derived it locally
		// would leave every other reader with nothing.
		//
		// "off" is the opt-out, and it has to be a sentinel. An empty
		// value is indistinguishable from never having set one, so an
		// empty gno field would simply hand the derived address back on
		// the next read.
		if k == "gno" {
			if v == "off" {
				v = ""
			} else if v == "" {
				v = owner.String()
			}
		}
		b.WriteString(escapeValue(v))
	}
	return b.String()
}

// Extension VALUES are free text — a bio can hold anything a person can
// type, newlines included — so they cannot be newline-separated raw.
// Escaping is done here rather than stripping, because silently eating a
// line break out of somebody's bio is data loss on a read path.
func escapeValue(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, "\n", `\n`)
	return strings.ReplaceAll(s, "\r", `\r`)
}

// RecentNames answers "what has just been registered" in one read.
//
// The site used to build this by listing every key and then reading each
// record one at a time — the same shape NamesOwnedBy replaced for a
// wallet's holdings, and the same problem: fine at thirteen names, one
// query per name forever after. A feed that gets slower every time
// somebody registers is a feed that eventually stops loading on the busy
// day you most wanted it.
//
// Returns rows of "label*domain,registered,expires,owner", newest first,
// and a cursor. Sorting happens across a PAGE, not the whole registry:
// the vault stores names alphabetically and there is no index by date,
// so a caller that wants the true newest reads every page and merges.
// That is one query per 200 names instead of one per name — enough of a
// difference to stop mattering, without pretending the vault has an
// index it does not have.
func RecentNames(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > maxHoldingsPage {
		limit = maxHoldingsPage
	}
	keys, nxt := nsdata.ExportNames("", after, limit)

	type row struct {
		text string
		at   int64
	}
	var found []row
	for _, key := range strings.Split(keys, ",") {
		if key == "" {
			continue
		}
		// The tree key is domain*label; the token ID is label*domain.
		at := strings.Index(key, "*")
		if at < 1 {
			continue
		}
		domainLabel, label := key[:at], key[at+1:]
		owner, registered, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
		found = append(found, row{
			text: ufmt.Sprintf("%s*%s,%d,%d,%s", label, domainLabel, registered, expires, owner.String()),
			at:   registered,
		})
	}

	// Insertion sort, newest first. The page is at most 200 entries and
	// gno has no sort in scope here; anything cleverer would be more code
	// than the problem deserves.
	for i := 1; i < len(found); i++ {
		v := found[i]
		j := i - 1
		for j >= 0 && found[j].at < v.at {
			found[j+1] = found[j]
			j--
		}
		found[j+1] = v
	}

	var b strings.Builder
	for _, r := range found {
		if b.Len() > 0 {
			b.WriteString(";")
		}
		b.WriteString(r.text)
	}
	return b.String(), nxt
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
BACKDATED NAMES, ON A REAL CHAIN, WITHOUT A BACKDOOR.

THE PROBLEM. Every expiry rule here is a function of a date, and every
date in this registry is a few weeks old. Live, in grace, and lapsed past
recovery are three different sets of behaviour — what renders, what can
be sold, what can be reclaimed, what the marketplace refuses — and only
the first has ever been seen. Waiting a year to find out is not a test
plan, and finding out on mainnet a year after launch is the outcome this
exists to prevent.

WHY NOT RestoreNames. Because it refuses, and it is right to. OpenRestore
panics on a populated vault:

    if d, n, _, _ := nsdata.Sizes(); d != 0 || n != 0 { panic(...) }

That guard was added for a specific reason recorded in restore.gno —
RestoreNameField can write any extension key on any EXISTING name, which
includes the payment addresses a name's pay page renders, and that is a
way to redirect somebody's incoming money with only the admin key. The
door is shut on any chain that holds records. It should stay shut, and
wanting test data is not a reason to widen it.

WHAT THIS IS INSTEAD. One function that moves an expiry, and it refuses
to touch anything outside a single domain that the admin has explicitly
nominated as the lab. Set no lab domain and this realm cannot move an
expiry at all — which is the state mainnet ships in, and the state it
stays in unless somebody deliberately changes it and says so on chain.

WHY THAT IS ENOUGH OF A GUARD. The admin can already deploy a logic realm
that does anything, so this grants no power that did not exist. What it
buys is that the power is NAMED, SCOPED and VISIBLE: LabDomain() is a
public read, so anybody can check that no lab is set, and every name this
can reach is under one extension that everybody can see and that
DeleteDomain removes in a call.

THE LAB DOMAIN IS NOT SPECIAL TO THE VAULT. It is an ordinary domain,
registered the ordinary way. Nothing about a name under it is fake — the
records, the artwork, the marketplace, the grace arithmetic are all the
real thing. The only unusual act is an admin moving a date, which is the
one thing a testnet cannot do by waiting.
*/

const keyLab = "labdomain"

// LabDomain is the domain that SetLabExpiry may touch, or "" when there
// is none — which must be the case on mainnet. A public read, so the
// claim above is checkable by anybody rather than asserted here.
func LabDomain() string { return nsdata.GetGlobal(keyLab) }

// SetLabDomain nominates a domain as the lab, or clears it with "".
//
// The domain must already exist, so the nomination cannot be made
// speculatively against a name somebody registers later.
func SetLabDomain(cur realm, label string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	label = strings.TrimSpace(label)
	if label == "" {
		setGlobal(cur, keyLab, "")
		return
	}
	if !nsdata.DomainExists(label) {
		panic("nslogic: no such domain — register it before nominating it as the lab")
	}
	setGlobal(cur, keyLab, label)
}

/*
SetLabExpiry moves one name's expiry to an absolute unix time.

It refuses outside the lab domain, and it refuses when no lab is set. The
two checks are separate on purpose: an empty lab must not match an empty
domain argument and quietly become a wildcard.

An expiry may be set into the past — that is the entire point. What it
may not be is before the name was registered, because that is not a state
the ordinary rules can produce and testing against an impossible record
teaches nothing.
*/
func SetLabExpiry(cur realm, label, domainLabel string, expires int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)

	lab := LabDomain()
	if !labScopeOK(lab, domainLabel) {
		if lab == "" {
			panic("nslogic: no lab domain is set; SetLabDomain first, and never on mainnet")
		}
		panic("nslogic: " + domainLabel + " is not the lab domain (" + lab + ")")
	}
	if !nsdata.NameExists(label, domainLabel) {
		panic("nslogic: no such name — register it first, then move its date")
	}
	_, registered, _, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	if !labDateOK(registered, expires) {
		panic("nslogic: that would expire the name before it was registered, " +
			"which the ordinary rules cannot produce")
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
}

// The scoping rule, alone and testable. Kept as its own function
// because the two conditions must stay SEPARATE: folded into one, an
// unset lab would match an unnamed domain and the guard becomes a
// wildcard pointing at every name in the registry.
func labScopeOK(lab, domainLabel string) bool {
	if lab == "" {
		return false
	}
	return domainLabel == lab
}

// An expiry may be in the past — that is the point — but not before the
// name existed, which is not a state the ordinary rules can produce.
func labDateOK(registered, expires int64) bool {
	return expires > 0 && expires >= registered
}

/*
RegisterLabName creates a name in the lab with a registration date in the
PAST, and an expiry wherever the test needs it.

FOUND ON THE FIRST RUN ON PEARL. SetLabExpiry moves an expiry but refuses
to put it before the registration date — and every lab name had been
registered minutes before its date was moved. So grace and lapsed could
not be produced at all, and neither could tenure: the metal ladder reads
years held from the registration date, which nothing could move.

No registry change is needed, and that is the reason this is shaped the
way it is. nsdata.RegisterNameRecord already takes `now` from its caller —
it is how a trusted logic realm records the moment of registration — so a
lab name is registered at a moment `heldDays` ago and its expiry set
after. A logic deploy, not a new registry.

Same fence as SetLabExpiry: admin only, the nominated lab domain only, and
never an expiry before the registration it now has. `paid` false makes a
free-tier name, held on the ledger like any other.
*/
func RegisterLabName(cur realm, label string, heldDays, expiresInDays int64, paid bool) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	lab := LabDomain()
	if !labScopeOK(lab, lab) {
		panic("nslogic: no lab domain is set; SetLabDomain first, and never on mainnet")
	}
	if heldDays < 0 || heldDays > 36500 {
		panic("nslogic: heldDays must be 0-36500")
	}
	validateLabel(label)
	now := time.Now().Unix()
	registered := now - heldDays*86400
	expires := now + expiresInDays*86400
	if !labDateOK(registered, expires) {
		panic("nslogic: that would expire the name before it was registered, " +
			"which the ordinary rules cannot produce")
	}
	if err := nsdata.RegisterNameRecord(cross(cur), label, lab, cur.Previous().Address(), registered, paid); err != nil {
		panic(err)
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, lab, expires)
}

// SetLabExpiryDays is the form a script actually wants: days from now,
// negative for the past. "expired eleven days ago" is a sentence; the
// unix time it corresponds to is not, and computing it in bash is how a
// test set ends up quietly one day out.
func SetLabExpiryDays(cur realm, label, domainLabel string, days int64) {
	SetLabExpiry(cur, label, domainLabel, time.Now().Unix()+days*86400)
}

/*
LabReport answers, for every name in the lab, what the registry thinks
its state is RIGHT NOW — read from the same GetGracePeriod the rest of
the realm uses rather than recomputed here.

It exists because the interesting failures are disagreements: the card
says lapsed, the marketplace still lists it, the reclaim path still
refuses. One line per name, so a script can diff what the chain believes
against what the site drew.

	label,expires,daysLeft,state
*/
func LabReport() string {
	lab := LabDomain()
	if lab == "" {
		return ""
	}
	now := time.Now().Unix()
	grace := nsdata.GetGracePeriod()

	var out []string
	after := ""
	for {
		keys, next := nsdata.ExportNames(lab, after, 200)
		if keys == "" {
			break
		}
		for _, k := range strings.Split(keys, ",") {
			k = strings.TrimSpace(k)
			if k == "" {
				continue
			}
			// THE STORAGE KEY IS domain*label, the reverse of a token id.
			// This has been got backwards more than once in this project.
			star := strings.Index(k, "*")
			if star < 0 {
				continue
			}
			label := k[star+1:]
			_, _, expires, _, _, _ := nsdata.GetNameInfo(label, lab)
			state := "LIVE"
			switch {
			case now >= expires+grace:
				state = "LAPSED"
			case now >= expires:
				state = "GRACE"
			}
			out = append(out, label+","+strconv.FormatInt(expires, 10)+","+
				strconv.FormatInt((expires-now)/86400, 10)+","+state)
		}
		if next == "" || next == after {
			break
		}
		after = next
	}
	return strings.Join(out, ";")
}

package nslogic

import (
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Profile field names inside a name's extension slot. The vault stores
// them as opaque strings and bounds their size; what they MEAN is this
// realm's convention, so new profile fields need no vault change.
const (
	keyDisplayName = "displayName"
	keyBio         = "bio"
	keyWebsite     = "website"
	keyAvatar      = "avatar"
)

// RegisterName mints `label*domain` under an existing domain. Anyone may
// call this. Minting still works while the parent domain is past its own
// due date, as long as its grace period hasn't fully lapsed and it isn't
// frozen — nsdata's RegisterNameRecord enforces that.
func RegisterName(cur realm, label, domainLabel string) {
	registerName(cur, label, domainLabel, "")
}

// RegisterNameRef is RegisterName with a referral code — the NAME of
// whoever sent the buyer here, as it appears in the link.
//
// It is a second entry point rather than a third argument on the first
// one because the first one is already deployed and already being called
// by wallets and by the site. Changing its arity would break every one
// of those callers at the same instant, which is exactly the failure the
// voting realm produced last time; adding a function breaks nothing and
// lets the front end pick whichever the deployed realm actually has.
//
// A code that does not resolve — misspelt, lapsed, or the buyer's own
// name — is IGNORED, not rejected. The registration goes through at
// list price. Refusing to sell somebody a name because they mistyped
// somebody else's would be an absurd way to lose a sale.
func RegisterNameRef(cur realm, label, domainLabel, refName string) {
	registerName(cur, label, domainLabel, refName)
}

func registerName(cur realm, label, domainLabel, refName string) {
	validateLabel(label)
	assertNotBlocked(label)
	if !DomainOpen(domainLabel) {
		panic("nslogic: this domain is not accepting new names")
	}
	caller := cur.Previous().Address()

	// Resolved BEFORE anything is written, so the tier and the discount
	// are read from the world the buyer was quoted in. Registering first
	// would change the buyer's own primary name and, on a self-referral
	// that slipped through, their tenure with it.
	ref := resolveReferrer(refName, caller)
	price := NamePrice(domainLabel, label)
	if ref != "" {
		if pct := tierPercent(RefDiscountRules(), TenureYears(ref)); pct > 0 {
			price -= price * pct / 100
		}
	}
	payTo, cut := referralCut(ref, price)
	takePaymentSplit(cur, price, payTo, cut)

	if err := nsdata.RegisterNameRecord(cross(cur), label, domainLabel, caller, time.Now().Unix(), true); err != nil {
		panic(err)
	}

	// Written after the record exists, because the extension slot is
	// created by registration. Only recorded when the cut was actually
	// paid: a referrer who earned nothing on the sale has no claim on
	// the renewals either, and storing them would say otherwise.
	if ref != "" && cut > 0 {
		setExtra(cur, label, domainLabel, keyRef, ref.String())
		creditReferral(cur, ref)
	}
}

// RenewName — same anchoring rule as RenewDomain: extends from the
// previous due date, not from the payment date. Deliberately does not
// call validateLabel — an already-registered name must keep renewing
// under whatever pattern was in force when it was minted.
func RenewName(cur realm, label, domainLabel string) {
	// No new code is accepted here and none is needed: the referrer was
	// fixed into this name when it was registered, and renewals keep
	// paying them for as long as the name survives unbroken. If it
	// lapses or is sold the vault destroys the record's extras, so the
	// link ends without this realm having to notice.
	//
	// Renewals pay the FULL price. The discount was a reason to arrive;
	// it is not a permanent lower rate, and compounding it every year
	// would make the referred name cheaper forever than the same name
	// bought directly.
	assertRoomToRenew(label, domainLabel)
	price := NamePrice(domainLabel, label)
	ref := ReferrerOf(label, domainLabel)
	payTo, cut := referralCut(ref, price)
	takePaymentSplit(cur, price, payTo, cut)

	caller := cur.Previous().Address()
	if err := nsdata.RenewNameRecord(cross(cur), label, domainLabel, caller, time.Now().Unix()); err != nil {
		panic(err)
	}
	if cut > 0 {
		creditReferral(cur, ref)
	}
}

// SetProfile writes the four conventional profile fields. Each lands in
// the name's extension slot, where the vault enforces size bounds.
func SetProfile(cur realm, label, domainLabel, displayName, bio, website, avatar string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	setExtra(cur, label, domainLabel, keyDisplayName, displayName)
	setExtra(cur, label, domainLabel, keyBio, bio)
	setExtra(cur, label, domainLabel, keyWebsite, website)
	setExtra(cur, label, domainLabel, keyAvatar, avatar)
}

// SetNameField writes a single arbitrary key — cross-chain addresses and
// anything else a future feature needs, with no vault change required.
// Keys used by this realm's own machinery are reserved.
func SetNameField(cur realm, label, domainLabel, key, value string) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if strings.HasPrefix(key, "_") {
		panic("nslogic: keys beginning with '_' are reserved")
	}
	// `ref` decides who gets paid out of every renewal of this name. A
	// holder who could write it would set it to an address they control
	// and take a permanent cut of their own renewals out of the
	// treasury — so the one key that moves money is the one key its
	// owner may not touch.
	if key == keyRef {
		panic("nslogic: '" + keyRef + "' is set at registration and cannot be edited")
	}
	setExtra(cur, label, domainLabel, key, value)
}

func setExtra(cur realm, label, domainLabel, key, value string) {
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic(err)
	}
}

func assertNameOwner(cur realm, label, domainLabel string) {
	if nsdata.GetNameOwner(label, domainLabel) != cur.Previous().Address() {
		panic("nslogic: restricted to name owner")
	}
}

// SetPrimaryName lets a wallet explicitly choose (and later change) which
// of its names is used for reverse resolution.
func SetPrimaryName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	caller := cur.Previous().Address()
	if nsdata.GetNameOwner(label, domainLabel) != caller {
		panic("nslogic: restricted to name owner")
	}
	if err := nsdata.SetPrimaryRecord(cross(cur), caller, label, domainLabel); err != nil {
		panic(err)
	}
}

/*
ClearPrimaryName switches reverse resolution OFF for the caller.

WHY THIS HAS TO EXIST, and it is a hole rather than a feature request.

nsdata sets the reverse pointer AUTOMATICALLY on a wallet's first
registration — RegisterNameRecord does it, and nothing asked the person
first. From that moment their address answers with their name, so anybody
who sees that address anywhere can find the persona attached to it, and
every transaction it has ever made becomes attributable. Retroactively:
the chain is permanent and indexers keep copies.

And until now there was NO WAY OUT. ClearPrimaryRecord is gated to
trusted logic, and no logic realm exposed it, so the one person the
pointer is about could not remove it. A name service is a bridge between
a persona and a wallet; publishing that bridge without consent and
without an exit is the worst version of it.

This is the exit. It takes no arguments on purpose: a wallet has exactly
one reverse pointer, and the only address it can clear is its own, so
there is nothing to pass and nothing to get wrong.

WHAT IT DOES NOT DO, said plainly because a promise we cannot keep would
be worse than the hole: clearing stops FUTURE lookups. It does not
unpublish what was already visible, and it cannot — the history is on
chain and other people have copies. The honest sequence is to choose
before publishing, which is why the site now shows what the link exposes
before it offers to make it.
*/
func ClearPrimaryName(cur realm) {
	assertNoSend(cur)
	nsdata.ClearPrimaryRecord(cross(cur), cur.Previous().Address())
}

// SetNameTTL is the owner's cache policy for their own name, in
// seconds, where 0 MEANS NEVER CACHE — copied from the ENS registry so
// integrators need not read anything of ours to handle it.
//
// The owner sets it rather than the registry because only they know the
// risk: a name being used to receive payments wants 0, since a cached
// answer after a sale pays the previous owner; a name used as a display
// handle can safely be cached for a long time.
func SetNameTTL(cur realm, label, domainLabel string, seconds int64) {
	assertNoSend(cur)
	assertNameOwner(cur, label, domainLabel)
	if seconds < 0 {
		panic("nslogic: ttl may not be negative")
	}
	if err := nsdata.SetNameTTLRecord(cross(cur), label, domainLabel, seconds); err != nil {
		panic(err)
	}
}

func FreezeName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
}

func UnfreezeName(cur realm, label, domainLabel string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetNameFrozen(cross(cur), label, domainLabel, false)
}

// -- resolution --

func ResolveName(label, domainLabel string) address {
	if !nsdata.IsNameValid(label, domainLabel) {
		panic("nslogic: name is expired")
	}
	return nsdata.GetNameOwner(label, domainLabel)
}

// ResolveAddress performs reverse resolution: address -> name.
//
// It must verify the ownership it is asserting, not merely that the
// pointed-at name exists and is unexpired. nsdata's `primary` tree is a
// record of what an address last SELECTED, not proof of what it still
// owns — and although nsdata now clears the pointer on transfer and
// reclaim, this check is the half that lives in the swappable realm and
// therefore stays correct even against pointers written by an older
// version of the logic. Without it, an address that sold or lost a name
// kept reverse-resolving to it, impersonating the new owner.
func ResolveAddress(addr address) string {
	tid := nsdata.GetPrimary(addr)
	if tid == "" {
		return ""
	}
	label, domainLabel := splitTokenID(tid)
	if !nsdata.IsNameValid(label, domainLabel) {
		return ""
	}
	if nsdata.GetNameOwner(label, domainLabel) != addr {
		return ""
	}
	return tid
}

// splitTokenID splits a `label*domain` token ID.
func splitTokenID(tid string) (label, domainLabel string) {
	for i := 0; i < len(tid); i++ {
		if tid[i] == '*' {
			return tid[:i], tid[i+1:]
		}
	}
	return tid, ""
}

package nslogic

import (
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// This realm only exposes the WRITE side of the GRC-721 surface. Reads
// (BalanceOf, OwnerOf, TokenURI, GetApproved, IsApprovedForAll, and
// every listing/status/profile query) have no authorization check to
// perform and are served directly by nsdata — no reason to duplicate
// them here.

func isDomainToken(tid string) bool {
	return strings.HasPrefix(tid, "*")
}

// isTokenValid checks the underlying domain/name's expiry via nsdata's
// own validity reads — the anti-scam pattern (an expired name must not
// be sellable) enforced at the transfer boundary, not just at read time.
func isTokenValid(tid string) bool {
	if isDomainToken(tid) {
		return nsdata.IsDomainValid(tid[1:])
	}
	label, domainLabel := splitTokenID(tid)
	return nsdata.IsNameValid(label, domainLabel)
}

// assertNotFrozen is the check that made freezing mean something.
//
// FreezeName set a bit that only ever gated RE-REGISTRATION after a
// lapse. Transfer, approval, listing and sale all ignored it, so the one
// manual lever the takedown process relies on did nothing about the case
// it exists for: a disputed or stolen name could be approved to a fresh
// wallet, listed and sold while the interface showed it as frozen.
//
// The bit was already stored and already readable — GetNameInfo returns
// it — so this needs no change to the permanent vault, only the read
// that was never performed.
func assertNotFrozen(tid string) {
	label, domainLabel := splitTokenID(tid)
	_, _, _, _, frozen, _ := nsdata.GetNameInfo(label, domainLabel)
	if frozen {
		panic("nslogic: this name is frozen and cannot be transferred or approved")
	}
}

/*
THERE ARE NO TRANSFER OR APPROVAL FUNCTIONS HERE ANY MORE.

Approve, SetApprovalForAll, TransferFrom and SafeTransferFrom lived in this
realm, and they could only work while this realm was the one place a
transfer could happen. In this generation ownership is in nsnft, and nsnft
sees whoever calls it as the caller — so a logic realm calling in on a
user's behalf would be refused as not approved, correctly. A logic realm
that COULD move people's tokens would be a logic realm that could steal
them.

So: holders approve and transfer on nsnft directly, and marketplaces —
ours included — settle as approved operators there.

The two policies these wrappers enforced moved to where they bind every
path, not just ours:
  - frozen names: a hold bit on the token in nsnft (nsdata.SetNameFrozen)
  - free-tier names: a hold bit set at mint (nsdata.RegisterNameRecord)
Expired names are refused by our marketplace and never resolve; an
external marketplace can move an expired token, as with any NFT. See
MIGRATION.md, second attempt, rule 6.

The helpers above stay because the marketplace-facing reads use them.
*/

package nslogic

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// takePayment verifies the attached send-envelope covers `price` ugnot,
// forwards the price to the treasury, and refunds any overpayment to the
// caller in the same transaction. Nothing is ever retained: every ugnot
// that arrives leaves again, as either payment or refund.
//
// It used to take a `beneficiary` and split the price fee/remainder,
// routing the remainder to treasury only while `beneficiary == admin`.
// That comparison was a proxy for "is this a project-owned domain", and
// it silently broke the moment `admin` rotated — the planned EOA-to-
// multisig step — because a domain's owner is frozen into its record at
// registration time. After a rotation, every registration's remainder
// would have been paid to the retired key instead of the treasury, with
// no error and no log line.
//
// The heuristic is gone rather than patched. Domains are admin-only to
// create and permanently non-transferable, so every domain is
// project-owned by construction and 100% of every payment belongs to the
// treasury. `platformFeeBps` stays in nsdata's config for a future logic
// realm that reintroduces third-party domain ownership; reinstating the
// split is then a logic-realm swap, not a migration.
func takePayment(cur realm, price int64) {
	takePaymentSplit(cur, price, "", 0)
}

// takePaymentSplit is takePayment with a referrer's cut carved out of the
// same price. The buyer pays exactly what they were quoted; the cut is
// not added on top, it is a share of what the treasury would otherwise
// have received.
//
// All three legs settle inside the buyer's own transaction — treasury,
// referrer, refund — so this realm's balance is the same after the call
// as before it. That is not a stylistic preference: holding a referrer's
// cut until they claim it would make this an account you can have a
// balance in, and that is a different kind of thing to operate, subject
// to a different set of rules, run by people with licences. The cut is
// paid now or it is not paid.
func takePaymentSplit(cur realm, price int64, cutTo address, cut int64) {
	if !cur.Previous().IsUserCall() {
		panic("nslogic: only direct wallet calls may attach payment")
	}
	caller := cur.Previous().Address()
	sent := unsafe.OriginSend()
	assertOnlyUgnot(sent)

	paid := sent.AmountOf(ugnot)
	if paid < price {
		panic(ufmt.Sprintf("nslogic: insufficient payment: need %d ugnot, got %d", price, paid))
	}
	excess := paid - price

	// Belt and braces. referralCut already caps the percentage, but this
	// is the line where the arithmetic becomes money leaving an address,
	// and a bug upstream must not be able to pay out more than came in.
	if cut < 0 || cut > price || cutTo == "" {
		cut = 0
	}

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	pkgAddr := cur.Address()
	if cut > 0 {
		b.SendCoins(pkgAddr, cutTo, chain.Coins{chain.NewCoin(ugnot, cut)})
	}
	if price-cut > 0 {
		b.SendCoins(pkgAddr, nsdata.GetTreasury(), chain.Coins{chain.NewCoin(ugnot, price-cut)})
	}
	if excess > 0 {
		b.SendCoins(pkgAddr, caller, chain.Coins{chain.NewCoin(ugnot, excess)})
	}
}

// assertOnlyUgnot rejects any other denomination outright. Only the
// ugnot amount was ever accounted for, and neither realm has a
// withdrawal path, so a foreign coin sent alongside a payment would have
// been stranded in this realm's address permanently. Refusing the whole
// transaction is simpler than sweeping it back and keeps the
// "this realm never retains funds" invariant absolute.
func assertOnlyUgnot(sent chain.Coins) {
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("nslogic: only ugnot is accepted, got: " + c.Denom)
		}
	}
}

// assertNoSend guards every entry point that has no price. Without it,
// coins attached to a free call (a renewal of a project domain, a
// profile edit, an admin setter) would land in this realm's address with
// no way back out.
//
// IT APPLIES TO DIRECT WALLET CALLS ONLY, and that qualification is not
// a loosening — it is the guard finally matching its own reason.
//
// OriginSend() reports what the TRANSACTION carried, not what this call
// received. Measured on sapphire-1 with a pair of probe realms: a user
// attaches 500000ugnot to realm A, A calls realm B, and B's OriginSend()
// reads 500000ugnot even though every one of those coins is sitting in
// A's address. B never saw them and cannot strand them.
//
// So for a realm-to-realm call this was rejecting a payment this realm
// never received. It is the reason a marketplace could not transfer a
// name inside the same transaction that pays for it — the transfer is a
// free call, the transaction is not, and the two are unrelated. A
// two-transaction sale is the alternative, and that means somebody's
// money or somebody's name sitting somewhere in between. Not here.
func assertNoSend(cur realm) {
	if !cur.Previous().IsUserCall() {
		return // the coins went to whoever called us, not to us
	}
	if !unsafe.OriginSend().IsZero() {
		panic("nslogic: this function takes no payment; do not attach coins")
	}
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Global pricing layers that sit ACROSS every domain rather than inside
// one — see SPEC.md §27.
//
// Two of them, and they work at different points:
//
//	GLOBAL LENGTH RULES are a FLOOR beneath each domain's own length
//	rules, consulted only when the domain has nothing to say about that
//	length. "three-character names cost $5 everywhere" becomes one entry
//	instead of an edit to all twenty-seven domains, and a domain that
//	wants its own answer still overrides it.
//
//	GLOBAL NAME PREMIUMS are an ADJUSTMENT applied after the price has
//	already resolved. Making `og` premium is one entry covering
//	`og*degen`, `og*meme` and every domain invented later. Deliberately
//	not the per-name override, which REPLACES a price outright: "this
//	name costs exactly X here" and "this name is worth more everywhere"
//	are different tools and both are worth having.
//
// Full order, most specific first:
//
//  1. per-name override      (domain "nm")
//  2. per-domain length rule (domain "len")
//  3. global length rule     (global "glen")
//  4. domain base price      (domain "price")
//  5. global default         (global "defaultPrice")
//     then the global name premium modifies the result,
//     then any referral discount comes off what is left.
const (
	keyGlobalLens = "glen"    // global length rules
	keyPremium    = "premium" // premium1, premium2, ... see below

	// The vault caps an extension value at maxExtraValueLen (512 bytes),
	// which is roughly 40-60 premium entries. The list is therefore split
	// across numbered keys rather than pretending one will do; a list
	// that silently truncated at the 512th byte would drop exactly the
	// entries nobody checked.
	maxPremiumKeys = 8
)

// GlobalLengthRule returns the global rule for a label length, if any.
func GlobalLengthRule(n int) (string, bool) {
	return lookupRule(nsdata.GetGlobal(keyGlobalLens), strconv.Itoa(n))
}

// PremiumFor returns the raw modifier for a name across all premium
// keys, or "" when the name is not premium anywhere.
func PremiumFor(label string) string {
	for i := 1; i <= maxPremiumKeys; i++ {
		csv := nsdata.GetGlobal(keyPremium + strconv.Itoa(i))
		if csv == "" {
			continue
		}
		if v, ok := lookupRule(csv, label); ok {
			return v
		}
	}
	return ""
}

// applyPremium adjusts an already-resolved price.
//
// ZERO ALWAYS STAYS ZERO. A fixed "+$2.00" would otherwise silently undo
// a giveaway tier set months earlier, and a free tier that quietly stops
// being free is worse than never having offered one. This is decided
// explicitly rather than inherited from the percentage case happening to
// work out at zero.
//
// Forms: "%5" / "+%5" five percent more · "-%10" ten percent less ·
// "2.00" two dollars more · "-0.25" twenty-five cents less ·
// "=5.00" exactly five dollars, ignoring everything resolved above.
func applyPremium(mod string, price int64) int64 {
	mod = strings.TrimSpace(mod)
	if mod == "" || price <= 0 {
		return price
	}

	// "=X" replaces outright. Checked before the sign handling because
	// an exact price is not a delta and has no direction.
	if strings.HasPrefix(mod, "=") {
		v, ok := parseUSD(mod[1:])
		if !ok || v < 0 {
			return price
		}
		return v
	}

	neg := false
	switch {
	case strings.HasPrefix(mod, "-"):
		neg, mod = true, mod[1:]
	case strings.HasPrefix(mod, "+"):
		mod = mod[1:]
	}

	var delta int64
	if strings.HasPrefix(mod, "%") {
		pct, err := strconv.ParseInt(mod[1:], 10, 64)
		if err != nil || pct < 0 {
			return price
		}
		delta = price * pct / 100
	} else {
		v, ok := parseUSD(mod)
		if !ok || v < 0 {
			return price
		}
		delta = v
	}

	if neg {
		// A discount may take a name to free, but never below it: a
		// negative price would be a payout, and this realm never pays
		// anybody to register.
		if delta >= price {
			return 0
		}
		return price - delta
	}
	return price + delta
}

// parseUSD reads a human dollar figure — "2", "2.5", "2.50", "0.069" —
// into micro-USD. Written by hand rather than with floats: a float would
// make "0.07" cost a different number of micro-dollars depending on the
// platform, and prices must be exact.
func parseUSD(s string) (int64, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, false
	}
	whole, frac := s, ""
	if i := strings.IndexByte(s, '.'); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	if whole == "" {
		whole = "0"
	}
	w, err := strconv.ParseInt(whole, 10, 64)
	if err != nil || w < 0 {
		return 0, false
	}
	// Pad or truncate the fraction to exactly six digits of micro-USD.
	if len(frac) > 6 {
		frac = frac[:6]
	}
	for len(frac) < 6 {
		frac += "0"
	}
	var f int64
	if frac != "" {
		f, err = strconv.ParseInt(frac, 10, 64)
		if err != nil || f < 0 {
			return 0, false
		}
	}
	return w*microUSD + f, true
}

// SetGlobalLengthRules writes the project-wide length rules:
// "1:300000000,2:150000000,3:60000000" prices one, two and three
// character names everywhere a domain has not said otherwise.
//
// IT HAD NO SETTER UNTIL NOW, which meant the only way to write it was
// the generic SetGlobal escape hatch — straight past normalizeRules, so
// a typo stored fine and then vanished at lookup time, because
// lookupRule skips a malformed pair in silence. A pricing layer whose
// only writer cannot validate is a pricing layer that fails open.
func SetGlobalLengthRules(cur realm, rules string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	setGlobal(cur, keyGlobalLens, normalizeRules(rules, true))
}

// SetPremiumNames writes one page of the premium keyword list, 1-based.
// The list is paged because the vault caps an extension value at 512
// bytes; see maxPremiumKeys.
//
// Same gap as above: normalizePremiums existed and nothing exported
// called it.
func SetPremiumNames(cur realm, page int, csv string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if page < 1 || page > maxPremiumKeys {
		panic("nslogic: premium page must be 1-" + strconv.Itoa(maxPremiumKeys))
	}
	v := normalizePremiums(csv)
	if len(v) > 512 {
		panic("nslogic: premium page " + strconv.Itoa(page) +
			" is " + strconv.Itoa(len(v)) + " bytes; the vault caps a value at 512. Split it across pages.")
	}
	setGlobal(cur, keyPremium+strconv.Itoa(page), v)
}

// PremiumNames reads one page back, so the admin panel can show what is
// stored rather than what it last sent.
func PremiumNames(page int) string {
	if page < 1 || page > maxPremiumKeys {
		return ""
	}
	return nsdata.GetGlobal(keyPremium + strconv.Itoa(page))
}

// GlobalLengthRules returns the whole rule string, for the same reason.
func GlobalLengthRules() string { return nsdata.GetGlobal(keyGlobalLens) }

// normalizePremiums validates a premium list before storage. Same
// reasoning as normalizeRules: a malformed entry must never reach the
// vault, because every later lookup would carry it.
func normalizePremiums(csv string) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad premium, want name:modifier — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" || strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in premium — " + k)
		}
		if seen[k] {
			panic("nslogic: duplicate premium name — " + k)
		}
		if !validPremiumValue(v) {
			panic("nslogic: bad premium modifier for " + k + " — " + v)
		}
		seen[k] = true
		out = append(out, k+":"+v)
	}
	return strings.Join(out, ",")
}

func validPremiumValue(v string) bool {
	if v == "" {
		return false
	}
	if strings.HasPrefix(v, "=") {
		_, ok := parseUSD(v[1:])
		return ok
	}
	if strings.HasPrefix(v, "-") || strings.HasPrefix(v, "+") {
		v = v[1:]
	}
	if strings.HasPrefix(v, "%") {
		p, err := strconv.ParseInt(v[1:], 10, 64)
		return err == nil && p >= 0
	}
	_, ok := parseUSD(v)
	return ok
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// Pricing lives here, not in the vault. The vault stores numbers as
// opaque strings and has no opinion about what they mean, so the whole
// model can be replaced by swapping this realm.
//
// PRICES ARE DENOMINATED IN USD, held as MICRO-USD (1 USD = 1_000_000)
// so fractions of a cent are expressible — a name that costs about a
// gumball needs that. Nothing is stored in ugnot: the chain's token is
// just the settlement rail, converted at payment time from a stored
// rate. Accepting a second token later is then only a second rate, not
// a second price list.
//
// PRECEDENCE — most specific wins:
//
//  1. per-name override      (keyNames: "420:5000000,gm:%500")
//  2. per-length rule        (keyLens:  "3:2000000,4:%150,5:0")
//  3. GLOBAL length rule     (global keyGlobalLens — see premium.gno)
//  4. domain base price      (keyPrice: "500000"  = $0.50)
//  5. global default         (global keyDefaultPrice)
//
// then the GLOBAL NAME PREMIUM adjusts the result, and a referral
// discount comes off last. Both live in premium.gno.
//
// A rule value is either an absolute micro-USD amount or "%N", meaning N
// percent of that domain's base — so repricing a domain once carries
// every relative rule under it. "0" means free, which is how giveaway
// tiers are expressed: "all five-character names under *pleb are free"
// is just a length rule resolving to zero.
//
// Rules are stored as CSV in ONE key each rather than one key per rule.
// The vault caps extension keys at 32 bytes and 24 entries per record; a
// key like "nm:somelongname" breaks the first and a few dozen premium
// names break the second. Two CSV keys sidestep both.
const (
	keyPrice        = "price" // domain base, micro-USD
	keyLens         = "len"   // length rules
	keyNames        = "nm"    // per-name overrides
	keyOpen         = "open"  // "0" closes the domain to new names
	keyDefaultPrice = "defaultPrice"
	keyRate         = "rateUgnotPerUsd" // ugnot equal to 1 USD

	microUSD         = int64(1_000_000)
	fallbackPriceUSD = int64(500_000) // $0.50
	// TESTNET PEG: $0.069 per GNOT, so 1 USD = 1/0.069 GNOT = 14.492753
	// GNOT = 14_492_753 ugnot. Deliberately a fixed number while we are on
	// a testnet whose token has no market price at all -- a "real" rate
	// there would be fiction dressed as precision. Replaced with a genuine
	// conversion before mainnet; tracked in MAINNET.md.
	fallbackRate = int64(14_492_753)
	maxRules     = 64
)

// DomainOpen reports whether names may currently be registered under a
// domain. An absent key means open — a domain created before this
// existed must not silently close.
func DomainOpen(domainLabel string) bool {
	return nsdata.GetDomainExtra(domainLabel, keyOpen) != "0"
}

// -- USD side --

func DefaultPriceUSD() int64 {
	if v := nsdata.GetGlobal(keyDefaultPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return fallbackPriceUSD
}

func DomainBasePriceUSD(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyPrice); v != "" {
		if p, err := strconv.ParseInt(v, 10, 64); err == nil && p >= 0 {
			return p
		}
	}
	return DefaultPriceUSD()
}

// NamePriceUSD resolves the four inputs in precedence order and returns
// micro-USD. This is the authoritative price; ugnot is derived from it.
func NamePriceUSD(domainLabel, label string) int64 {
	return applyPremium(PremiumFor(label), resolveBeforePremium(domainLabel, label))
}

// resolveBeforePremium runs steps 1-5. Separated from NamePriceUSD so
// the admin panel can show WHY a price is what it is: the figure before
// the premium and the figure after are both meaningful, and a single
// function returning only the total makes a wrong price impossible to
// diagnose.
func resolveBeforePremium(domainLabel, label string) int64 {
	base := DomainBasePriceUSD(domainLabel)
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyNames), label); ok {
		return applyRule(v, base)
	}
	if v, ok := lookupRule(nsdata.GetDomainExtra(domainLabel, keyLens), strconv.Itoa(len(label))); ok {
		return applyRule(v, base)
	}
	// The global length rule is a floor, not a replacement: it applies
	// only where the domain itself had nothing to say about this length.
	if v, ok := GlobalLengthRule(len(label)); ok {
		return applyRule(v, base)
	}
	return base
}

// ExplainPriceUSD returns each stage of the resolution, so the control
// panel can show the arithmetic rather than assert a total. Returns the
// price before any premium, the premium modifier that applied (empty if
// none), and the final price.
func ExplainPriceUSD(domainLabel, label string) (beforePremium int64, modifier string, final int64) {
	before := resolveBeforePremium(domainLabel, label)
	mod := PremiumFor(label)
	return before, mod, applyPremium(mod, before)
}

// -- settlement side --

// RateUgnotPerUsd is how many ugnot one USD buys.
//
// This is a MANUALLY MAINTAINED rate, not a market oracle: an admin
// writes it and it sits there until rewritten. That is a real
// operational hazard — a stale rate during a sharp move sells names at
// the wrong price in whichever direction hurts — and the mitigation is
// keeping it fresh, not anything this code can do. Kept as one global so
// a future logic realm can swap in a real oracle without touching the
// vault or restating a single price.
func RateUgnotPerUsd() int64 {
	if v := nsdata.GetGlobal(keyRate); v != "" {
		if r, err := strconv.ParseInt(v, 10, 64); err == nil && r > 0 {
			return r
		}
	}
	return fallbackRate
}

// NamePrice converts the USD price to ugnot for settlement. Rounds UP,
// so rounding never sells a name below its listed price; a free name
// stays exactly free.
func NamePrice(domainLabel, label string) int64 {
	usd := NamePriceUSD(domainLabel, label)
	if usd <= 0 {
		return 0
	}
	rate := RateUgnotPerUsd()
	return (usd*rate + microUSD - 1) / microUSD
}

// -- rule plumbing --

func applyRule(v string, base int64) int64 {
	if strings.HasPrefix(v, "%") {
		pct, err := strconv.ParseInt(v[1:], 10, 64)
		if err != nil || pct < 0 {
			return base
		}
		return base * pct / 100
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil || n < 0 {
		return base
	}
	return n
}

func lookupRule(csv, want string) (string, bool) {
	if csv == "" {
		return "", false
	}
	for _, pair := range strings.Split(csv, ",") {
		parts := strings.SplitN(strings.TrimSpace(pair), ":", 2)
		if len(parts) != 2 {
			continue
		}
		if strings.TrimSpace(parts[0]) == want {
			return strings.TrimSpace(parts[1]), true
		}
	}
	return "", false
}

// normalizeRules validates and canonicalises a rule string before it is
// stored, so a malformed entry can never reach storage and poison every
// later lookup.
func normalizeRules(csv string, numericKeys bool) string {
	if strings.TrimSpace(csv) == "" {
		return ""
	}
	var out []string
	seen := map[string]bool{}
	for _, pair := range strings.Split(csv, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		parts := strings.SplitN(pair, ":", 2)
		if len(parts) != 2 {
			panic("nslogic: bad rule, want key:value — got " + pair)
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		if k == "" {
			panic("nslogic: empty rule key")
		}
		if numericKeys {
			if n, err := strconv.Atoi(k); err != nil || n <= 0 {
				panic("nslogic: length must be a positive number — got " + k)
			}
		} else if strings.ContainsAny(k, "*, \t\n") {
			panic("nslogic: invalid name in rule — " + k)
		}
		if strings.HasPrefix(v, "%") {
			if p, err := strconv.ParseInt(v[1:], 10, 64); err != nil || p < 0 {
				panic("nslogic: bad percentage — " + v)
			}
		} else if n, err := strconv.ParseInt(v, 10, 64); err != nil || n < 0 {
			panic("nslogic: bad amount — " + v)
		}
		if seen[k] {
			panic("nslogic: duplicate rule key — " + k)
		}
		seen[k] = true
		out = append(out, k+":"+v)
		if len(out) > maxRules {
			panic("nslogic: too many rules (max 64)")
		}
	}
	return strings.Join(out, ",")
}

package nslogic

import (
	"strconv"
	"strings"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// The referral programme.
//
// SINGLE LEVEL, ALWAYS. One buyer, one referrer, one cut, taken out of
// an actual sale. There is no downline, no override on somebody else's
// referrals, and no bonus for recruiting other referrers — and there is
// no code here that could be extended into one without being obvious
// about it. That is the line between an affiliate programme and the
// other thing, and this realm stays on the near side of it.
//
// WHERE THE LINK LIVES. The referrer is recorded on the REFERRED NAME,
// in its extension slot, at the moment it is registered. That placement
// does the work of two rules for free, because nsdata already destroys a
// name's extras when a lapsed name is re-registered (names.Remove, then
// a fresh record) and when a name changes hands (wipeOnHandover):
//
//	a name that lapses loses its referrer
//	a name that is sold loses its referrer
//
// Neither needs code to enforce. Both would need code to PREVENT.
//
// WHO GETS PAID. An address, not a name. The referrer's wallet is fixed
// into the referred name at registration, so they may let their own name
// go, buy a different one, or hold ten — the commission does not move.
// What they cannot do is leave: paying out requires the referrer to
// still hold at least one name, checked at payment time.
//
// A SKIPPED PAYOUT IS NOT A DEBT. If the referrer holds nothing when a
// renewal comes through, the cut is simply not taken — the buyer pays
// less and the treasury keeps the difference. Nothing accrues, because
// accruing would mean holding somebody else's money until they qualify,
// and this realm holds nobody's money at any point.
//
// SELF-REFERRAL IS REFUSED. Otherwise the informed apply their own code
// forever and the cut becomes a silent discount for people who read the
// source.
//
// EVERYTHING SETTLES IN ONE TRANSACTION. Buyer pays, treasury is paid,
// referrer is paid, overpayment goes back — all inside the message the
// buyer signed. No escrow, no float, not for a block.
const (
	keyRef     = "ref"     // on a NAME: the referrer's address
	keyRefCut  = "refcut"  // global: tier table, referrer's percentage
	keyRefDisc = "refdisc" // global: tier table, buyer's discount
	keyRefStat = "ref:"    // global, per address: how many referred
	keyRefWin  = "refwin"  // global: days a captured code stays valid

	maxRefPercent = 50 // a cut plus a discount above this stops being a business
)

// -- tier tables --

// A tier table reads like the length rules do: "0:5,2:8,5:12" means five
// percent from the start, eight once the referrer has held a name two
// years, twelve at five. The highest tier at or below their tenure wins,
// so gaps are fine and the table never has to be exhaustive. An empty
// table means the programme pays nothing, which is also how it is
// switched off.
func tierPercent(spec string, years int64) int64 {
	best := int64(0)
	bestAt := int64(-1) // the threshold of the tier `best` came from
	for _, part := range strings.Split(spec, ",") {
		kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
		if len(kv) != 2 {
			continue
		}
		at, err1 := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64)
		pct, err2 := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err1 != nil || err2 != nil || at < 0 || pct < 0 {
			continue
		}
		if pct > maxRefPercent {
			pct = maxRefPercent
		}
		/* THE HIGHEST TIER THAT APPLIES, not the biggest number in the
		   table. This compared percentages, so a table where a later
		   tier pays LESS — the shape a taper needs, and the shape the
		   buyer-discount table is most likely to take — silently paid
		   the earlier, larger rate forever. Tracking the tier's
		   threshold instead makes the table mean what it reads as. */
		if years >= at && at >= bestAt {
			bestAt = at
			best = pct
		}
	}
	return best
}

// THE PRESET THE PROJECT LAUNCHES WITH.
//
// The referrer's CUT starts at five percent and gains five for each year
// they have held their name, reaching thirty at five years and above.
// The buyer's DISCOUNT starts at five and gains one a year, to ten. The
// two tables deliberately climb at different rates: what a referrer earns
// should reward standing still for years, while what a buyer saves should
// stay a nudge rather than becoming the reason to buy.
//
// It is written here rather than typed into the admin panel at launch for
// one reason: a number that exists only in somebody's memory of a
// conversation is a number that gets set wrong once and noticed a month
// later.
//
// THE SUM IS WHAT LEAVES THE TREASURY, and SetReferralRules refuses a
// pair above fifty percent at any tier either table mentions. This pair
// peaks at forty, at five years: thirty to the referrer, ten off the
// price. That is the number to look at when either table is edited — not
// the two columns separately.
//
// SIX STEPS because the panel shows six, and a table the panel cannot
// display is a table nobody will edit correctly. The last one is the
// "and above" tier: tierPercent takes the highest step at or below the
// referrer's tenure, so five years and fifty both pay ten.
//
// It is a DEFAULT, not a policy. SetReferralRules overwrites it and an
// empty table still means the programme pays nothing, which is how it is
// switched off — seeding must never take that away.
const (
	defaultRefCut      = "0:5,1:10,2:15,3:20,4:25,5:30"
	defaultRefDiscount = "0:5,1:6,2:7,3:8,4:9,5:10"
)

// DefaultReferralRules lets the site show what the presets are before
// anybody commits them, so the panel can offer them as a starting point
// instead of asking somebody to remember six numbers.
func DefaultReferralRules() (cut, discount string) {
	return defaultRefCut, defaultRefDiscount
}

// SeedReferralRules writes the presets, and ONLY into an empty table.
//
// Deliberately not an init(). This realm writes through nsdata, which
// refuses a writer it does not yet trust, and at init time a freshly
// deployed logic realm has not been granted that trust — so an init()
// would either panic the deploy or, worse, be silently skipped and leave
// the operator believing the defaults were applied.
//
// Refusing to overwrite is what makes it safe to call twice, and safe to
// call by mistake: it can restore a launch default, and it can never
// quietly undo a rate somebody chose on purpose.
func SeedReferralRules(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if nsdata.GetGlobal(keyRefCut) != "" || nsdata.GetGlobal(keyRefDisc) != "" {
		panic("nslogic: referral rules are already set; use SetReferralRules to change them")
	}
	SetReferralRules(cur, defaultRefCut, defaultRefDiscount)
}

func RefCutRules() string      { return nsdata.GetGlobal(keyRefCut) }
func RefDiscountRules() string { return nsdata.GetGlobal(keyRefDisc) }

// RefWindowDays is how long a clicked link keeps counting for. It is
// enforced by the browser that captured the code, not by this realm —
// the chain never sees the click, only the registration that quotes a
// code — so it is stored here purely to be ONE number rather than a
// constant baked separately into the site, the FAQ and the rules page.
// Zero means the default; the site treats an absent value the same way.
func RefWindowDays() int64 {
	d := parseInt64(nsdata.GetGlobal(keyRefWin))
	if d <= 0 {
		return 30
	}
	return d
}

func SetReferralWindow(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if days < 0 || days > 3650 {
		panic("nslogic: window must be 0-3650 days")
	}
	setGlobal(cur, keyRefWin, strconv.FormatInt(days, 10))
}

// ReferralQuote is what a code is worth, answered before anybody signs
// anything. One call rather than four, because the site needs all of it
// at once to show a price and every extra round trip is a moment where
// the number on screen is not the number the chain will charge.
//
// A referrer of "" means the code did not resolve, and the two
// percentages are then both zero.
func ReferralQuote(refName string, buyer address) (referrer address, tenure, discountPct, cutPct int64) {
	ref := resolveReferrer(refName, buyer)
	if ref == "" {
		return "", 0, 0, 0
	}
	years := TenureYears(ref)
	cut := int64(0)
	// The cut is zero for a referrer holding nothing, and saying so up
	// front is better than showing a percentage that silently will not
	// be paid when the transaction lands.
	//
	// ResolveAddress, NOT BalanceOf — the same test referralCut applies
	// when it actually pays. BalanceOf counts a lapsed name that nobody
	// has reclaimed yet (and, since every name became a token, free-tier
	// names too), so the quote promised a cut the payout then refused.
	if ResolveAddress(ref) != "" {
		cut = tierPercent(RefCutRules(), years)
	}
	return ref, years, tierPercent(RefDiscountRules(), years), cut
}

// SetReferralRules replaces both tier tables at once, because setting one
// without the other is how a cut ends up larger than the margin. Passing
// two empty strings turns the programme off: no discount, no commission,
// and registrations stop writing a referrer at all.
func SetReferralRules(cur realm, cutSpec, discountSpec string) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	cut := normalizeTiers(cutSpec)
	disc := normalizeTiers(discountSpec)
	// The two are paid out of the same list price, so their sum is what
	// actually leaves the treasury. Checked at every tenure either table
	// mentions rather than only at tier zero, since the tables need not
	// step at the same points.
	for _, y := range tierYears(cut, disc) {
		if tierPercent(cut, y)+tierPercent(disc, y) > maxRefPercent {
			panic("nslogic: cut plus discount exceeds 50% at year " + strconv.FormatInt(y, 10))
		}
	}
	setGlobal(cur, keyRefCut, cut)
	setGlobal(cur, keyRefDisc, disc)
}

func tierYears(specs ...string) []int64 {
	var out []int64
	seen := map[int64]bool{}
	for _, spec := range specs {
		for _, part := range strings.Split(spec, ",") {
			kv := strings.SplitN(strings.TrimSpace(part), ":", 2)
			if len(kv) != 2 {
				continue
			}
			if y, err := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64); err == nil && !seen[y] {
				seen[y] = true
				out = append(out, y)
			}
		}
	}
	if len(out) == 0 {
		out = append(out, 0)
	}
	return out
}

// normalizeTiers rejects a malformed table before it is stored, for the
// same reason normalizeRules does: a bad entry that reaches storage is
// then read silently and wrongly on every sale afterwards.
func normalizeTiers(spec string) string {
	if strings.TrimSpace(spec) == "" {
		return ""
	}
	var out []string
	seen := map[int64]bool{}
	for _, part := range strings.Split(spec, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		kv := strings.SplitN(part, ":", 2)
		if len(kv) != 2 {
			panic("nslogic: bad tier, want years:percent — got " + part)
		}
		y, err := strconv.ParseInt(strings.TrimSpace(kv[0]), 10, 64)
		if err != nil || y < 0 || y > 100 {
			panic("nslogic: tier years must be 0-100 — got " + kv[0])
		}
		p, err := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err != nil || p < 0 || p > maxRefPercent {
			panic("nslogic: tier percent must be 0-50 — got " + kv[1])
		}
		if seen[y] {
			panic("nslogic: duplicate tier year — " + kv[0])
		}
		seen[y] = true
		out = append(out, strconv.FormatInt(y, 10)+":"+strconv.FormatInt(p, 10))
		if len(out) > 16 {
			panic("nslogic: too many tiers (max 16)")
		}
	}
	return strings.Join(out, ",")
}

// -- tenure --

// TenureYears is how long a wallet counts as having been here, measured
// from its PRIMARY name and nothing else.
//
// The honest alternative — the oldest name the wallet holds — means
// walking the whole registry on every quote, which is a read that gets
// slower every time somebody registers and eventually stops working.
// Primary is one lookup and never gets slower. It is also already the
// wallet's declared identity, it is set automatically at a wallet's first
// registration, and a holder who wants an older name counted only has to
// make it their primary. The site says so on the referral page.
//
// A lapsed or missing primary is zero years, not an error: tier zero.
func TenureYears(who address) int64 {
	/* RESOLVED, NOT READ RAW. GetPrimary reports what an address last
	   SELECTED, not what it still holds — and a sale on the token ledger
	   no longer clears the seller's pointer. So a seller kept the tenure of
	   a five-year name they had sold, and every referral through their
	   young name got the top discount tier, paid by the treasury. An audit
	   found it; ResolveAddress re-checks the owner and the expiry. */
	tid := ResolveAddress(who)
	at := strings.Index(tid, "*")
	if at < 1 {
		return 0
	}
	_, _, _, streak, _, _ := nsdata.GetNameInfo(tid[:at], tid[at+1:])
	return streak
}

// -- where it gets paid --

// Commissions go to the referring wallet. There is no way to redirect
// them, and that is a decision rather than an omission.
//
// There WAS a redirect — SetReferralPayout, "a forwarding address, not a
// transferable right". It does not survive the obvious question: how
// would this realm tell somebody moving money between their own two
// wallets from somebody who has sold the stream to a stranger? It
// cannot. Nothing on chain distinguishes those, and a rule that cannot
// be enforced is not a rule, it is a sentence in a document.
//
// What settled it is that the redirect did not even serve the case it
// was written for. Calling it required signing from the ORIGINAL wallet,
// so "I lost access to my wallet" was never covered; the only wallet
// that could redirect was one whose owner could equally have received
// the money and forwarded it. It gave nothing to the honest case and
// gave the shape of an assignable income stream to the other one.
//
// So the destination is the referrer's own address, fixed. Selling the
// entitlement now means handing over private keys, which is a deterrent
// no contract clause could match.
func PayoutFor(who address) address { return who }

// -- the record on a name --

// ReferrerOf reads the wallet credited with a name, or the empty address.
func ReferrerOf(label, domainLabel string) address {
	v := nsdata.GetNameExtra(label, domainLabel, keyRef)
	if a := address(v); v != "" && a.IsValid() {
		return a
	}
	return ""
}

// resolveReferrer turns a claimed referring NAME into the wallet to
// credit, or the empty address if the claim does not stand up. Every
// rejection is silent on purpose: a mistyped or self-referral should not
// fail somebody's registration, it should simply earn nobody anything.
func resolveReferrer(refName string, buyer address) address {
	at := strings.Index(refName, "*")
	if refName == "" || at < 1 || at == len(refName)-1 {
		return ""
	}
	label, domainLabel := refName[:at], refName[at+1:]
	if !nsdata.NameExists(label, domainLabel) || !nsdata.IsNameValid(label, domainLabel) {
		return "" // a lapsed name is not a working code
	}
	owner := nsdata.GetNameOwner(label, domainLabel)
	if owner == buyer {
		return "" // no referring yourself
	}
	return owner
}

// -- the money --

// PriceWithReferral is what a buyer actually pays given the code they
// arrived with. Exported so the site can display the number the chain
// will charge instead of computing its own and hoping they agree.
func PriceWithReferral(domainLabel, label, refName string, buyer address) int64 {
	price := NamePrice(domainLabel, label)
	if price <= 0 {
		return 0 // free is free, and a percentage of nothing is nothing
	}
	ref := resolveReferrer(refName, buyer)
	if ref == "" {
		return price
	}
	pct := tierPercent(RefDiscountRules(), TenureYears(ref))
	if pct <= 0 {
		return price
	}
	return price - (price * pct / 100)
}

// referralCut is what leaves for the referrer out of a payment of
// `price`, and is zero unless they still hold a name. Returns the
// destination address and the amount; the caller pays it in the same
// banker call that pays the treasury.
func referralCut(ref address, price int64) (address, int64) {
	if ref == "" || price <= 0 {
		return "", 0
	}
	/* STILL HERE, AND STILL VALID.
	   This tested nsdata.BalanceOf, which has no expiry filter — and a
	   token is burned only when somebody else re-registers the label. So
	   a referrer who bought one cheap name, earned credits and walked
	   away kept a balance of one forever, and every renewal of every
	   name they ever referred kept paying them out of treasury revenue.
	   That is exactly the standing charge the note above says the check
	   prevents.
	   ResolveAddress is the honest test: it returns a name only when the
	   address still owns it AND it has not expired. TenureYears does the
	   same lookup two lines below, so this costs nothing extra. */
	if ResolveAddress(ref) == "" {
		return "", 0
	}
	pct := tierPercent(RefCutRules(), TenureYears(ref))
	if pct <= 0 {
		return "", 0
	}
	cut := price * pct / 100
	if cut <= 0 {
		return "", 0
	}
	return PayoutFor(ref), cut
}

// -- the scoreboard --

// creditReferral records one paid referral against a wallet.
//
// The COUNT and nothing else. There was a running total of micro-USD
// beside it, and it is gone, because a number stored in the vault is a
// number anyone with an RPC endpoint can read — there is no such thing
// as an admin-only global on a public chain, and building the site as
// though there were would be the kind of privacy that works right up
// until somebody checks.
//
// Not storing it is the only real reduction available. The payments are
// still in the block history and always will be, so anyone determined
// can add them up; what we can decline to do is publish a convenient
// running total ourselves. tools/referrals.py reconstructs it from the
// chain when we want it, which costs no storage and publishes nothing.
//
// The registrant's transaction pays for this entry. It is about forty
// bytes, written once per referrer and overwritten after, and it is the
// price of the discount they just received.
func creditReferral(cur realm, ref address) {
	if ref == "" {
		return
	}
	setGlobal(cur, keyRefStat+ref.String(),
		strconv.FormatInt(ReferralCount(ref)+1, 10))
}

// ReferralCount is how many paid registrations a wallet has been
// credited with. Public, like every other global here.
func ReferralCount(who address) int64 {
	return parseInt64(nsdata.GetGlobal(keyRefStat + who.String()))
}

func parseInt64(s string) int64 {
	v, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		return 0
	}
	return v
}

// ReferralBoard pages through every credited wallet for the
// leaderboard: one "address,count" row per line. The vault stores
// globals in a sorted tree, so the "ref:" entries are one contiguous run
// and the walk stops at the first key past it rather than reading the
// rest of the config.
func ReferralBoard(after string, limit int) (rows, next string) {
	if limit <= 0 || limit > 200 {
		limit = 200
	}
	from := keyRefStat
	if after != "" {
		from = keyRefStat + after
	}
	var out []string
	for len(out) < limit {
		keys, more := nsdata.ExportGlobalKeys(from, limit)
		if keys == "" {
			break
		}
		stop := false
		for _, k := range strings.Split(keys, ",") {
			if !strings.HasPrefix(k, keyRefStat) {
				stop = true
				break
			}
			addr := k[len(keyRefStat):]
			n := ReferralCount(address(addr))
			if n <= 0 {
				continue
			}
			out = append(out, addr+","+strconv.FormatInt(n, 10))
			if len(out) >= limit {
				next = addr
				break
			}
		}
		if stop || more == "" || more == from {
			break
		}
		from = more
	}
	return strings.Join(out, "\n"), next
}

package nslogic

import (
	"strconv"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// GENERATED BY tools/gen-reserved.py FROM collections/reserved-labels.json.
// Do not edit by hand: the site reads the same source, and a change made
// in one place only is a label the site offers and the chain refuses.
//
// STRUCTURAL RULES ONLY. The wordlists live off chain, in that JSON,
// because storage is 100 ugnot per byte and a ten-thousand-word
// dictionary is about 57 GNOT paid forever to encode a marketing
// decision that will change. This is the backstop against a bug in the
// issuer, not the place the policy lives.
//
// THE NUMBERS ARE SETTABLE, the shape is not. A minimum length is a
// promotion knob and belongs in the panel — redeploying this realm to
// change a 5 to a 4 costs about 22 GNOT. So the lengths read from the
// vault's globals and fall back to the values generated here; the
// pattern rules are structural facts about what a handle looks like and
// stay in code.

const (
	defaultFreeMinLength = 5
	defaultFreeMaxLength = 63

	keyFreeMin = "freemin"
	keyFreeMax = "freemax"
)

// FreeMinLength is the shortest label the free tier will issue. Settable
// from the panel, because which lengths are worth money is a commercial
// judgement that moves.
func FreeMinLength() int {
	if v := nsdata.GetGlobal(keyFreeMin); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 63 {
			return n
		}
	}
	return defaultFreeMinLength
}

func FreeMaxLength() int {
	if v := nsdata.GetGlobal(keyFreeMax); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 63 {
			return n
		}
	}
	return defaultFreeMaxLength
}

/*
FreeLabelAllowed reports whether a label may be ISSUED on the free tier.

ISSUED, and never renewed. This is called by GrantFreeName and by
nothing else, deliberately: if the minimum length rises from three to
five, somebody who already holds a three-character free name keeps it
and keeps renewing it free. Tightening a rule must not reach backwards
and take away what was already given — that is the single fastest way to
make a giveaway cost more trust than it ever bought.

A name that LAPSES and is registered again is a new issuance, and gets
whatever the rules say that day. That is not retroactive; it is a
different name event.
*/
func FreeLabelAllowed(label string) bool {
	n := len(label)
	if n < FreeMinLength() || n > FreeMaxLength() {
		return false
	}
	// Pure digits: 1337, 420, years. Collectible, and no handle is one.
	digits := true
	for i := 0; i < n; i++ {
		if label[i] < '0' || label[i] > '9' {
			digits = false
			break
		}
	}
	if digits {
		return false
	}
	// aaaa — every character the same.
	same := true
	for i := 1; i < n; i++ {
		if label[i] != label[0] {
			same = false
			break
		}
	}
	if same {
		return false
	}
	// abab — a two-character cycle. Also collectible, also not a handle.
	if n >= 4 {
		cycle := true
		for i := 2; i < n; i++ {
			if label[i] != label[i-2] {
				cycle = false
				break
			}
		}
		if cycle {
			return false
		}
	}
	return true
}

package nslogic

import (
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

/*
REBUILDING THE REGISTRY ON A NEW CHAIN.

WHY THIS EXISTS. gno.land replaces testnets rather than preserving them:
topaz-1 was superseded by sapphire-1 on twenty-four hours' notice and
every name registered on it went to zero. tools/snapshot.js keeps a
complete off-chain copy of the vault for exactly that morning. This is
the other half — the path that turns a snapshot back into a live
registry, so that people who paid for a name get that name back rather
than an apology.

THIS IS A BACKDOOR, AND IT IS TREATED AS ONE.

A function that can mint any name, to any address, with any registration
date, is precisely the thing that would make every name here worthless
if it could be reached whenever the admin felt like it. Ownership means
nothing if history is editable on demand. So the capability is not
merely admin-gated — admin-gated is what everything else here already
is, and it is not enough for this. It is a ONE-SHOT:

  - it starts closed, and on a chain where nothing needs restoring it is
    sealed immediately and can never be used at all;
  - opening it is a deliberate, separate, announced act with a deadline
    attached, so forgetting to close it is not the same as leaving it
    open forever;
  - sealing is IRREVERSIBLE. Sealed cannot be reopened. There is no
    argument that unseals it, including a good one;
  - it refuses to touch a name that already exists. It fills gaps in an
    empty registry; it cannot rewrite a live one.

WHERE THE SEAL LIVES, AND WHY IT IS NOT HERE. This realm holds no state
at all — that is the whole reason prices and names survive a logic
upgrade untouched. If the seal lived in this realm's variables it would
reset to "never opened" the moment a new generation was deployed, which
would make "irreversible" a lie with a two-hour shelf life. It lives in
the vault's global slot instead, so a new logic generation inherits a
seal it cannot talk its way out of.

WHAT THAT DOES AND DOES NOT GUARANTEE. It is a real barrier against
every accident and against this realm being reached later for something
it was not built for. It is not a barrier against the admin themselves,
who can deploy a further logic realm and have the vault trust it — but
that is already total control by definition, and no flag in a realm the
admin can replace was ever going to change it. What the seal gives is
the thing that actually matters in practice: the state is public, it is
checkable by anybody at any time through RestoreStatus, and moving it
backwards leaves a permanent trace on chain.

WHAT IT DELIBERATELY DOES NOT RESTORE. Marketplace listings and open
votes. Those live in their own realms, are intentions rather than facts,
and are re-creatable by the people who made them in one transaction
each. Re-materialising somebody's month-old asking price as though they
had just set it would be inventing a decision on their behalf.
*/

// The vault key holding the state of this whole mechanism.
const keyRestore = "restore"

// Restore states, stored as a string in the vault's global slot.
const (
	restoreNever  = ""       // never opened; the normal state forever
	restoreSealed = "sealed" // closed permanently; cannot be reopened
	restoreOpen   = "open:"  // followed by the unix second it lapses
)

// The longest a restore window may be left open. A restore is a day of
// work, not a season, and an unbounded window is just "open forever"
// spelled differently — the failure here is nobody remembering to seal
// it, so the deadline seals it for them.
const maxRestoreDays = 30

// RestoreStatus reports the state of the restore mechanism in a form a
// person can read, and is deliberately PUBLIC AND UNAUTHENTICATED.
// Anybody at all can check whether this registry currently has a door in
// it, without asking us and without trusting the answer we would give.
//
// Returns the state ("never", "open", "expired" or "sealed"), the unix
// second an open window lapses (0 otherwise), and how many records have
// been restored in the lifetime of this vault.
func RestoreStatus() (state string, deadline int64, restored int64) {
	st, d := readRestoreState(nsdata.GetGlobal(keyRestore), time.Now().Unix())
	return st, d, restoredCount()
}

// readRestoreState is the state machine on its own, with the clock passed
// in. Split out so the one piece of logic that decides whether the door
// is open can be tested exhaustively without a chain under it.
func readRestoreState(raw string, now int64) (state string, deadline int64) {
	switch {
	case raw == restoreSealed:
		return "sealed", 0
	case strings.HasPrefix(raw, restoreOpen):
		d, err := strconv.ParseInt(raw[len(restoreOpen):], 10, 64)
		if err != nil || d <= 0 {
			// An unparseable deadline is read as NO permission. The safe
			// reading of a door whose lock is broken is "shut" — a corrupt
			// value must never widen what somebody is allowed to do.
			return "sealed", 0
		}
		if now >= d {
			return "expired", d
		}
		return "open", d
	}
	return "never", 0
}

const keyRestoredCount = "restored"

func restoredCount() int64 {
	if v := nsdata.GetGlobal(keyRestoredCount); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			return n
		}
	}
	return 0
}

/*
THE RESERVED-KEY DOOR DOES NOT EXIST ON THE DEPLOYED VAULT, so these
writes go through the ordinary setter.

nsdata/v1 is live and permanent, and its SetGlobalRecord takes any key
with no reserved-key guard at all. The two-door design — a general setter
that refuses "restore"/"restored" plus SetReservedGlobalRecord for the
machinery — exists only in the local nsdata source, which can never be
deployed over a vault holding real records. Calling for a door that is
not in the wall does not fail at review; it fails at deploy, after the
deposit is spent.

So the seal is guarded in ONE place: setGlobal in admin.gno, which panics
on both keys. That is weaker than the intended belt-and-braces — a future
logic realm could drop the guard by forgetting it, and the vault would
not catch it — and it is the strongest version available on this chain.
Do not "restore" the reserved call: it will not link.
*/
func bumpRestored(cur realm, n int64) {
	nsdata.SetGlobalRecord(cross(cur), keyRestoredCount,
		strconv.FormatInt(restoredCount()+n, 10))
}

// assertRestoring is the gate every Restore* function passes through.
func assertRestoring(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	state, _, _ := RestoreStatus()
	switch state {
	case "open":
		return
	case "sealed":
		panic("nslogic: restore was sealed and cannot be reopened. This is " +
			"not recoverable by design — a registry whose history can be " +
			"rewritten on request does not have owners, it has guests.")
	case "expired":
		panic("nslogic: the restore window has lapsed. Deploy a fresh vault " +
			"and open a new window there; an expired one does not reopen.")
	}
	panic("nslogic: restore has never been opened. Call OpenRestore first, " +
		"and mean it.")
}

// OpenRestore opens the window, once, for a bounded number of days.
//
// Only ever valid on a chain where the registry is EMPTY because the
// previous chain was retired. It cannot be called on a vault that has
// been sealed, and it cannot be called twice.
func OpenRestore(cur realm, days int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)

	state, _, _ := RestoreStatus()
	if state != "never" {
		panic("nslogic: restore may be opened exactly once per vault; this " +
			"one is already " + state + ". A door that reopens is a door.")
	}
	if days < 1 || days > maxRestoreDays {
		panic("nslogic: a restore window must be between 1 and " +
			strconv.Itoa(maxRestoreDays) + " days")
	}
	/* THE PRECONDITION THE COMMENT ABOVE ALREADY CLAIMS.
	   "Only ever valid on a chain where the registry is EMPTY" was a
	   statement of intent that nothing enforced, so the window was
	   openable on a populated vault. The record restorers all refuse an
	   existing record, but RestoreNameField does not — it writes any
	   extension key on any EXISTING name, which includes the payment
	   addresses the site renders on a name's pay page. That is a way to
	   redirect somebody else's incoming money using only the admin key,
	   without the timelock and public event that granting a fresh logic
	   realm would cost. Now it is what it said it was. */
	/* NAMES ONLY, not domains. A registry is now born with its domains
	   (genesis), so "no domains" can never be true again and the guard
	   would have made disaster recovery impossible on every new chain.
	   The hazard it exists for is RestoreNameField writing onto EXISTING
	   NAMES — somebody's pay address — and only names carry that. */
	if _, n, _, _ := nsdata.Sizes(); n != 0 {
		panic("nslogic: restore is for a registry holding no names yet; " +
			"this one already holds records")
	}
	deadline := time.Now().Unix() + days*86400
	nsdata.SetGlobalRecord(cross(cur), keyRestore,
		restoreOpen+strconv.FormatInt(deadline, 10))
}

// SealRestore closes the door permanently. Valid from any state,
// including "never" — which is how it should be called on a chain that
// has nothing to restore, so that the capability is provably dead rather
// than merely unused.
//
// There is no matching unseal, and adding one later would defeat every
// word written at the top of this file.
func SealRestore(cur realm) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	nsdata.SetGlobalRecord(cross(cur), keyRestore, restoreSealed)
}

/*
RestoreDomain re-creates one domain with its original dates.

ORDER MATTERS: domains before their names. The vault refuses to register
a name under a domain that does not exist or had lapsed at the moment
the name claims to have been registered, which is correct behaviour and
also exactly the order a snapshot should be replayed in.

The vault's own registration path sets `registered` to whatever instant
it is handed and derives the expiry from the term length, so the
registration date is restored by passing the ORIGINAL one, and the
expiry is then corrected to the recorded value rather than a computed
one. Anything else would quietly hand everybody a fresh term.
*/
func RestoreDomain(cur realm, label string, owner address, registered, expires, ttl int64, frozen bool) {
	assertRestoring(cur)
	if nsdata.DomainExists(label) {
		panic("nslogic: " + label + " already exists; restore fills an empty " +
			"registry and never overwrites a live record")
	}
	if registered <= 0 || expires <= 0 {
		panic("nslogic: a restored record needs its original dates")
	}
	if err := nsdata.RegisterDomainRecord(cross(cur), label, owner, registered); err != nil {
		panic("nslogic: " + err.Error())
	}
	nsdata.SetDomainExpiryRecord(cross(cur), label, expires)
	if ttl != 0 {
		if err := nsdata.SetDomainTTLRecord(cross(cur), label, ttl); err != nil {
			panic("nslogic: " + err.Error())
		}
	}
	if frozen {
		nsdata.SetDomainFrozen(cross(cur), label, true)
	}
	bumpRestored(cur, 1)
}

// RestoreName re-creates one name. See RestoreDomain on ordering and on
// why the dates are passed rather than computed.
//
// isNFT is carried across under its old name so snapshot blobs stay
// readable, and now means PAID: false restores a free-tier name with the
// hold on its token, so a restore can never quietly make a free name
// sellable.
func RestoreName(cur realm, label, domainLabel string, owner address, registered, expires, ttl int64, frozen, isNFT bool) {
	assertRestoring(cur)
	if nsdata.NameExists(label, domainLabel) {
		panic("nslogic: " + label + "*" + domainLabel + " already exists; " +
			"restore fills an empty registry and never overwrites a live record")
	}
	if registered <= 0 || expires <= 0 {
		panic("nslogic: a restored record needs its original dates")
	}
	// RestoreNameRecord, not RegisterNameRecord: it ADOPTS a token the
	// ledger already holds, which is the whole point of a migration —
	// records move, tokens do not. If the ledger's holder is not the
	// snapshot's owner, the record is written for the holder and the
	// snapshot's profile is not replayed onto it.
	if err := nsdata.RestoreNameRecord(cross(cur), label, domainLabel, owner, registered, isNFT); err != nil {
		panic("nslogic: " + err.Error())
	}
	nsdata.SetNameExpiryRecord(cross(cur), label, domainLabel, expires)
	if ttl != 0 {
		if err := nsdata.SetNameTTLRecord(cross(cur), label, domainLabel, ttl); err != nil {
			panic("nslogic: " + err.Error())
		}
	}
	if frozen {
		nsdata.SetNameFrozen(cross(cur), label, domainLabel, true)
	}
	bumpRestored(cur, 1)
}

/*
RestoreNames replays many names in ONE transaction.

WHY A BLOB AND NOT A LOOP OF CALLS. A restore is done in one sitting
against a clock: the window is bounded and the people whose names are
missing are watching. One transaction per name is one signature per
name, and at a few hundred names that is an afternoon of clicking during
which a single mistimed refresh loses the thread. The compact form here
is unpleasant to read and it is the difference between a restore that
gets finished and one that gets abandoned half way.

The format is records separated by "|", fields separated by ",":

	label,domain,owner,registered,expires,ttl,frozen,isNFT

Neither a label nor a domain may contain "," or "|" — the character set
is enforced at registration — and an address contains neither, so the
split is unambiguous. tools/snapshot.js writes the JSON this is built
from; see tools/restore-blob.js for the conversion.

It stops at the first bad record and panics, taking the whole
transaction with it. That is deliberate: a partial batch that silently
skipped four names would leave four people without theirs and nothing
anywhere saying which four.
*/
func RestoreNames(cur realm, blob string) int {
	assertRestoring(cur)
	if blob == "" {
		panic("nslogic: nothing to restore")
	}
	recs := strings.Split(blob, "|")
	if len(recs) > 50 {
		panic("nslogic: at most 50 records per call, or the transaction " +
			"runs out of gas half way and it is unclear what landed")
	}
	done := 0
	for i, rec := range recs {
		if rec == "" {
			continue
		}
		r := parseRestoreRecord(rec, i)
		if nsdata.NameExists(r.label, r.domain) {
			panic("nslogic: record " + strconv.Itoa(i) + " (" + r.label + "*" + r.domain +
				") already exists; restore never overwrites a live record")
		}
		if err := nsdata.RestoreNameRecord(cross(cur), r.label, r.domain, r.owner, r.registered, r.isNFT); err != nil {
			panic("nslogic: record " + strconv.Itoa(i) + ": " + err.Error())
		}
		nsdata.SetNameExpiryRecord(cross(cur), r.label, r.domain, r.expires)
		if r.ttl != 0 {
			if err := nsdata.SetNameTTLRecord(cross(cur), r.label, r.domain, r.ttl); err != nil {
				panic("nslogic: record " + strconv.Itoa(i) + ": " + err.Error())
			}
		}
		if r.frozen {
			nsdata.SetNameFrozen(cross(cur), r.label, r.domain, true)
		}
		done++
	}
	bumpRestored(cur, int64(done))
	return done
}

// restoreRec is one parsed line of the blob.
type restoreRec struct {
	label, domain string
	owner         address
	registered    int64
	expires, ttl  int64
	frozen, isNFT bool
}

/*
parseRestoreRecord reads one record and refuses anything it is not sure
about.

EVERY CHECK HERE IS A PANIC AND NOT A SKIP. The blob is machine-written
from a snapshot, so a malformed record does not mean "this one name is
odd", it means the file is not what it was believed to be — and the
worst outcome available is a restore that appears to succeed while
quietly dropping the records it could not read. Somebody would find out
months later when one person asked where their name went.
*/
func parseRestoreRecord(rec string, i int) restoreRec {
	f := strings.Split(rec, ",")
	if len(f) != 8 {
		panic("nslogic: record " + strconv.Itoa(i) + " has " +
			strconv.Itoa(len(f)) + " fields, expected 8 " +
			"(label,domain,owner,registered,expires,ttl,frozen,isNFT)")
	}
	if f[0] == "" || f[1] == "" {
		panic("nslogic: record " + strconv.Itoa(i) + " has no name")
	}
	out := restoreRec{
		label:      f[0],
		domain:     f[1],
		owner:      address(f[2]),
		registered: mustSecs(f[3], i, "registered"),
		expires:    mustSecs(f[4], i, "expires"),
		ttl:        mustSecs(f[5], i, "ttl"),
		frozen:     f[6] == "1",
		isNFT:      f[7] == "1",
	}
	if !out.owner.IsValid() {
		panic("nslogic: record " + strconv.Itoa(i) + " has an invalid owner address")
	}
	if out.registered <= 0 || out.expires <= 0 {
		panic("nslogic: record " + strconv.Itoa(i) + " is missing its original dates")
	}
	// An expiry before the registration is not a record, it is a
	// corruption, and restoring it would create a name that was already
	// reclaimable the day it was bought.
	if out.expires < out.registered {
		panic("nslogic: record " + strconv.Itoa(i) + " expires before it was registered")
	}
	return out
}

func mustSecs(s string, i int, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v < 0 {
		panic("nslogic: record " + strconv.Itoa(i) + " has a bad " + what)
	}
	return v
}

// RestoreNameField and RestoreDomainField put back a record's extension
// keys — profiles, cross-chain addresses, tier markers, and a domain's
// pricing rules. Separate calls because the extension slot has no fixed
// shape by design, which is the same reason the snapshot captures it by
// enumeration rather than by schema.
func RestoreNameField(cur realm, label, domainLabel, key, value string) {
	assertRestoring(cur)
	/* ONLY ONTO A RECORD A RESTORE WROTE, AND ONLY FOR ITS HOLDER.

	   Profile fields include pay addresses, so replaying one is replaying
	   where money goes. Two audit findings meet here: a name sold between
	   the snapshot and the restore would have had the seller's addresses
	   written onto the buyer's name, and a name a user registered DURING
	   the restore window could have had its pay fields rewritten with the
	   admin key alone. RestoredFor is set only by RestoreNameRecord, and
	   only when the ledger's holder matched the snapshot.

	   Skipped rather than panicked, deliberately: a blob of fields rides in
	   one transaction, and one sold name must not abort everybody else's
	   restore. tools/restore-blob.js reads the fields back afterwards. */
	rf := nsdata.RestoredFor(label, domainLabel)
	if rf == "" || nsdata.GetNameOwner(label, domainLabel) != rf {
		return
	}
	if err := nsdata.SetNameExtraRecord(cross(cur), label, domainLabel, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

func RestoreDomainField(cur realm, label, key, value string) {
	assertRestoring(cur)
	if err := nsdata.SetDomainExtraRecord(cross(cur), label, key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestoreGlobal puts back the vault's global slot — where the default
// price, the referral tiers and the seasonal card effects live.
//
// It refuses to write the restore keys themselves. Without that, a
// snapshot taken while a window was open would, on being replayed,
// cheerfully restore the open window along with everything else — and a
// seal that a backup file can undo is not a seal.
func RestoreGlobal(cur realm, key, value string) {
	assertRestoring(cur)
	if key == keyRestore || key == keyRestoredCount {
		panic("nslogic: the restore mechanism does not restore itself")
	}
	if err := nsdata.SetGlobalRecord(cross(cur), key, value); err != nil {
		panic("nslogic: " + err.Error())
	}
}

// RestorePrimary puts back reverse resolution — which name an address
// answers to. Registration already sets this for an owner who had none,
// so this exists for the owners who had chosen a different one.
func RestorePrimary(cur realm, owner address, label, domainLabel string) {
	assertRestoring(cur)
	if err := nsdata.SetPrimaryRecord(cross(cur), owner, label, domainLabel); err != nil {
		panic("nslogic: " + err.Error())
	}
}

package nslogic

import (
	"strconv"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// How far ahead a name may be paid.
//
// Renewal was unbounded. RenewNameRecord adds one term to the previous
// due date and asks no further questions, so a holder pressing renew
// seven times bought seven years of runway, and nothing anywhere said
// that was not intended. It is a bug in two directions at once:
//
//   - Free domains have a base price of zero. Renewal is free too, so a
//     script could take every good name under *gnoland and hold it for a
//     century for the cost of gas. There is no economic brake on a free
//     name at all; the term limit IS the brake.
//   - A paid name held fifty years ahead is fifty years of a promise we
//     have made against a rate written by hand and a testnet that will
//     be replaced. Selling that is easy and honouring it is not.
//
// The limit is RUNWAY, not total lifetime: at most N years may be
// outstanding at any moment. Nobody is stopped from holding a name
// forever — they renew as the runway burns down, which is the same
// arrangement every domain registrar has always used and the one people
// already understand.
//
// Per domain first, then a project-wide default, so a free domain can be
// capped at one year without capping anything else.
const (
	keyMaxTerm      = "maxterm" // domain extra AND global: years of runway
	defaultMaxTerm  = int64(5)
	maxMaxTermYears = int64(100)
)

// MaxTermYears is the cap that applies to names under this domain.
func MaxTermYears(domainLabel string) int64 {
	if v := nsdata.GetDomainExtra(domainLabel, keyMaxTerm); v != "" {
		if y, err := strconv.ParseInt(v, 10, 64); err == nil && y > 0 {
			return y
		}
	}
	if v := nsdata.GetGlobal(keyMaxTerm); v != "" {
		if y, err := strconv.ParseInt(v, 10, 64); err == nil && y > 0 {
			return y
		}
	}
	return defaultMaxTerm
}

// SetMaxTerm caps a single domain, or the whole project when the domain
// label is empty. A domain's own cap always wins, so tightening one free
// domain does not disturb the rest.
func SetMaxTerm(cur realm, domainLabel string, years int64) {
	assertNoSend(cur)
	assertIsAdmin(cur)
	if years < 1 || years > maxMaxTermYears {
		panic("nslogic: term cap must be 1-100 years")
	}
	v := strconv.FormatInt(years, 10)
	if domainLabel == "" {
		setGlobal(cur, keyMaxTerm, v)
		return
	}
	if !nsdata.DomainExists(domainLabel) {
		panic("nslogic: unknown domain")
	}
	if err := nsdata.SetDomainExtraRecord(cross(cur), domainLabel, keyMaxTerm, v); err != nil {
		panic(err)
	}
}

// RenewalsLeft is how many more years may be added to a name right now.
// Zero means the renew button should be off, and the site reads this
// rather than doing the arithmetic itself — the cap can be per domain,
// and a page that guesses it will guess wrong on exactly the domains
// where it matters.
//
// An unregistered name reports the full allowance: nothing is holding
// runway yet.
func RenewalsLeft(label, domainLabel string) int64 {
	maxYears := MaxTermYears(domainLabel)
	if !nsdata.NameExists(label, domainLabel) {
		return maxYears
	}
	term := nsdata.GetTermLength()
	if term <= 0 {
		return 0
	}
	_, _, expires, _, _, _ := nsdata.GetNameInfo(label, domainLabel)
	return renewalsLeft(expires, time.Now().Unix(), term, maxYears)
}

// renewalsLeft is the arithmetic on its own, so it can be tested without
// a chain under it.
//
// Runway is measured from NOW, not from the registration date, so a name
// deep in its grace period counts as zero rather than as a negative that
// would then read as extra room. Years already bought round UP: a name
// with thirteen months left is holding two of its five, because the
// alternative lets somebody sit permanently at four-years-and-eleven-
// months and renew every month forever.
func renewalsLeft(expires, now, term, maxYears int64) int64 {
	if term <= 0 {
		return 0
	}
	runway := expires - now
	if runway < 0 {
		runway = 0
	}
	left := maxYears - (runway+term-1)/term
	if left < 0 {
		return 0
	}
	return left
}

// assertRoomToRenew is the enforcement. It runs before payment is taken,
// so a rejected renewal costs gas and nothing else — taking the money
// first and reverting would work too, but only because a panic reverts,
// and depending on that for a refund is a habit that eventually meets a
// path where it is not true.
func assertRoomToRenew(label, domainLabel string) {
	if RenewalsLeft(label, domainLabel) > 0 {
		return
	}
	panic(ufmt.Sprintf(
		"nslogic: %s*%s is already paid %d years ahead, which is the limit. Renew again when it has run down.",
		label, domainLabel, MaxTermYears(domainLabel)))
}

// Package nslogic is the swappable "business rules" half of the split
// (NOTES.md §9t). It holds every piece of policy that might reasonably
// change — pricing, character validation, payment/refund, freeze rules,
// transfer restrictions — and no persistent records of its own.
//
// Every mutation here ends by calling into nsdata's narrow Record/Raw
// API via cross(cur). nsdata trusts whichever address is currently wired
// up as trustedLogic to have done its own authorization checks
// correctly, so THIS realm is where "is the caller allowed to do this"
// actually lives. If a bug is found here, admin deploys a fixed nslogic
// and re-points the vault at it (ProposeTrustedLogicGrant, then
// ExecutePending after the timelock) — no data migration,
// records and config untouched.
//
// Deliberately reads config fresh from nsdata on every call rather than
// caching it. The one thing that cannot be read fresh is a COMPILED
// regex — avl trees store the pattern string, not the compiled object —
// so that one value is cached, and the cache is validated against
// nsdata on every use.
package nslogic

const (
	ugnot    = "ugnot"
	bpsDenom = 10_000
)

package nslogic

import (
	"strings"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1pmffzfv3326akjjs27mqp4zgumlnqne7urjm7x/nsdata/v1"
)

// THE LABEL RULE IS WRITTEN OUT, NOT COMPILED.
//
// It used to be a regexp, and that regexp was the single most expensive
// thing in this realm — by a wide margin, and not by a little. Measured
// on sapphire-1 with vm/qstorage against purpose-built probe realms:
//
//	a realm with code and no package-level state      2,711 bytes
//	the same realm plus ONE compiled regexp         154,877 bytes
//
// A compiled regexp is an object graph, and gno charges 100 ugnot for
// every byte of it, forever. That one variable was 15.2 GNOT of the
// 22.5 GNOT it costs to deploy this realm — about 68% of the bill, to
// enforce a rule that fits in thirty lines.
//
// The second regexp was worse, because it was compiled LAZILY and cached
// in a package-level var. That does not avoid the cost, it MOVES it: the
// first person to register a name after a fresh deploy would have had
// their transaction grow this realm's storage by 150KB and been charged
// ~15 GNOT of deposit for it. Confirmed by probe, not inferred — a realm
// deployed at 2,711 bytes went to 154,149 the moment one call compiled
// and cached a regexp, billed to the caller. Somebody buying a ten-cent
// name would have been asked for fifteen GNOT.
//
// The hand-written version is also 6x cheaper in gas on every call
// (1.06M against 6.67M), so there is no axis on which the regexp was
// the better choice. It read better. That was the whole of its case.
//
// WHAT THIS COSTS US. The pattern is no longer admin-tunable at runtime:
// changing the rule now means redeploying this realm. That is a fair
// trade at 7 GNOT a deploy, it was never a rule that should change
// casually, and SetLabelPattern refuses anything but the implemented
// pattern so the stored string can never describe rules the code does
// not enforce.

// labelRule is the pattern this realm implements, kept as a string so
// nsdata, the error messages and the site all quote the same thing.
const labelRule = `^[a-z0-9]+(-[a-z0-9]+)*$`

// matchesLabelRule is that pattern, by hand: lowercase letters and
// digits, single hyphens between them, none at either end.
func matchesLabelRule(s string) bool {
	if s == "" {
		return false
	}
	prevHyphen := true // a leading hyphen is not allowed
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
			prevHyphen = false
		case c == '-':
			if prevHyphen {
				return false // leading, or two in a row
			}
			prevHyphen = true
		default:
			return false
		}
	}
	return !prevHyphen // nor a trailing one
}

// looksLikeAddress was `^g1[a-z0-9]{20,38}$`. Anything shaped like a real
// gno.land address is refused as a label, so a name can never be mistaken
// for a raw wallet address in a UI.
func looksLikeAddress(s string) bool {
	if len(s) < 22 || len(s) > 40 || !strings.HasPrefix(s, "g1") {
		return false
	}
	for i := 2; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') {
			return false
		}
	}
	return true
}

// validateLabel — same policy as the original single-realm build (see
// NOTES.md for the ENS/Starname/r/sys/users research behind it). The
// length bounds are still read from nsdata, so they survive a swap of
// this realm; the character rule is now this realm's own.
//
// Call sites, and why: RegisterName/RegisterDomain only (both the
// first-ever mint AND reclaiming a past-grace slot — a reclaim is a
// genuine new mint with a new owner). RenewName/RenewDomain deliberately
// do NOT call this — an already-registered name must keep renewing under
// whatever rule was in force when it was minted.
func validateLabel(label string) {
	minLen, maxLen := nsdata.GetLabelLength()
	if len(label) < minLen || len(label) > maxLen {
		panic(ufmt.Sprintf("nslogic: label must be %d-%d characters", minLen, maxLen))
	}
	// Structural invariant, enforced regardless of what the pattern
	// happens to allow: "*" is the separator in both the token ID
	// (label*domain) and nsdata's storage key (domain*label). A label or
	// domain containing one would make those encodings ambiguous and let
	// two different names collide onto a single record.
	if strings.Contains(label, "*") {
		panic("nslogic: label may not contain '*'")
	}
	if !matchesLabelRule(label) {
		panic("nslogic: a name is lowercase letters, digits and single hyphens between them — " + labelRule)
	}
	if looksLikeAddress(label) {
		panic("nslogic: label looks like a wallet address, not allowed")
	}
}
